module.exports = [{"id":"hp-7a-u1","title":"史前时期：原始社会与中华文明的起源 单元测试","subtitle":"七年级上册 · 第一单元","grade":"7a","tags":["七年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 9 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u1-q1","type":"choice","stem":"我国境内目前已知最早的古人类之一，距今约 170 万年，其化石发现于今云南省的是","answer":"A","explain":"元谋人发现于云南元谋，距今约 170 万年，是我国境内目前已知最早的古人类之一。","options":["元谋人","北京人","山顶洞人","半坡人"],"tags":["史前时期","时空观念"]},{"id":"cat-7a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 元谋人生活在云南元谋\n② 北京人生活在周口店\n③ 山顶洞人","answer":"A","explain":"按时间顺序应为：①元谋人生活在云南元谋（约 170 万年前）→②北京人生活在周口店（约 70 万—20 万年前）→③山顶洞人（约 3 万年前）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-1-1-g2","type":"choice","stem":"下列关于「远古时期的人类活动」的表述，错误的是","answer":"A","explain":"认为北京人会人工取火——这是最常见的混淆点，选项常把两者对调。正确表述：北京人会使用天然火并保存火种；人工取火是山顶洞人。","options":["认为北京人会人工取火。","北京人会使用天然火并保存火种；人工取火是山顶洞人。","中华文明的起源具有**本土性**（元谋人、北京人一脉相承）与**多元一体**（黄河流域、长江流域等多点并发）两大特征。","北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"cat-7a-1-2-g2","type":"choice","stem":"下列关于「原始农业与史前社会」的表述，错误的是","answer":"A","explain":"把河姆渡与半坡的农作物写反——记「南稻北粟」，与「南干栏北半地穴」一起记。正确表述：河姆渡→水稻（南方）；半坡→粟（北方）。","options":["把河姆渡与半坡的农作物写反。","河姆渡→水稻（南方）；半坡→粟（北方）。","生产力决定生活方式：种植水稻需要水田 → 长江流域的干栏式建筑；种植粟、气候干燥 → 黄河流域的半地穴式房屋。","原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-1-2-g5","type":"choice","stem":"「河姆渡文化（长江流域）」发生于","answer":"A","explain":"本课时间轴：河姆渡文化（长江流域）（约 7000 年前）。种植水稻、干栏式建筑、木结构水井。其余三个时间是同一单元相邻课时的事件时间。","options":["约 7000 年前","约 170 万年前","约 70 万—20 万年前","约 3 万年前"],"difficulty":1,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7a-u1-q3","type":"choice","stem":"良渚古城与陶寺古城的考古发现，最主要的价值在于","answer":"B","explain":"两处古城都出现城市、阶级分化与王权，是中华文明五千多年历史的实证，也说明中华文明本土起源、多元一体。","options":["证明中华文明是由西方传入的","为中华文明五千多年历史提供实证","说明我国最早的文字出现在长江流域","证明夏朝是我国第一个王朝"],"tags":["文明起源","家国情怀"]},{"id":"h7a-u1-q4","type":"choice","stem":"「禅让」制下，部落联盟首领产生的方式是","answer":"B","explain":"尧舜禹时期通过推举贤能者继位，称为禅让。父死子继的世袭制自夏启开始。","options":["父死子继","推举贤能者","以战功决定","由占卜决定"],"tags":["禅让制","历史解释"]},{"id":"cat-7a-1-3-g2","type":"choice","stem":"下列关于「中华文明的起源」的表述，错误的是","answer":"A","explain":"把尧舜禹的「禅让」说成世袭——「公天下」到「家天下」的转折点是夏朝建立，不是尧舜时期。正确表述：禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","options":["把尧舜禹的「禅让」说成世袭。","禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","考古发现是研究史前历史的**唯一可靠依据**；传说（炎黄、尧舜禹）需要考古材料印证，不能当作信史。","良渚、陶寺古城的意义：证明中国在距今约 5000 多年已出现早期国家与文明。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7a-u1-m1-q1","type":"short","stem":"（1）材料一中的灰烬层能说明北京人已经掌握了什么技能？这一发现有何意义？（4 分）","answer":"说明北京人已经会使用火并能够保存火种。意义：火的使用改善了生存条件（烧烤食物、照明、取暖、驱赶野兽），是人类进化过程中的重大进步；周口店遗址是研究人类起源的直接证据。","explain":"","tags":["史料实证","史前时期"],"rubric":["答出「使用火、保存火种」","答出火的作用（取暖/熟食/驱兽任一点）","答出遗址的史料价值"]},{"id":"cat-7a-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1921 年安特生、师丹斯基在北京周口店龙骨山发现遗址；1929 年 12 月裴文中发掘出第一个完整的北京人头盖骨化石。此后陆续发现 40 多个个体的人骨化石。（中国社会科学院考古研究所《北京人遗址》相关记述）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"远古时期的人类活动；北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。","explain":"材料出自中国社会科学院考古研究所《北京人遗址》相关记述。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-7a-u2","title":"夏商周时期：奴隶制王朝的更替和向封建社会的过渡 单元测试","subtitle":"七年级上册 · 第二单元","grade":"7a","tags":["七年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u2-q1","type":"choice","stem":"「大道之行也，天下为公，选贤与能……今大道既隐，天下为家。」「天下为家」开始于","answer":"B","explain":"启继承禹的王位，世袭制代替禅让制，「公天下」变为「家天下」。","options":["禹建立夏朝","启继承王位","汤灭夏建商","武王伐纣"],"tags":["世袭制","历史解释"]},{"id":"h7a-u2-q2","type":"choice","stem":"「封建亲戚，以藩屏周」反映的西周制度是","answer":"B","explain":"分封制把土地和人民分给宗亲、功臣，让他们建立诸侯国，起到拱卫王室的作用。","options":["禅让制","分封制","郡县制","世袭制"],"tags":["分封制","史料实证"]},{"id":"cat-7a-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 禹建立夏朝\n② 武王伐纣，牧野之战后建立西周\n③ 犬戎攻破镐京，西周灭亡","answer":"A","explain":"按时间顺序应为：①禹建立夏朝（约公元前 2070 年）→②武王伐纣，牧野之战后建立西周（公元前 1046 年）→③犬戎攻破镐京，西周灭亡（公元前 771 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-1-g2","type":"choice","stem":"下列关于「夏商西周王朝的更替」的表述，错误的是","answer":"A","explain":"把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」——制度与朝代配对是最常设的陷阱，答题前先想「哪个朝代」。正确表述：分封制是西周的制度；夏朝是世袭制王朝。","options":["把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」。","分封制是西周的制度；夏朝是世袭制王朝。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","夏朝是我国历史上第一个王朝，世袭制代替禅让制，「公天下」变为「家天下」。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-1-g3","type":"choice","stem":"下列结论中，属于「夏商西周王朝的更替」的是","answer":"A","explain":"本课结论：分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","评价变法要一分为二：商鞅变法使秦国富强，但严刑峻法也激化了社会矛盾。","百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"h7a-u2-q5","type":"choice","stem":"春秋战国时期出现「百家争鸣」局面的根本原因是","answer":"B","explain":"根本原因是生产力发展带来的社会大变革：经济基础变化引起上层建筑与思想的变动。其余选项是重要条件而非根本原因。","options":["各诸侯国竞相招揽人才","铁制农具和牛耕的推广，社会生产力提高","私学兴起，学术下移","周王室衰微，诸侯争霸"],"tags":["百家争鸣","唯物史观"]},{"id":"cat-7a-2-2-g2","type":"choice","stem":"下列关于「动荡变化中的春秋时期」的表述，错误的是","answer":"A","explain":"把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」——制度与朝代配对是最常设的陷阱，答题前先想「哪个朝代」。正确表述：分封制是西周的制度；夏朝是世袭制王朝。","options":["把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」。","分封制是西周的制度；夏朝是世袭制王朝。","生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-2-g3","type":"choice","stem":"下列结论中，属于「动荡变化中的春秋时期」的是","answer":"A","explain":"本课结论：生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","评价变法要一分为二：商鞅变法使秦国富强，但严刑峻法也激化了社会矛盾。","百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-2-g5","type":"choice","stem":"「春秋时期」发生于","answer":"A","explain":"本课时间轴：春秋时期（公元前 770—前 476 年）。铁制农具与牛耕出现；王室衰微，诸侯争霸。其余三个时间是同一单元相邻课时的事件时间。","options":["公元前 770—前 476 年","约公元前 2070 年","公元前 1046 年","公元前 771 年"],"difficulty":1,"tags":["七年级上册","第二单元","本课练习"]},{"id":"h7a-u2-q4","type":"choice","stem":"商鞅变法中最能体现「社会转型」的措施是","answer":"C","explain":"废除井田制、承认土地私有，标志着土地制度由奴隶制向封建制转变，最能体现社会转型。","options":["奖励耕织","确立县制","废除井田制，允许土地自由买卖","统一度量衡"],"tags":["商鞅变法","唯物史观"]},{"id":"h7a-u2-m1-q1","type":"short","stem":"（1）材料一反映的是西周的什么制度？受封者对周王承担哪些义务？（4 分）","answer":"分封制。义务：服从周王的调遣，向周王进献贡赋，平时镇守疆土、战时随从周王作战（「述职」「朝觐」）。","explain":"","tags":["分封制","历史解释"],"rubric":["答出分封制","答出服从调遣/随从作战","答出缴纳贡赋"]},{"id":"cat-7a-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：河南偃师二里头遗址发现宫殿基址、青铜爵、绿松石龙形器，学界多认为其与夏朝晚期都城有关，是探索夏文化的重要遗址。（中国社会科学院考古研究所《二里头》发掘报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"夏商西周王朝的更替；夏朝是我国历史上第一个王朝，世袭制代替禅让制，「公天下」变为「家天下」。","explain":"材料出自中国社会科学院考古研究所《二里头》发掘报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-7a-u3","title":"秦汉时期：统一多民族封建国家的建立和巩固 单元测试","subtitle":"七年级上册 · 第三单元","grade":"7a","tags":["七年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u3-q1","type":"choice","stem":"秦朝在地方上推行的、对后世影响最深远的制度是","answer":"B","explain":"郡县制下郡县长官由皇帝直接任免、不世袭，开创了此后两千多年的中央集权地方行政制度。行省制是元朝，科举制是隋朝。","options":["分封制","郡县制","行省制","科举制"],"tags":["郡县制","制度创新"]},{"id":"cat-7a-3-1-g2","type":"choice","stem":"下列关于「秦统一中国」的表述，错误的是","answer":"A","explain":"把「推恩令」与「分封制」混为一谈——它表面是「恩」，实质是削藩，材料题常问「高明之处」。正确表述：推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","options":["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","秦朝巩固统一的措施：皇帝制、三公九卿、郡县制；统一文字（小篆）、货币（圆形方孔半两钱）、度量衡；修长城、开灵渠。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-1-g3","type":"choice","stem":"下列结论中，属于「秦统一中国」的是","answer":"A","explain":"本课结论：秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"h7a-u3-q2","type":"choice","stem":"汉武帝采纳主父偃建议颁布「推恩令」，其高明之处在于","answer":"B","explain":"推恩令让诸侯王的子弟分封土地，封国越分越小，中央集权得到加强，且避免了激化矛盾。","options":["直接剥夺诸侯王的封地","使诸侯国越分越小，不费兵卒削弱了诸侯势力","以武力镇压诸侯叛乱","废除分封，全面推行郡县"],"tags":["推恩令","历史解释"]},{"id":"h7a-u3-q3","type":"choice","stem":"标志今新疆地区正式归属中央政权管辖的事件是","answer":"C","explain":"公元前 60 年西汉设置西域都护，标志西域正式归属中央政权管辖。","options":["张骞第一次出使西域","丝绸之路的开通","公元前 60 年西汉设置西域都护","班超经营西域"],"tags":["西域都护","时空观念"]},{"id":"cat-7a-3-2-g2","type":"choice","stem":"下列关于「秦末农民大起义」的表述，错误的是","answer":"A","explain":"把「推恩令」与「分封制」混为一谈——它表面是「恩」，实质是削藩，材料题常问「高明之处」。正确表述：推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","options":["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","秦亡的原因与启示：赋税徭役沉重、刑法严苛、秦二世更加残暴 → 农民起义。启示：治国要爱惜民力。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-2-g3","type":"choice","stem":"下列结论中，属于「秦末农民大起义」的是","answer":"A","explain":"本课结论：「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-3-g2","type":"choice","stem":"下列关于「西汉建立和“文景之治”」的表述，错误的是","answer":"A","explain":"认为西域都护设置于东汉——时间点是最爱设的陷阱，要记「前 60 年、西汉」。正确表述：公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","options":["认为西域都护设置于东汉。","公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-3-g3","type":"choice","stem":"下列结论中，属于「西汉建立和“文景之治”」的是","answer":"A","explain":"本课结论：大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-3-g5","type":"choice","stem":"「刘邦建立西汉，定都长安」发生于","answer":"A","explain":"本课时间轴：刘邦建立西汉，定都长安（公元前 202 年）。吸取秦亡教训，推行休养生息政策。其余三个时间是同一单元相邻课时的事件时间。","options":["公元前 202 年","公元前 221 年","公元前 213—前 212 年","公元前 209 年"],"difficulty":1,"tags":["七年级上册","第三单元","本课练习"]},{"id":"h7a-u3-m1-q2","type":"short","stem":"（2）材料三中的建议被哪位皇帝采纳？该措施为什么能加强中央集权？（4 分）","answer":"汉武帝采纳主父偃的建议，颁布「推恩令」。原因：名义上是把恩惠推及诸侯子弟，实际上使诸侯国的封地不断分割、越分越小，无力对抗中央；同时又避免了直接削藩引发叛乱，中央集权因此大大加强。","explain":"","tags":["推恩令","中央集权"],"rubric":["答出汉武帝/推恩令","答出封地越分越小","答出削弱诸侯实力","答出加强中央集权"]},{"id":"cat-7a-3-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：秦朝在中央设丞相、太尉、御史大夫，地方推行郡县制；统一文字为小篆、统一货币为圆形方孔半两钱、统一度量衡；修驰道、直道，开凿灵渠，连接湘江与漓江。（《史记·秦始皇本纪》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"秦统一中国；秦朝巩固统一的措施：皇帝制、三公九卿、郡县制；统一文字（小篆）、货币（圆形方孔半两钱）、度量衡；修长城、开灵渠。","explain":"材料出自《史记·秦始皇本纪》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-7a-u4","title":"三国两晋南北朝时期：政权分立与民族交融 单元测试","subtitle":"七年级上册 · 第四单元","grade":"7a","tags":["七年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u4-q1","type":"choice","stem":"为三国鼎立局面形成奠定基础的战役是","answer":"B","explain":"208 年赤壁之战中孙刘联军打败曹操，为三国鼎立局面的形成奠定基础。官渡之战为曹操统一北方奠定基础。","options":["官渡之战","赤壁之战","淝水之战","巨鹿之战"],"tags":["赤壁之战","时空观念"]},{"id":"cat-7a-4-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 官渡之战\n② 赤壁之战\n③ 曹丕称帝建魏，定都洛阳","answer":"A","explain":"按时间顺序应为：①官渡之战（200 年）→②赤壁之战（208 年）→③曹丕称帝建魏，定都洛阳（220 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-1-g2","type":"choice","stem":"下列关于「三国鼎立」的表述，错误的是","answer":"A","explain":"认为赤壁之战使曹操统一了全国——官渡之战与赤壁之战的结果、意义最容易被调换。正确表述：赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","options":["认为赤壁之战使曹操统一了全国。","赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-1-g3","type":"choice","stem":"下列结论中，属于「三国鼎立」的是","answer":"A","explain":"本课结论：分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","文化成就与时代相关：战乱与民族交融时期，宗教艺术（石窟）与书法艺术特别兴盛。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"h7a-u4-q2","type":"choice","stem":"北魏孝文帝改革措施中，最能体现民族交融的是","answer":"B","explain":"语言、服饰、姓氏与婚姻的汉化直接促进了鲜卑族与汉族的交融；迁都洛阳是为改革创造条件。","options":["迁都洛阳","说汉语、穿汉服、改汉姓、与汉族通婚","奖励军功","实行均田制"],"tags":["孝文帝改革","民族交融"]},{"id":"h7a-u4-q3","type":"choice","stem":"魏晋南北朝时期江南地区得到开发的最主要原因是","answer":"B","explain":"北人南迁带来了劳动力与先进的生产技术，是江南开发最主要的原因，其余是重要条件。","options":["江南自然条件优越","北方人口大量南迁，带来劳动力和先进技术","南方统治者重视农业","南方战乱较少"],"tags":["江南开发","唯物史观"]},{"id":"cat-7a-4-2-g2","type":"choice","stem":"下列关于「西晋的短暂统一和北方各族的内迁」的表述，错误的是","answer":"A","explain":"认为赤壁之战使曹操统一了全国——官渡之战与赤壁之战的结果、意义最容易被调换。正确表述：赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","options":["认为赤壁之战使曹操统一了全国。","赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-2-g3","type":"choice","stem":"下列结论中，属于「西晋的短暂统一和北方各族的内迁」的是","answer":"A","explain":"本课结论：分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","文化成就与时代相关：战乱与民族交融时期，宗教艺术（石窟）与书法艺术特别兴盛。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"h7a-u4-q4","type":"choice","stem":"把圆周率精确到小数点以后第七位数字的南朝科学家是","answer":"B","explain":"祖冲之在数学上把圆周率精确到小数点后第七位，领先世界近千年。","options":["贾思勰","祖冲之","郦道元","王羲之"],"tags":["科技文化","祖冲之"]},{"id":"cat-7a-4-3-g2","type":"choice","stem":"下列关于「东晋南朝政治和江南地区开发」的表述，错误的是","answer":"A","explain":"认为江南开发只是因为自然条件好——「主要原因」与「条件」的区分是得分点。正确表述：主要原因是北方人口南迁带来劳动力与先进生产技术，自然条件与社会安定是重要条件。","options":["认为江南开发只是因为自然条件好。","主要原因是北方人口南迁带来劳动力与先进生产技术，自然条件与社会安定是重要条件。","分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：曹操率军南下，孙权派周瑜、刘备派诸葛亮联合抗曹。联军利用曹军不习水战、疫病流行等弱点，以火攻大破曹军。（《三国志·吴书·周瑜传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"三国鼎立；三国鼎立：魏（220，曹丕，洛阳）、汉/蜀（221，刘备，成都）、吴（229，孙权，建业）；赤壁之战是局面形成的关键战役。","explain":"材料出自《三国志·吴书·周瑜传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7a-4-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：西晋宗室诸王为争夺中央权力，先后有八位诸侯王卷入混战，历时十六年，中原人口大量死亡、南迁，形成第一次大规模南迁浪潮。（《晋书·八王传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"西晋的短暂统一和北方各族的内迁；民族交融的表现：内迁各族与汉族杂居、通婚、相互学习（生产、饮食、服饰、语言、习俗）。","explain":"材料出自《晋书·八王传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-7b-u1","title":"隋唐时期：繁荣与开放的时代 单元测试","subtitle":"七年级下册 · 第一单元","grade":"7b","tags":["七年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7b-u1-q1","type":"choice","stem":"605 年起下令开凿大运河，以洛阳为中心、北抵涿郡、南至余杭的皇帝是","answer":"B","explain":"大运河由隋炀帝下令开凿（605 年起），以洛阳为中心，北抵涿郡，南至余杭，是古代世界上最长的运河。隋文帝的功绩是统一全国、创立三省六部制与分科考试选官。","options":["隋文帝","隋炀帝","唐高祖","唐玄宗"],"tags":["大运河","时空观念"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"h7b-u1-q6","type":"choice","stem":"关于五代十国，下列说法正确的是","answer":"A","explain":"五代十国是唐末藩镇割据局面的延续。北方政权更迭频繁、战乱不断；南方相对安定，经济得到发展；统一始终是历史发展的必然趋势。","options":["五代十国是唐末以来藩镇割据局面的延续","五代十国时期南方经济遭到严重破坏","五代十国都是由少数民族建立的政权","五代十国时期全国长期处于统一状态"],"tags":["五代十国","历史解释"]},{"id":"cat-7b-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杨坚夺取北周政权，建立隋朝，定都长安\n② 隋炀帝下令开凿大运河\n③ 设置进士科，科举制正式确立\n④ 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","answer":"A","explain":"按时间顺序应为：①杨坚夺取北周政权，建立隋朝，定都长安（581 年）→②隋炀帝下令开凿大运河（605 年起）→③设置进士科，科举制正式确立（隋炀帝时）→④隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g2","type":"choice","stem":"下列关于「隋朝统一与灭亡」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g3","type":"choice","stem":"下列结论中，属于「隋朝统一与灭亡」的是","answer":"A","explain":"本课结论：科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h7b-u1-q4","type":"choice","stem":"唐太宗说「舟所以比人君，水所以比黎庶，水能载舟，亦能覆舟」，这说明他","answer":"B","explain":"唐太宗从隋朝因暴政速亡的教训中认识到百姓的力量，因此减轻赋税徭役、推行有利于生产恢复的政策，这才有「贞观之治」。","options":["主张严刑峻法以驾驭臣下","注意吸取隋亡教训，爱惜民力","主张大力开疆拓土","主张抑制商业发展"],"tags":["贞观之治","家国情怀"]},{"id":"cat-7b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安\n② 唐太宗统治时期，出现「贞观之治」\n③ 玄奘西行天竺取经，后口述成《大唐西域记》\n④ 唐太宗把文成公主嫁给吐蕃赞普松赞干布","answer":"A","explain":"按时间顺序应为：①隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）→②唐太宗统治时期，出现「贞观之治」（627—649 年）→③玄奘西行天竺取经，后口述成《大唐西域记》（唐太宗时）→④唐太宗把文成公主嫁给吐蕃赞普松赞干布（641 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-2-g2","type":"choice","stem":"下列关于「唐朝建立与“贞观之治”」的表述，错误的是","answer":"A","explain":"把科举制的创立说成唐朝，或认为进士科是唐太宗设立的——「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。正确表述：科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","options":["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-2-g3","type":"choice","stem":"下列结论中，属于「唐朝建立与“贞观之治”」的是","answer":"A","explain":"本课结论：隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：永济渠（洛阳至涿郡）、通济渠（洛阳至淮水）、邗沟（淮水至江都入长江）、江南河（长江至余杭），沟通海河、黄河、淮河、长江、钱塘江五大水系。（《隋书·食货志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"隋朝统一与灭亡；隋朝的制度创新与统一：结束分裂、实现统一，创立科举制与三省六部制，开凿大运河，为唐朝的繁荣奠定了基础。","explain":"材料出自《隋书·食货志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h7b-u1-m1-q2","type":"short","stem":"（2）材料二、三分别反映了唐太宗怎样的治国做法？这些做法与「贞观之治」的出现有何关系？（5 分）","answer":"材料二反映唐太宗重视百姓、以民为本，注意减轻百姓负担（这是吸取隋亡教训的结果）；材料三反映他重视科举取士、笼络人才、扩大统治基础。关系：正因为唐太宗减轻赋税徭役、虚心纳谏、知人善任，并进一步完善三省六部制与科举制，才使政治比较清明、经济得到恢复和发展、社会秩序安定、国力增强，从而出现了「贞观之治」的局面。","explain":"","tags":["贞观之治","历史解释"],"rubric":["材料二：以民为本、重视百姓（减轻负担）","材料三：重视科举取士、重用人才","答出措施与治世之间的因果对应","答出贞观之治的表现（政治清明/经济发展/社会安定）"]}]},{"id":"hp-7b-u2","title":"辽宋夏金元时期：民族关系发展和社会变化 单元测试","subtitle":"七年级下册 · 第二单元","grade":"7b","tags":["七年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7b-u2-q1","type":"choice","stem":"宋太祖「杯酒释兵权」，并推行重文轻武的政策，其主要目的是","answer":"B","explain":"宋太祖吸取唐末以来武将专权、藩镇割据的教训，通过解除禁军将领兵权、重用文臣等办法防止武将专权，加强中央集权。其结果是军队战斗力有所削弱、财政负担加重。","options":["提高军队的战斗力","防止武将专权，加强中央集权","减轻农民的赋税负担","增加国家的财政收入"],"tags":["重文轻武","中央集权"]},{"id":"cat-7b-2-1-g2","type":"choice","stem":"下列关于「北宋的政治」的表述，错误的是","answer":"A","explain":"认为经济重心南移完成于唐朝——「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。正确表述：经济重心南移**从唐朝中期开始，到南宋时最后完成**。","options":["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-1-g3","type":"choice","stem":"下列结论中，属于「北宋的政治」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-1-g5","type":"choice","stem":"「赵匡胤建立北宋，定都东京（今河南开封）」发生于","answer":"A","explain":"本课时间轴：赵匡胤建立北宋，定都东京（今河南开封）（960 年）。赵匡胤即宋太祖；他「杯酒释兵权」，解除禁军将领的兵权，推行重文轻武政策。其余三个时间是同一单元相邻课时的事件时间。","options":["960 年","1005 年","1038 年","1115 年"],"difficulty":1,"tags":["七年级下册","第二单元","本课练习"]},{"id":"h7b-u2-q2","type":"choice","stem":"宋辽之间保持长时间的和平局面，开始于","answer":"B","explain":"1005 年宋辽订立澶渊之盟，北宋每年给辽岁币，此后很长时间里宋辽保持了和平局面，边境贸易发展。","options":["北宋建立","澶渊之盟的订立","靖康之变","宋金议和"],"tags":["澶渊之盟","时空观念"]},{"id":"cat-7b-2-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 宋辽订立「澶渊之盟」\n② 党项族首领元昊称帝，建立西夏\n③ 女真族首领完颜阿骨打建立金\n④ 铁木真统一蒙古草原，建立蒙古政权，被尊为成吉思汗","answer":"A","explain":"按时间顺序应为：①宋辽订立「澶渊之盟」（1005 年）→②党项族首领元昊称帝，建立西夏（1038 年）→③女真族首领完颜阿骨打建立金（1115 年）→④铁木真统一蒙古草原，建立蒙古政权，被尊为成吉思汗（1206 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-2-g2","type":"choice","stem":"下列关于「辽、西夏与北宋并立」的表述，错误的是","answer":"A","explain":"把「澶渊之盟」与「靖康之变」混为一谈——一个发生在宋辽之间、一个发生在宋金之间，时间与对象都不能混。正确表述：澶渊之盟是 1005 年宋辽之间的议和；靖康之变是 1127 年金灭北宋。","options":["把「澶渊之盟」与「靖康之变」混为一谈。","澶渊之盟是 1005 年宋辽之间的议和；靖康之变是 1127 年金灭北宋。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-2-g3","type":"choice","stem":"下列结论中，属于「辽、西夏与北宋并立」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"h7b-u2-q3","type":"choice","stem":"世界上最早的纸币「交子」出现的时间和地区是","answer":"A","explain":"北宋前期，四川地区出现「交子」，这是世界上最早的纸币，反映了宋代商品经济的繁荣。","options":["北宋前期的四川地区","唐朝中期的江南地区","南宋时期的临安","元朝的大都"],"tags":["交子","宋代经济"]},{"id":"h7b-u2-q5","type":"choice","stem":"我国经济重心南移最后完成于","answer":"C","explain":"经济重心南移从唐朝中期开始，到南宋时最后完成，南方成为全国的经济重心，出现「苏湖熟，天下足」的局面。","options":["唐朝中期","北宋","南宋","元朝"],"tags":["经济重心南移","时空观念"]},{"id":"cat-7b-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：北宋扩大科举取士，重用文臣掌兵权，地方设通判监督知州，设转运使收财权，形成「强干弱枝」格局。（《宋史·职官志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"北宋的政治；北宋加强中央集权与「重文轻武」：宋太祖解除禁军将领兵权，分割宰相权力，派文臣担任地方长官并设通判加以牵制，同时大力发展科举、重用文臣。","explain":"材料出自《宋史·职官志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-2-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1004 年辽军南下，宋真宗在寇准力劝下亲征澶州。1005 年双方议和：宋每年给辽白银十万两、绢二十万匹，辽撤兵，双方约为兄弟之国。（《续资治通鉴长编》卷五十八）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"辽、西夏与北宋并立；辽、西夏、金与两宋的和战：1005 年宋辽订立澶渊之盟后长期和平；北宋与西夏议和；1141 年宋金议和，以淮河至大散关一线划界，南宋向金称臣、送岁币。","explain":"材料出自《续资治通鉴长编》卷五十八。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-7b-u3","title":"明清时期（至鸦片战争前）：统一多民族封建国家的巩固与发展 单元测试","subtitle":"七年级下册 · 第三单元","grade":"7b","tags":["七年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7b-u3-q6","type":"choice","stem":"清朝雍正帝设立、使君主专制进一步强化的机构是","answer":"C","explain":"雍正帝时设立军机处，军机大臣只是跪受笔录、传达皇帝的旨意，君主专制进一步强化。锦衣卫、东厂是明朝的特务机构。","options":["中书省","内阁","军机处","锦衣卫"],"tags":["军机处","君主专制"]},{"id":"cat-7b-3-1-g2","type":"choice","stem":"下列关于「明朝的统治」的表述，错误的是","answer":"A","explain":"认为郑和下西洋是为了开拓海外殖民地、发展海外贸易——它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。正确表述：郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","options":["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","明朝强化皇权：中央废除丞相和中书省，权力分给六部；地方废除行省，设立三司；设锦衣卫、东厂等特务机构；实行八股取士。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-1-g3","type":"choice","stem":"下列结论中，属于「明朝的统治」的是","answer":"A","explain":"本课结论：明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-1-g5","type":"choice","stem":"「朱元璋建立明朝，定都应天府（今江苏南京）」发生于","answer":"A","explain":"本课时间轴：朱元璋建立明朝，定都应天府（今江苏南京）（1368 年）。朱元璋即明太祖；同年明军攻占大都，元朝在全国的统治结束。其余三个时间是同一单元相邻课时的事件时间。","options":["1368 年","16 世纪中期","1553 年","1616 年"],"difficulty":1,"tags":["七年级下册","第三单元","本课练习"]},{"id":"h7b-u3-q2","type":"choice","stem":"郑和下西洋最远到达的地区是","answer":"B","explain":"1405—1433 年郑和七次下西洋，到达亚非三十多个国家和地区，最远到达非洲东海岸和红海沿岸，是世界航海史上的空前壮举。","options":["印度半岛南端","非洲东海岸和红海沿岸","波斯湾沿岸","美洲西海岸"],"tags":["郑和下西洋","时空观念"]},{"id":"cat-7b-3-2-g2","type":"choice","stem":"下列关于「明朝的对外关系」的表述，错误的是","answer":"A","explain":"认为郑和下西洋是为了开拓海外殖民地、发展海外贸易——它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。正确表述：郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","options":["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-2-g3","type":"choice","stem":"下列结论中，属于「明朝的对外关系」的是","answer":"A","explain":"本课结论：对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。","明清科技具有「总结性」而缺乏创新性：《本草纲目》《天工开物》《农政全书》都是对传统医药、农业与手工业经验的总结，而同一时期的欧洲正走向近代科学。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-2-g5","type":"choice","stem":"「戚继光率「戚家军」抗倭，东南沿海的倭患基本平息」发生于","answer":"A","explain":"本课时间轴：戚继光率「戚家军」抗倭，东南沿海的倭患基本平息（16 世纪中期）。戚继光先后在台州、福建、广东大败倭寇，是我国历史上的民族英雄。其余三个时间是同一单元相邻课时的事件时间。","options":["16 世纪中期","1368 年","明太祖、明成祖时","1616 年"],"difficulty":1,"tags":["七年级下册","第三单元","本课练习"]},{"id":"h7b-u3-q1","type":"choice","stem":"明朝废除丞相、撤销中书省，把权力分给六部，这一措施的主要作用是","answer":"A","explain":"废除丞相后，六部直接对皇帝负责，君主专制大大加强，但也使皇帝政务负担加重。","options":["加强了君主专制","削弱了皇权","提高了地方的自主权","形成了内阁制"],"tags":["明朝皇权强化","制度创新"]},{"id":"h7b-u3-q3","type":"choice","stem":"清朝设置台湾府，隶属福建省，此事发生在","answer":"C","explain":"1662 年郑成功从荷兰殖民者手中收复台湾；1684 年清朝设置台湾府，隶属福建省，加强了中央政府对台湾的管辖。","options":["1662 年","1683 年","1684 年","1689 年"],"tags":["台湾府","边疆管辖"]},{"id":"cat-7b-3-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1380 年，明太祖借胡惟庸案废除中书省和丞相，由六部直接对皇帝负责，君主专制空前加强。（《明史·太祖本纪》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"明朝的统治；明朝强化皇权：中央废除丞相和中书省，权力分给六部；地方废除行省，设立三司；设锦衣卫、东厂等特务机构；实行八股取士。","explain":"材料出自《明史·太祖本纪》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-3-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：郑和船队最多时有两百余艘船、两万七千余人，比欧洲航海家远航早半个多世纪，是中国古代规模最大的远洋航行。（《明史·郑和传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"明朝的对外关系；郑和下西洋（1405—1433 年，共七次）：目的是提高明朝在国外的地位和威望、加强与海外各国的联系，最远到达非洲东海岸和红海沿岸。","explain":"材料出自《明史·郑和传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-8a-u1","title":"中国开始沦为半殖民地半封建社会 单元测试","subtitle":"八年级上册 · 第一单元","grade":"8a","tags":["八年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8a-u1-q1","type":"choice","stem":"英国发动鸦片战争的根本原因是","answer":"B","explain":"鸦片战争是英国资本主义发展的必然结果：工业革命后英国急需商品市场和原料产地。虎门销烟只是英国发动战争的借口，即直接原因。","options":["林则徐在虎门销烟","英国为打开中国市场、推销工业品并掠夺原料","清政府闭关自守、禁止通商","中英两国贸易长期不平衡"],"tags":["鸦片战争","历史解释"]},{"id":"h8a-u1-q2","type":"choice","stem":"《南京条约》的各项内容中，最能反映英国打开中国市场、便利经济侵略意图的是","answer":"C","explain":"五口通商打开了中国大门，协定关税破坏了中国关税自主权，使列强可以低价倾销商品、掠夺原料，最能体现其经济侵略意图。割地赔款是政治与财政层面的侵害。","options":["割香港岛给英国","赔款 2100 万银元","开放五处通商口岸并协定关税","英军占领广州"],"tags":["南京条约","史料实证"]},{"id":"cat-8a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 林则徐在广东虎门销烟\n② 鸦片战争\n③ 中英《南京条约》签订","answer":"A","explain":"按时间顺序应为：①林则徐在广东虎门销烟（1839 年 6 月）→②鸦片战争（1840 年 6 月—1842 年 8 月）→③中英《南京条约》签订（1842 年 8 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-1-g2","type":"choice","stem":"下列关于「鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。","列强侵华的核心目的是把中国变成其商品市场和原料产地；《南京条约》中的**协定关税**破坏中国关税自主权，便利了列强的经济侵略。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8a-u1-q3","type":"choice","stem":"1860 年焚毁圆明园的侵略者是","answer":"B","explain":"第二次鸦片战争中，1860 年 10 月英法联军攻入北京，抢劫并焚毁了圆明园。八国联军侵华是 1900 年的事。","options":["英国军队","英法联军","八国联军","日本军队"],"tags":["第二次鸦片战争","时空观念"]},{"id":"cat-8a-1-2-g2","type":"choice","stem":"下列关于「第二次鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-2-g5","type":"choice","stem":"「第二次鸦片战争」发生于","answer":"A","explain":"本课时间轴：第二次鸦片战争（1856 年 10 月—1860 年 10 月）。英法联军发动，是鸦片战争的继续和扩大；1858 年《天津条约》。其余三个时间是同一单元相邻课时的事件时间。","options":["1856 年 10 月—1860 年 10 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-2-g6","type":"choice","stem":"下列考点中，属于「第二次鸦片战争」的是","answer":"A","explain":"本课考点（重点）：第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联军 1860 年所为。其余三项是同一单元相邻课时的考点。","options":["第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联…","鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战…","《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、…","鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8a-u1-q4","type":"choice","stem":"太平天国运动中，标志其由盛转衰的事件是","answer":"C","explain":"1856 年的天京事变是太平天国领导集团内讧，使其由盛转衰；1864 年天京陷落标志运动失败。","options":["金田起义","定都天京","天京事变","天京陷落"],"tags":["太平天国运动","时空观念"]},{"id":"cat-8a-1-3-g2","type":"choice","stem":"下列关于「太平天国运动」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8a-u1-m1-q1","type":"short","stem":"（1）依据材料一，说明林则徐主张禁烟的原因；结合所学指出虎门销烟的意义。（4 分）","answer":"原因：鸦片大量输入使中国白银外流、财政困难（「无可以充饷之银」），并严重摧残吸食者的体质，军队战斗力削弱（「无可以御敌之兵」），危及清朝统治。意义：虎门销烟是中国人民禁烟斗争的伟大胜利，显示了中华民族反抗外来侵略的坚强意志，林则徐是当之无愧的民族英雄。","explain":"","tags":["虎门销烟","史料实证"],"rubric":["答出白银外流、财政困难","答出兵弱、摧残体质","答出禁烟斗争的伟大胜利","答出反抗侵略的坚强意志/民族英雄"]},{"id":"h8a-u1-m1-q2","type":"short","stem":"（2）依据材料二，指出《南京条约》中破坏中国关税自主权的条款，并结合材料三说明鸦片战争对中国社会性质的影响。（6 分）","answer":"条款：英商进出口货物应纳税款必须经过双方协议（协定关税）。影响：中国的领土完整和主权遭到破坏，开始沦为半殖民地；封建经济逐步解体，被卷入资本主义世界市场，开始沦为半封建。总之，鸦片战争后中国开始沦为半殖民地半封建社会，鸦片战争成为中国近代史的开端。","explain":"","tags":["南京条约","半殖民地半封建社会"],"rubric":["答出协定关税","答出领土、主权遭到破坏","答出封建经济开始解体","答出开始沦为半殖民地半封建社会","答出是中国近代史的开端"]}]},{"id":"hp-8a-u2","title":"早期现代化的初步探索和民族危机加剧 单元测试","subtitle":"八年级上册 · 第二单元","grade":"8a","tags":["八年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8a-u2-q1","type":"choice","stem":"洋务运动「只学习西方技术而不改变封建制度」，导致其最终破产。标志其破产的事件是","answer":"B","explain":"1895 年初威海卫战役中北洋舰队全军覆没，甲午战争中国战败，宣告了洋务运动的破产，也说明单靠引进技术不能救中国。","options":["太平天国运动失败","甲午中日战争中国战败、北洋舰队全军覆没","《辛丑条约》的签订","戊戌变法失败"],"tags":["洋务运动","历史解释"]},{"id":"h8a-u2-q3","type":"choice","stem":"「法者天下之公器也，变者天下之公理也」的提出者，也是戊戌变法主要领导人之一的是","answer":"B","explain":"此语出自梁启超《变法通议》。梁启超与康有为是维新变法的主要领导人，严复译述《天演论》宣传进化论，李鸿章是洋务派代表。","options":["李鸿章","梁启超","严复","孙中山"],"tags":["戊戌变法","历史解释"]},{"id":"cat-8a-2-1-g2","type":"choice","stem":"下列关于「洋务运动和边疆危机」的表述，错误的是","answer":"A","explain":"认为洋务运动是中国近代史的开端——「近代史」讲社会性质变化，「近代化」讲向工业化、民主化迈进，两个概念必须分清。正确表述：中国近代史的开端是鸦片战争；洋务运动是中国**近代化**的开端。","options":["认为洋务运动是中国近代史的开端。","中国近代史的开端是鸦片战争；洋务运动是中国**近代化**的开端。","近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","洋务运动：以「自强」「求富」为口号，创办安庆内军械所、江南机器制造总局、福州船政局等军事工业和轮船招商局、开平煤矿、汉阳铁厂、湖北织布局等民用企业，筹建北洋舰队等新式海陆军。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-1-g3","type":"choice","stem":"下列结论中，属于「洋务运动和边疆危机」的是","answer":"A","explain":"本课结论：近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。","《马关条约》允许日本在通商口岸开设工厂，标志列强对华侵略**由以商品输出为主转向以资本输出为主**，中国的民族危机空前严重。","改革要顺应历史潮流并依靠可靠的力量：戊戌变法失败说明**资产阶级改良道路在中国行不通**，这为后来辛亥革命用暴力推翻清政府提供了历史教训。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"h8a-u2-q2","type":"choice","stem":"标志列强对华经济侵略由以商品输出为主转向以资本输出为主的不平等条约条款是","answer":"B","explain":"允许在通商口岸开设工厂，意味着列强可以直接利用中国的原料和劳动力进行生产，是资本输出的典型方式，故《马关条约》是这一转变的标志。","options":["《南京条约》中的协定关税","《马关条约》中允许日本在通商口岸开设工厂","《辛丑条约》中的巨额赔款","《北京条约》中的增开天津为商埠"],"tags":["马关条约","资本输出"]},{"id":"h8a-u2-q4","type":"choice","stem":"《辛丑条约》中，最能说明清政府已成为「洋人的朝廷」的条款是","answer":"C","explain":"「保证严禁人民参加反帝活动」意味着清政府由中国的政权机构变成列强镇压中国人民的工具，故称「洋人的朝廷」，标志中国完全陷入半殖民地半封建社会的深渊。","options":["赔款白银 4.5 亿两","划定北京东交民巷为使馆界","清政府保证严禁人民参加各种形式的反帝活动","拆毁大沽炮台"],"tags":["辛丑条约","历史解释"]},{"id":"cat-8a-2-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 甲午中日战争\n② 《马关条约》签订\n③ 康有为、梁启超等发起公车上书\n④ 《辛丑条约》签订","answer":"A","explain":"按时间顺序应为：①甲午中日战争（1894 年 7 月—1895 年 4 月）→②《马关条约》签订（1895 年 4 月）→③康有为、梁启超等发起公车上书（1895 年）→④《辛丑条约》签订（1901 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-2-g2","type":"choice","stem":"下列关于「甲午中日战争与列强瓜分中国狂潮」的表述，错误的是","answer":"A","explain":"认为北洋舰队是在黄海海战中全军覆没的——两场海战的结果最易互换，记「黄海海战失致远，威海卫之战全军覆没」。正确表述：黄海海战只是重创北洋舰队；1895 年初的威海卫战役中北洋舰队全军覆没，标志洋务运动的破产。","options":["认为北洋舰队是在黄海海战中全军覆没的。","黄海海战只是重创北洋舰队；1895 年初的威海卫战役中北洋舰队全军覆没，标志洋务运动的破产。","甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。","《马关条约》允许日本在通商口岸开设工厂，标志列强对华侵略**由以商品输出为主转向以资本输出为主**，中国的民族危机空前严重。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-2-g3","type":"choice","stem":"下列结论中，属于「甲午中日战争与列强瓜分中国狂潮」的是","answer":"A","explain":"本课结论：甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。","近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","改革要顺应历史潮流并依靠可靠的力量：戊戌变法失败说明**资产阶级改良道路在中国行不通**，这为后来辛亥革命用暴力推翻清政府提供了历史教训。","《辛丑条约》使中国**完全陷入半殖民地半封建社会的深渊**，清政府完全成为帝国主义统治中国的工具，中国人民必须推翻清政府的反动统治才能救亡图存。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-3-g2","type":"choice","stem":"下列关于「戊戌变法」的表述，错误的是","answer":"A","explain":"把公车上书与百日维新混为一谈——时间与性质不同，问「变法开始的标志」要答百日维新，问「序幕」才答公车上书。正确表述：公车上书（1895 年）揭开了维新变法运动的序幕；百日维新（1898 年 6—9 月）是变法的实际推行阶段。","options":["把公车上书与百日维新混为一谈。","公车上书（1895 年）揭开了维新变法运动的序幕；百日维新（1898 年 6—9 月）是变法的实际推行阶段。","近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","改革要顺应历史潮流并依靠可靠的力量：戊戌变法失败说明**资产阶级改良道路在中国行不通**，这为后来辛亥革命用暴力推翻清政府提供了历史教训。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"h8a-u2-m1-q1","type":"short","stem":"（1）材料一反映了洋务派的什么主张？依据材料一、二说明这一主张在甲午战后为什么被国人普遍质疑。（6 分）","answer":"主张：认为中国的政治制度和文教制度远胜西方，只是在武器技术上不如人，因此主张「师夷长技」，只学习西方先进技术而不改变封建制度。被质疑的原因：甲午中日战争中国战败、北洋舰队全军覆没，说明单靠引进洋枪洋炮、创办近代军事工业，并不能挽救民族危亡；而材料二梁启超主张「变者天下之公理也」，认为必须变革制度。可见洋务运动「只学技术、不改制度」的道路走不通，必须进行制度变革。","explain":"","tags":["洋务运动","历史解释"],"rubric":["答出「只学技术」的主张","答出甲午战败、北洋舰队覆没","答出洋务运动破产","答出必须变革制度"]},{"id":"cat-8a-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：军事工业有安庆内军械所、江南机器制造总局、福州船政局；民用工业有轮船招商局、开平煤矿、汉阳铁厂、湖北织布局。（2024 部编版八上第 4 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"洋务运动和边疆危机；洋务运动：以「自强」「求富」为口号，创办安庆内军械所、江南机器制造总局、福州船政局等军事工业和轮船招商局、开平煤矿、汉阳铁厂、湖北织布局等民用企业，筹建北洋舰队等新式海陆军。","explain":"材料出自2024 部编版八上第 4 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-8a-u3","title":"资产阶级民主革命与中华民国的建立 单元测试","subtitle":"八年级上册 · 第三单元","grade":"8a","tags":["八年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8a-u3-q1","type":"choice","stem":"孙中山提出的三民主义中，对应同盟会纲领「创立民国」的是","answer":"B","explain":"民族主义对应「驱除鞑虏，恢复中华」，民权主义对应「创立民国」，民生主义对应「平均地权」。民权主义是三民主义的核心。","options":["民族主义","民权主义","民生主义","民主主义"],"tags":["三民主义","历史解释"]},{"id":"h8a-u3-q2","type":"choice","stem":"辛亥革命爆发的标志性事件是","answer":"B","explain":"1911 年 10 月 10 日武昌起义爆发，各省纷纷响应，清朝统治迅速崩溃。因 1911 年为农历辛亥年，故称辛亥革命。","options":["黄花岗起义","武昌起义","中华民国成立","《中华民国临时约法》颁布"],"tags":["武昌起义","时空观念"]},{"id":"h8a-u3-q4","type":"choice","stem":"下列关于辛亥革命的说法，正确的是","answer":"C","explain":"辛亥革命的最大功绩是推翻清朝统治、结束君主专制制度、建立中华民国、使民主共和观念深入人心；但它没有改变社会性质，没有完成反帝反封建任务，革命果实被袁世凯窃取。","options":["它改变了中国半殖民地半封建社会的性质","它完成了反帝反封建的革命任务","它推翻了清王朝，结束了中国两千多年的君主专制制度","它建立了亚洲第一个资产阶级共和国并长期巩固下来"],"tags":["辛亥革命的评价","唯物史观"]},{"id":"cat-8a-3-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 孙中山在檀香山成立兴中会\n② 中国同盟会在日本东京成立\n③ 黄花岗起义\n④ 武昌起义","answer":"A","explain":"按时间顺序应为：①孙中山在檀香山成立兴中会（1894 年）→②中国同盟会在日本东京成立（1905 年 8 月）→③黄花岗起义（1911 年 4 月）→④武昌起义（1911 年 10 月 10 日）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"cat-8a-3-1-g2","type":"choice","stem":"下列关于「中国同盟会」的表述，错误的是","answer":"A","explain":"认为辛亥革命推翻了封建制度——「封建制度」包含经济、政治、思想等多方面，辛亥革命没有改变封建土地制度与社会性质，写错就丢掉关键分。正确表述：辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","options":["认为辛亥革命推翻了封建制度。","辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","辛亥革命是中国近代史上一次伟大的反帝反封建的**资产阶级民主革命**，它的最大功绩是推翻清朝统治、结束君主专制制度、使民主共和观念深入人心。","评价辛亥革命要一分为二：**成功在于推翻帝制、建立民国**；**失败在于没有改变半殖民地半封建的社会性质，没有完成反帝反封建任务**。"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"cat-8a-3-1-g3","type":"choice","stem":"下列结论中，属于「中国同盟会」的是","answer":"A","explain":"本课结论：辛亥革命是中国近代史上一次伟大的反帝反封建的**资产阶级民主革命**，它的最大功绩是推翻清朝统治、结束君主专制制度、使民主共和观念深入人心。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辛亥革命是中国近代史上一次伟大的反帝反封建的**资产阶级民主革命**，它的最大功绩是推翻清朝统治、结束君主专制制度、使民主共和观念深入人心。","评价辛亥革命要一分为二：**成功在于推翻帝制、建立民国**；**失败在于没有改变半殖民地半封建的社会性质，没有完成反帝反封建任务**。","《中华民国临时约法》体现了**主权在民、三权分立、法律面前人人平等**的资产阶级民主原则，是中国政治民主化的重要成果。","资产阶级革命派**不敢充分发动和依靠人民群众，也不敢明确提出反帝要求**，这是辛亥革命失败的根本原因，也是后来中国革命必须由无产阶级领导的深刻教训。"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"h8a-u3-q3","type":"choice","stem":"《中华民国临时约法》的性质是","answer":"B","explain":"《中华民国临时约法》由南京临时政府颁布，确认主权在民、三权分立，是中国历史上第一部具有资产阶级共和国宪法性质的重要文件。","options":["中国第一部社会主义类型的宪法","中国历史上第一部具有资产阶级共和国宪法性质的重要文件","清政府颁布的君主立宪文件","北洋政府制定的军事法令"],"tags":["临时约法","史料实证"]},{"id":"cat-8a-3-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 武昌起义\n② 中华民国临时政府在南京成立\n③ 《中华民国临时约法》颁布","answer":"A","explain":"按时间顺序应为：①武昌起义（1911 年 10 月 10 日）→②中华民国临时政府在南京成立（1912 年 1 月 1 日）→③《中华民国临时约法》颁布（1912 年 3 月 11 日）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"cat-8a-3-2-g2","type":"choice","stem":"下列关于「辛亥革命」的表述，错误的是","answer":"A","explain":"认为辛亥革命推翻了封建制度——「封建制度」包含经济、政治、思想等多方面，辛亥革命没有改变封建土地制度与社会性质，写错就丢掉关键分。正确表述：辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","options":["认为辛亥革命推翻了封建制度。","辛亥革命推翻的是清王朝的统治和两千多年的君主专制制度（封建帝制），中国的社会性质仍然是半殖民地半封建社会。","辛亥革命是中国近代史上一次伟大的反帝反封建的**资产阶级民主革命**，它的最大功绩是推翻清朝统治、结束君主专制制度、使民主共和观念深入人心。","评价辛亥革命要一分为二：**成功在于推翻帝制、建立民国**；**失败在于没有改变半殖民地半封建的社会性质，没有完成反帝反封建任务**。"],"difficulty":2,"tags":["八年级上册","第三单元","本课练习"]},{"id":"h8a-u3-q5","type":"choice","stem":"1916 年袁世凯死去后，中国出现的政治局面是","answer":"B","explain":"袁世凯死后，北洋军阀分裂为直系、皖系、奉系等派系，中国陷入军阀割据混战的局面，人民生活痛苦，民主共和名存实亡。","options":["南北对峙、国共对立","军阀割据混战","列强共同支配下的「以华治华」","君主立宪制的确立"],"tags":["军阀割据","时空观念"]},{"id":"h8a-u3-m1-q1","type":"short","stem":"（1）依据材料一，写出孙中山阐发的三大主义，并指出这一思想体系的局限性。（4 分）","answer":"三大主义：民族主义、民权主义、民生主义（合称三民主义）。局限性：没有明确提出反对帝国主义的要求，也没有彻底的土地革命纲领，不能彻底解决农民的土地问题，因而无法完成反帝反封建的革命任务。","explain":"","tags":["三民主义","历史解释"],"rubric":["答出民族、民权、民生三大主义","答出没有明确提出反帝要求","答出没有彻底的土地纲领","答出无法完成反帝反封建任务"]},{"id":"h8a-u3-m1-q2","type":"short","stem":"（2）依据材料二说明《中华民国临时约法》体现的原则，并结合材料三谈谈你对辛亥革命结果的认识。（6 分）","answer":"原则：主权在民（中华民国的主权属于国民全体）；法律面前人人平等；三权分立与责任内阁制（国务员负其责任，用以限制总统权力）。认识：袁世凯窃取革命果实、复辟帝制，说明辛亥革命虽然推翻了清朝统治、结束了君主专制制度、建立了中华民国，但没有改变中国半殖民地半封建社会的性质，没有完成反帝反封建的任务；军阀割据混战也说明民主共和的实现需要强大的社会力量支撑，资产阶级革命派不能领导中国革命走向彻底胜利。","explain":"","tags":["临时约法","辛亥革命的评价"],"rubric":["答出主权在民","答出平等/分权与责任内阁","答出革命果实被袁世凯窃取","答出没有改变社会性质、没有完成反帝反封建任务","答出资产阶级革命派的局限"]}]},{"id":"hp-8a-u4","title":"新民主主义革命的兴起 单元测试","subtitle":"八年级上册 · 第四单元","grade":"8a","tags":["八年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 9 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8a-u4-q1","type":"choice","stem":"新文化运动开始的标志是","answer":"B","explain":"1915 年陈独秀在上海创办《青年杂志》（自第二卷起改名《新青年》），标志新文化运动开始。《天演论》是维新变法的思想武器。","options":["严复译述《天演论》","陈独秀在上海创办《青年杂志》","五四运动爆发","中共一大召开"],"tags":["新文化运动","时空观念"]},{"id":"h8a-u4-q2","type":"choice","stem":"五四运动爆发的导火线是","answer":"B","explain":"1919 年巴黎和会拒绝中国正当要求，竟将德国在山东的特权转让给日本，消息传回国内直接引发五四运动。","options":["日本提出「二十一条」","巴黎和会上中国外交的失败","北洋政府镇压学生游行","中国共产党号召反帝反封建"],"tags":["五四运动","历史解释"]},{"id":"h8a-u4-q3","type":"choice","stem":"五四运动被称为中国新民主主义革命的开端，主要因为它","answer":"C","explain":"判断革命阶段的关键是领导阶级与指导思想。五四运动中工人阶级成为主力，运动具有彻底反帝反封建的性质，因此成为新民主主义革命的开端。","options":["取得了彻底胜利","由学生首先发起","工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质","建立了中国共产党"],"tags":["五四运动","唯物史观"]},{"id":"cat-8a-4-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 陈独秀在上海创办《青年杂志》（后改名《新青年》）\n② 李大钊发表《庶民的胜利》《布尔什维主义的胜利》\n③ 五四运动爆发","answer":"A","explain":"按时间顺序应为：①陈独秀在上海创办《青年杂志》（后改名《新青年》）（1915 年）→②李大钊发表《庶民的胜利》《布尔什维主义的胜利》（1918 年）→③五四运动爆发（1919 年 5 月 4 日）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第四单元","本课练习"]},{"id":"cat-8a-4-1-g2","type":"choice","stem":"下列关于「五四运动」的表述，错误的是","answer":"A","explain":"把五四运动的导火线说成「二十一条」的签订——两件事都与日本侵略山东有关，但时间与性质不同，属高频陷阱。正确表述：导火线是 1919 年巴黎和会上中国外交的失败（列强将德国在山东的特权转让给日本）；「二十一条」是 1915 年日本提出、袁世凯接受的事件。","options":["把五四运动的导火线说成「二十一条」的签订。","导火线是 1919 年巴黎和会上中国外交的失败（列强将德国在山东的特权转让给日本）；「二十一条」是 1915 年日本提出、袁世凯接受的事件。","新文化运动是**中国近代史上一次伟大的思想解放运动**：它动摇了封建道德礼教的统治地位，使中国人民特别是青年知识分子的思想得到极大解放，为马克思主义在中国的传播创造了条件。","五四运动是**中国新民主主义革命的开端**：工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质，促进了马克思主义与中国工人运动的结合。"],"difficulty":2,"tags":["八年级上册","第四单元","本课练习"]},{"id":"h8a-u4-q4","type":"choice","stem":"中共一大确定党的奋斗目标是","answer":"B","explain":"中共一大通过党的第一个纲领，确定党的名称为中国共产党，奋斗目标是推翻资产阶级政权，建立无产阶级专政，实现共产主义。A 项是中共二大提出的民主革命纲领的内容。","options":["打倒军阀、推翻国际帝国主义的压迫","推翻资产阶级政权，建立无产阶级专政，实现共产主义","联俄、联共、扶助农工","建立抗日民族统一战线"],"tags":["中共一大","历史解释"]},{"id":"h8a-u4-q5","type":"choice","stem":"第一次明确提出彻底的反帝反封建民主革命纲领的会议是","answer":"B","explain":"1922 年中共二大重申最高纲领，并第一次明确提出彻底的反帝反封建的民主革命纲领，为中国革命指明了方向。","options":["中共一大","中共二大","国民党一大","中共七大"],"tags":["中共二大","历史解释"]},{"id":"cat-8a-4-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 李大钊发表《庶民的胜利》《布尔什维主义的胜利》\n② 中共一大在上海召开，后转到浙江嘉兴南湖游船\n③ 京汉铁路工人大罢工","answer":"A","explain":"按时间顺序应为：①李大钊发表《庶民的胜利》《布尔什维主义的胜利》（1918 年）→②中共一大在上海召开，后转到浙江嘉兴南湖游船（1921 年 7 月）→③京汉铁路工人大罢工（1923 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第四单元","本课练习"]},{"id":"cat-8a-4-2-g2","type":"choice","stem":"下列关于「中国共产党诞生」的表述，错误的是","answer":"A","explain":"把新民主主义革命的开端记为中国共产党成立——两个结论都对，但对应不同事件，必须按设问区分。正确表述：新民主主义革命的开端是五四运动（1919 年）；中国共产党的成立使中国革命的面貌焕然一新。","options":["把新民主主义革命的开端记为中国共产党成立。","新民主主义革命的开端是五四运动（1919 年）；中国共产党的成立使中国革命的面貌焕然一新。","新文化运动是**中国近代史上一次伟大的思想解放运动**：它动摇了封建道德礼教的统治地位，使中国人民特别是青年知识分子的思想得到极大解放，为马克思主义在中国的传播创造了条件。","五四运动是**中国新民主主义革命的开端**：工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质，促进了马克思主义与中国工人运动的结合。"],"difficulty":2,"tags":["八年级上册","第四单元","本课练习"]},{"id":"h8a-u4-m1-q1","type":"short","stem":"（1）材料一中的「两位先生」指什么？依据材料一并结合所学，说明新文化运动的作用。（5 分）","answer":"「两位先生」指民主与科学。作用：新文化运动动摇了封建道德礼教的统治地位，使中国人民特别是青年知识分子的思想得到极大解放；它提倡白话文，推动了文学革命与文化普及；为马克思主义在中国的传播和五四运动的爆发创造了条件。总起来说，它是一次伟大的思想解放运动。","explain":"","tags":["新文化运动","史料实证"],"rubric":["答出民主与科学","答出动摇封建道德礼教/解放思想","答出为马克思主义传播创造条件","答出是伟大的思想解放运动"]},{"id":"h8a-u4-m1-q2","type":"short","stem":"（2）材料二体现了五四运动的什么精神？结合材料三说明中国共产党成立后中国革命为什么「面貌焕然一新」。（6 分）","answer":"精神：材料二表现出誓死捍卫国家主权、不向侵略者低头的爱国主义精神，即五四精神，其核心是爱国主义（还包括进步、民主、科学）。「焕然一新」的原因：中国共产党以马克思主义为指导思想，有了科学理论的指导；中共一大确定了推翻资产阶级政权、实现共产主义的奋斗目标，中共二大又第一次明确提出彻底的反帝反封建的民主革命纲领，使中国革命有了明确方向；中国共产党代表工人阶级和广大人民利益，能够深入发动群众，从而开辟了与以往一切政治力量都不相同的革命道路。","explain":"","tags":["五四运动","中共成立"],"rubric":["答出爱国主义/五四精神","答出以马克思主义为指导","答出提出彻底的反帝反封建纲领","答出代表人民利益、发动群众","答出中国革命有了坚强领导核心"]}]},{"id":"hp-8a-u5","title":"从国共合作到农村革命根据地的建立 单元测试","subtitle":"八年级上册 · 第五单元","grade":"8a","tags":["八年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8a-u5-q1","type":"choice","stem":"标志国共第一次合作正式建立的事件是","answer":"B","explain":"1924 年 1 月国民党一大召开，把旧三民主义发展为新三民主义，确立联俄、联共、扶助农工三大政策，标志国共第一次合作正式建立。黄埔军校创办是合作的成果。","options":["中共三大的召开","国民党一大在广州召开","黄埔军校创办","北伐战争开始"],"tags":["国共合作","时空观念"]},{"id":"h8a-u5-q3","type":"choice","stem":"1927 年秋收起义受挫后，毛泽东率部队向井冈山进军，其深远意义在于","answer":"B","explain":"秋收起义受挫后转向农村，创建井冈山革命根据地，开辟了农村包围城市、武装夺取政权的道路，这是马克思主义与中国国情相结合的正确道路。","options":["完成了北伐战争的任务","开创了农村包围城市、武装夺取政权的革命道路","促成了国共第二次合作","建立了中华苏维埃共和国"],"tags":["井冈山道路","历史解释"]},{"id":"cat-8a-5-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 国民党一大在广州召开\n② 黄埔军校在广州创办\n③ 国民革命军出师北伐\n④ 四一二反革命政变，南京国民政府成立","answer":"A","explain":"按时间顺序应为：①国民党一大在广州召开（1924 年 1 月）→②黄埔军校在广州创办（1924 年 5 月）→③国民革命军出师北伐（1926 年）→④四一二反革命政变，南京国民政府成立（1927 年 4 月）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-1-g2","type":"choice","stem":"下列关于「国共合作与北伐战争」的表述，错误的是","answer":"A","explain":"认为北伐战争胜利了，国民革命就成功了——「北伐胜利」与「国民革命失败」两句话都对，指向不同层面，材料题常要求分别说明。正确表述：北伐战争取得了胜利进军、基本推翻北洋军阀统治；但 1927 年蒋介石、汪精卫相继叛变革命，国民革命最终失败。","options":["认为北伐战争胜利了，国民革命就成功了。","北伐战争取得了胜利进军、基本推翻北洋军阀统治；但 1927 年蒋介石、汪精卫相继叛变革命，国民革命最终失败。","**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。","第一次国共合作的成果：创办黄埔军校，培养革命军事政治人才；推动北伐战争胜利进军，基本推翻了北洋军阀的统治。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-1-g3","type":"choice","stem":"下列结论中，属于「国共合作与北伐战争」的是","answer":"A","explain":"本课结论：**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。","**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。","**遵义会议是党的历史上生死攸关的转折点**：它在危急关头挽救了党、挽救了红军、挽救了中国革命，是中国共产党从幼年走向成熟的标志。","**长征胜利使中国革命转危为安**：它保存了革命的基干力量，播下了革命种子，为开创抗日战争的新局面奠定了基础。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"h8a-u5-q2","type":"choice","stem":"南昌起义最重要的历史意义是","answer":"B","explain":"1927 年 8 月 1 日南昌起义打响武装反抗国民党反动统治的第一枪，是中国共产党独立领导武装斗争、创建人民军队的开始，故 8 月 1 日为建军节。","options":["建立了第一个农村革命根据地","打响武装反抗国民党反动统治的第一枪，是中国共产党创建人民军队的开始","开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位","使中国革命转危为安"],"tags":["南昌起义","历史解释"]},{"id":"cat-8a-5-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 南昌起义\n② 八七会议与秋收起义\n③ 井冈山会师，成立中国工农红军第四军","answer":"A","explain":"按时间顺序应为：①南昌起义（1927 年 8 月 1 日）→②八七会议与秋收起义（1927 年 8—9 月）→③井冈山会师，成立中国工农红军第四军（1928 年 4 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-2-g2","type":"choice","stem":"下列关于「毛泽东开辟井冈山道路」的表述，错误的是","answer":"A","explain":"把井冈山革命根据地与井冈山会师的时间、意义混在一起——「创建根据地」与「会师建军队」是两件事，时序题常设陷阱。正确表述：1927 年 10 月毛泽东创建井冈山革命根据地（第一个农村革命根据地）；1928 年 4 月井冈山会师成立红四军。","options":["把井冈山革命根据地与井冈山会师的时间、意义混在一起。","1927 年 10 月毛泽东创建井冈山革命根据地（第一个农村革命根据地）；1928 年 4 月井冈山会师成立红四军。","**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。","南昌起义的意义：打响武装反抗国民党反动统治的第一枪，是中国共产党独立领导武装斗争、创建人民军队的开始，8 月 1 日由此成为建军节。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-2-g3","type":"choice","stem":"下列结论中，属于「毛泽东开辟井冈山道路」的是","answer":"A","explain":"本课结论：**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。","**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。","**遵义会议是党的历史上生死攸关的转折点**：它在危急关头挽救了党、挽救了红军、挽救了中国革命，是中国共产党从幼年走向成熟的标志。","**长征胜利使中国革命转危为安**：它保存了革命的基干力量，播下了革命种子，为开创抗日战争的新局面奠定了基础。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"h8a-u5-q4","type":"choice","stem":"被称为「党的历史上生死攸关的转折点」的会议是","answer":"B","explain":"1935 年 1 月遵义会议开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位，在危急关头挽救了党、挽救了红军、挽救了中国革命。","options":["八七会议","遵义会议","中共七大","中共二大"],"tags":["遵义会议","历史解释"]},{"id":"cat-8a-5-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1924 年 5 月创办，全称「中国国民党陆军军官学校」，孙中山任总理，蒋介石任校长，周恩来任政治部主任。（《黄埔军校史料》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"国共合作与北伐战争；第一次国共合作的成果：创办黄埔军校，培养革命军事政治人才；推动北伐战争胜利进军，基本推翻了北洋军阀的统治。","explain":"材料出自《黄埔军校史料》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-5-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1928 年 4 月，朱德、陈毅率南昌起义余部与毛泽东领导的工农革命军在井冈山会师，合编为工农红军第四军。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"毛泽东开辟井冈山道路；南昌起义的意义：打响武装反抗国民党反动统治的第一枪，是中国共产党独立领导武装斗争、创建人民军队的开始，8 月 1 日由此成为建军节。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-8a-u6","title":"中华民族的抗日战争 单元测试","subtitle":"八年级上册 · 第六单元","grade":"8a","tags":["八年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8a-u6-q1","type":"choice","stem":"中国人民抗日战争的起点，也是中国局部抗战开始的事件是","answer":"A","explain":"1931 年九一八事变是中国人民抗日战争的起点，中国人民的局部抗战由此开始；1937 年七七事变标志全民族抗战开始。","options":["九一八事变","华北事变","七七事变","八一三事变"],"tags":["九一八事变","时空观念"]},{"id":"h8a-u6-q2","type":"choice","stem":"西安事变和平解决的最重要意义是","answer":"B","explain":"西安事变的和平解决，标志着十年内战基本结束，抗日民族统一战线初步形成，成为扭转时局的关键。","options":["迫使蒋介石放弃了反共立场","标志十年内战基本结束，抗日民族统一战线初步形成","使红军获得了合法地位","标志抗日战争的胜利"],"tags":["西安事变","历史解释"]},{"id":"cat-8a-6-1-g2","type":"choice","stem":"下列关于「从九一八事变到西安事变」的表述，错误的是","answer":"A","explain":"把「中国人民抗日战争的起点」记为 1937 年七七事变——「起点」与「全民族抗战开始」是两个不同层级的结论，是高频易错点。正确表述：中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","options":["把「中国人民抗日战争的起点」记为 1937 年七七事变。","中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。","**中国共产党是全民族抗战的中流砥柱**：最早举起抗日旗帜、提出全面抗战路线、开辟敌后战场、坚持抗战、反对投降，为抗战胜利作出了决定性贡献。"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-1-g5","type":"choice","stem":"「九一八事变」发生于","answer":"A","explain":"本课时间轴：九一八事变（1931 年 9 月 18 日）。日本关东军炸毁南满铁路柳条湖段并进攻沈阳北大营；中国人民的局部抗战开始，这也是中国人民抗日战争的起点。其余三个时间是同一单元相邻课时的事件时间。","options":["1931 年 9 月 18 日","1936 年 12 月 12 日","1937 年 7 月 7 日","1937 年 12 月 13 日"],"difficulty":1,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 西安事变（双十二事变）\n② 七七事变（卢沟桥事变）\n③ 南京大屠杀","answer":"A","explain":"按时间顺序应为：①西安事变（双十二事变）（1936 年 12 月 12 日）→②七七事变（卢沟桥事变）（1937 年 7 月 7 日）→③南京大屠杀（1937 年 12 月 13 日）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-2-g2","type":"choice","stem":"下列关于「七七事变与全民族抗战」的表述，错误的是","answer":"A","explain":"把「中国人民抗日战争的起点」记为 1937 年七七事变——「起点」与「全民族抗战开始」是两个不同层级的结论，是高频易错点。正确表述：中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","options":["把「中国人民抗日战争的起点」记为 1937 年七七事变。","中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。","西安事变的和平解决：标志着十年内战基本结束，抗日民族统一战线初步形成，成为扭转时局的关键。"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"h8a-u6-q3","type":"choice","stem":"下列战役中，属于抗战以来中国正面战场取得的最大一场胜仗的是","answer":"B","explain":"1938 年台儿庄战役由李宗仁指挥，歼敌 1 万余人，是抗战以来中国正面战场取得的最大一场胜仗。平型关大捷与百团大战属于敌后战场的作战。","options":["平型关大捷","台儿庄战役","百团大战","第三次长沙会战"],"tags":["台儿庄战役","时空观念"]},{"id":"cat-8a-6-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 平型关大捷\n② 台儿庄战役\n③ 百团大战","answer":"A","explain":"按时间顺序应为：①平型关大捷（1937 年 9 月）→②台儿庄战役（1938 年 3—4 月）→③百团大战（1940 年下半年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-3-g2","type":"choice","stem":"下列关于「全民族抗战中的正面战场和敌后战场」的表述，错误的是","answer":"A","explain":"把台儿庄战役与百团大战的战场和意义弄反——两个「最大」分别属于不同战场，材料题按「战场—指挥者—意义」三项对应作答。正确表述：台儿庄战役是正面战场取得的最大一场胜仗（李宗仁指挥，国民党军队）；百团大战是敌后战场主动出击日军的最大规模战役（彭德怀指挥，八路军）。","options":["把台儿庄战役与百团大战的战场和意义弄反。","台儿庄战役是正面战场取得的最大一场胜仗（李宗仁指挥，国民党军队）；百团大战是敌后战场主动出击日军的最大规模战役（彭德怀指挥，八路军）。","**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。","**中国共产党是全民族抗战的中流砥柱**：最早举起抗日旗帜、提出全面抗战路线、开辟敌后战场、坚持抗战、反对投降，为抗战胜利作出了决定性贡献。"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-3-g5","type":"choice","stem":"「平型关大捷」发生于","answer":"A","explain":"本课时间轴：平型关大捷（1937 年 9 月）。八路军第 115 师取得的胜利，是全国抗战爆发后中国军队主动出击的第一个大胜仗。其余三个时间是同一单元相邻课时的事件时间。","options":["1937 年 9 月","1931 年 9 月 18 日","1936 年 12 月 12 日","1937 年 7 月 7 日"],"difficulty":1,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：中共从全民族利益出发，主张和平解决，派周恩来等赴西安调停。蒋介石被迫接受停止内战、联共抗日的主张，西安事变和平解决，成为扭转时局的关键。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"从九一八事变到西安事变；九一八事变与局部抗战：日本发动九一八事变侵占东北，中国人民的局部抗战开始；由于蒋介石的不抵抗政策，东北三省沦陷。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h8a-u6-m1-q1","type":"short","stem":"（1）依据材料一，说明毛泽东提出了怎样的抗战主张；结合材料二指出中国共产党为建立抗日民族统一战线作出了哪些努力。（6 分）","answer":"主张：抗日战争必须是全民族的抗战，要广泛发动和依靠人民群众，实行全面抗战路线（《论持久战》还指出抗战是持久战，最后胜利属于中国）。努力：发表国共合作宣言，表示愿为彻底实现三民主义而奋斗；取消推翻国民党政权的暴动政策，取消苏维埃政府，把红军改编为国民革命军，主动作出让步；促成西安事变的和平解决，最终推动国共实现第二次合作，正式建立抗日民族统一战线。","explain":"","tags":["全民族抗战","史料实证"],"rubric":["答出全民族抗战/全面抗战路线","答出发动依靠人民群众","答出发表国共合作宣言、改编红军等让步","答出推动国共第二次合作、建立统一战线"]}]},{"id":"hp-8a-u7","title":"人民解放战争 单元测试","subtitle":"八年级上册 · 第七单元","grade":"8a","tags":["八年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8a-u7-q1","type":"choice","stem":"1945 年毛泽东赴重庆谈判的主要目的是","answer":"A","explain":"毛泽东赴重庆谈判是为了尽一切可能争取和平、避免内战，同时揭穿蒋介石假和平真内战的阴谋，教育人民、争取政治上的主动。","options":["争取和平民主，揭穿蒋介石假和平真内战的阴谋","与国民党共同建立联合政府","争取美国对中共的支持","拖延时间准备内战"],"tags":["重庆谈判","历史解释"]},{"id":"h8a-u7-q2","type":"choice","stem":"全面内战爆发的标志是","answer":"B","explain":"1946 年 6 月，国民党军队 20 多万人进攻中原解放区，标志着全面内战爆发。进攻延安与挺进大别山都发生在 1947 年。","options":["《双十协定》被撕毁","1946 年 6 月国民党军队进攻中原解放区","国民党军队进攻延安","刘邓大军挺进大别山"],"tags":["全面内战","时空观念"]},{"id":"h8a-u7-q3","type":"choice","stem":"揭开了人民解放军战略进攻序幕的事件是","answer":"B","explain":"1947 年夏，刘伯承、邓小平率晋冀鲁豫解放军主力挺进大别山，直接威胁国民党统治中心南京、武汉，揭开了人民解放军战略进攻的序幕。","options":["转战陕北","刘伯承、邓小平率部挺进大别山","辽沈战役开始","渡江战役开始"],"tags":["战略进攻","时空观念"]},{"id":"cat-8a-7-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 重庆谈判\n② 国民党军队进攻中原解放区\n③ 国民党军队重点进攻陕北和山东解放区","answer":"A","explain":"按时间顺序应为：①重庆谈判（1945 年 8—10 月）→②国民党军队进攻中原解放区（1946 年 6 月）→③国民党军队重点进攻陕北和山东解放区（1947 年 3 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第七单元","本课练习"]},{"id":"cat-8a-7-1-g2","type":"choice","stem":"下列关于「国民党挑起内战」的表述，错误的是","answer":"A","explain":"把全面内战爆发的标志记为重庆谈判破裂或《双十协定》被撕毁——《双十协定》后蒋介石仍加紧备战，标志性事件必须是军事进攻，属高频细节。正确表述：1946 年 6 月国民党军队进攻中原解放区，标志着全面内战爆发。","options":["把全面内战爆发的标志记为重庆谈判破裂或《双十协定》被撕毁。","1946 年 6 月国民党军队进攻中原解放区，标志着全面内战爆发。","国民党的失败是必然的：**发动内战不得人心，政治孤立、经济崩溃、失去民心**，其失败证明了「谁代表人民利益，谁就能赢得胜利」。","重庆谈判：蒋介石一面积极准备内战、一面三次电邀毛泽东赴重庆，企图赢得备战时间并把内战责任推给共产党；毛泽东赴重庆谈判是为了尽一切可能争取和平、揭穿蒋介石假和平真内战的阴谋、教育人民。"],"difficulty":2,"tags":["八年级上册","第七单元","本课练习"]},{"id":"h8a-u7-q4","type":"choice","stem":"奠定了解放长江以南各省基础的战役是","answer":"B","explain":"淮海战役以徐州为中心，共歼灭国民党军队 55 万余人，奠定了解放长江以南各省的基础。辽沈战役解放东北全境，平津战役使华北全境基本解放。","options":["辽沈战役","淮海战役","平津战役","渡江战役"],"tags":["淮海战役","时空观念"]},{"id":"h8a-u7-q5","type":"choice","stem":"标志国民党在大陆统治结束的事件是","answer":"B","explain":"1949 年 4 月，人民解放军发起渡江战役，4 月 23 日占领南京，标志国民党在大陆统治的结束。中华人民共和国成立于 1949 年 10 月 1 日。","options":["三大战役的胜利","1949 年 4 月 23 日南京解放","北平和平解放","中华人民共和国成立"],"tags":["渡江战役","时空观念"]},{"id":"cat-8a-7-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中国共产党颁布《中国土地法大纲》\n② 辽沈、淮海、平津三大战役\n③ 渡江战役，4 月 23 日南京解放","answer":"A","explain":"按时间顺序应为：①中国共产党颁布《中国土地法大纲》（1947 年）→②辽沈、淮海、平津三大战役（1948 年 9 月—1949 年 1 月）→③渡江战役，4 月 23 日南京解放（1949 年 4 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第七单元","本课练习"]},{"id":"cat-8a-7-2-g2","type":"choice","stem":"下列关于「人民解放战争的胜利」的表述，错误的是","answer":"A","explain":"把刘邓大军挺进大别山与三大战役的性质混同——「战略进攻」与「战略决战」是两个阶段，材料题常要求排序并说明阶段特征。正确表述：挺进大别山是战略进攻的开始（1947 年夏）；三大战役是战略决战（1948 年 9 月—1949 年 1 月）。","options":["把刘邓大军挺进大别山与三大战役的性质混同。","挺进大别山是战略进攻的开始（1947 年夏）；三大战役是战略决战（1948 年 9 月—1949 年 1 月）。","**得民心者得天下，失民心者失天下**：中国共产党通过土地改革满足了农民的土地要求，赢得人民群众的衷心拥护，这是解放战争迅速胜利的根本原因。","三大战役：辽沈战役（解放东北全境）、淮海战役（以徐州为中心，奠定解放长江以南各省的基础）、平津战役（北平和平解放，傅作义接受和平改编）。三大战役共歼灭和改编国民党军队 150 多万人，国民党军队主力基本被消灭。"],"difficulty":2,"tags":["八年级上册","第七单元","本课练习"]},{"id":"cat-8a-7-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 重庆谈判\n② 国民党军队进攻中原解放区\n③ 国民党军队重点进攻陕北和山东解放区\n④ 刘伯承、邓小平率部挺进大别山","answer":"A","explain":"按时间顺序应为：①重庆谈判（1945 年 8—10 月）→②国民党军队进攻中原解放区（1946 年 6 月）→③国民党军队重点进攻陕北和山东解放区（1947 年 3 月）→④刘伯承、邓小平率部挺进大别山（1947 年夏）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级上册","第七单元","本课练习"]},{"id":"cat-8a-7-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1945 年 8 月 28 日至 10 月 10 日，毛泽东应蒋介石邀请赴重庆谈判，双方签订《政府与中共代表会谈纪要》（《双十协定》），确定和平建国方针。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"国民党挑起内战；重庆谈判：蒋介石一面积极准备内战、一面三次电邀毛泽东赴重庆，企图赢得备战时间并把内战责任推给共产党；毛泽东赴重庆谈判是为了尽一切可能争取和平、揭穿蒋介石假和平真内战的阴谋、教育人民。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第七单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-7-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：辽沈战役（1948 年 9—11 月）、淮海战役（1948 年 11 月—1949 年 1 月）、平津战役（1948 年 11 月—1949 年 1 月），共歼灭和改编国民党军 154 万余人。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"人民解放战争的胜利；三大战役：辽沈战役（解放东北全境）、淮海战役（以徐州为中心，奠定解放长江以南各省的基础）、平津战役（北平和平解放，傅作义接受和平改编）。三大战役共歼灭和改编国民党军队 150 多万人，国民党军队主力基本被消灭。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第七单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-8b-u1","title":"中华人民共和国成立和社会主义制度建立 单元测试","subtitle":"八年级下册 · 第一单元","grade":"8b","tags":["八年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8b-u1-q1","type":"choice","stem":"标志着中国人民从此站起来了、成为国家的主人的历史事件是","answer":"B","explain":"1949 年 10 月 1 日开国大典宣告中华人民共和国中央人民政府成立，中国人民从此站起来了，成为国家的主人。政协会议是成立前的筹备，西藏和平解放与抗美援朝是新中国成立后巩固政权的措施。","options":["中国人民政治协商会议第一届全体会议召开","开国大典，中华人民共和国成立","西藏和平解放","抗美援朝战争取得胜利"],"tags":["新中国成立","时空观念"]},{"id":"h8b-u1-q5","type":"choice","stem":"1949 年 9 月，中国人民政治协商会议第一届全体会议通过的、在 1954 年宪法颁布前起临时宪法作用的文件是","answer":"B","explain":"《共同纲领》是在 1954 年宪法颁布前起临时宪法作用的文件；1954 年宪法是我国第一部社会主义类型的宪法；《土地改革法》是 1950 年颁布的。","options":["《中华民国临时约法》","《中国人民政治协商会议共同纲领》","《中华人民共和国宪法》","《中华人民共和国土地改革法》"],"tags":["共同纲领","史料实证"]},{"id":"cat-8b-1-1-g2","type":"choice","stem":"下列关于「中华人民共和国成立」的表述，错误的是","answer":"A","explain":"把《共同纲领》说成 1954 年宪法——「起临时宪法作用的文件」不等于「宪法」，这是两句不同的话。正确表述：1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","options":["把《共同纲领》说成 1954 年宪法。","1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利，中国人民从此站起来了，成为国家的主人，中国历史从此揭开了新的篇章。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-1-1-g5","type":"choice","stem":"「中国人民政治协商会议第一届全体会议在北平召开」发生于","answer":"A","explain":"本课时间轴：中国人民政治协商会议第一届全体会议在北平召开（1949 年 9 月）。通过《中国人民政治协商会议共同纲领》，起临时宪法作用；决定国旗为五星红旗、以《义勇军进行曲》为代国歌、首都为北京、采用公元纪年。其余三个时间是同一单元相邻课时的事件时间。","options":["1949 年 9 月","1950 年 6 月","1950 年 10 月","1951 年"],"difficulty":1,"tags":["八年级下册","第一单元","本课练习"]},{"id":"h8b-u1-q2","type":"choice","stem":"1951 年西藏和平解放的重要意义是","answer":"A","explain":"西藏和平解放使祖国大陆获得统一，各族人民实现了大团结。民族区域自治制度在 1954 年宪法中确立为一项基本政治制度；西藏自治区成立于 1965 年；台湾问题尚未解决，不能说「祖国获得完全统一」。","options":["祖国大陆获得统一，各族人民实现大团结","标志着祖国获得完全统一","标志着民族区域自治制度正式确立","西藏自治区正式成立"],"tags":["西藏和平解放","时空观念"]},{"id":"h8b-u1-q4","type":"choice","stem":"1950—1952 年底土地改革完成后，我国农村土地的所有权状况是","answer":"D","explain":"土地改革废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，土地归农民私有。土地归集体所有是 1953—1956 年农业合作化的结果。","options":["归国家所有","归集体所有","归地主与农民共同所有","归农民所有"],"tags":["土地改革","历史解释"]},{"id":"h8b-u1-q6","type":"choice","stem":"抗美援朝战争的胜利对中国最主要的影响是","answer":"D","explain":"抗美援朝战争的胜利打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。中国进入社会主义社会以 1956 年三大改造基本完成为标志，结束半殖民地半封建社会历史以新中国成立为标志。","options":["使中国完成了国家统一","使中国从此进入社会主义社会","结束了半殖民地半封建社会的历史","打破了美军不可战胜的神话，大大提高了我国的国际地位"],"tags":["抗美援朝","历史解释"]},{"id":"cat-8b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中央人民政府颁布《中华人民共和国土地改革法》，土…\n② 中国人民志愿军开赴朝鲜，抗美援朝战争开始\n③ 西藏和平解放\n④ 全国大陆基本上完成土地改革","answer":"A","explain":"按时间顺序应为：①中央人民政府颁布《中华人民共和国土地改革法》，土地改革在全国展开（1950 年 6 月）→②中国人民志愿军开赴朝鲜，抗美援朝战争开始（1950 年 10 月）→③西藏和平解放（1951 年）→④全国大陆基本上完成土地改革（1952 年底）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-1-2-g2","type":"choice","stem":"下列关于「巩固人民民主政权」的表述，错误的是","answer":"A","explain":"把抗美援朝战争开始的时间记成 1953 年——1950 年是「出兵」，1953 年是「停战」，两个时间点最容易被调换。正确表述：1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","options":["把抗美援朝战争开始的时间记成 1953 年。","1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。","土地改革彻底摧毁了在我国延续两千多年的封建土地制度，消灭了地主阶级，农民成为土地的主人，解放了农村生产力，为国家工业化建设准备了条件。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"h8b-u2-q2","type":"choice","stem":"1954 年《中华人民共和国宪法》的历史地位是","answer":"D","explain":"1954 年宪法是我国第一部社会主义类型的宪法，也是我国有史以来真正反映人民利益的宪法；起临时宪法作用的文件是 1949 年的《共同纲领》。","options":["我国第一部宪法性质的临时文件","我国第一部资产阶级民主主义宪法","我国第一部民族区域自治法","我国第一部社会主义类型的宪法"],"tags":["1954 年宪法","历史解释"]},{"id":"cat-8b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：五星红旗由曾联松设计；《义勇军进行曲》由田汉作词、聂耳作曲，原为电影《风云儿女》主题歌，1949 年被定为代国歌。（《中华人民共和国史》；2024 部编版八下第 1 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"中华人民共和国成立；1949 年 10 月 1 日的开国大典，标志着中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利。","explain":"材料出自《中华人民共和国史》；2024 部编版八下第 1 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h8b-u1-m1-q2","type":"short","stem":"（2）据材料二，土地改革废除的是什么制度、实行的是什么制度？据材料三并结合所学，说明土地改革的作用。（6 分）","answer":"废除地主阶级封建剥削的土地所有制，实行农民的土地所有制。作用：彻底摧毁了我国延续两千多年的封建土地制度，消灭了地主阶级；农民翻了身，成为土地的主人，人民政权更加巩固；大大解放了农村生产力，农业生产迅速恢复和发展，为国家工业化建设准备了条件。","explain":"","tags":["土地改革","历史解释"],"rubric":["答出「废除地主阶级封建剥削的土地所有制」","答出「实行农民的土地所有制」","答出「摧毁封建土地制度、消灭地主阶级」","答出「农民成为土地的主人／巩固人民政权」","答出「解放农村生产力／为国家工业化准备条件」"]}]},{"id":"hp-8b-u2","title":"社会主义建设道路的探索 单元测试","subtitle":"八年级下册 · 第二单元","grade":"8b","tags":["八年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8b-u2-q4","type":"choice","stem":"被称为「探索建设社会主义道路的良好开端」的会议是","answer":"D","explain":"1956 年召开的中共八大正确分析了国内主要矛盾，提出集中力量发展社会生产力，是探索建设社会主义道路的良好开端。","options":["中共七大","第一届全国人民代表大会","中共十一届三中全会","中共八大"],"tags":["中共八大","历史解释"]},{"id":"h8b-u2-q5","type":"choice","stem":"「大跃进」和人民公社化运动给我们的最主要教训是","answer":"C","explain":"这两次失误反映了人民群众迫切改变落后面貌的愿望，但急于求成、忽视客观经济规律，造成 1959—1961 年国民经济严重困难。教训是必须从国情出发、实事求是、按客观经济规律办事。","options":["必须以阶级斗争为纲","必须优先发展重工业","必须从国情出发，按客观经济规律办事","必须加快生产资料公有化的速度"],"tags":["大跃进","唯物史观"]},{"id":"cat-8b-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 「大跃进」和农村人民公社化运动在全国展开\n② 实行「调整、巩固、充实、提高」的八字方针，调整国…\n③ 「文化大革命」","answer":"A","explain":"按时间顺序应为：①「大跃进」和农村人民公社化运动在全国展开（1958 年）→②实行「调整、巩固、充实、提高」的八字方针，调整国民经济（1961—1965 年）→③「文化大革命」（1966—1976 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"cat-8b-2-1-g2","type":"choice","stem":"下列关于「艰辛探索与曲折发展」的表述，错误的是","answer":"A","explain":"认为「大跃进」和人民公社化运动是成功的探索——材料题要求「谈谈认识」，落脚点是「尊重客观经济规律、实事求是」，不能一味肯定。正确表述：它们是党在探索社会主义建设道路过程中的严重失误，忽视了客观经济规律，人民公社化运动还严重挫伤了农民的生产积极性。","options":["认为「大跃进」和人民公社化运动是成功的探索。","它们是党在探索社会主义建设道路过程中的严重失误，忽视了客观经济规律，人民公社化运动还严重挫伤了农民的生产积极性。","1956 年底三大改造基本完成，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段；社会主义制度的建立是中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础。","第一个五年计划的超额完成，使我国开始改变工业落后的面貌，向社会主义工业化迈进。"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"h8b-u2-q6","type":"choice","stem":"在社会主义建设的火热年代，被誉为「党的好干部」、带领兰考人民治理内涝风沙盐碱的是","answer":"D","explain":"焦裕禄任河南兰考县委书记，带领群众治理内涝、风沙、盐碱，被誉为「党的好干部」。王进喜是大庆石油会战中的「铁人」，雷锋被誉为「解放军好战士」。","options":["王进喜","雷锋","邓稼先","焦裕禄"],"tags":["模范人物","家国情怀"]},{"id":"cat-8b-2-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 第一个五年计划开始执行\n② 第一届全国人民代表大会第一次会议在北京召开，通过…\n③ 对农业、手工业和资本主义工商业的社会主义改造基本…\n④ 中国共产党第八次全国代表大会召开","answer":"A","explain":"按时间顺序应为：①第一个五年计划开始执行（1953 年）→②第一届全国人民代表大会第一次会议在北京召开，通过《中华人民共和国宪法》（1954 年 9 月）→③对农业、手工业和资本主义工商业的社会主义改造基本完成（1956 年底）→④中国共产党第八次全国代表大会召开（1956 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"cat-8b-2-2-g2","type":"choice","stem":"下列关于「社会主义建设的巨大成就和先锋模范」的表述，错误的是","answer":"A","explain":"把《共同纲领》与 1954 年宪法混为一谈——两者都是「宪法类」文件，但性质与地位不同，选择题常并列作选项。正确表述：1949 年《共同纲领》起临时宪法作用；1954 年宪法是我国第一部社会主义类型的宪法，以根本法形式确定了人民代表大会制度。","options":["把《共同纲领》与 1954 年宪法混为一谈。","1949 年《共同纲领》起临时宪法作用；1954 年宪法是我国第一部社会主义类型的宪法，以根本法形式确定了人民代表大会制度。","1956 年底三大改造基本完成，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段；社会主义制度的建立是中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础。","第一个五年计划的超额完成，使我国开始改变工业落后的面貌，向社会主义工业化迈进。"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"cat-8b-2-2-g5","type":"choice","stem":"「第一个五年计划开始执行」发生于","answer":"A","explain":"本课时间轴：第一个五年计划开始执行（1953 年）。集中主要力量发展重工业，到 1957 年底超额完成。其余三个时间是同一单元相邻课时的事件时间。","options":["1953 年","1958 年","1961—1965 年","1966—1976 年"],"difficulty":1,"tags":["八年级下册","第二单元","本课练习"]},{"id":"h8b-u5-q4","type":"choice","stem":"中美关系开始走向正常化的标志是","answer":"B","explain":"1972 年 2 月尼克松访华，中美双方签署《联合公报》，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","options":["1971 年基辛格秘密访华","1972 年尼克松访华，中美双方签署《联合公报》","1972 年中日两国正式建立外交关系","1979 年中美正式建立外交关系"],"tags":["中美关系","时空观念"]},{"id":"h8b-u5-q5","type":"choice","stem":"1972 年中日两国正式建立外交关系，其直接推动因素是","answer":"B","explain":"1972 年中美关系开始走向正常化，直接推动了中日建交。中国恢复联合国合法席位（1971 年）有利于打开外交新局面，但不是中日建交的直接推动因素。","options":["中国恢复在联合国的合法席位","中美关系开始走向正常化","万隆会议的召开","和平共处五项原则的提出"],"tags":["中日建交","历史解释"]},{"id":"h8b-u2-m1-q2","type":"short","stem":"（2）材料二反映了什么历史现象？结合材料三，说明这一现象与中共八大召开的内在联系。（6 分）","answer":"材料二反映了 1956 年底我国基本完成了对农业、手工业和资本主义工商业的社会主义改造。联系：三大改造的完成，实现了生产资料私有制向社会主义公有制的转变，社会主义基本制度在我国建立起来，我国进入社会主义初级阶段；在这一基础上，中共八大正确分析了国内主要矛盾的变化，指出党和人民的主要任务是集中力量把我国尽快地从落后的农业国变为先进的工业国，成为探索建设社会主义道路的良好开端。","explain":"","tags":["三大改造","中共八大"],"rubric":["答出「三大改造基本完成」","答出「生产资料私有制向公有制转变／社会主义基本制度建立」","答出「我国进入社会主义初级阶段」","答出八大正确分析主要矛盾","答出八大的地位：良好开端"]},{"id":"cat-8b-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1961 年中共八届九中全会确定「调整、巩固、充实、提高」方针，国民经济逐步恢复。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"艰辛探索与曲折发展；中共八大（1956 年）指出，国内的主要矛盾是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾；党和人民的主要任务是集中力量把我国尽快地从落后的农业国变为先进的工业国。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-8b-u3","title":"改革开放与中国特色社会主义的开创 单元测试","subtitle":"八年级下册 · 第三单元","grade":"8b","tags":["八年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8b-u3-q1","type":"choice","stem":"中共十一届三中全会之所以被称为「新中国成立以来党的历史上具有深远意义的伟大转折」，主要是因为它","answer":"B","explain":"十一届三中全会冲破长期「左」的错误的严重束缚，确定解放思想、实事求是的指导方针，把工作中心转移到经济建设上来、实行改革开放，开启了改革开放和社会主义现代化建设新时期。建立社会主义市场经济体制的目标由 1992 年中共十四大提出。","options":["确立了毛泽东思想的指导地位","作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策","提出了建立社会主义市场经济体制的目标","宣布我国进入社会主义初级阶段"],"tags":["十一届三中全会","历史解释"]},{"id":"cat-8b-3-1-g2","type":"choice","stem":"下列关于「伟大的历史转折」的表述，错误的是","answer":"A","explain":"把十一届三中全会的意义说成「标志我国进入社会主义社会」——两个时间点、两种表述，是选择题最常见的错项组合。正确表述：我国进入社会主义初级阶段以 1956 年三大改造基本完成为标志；十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折。","options":["把十一届三中全会的意义说成「标志我国进入社会主义社会」。","我国进入社会主义初级阶段以 1956 年三大改造基本完成为标志；十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","中共十一届三中全会的伟大转折：冲破长期「左」的错误的严重束缚，确定了解放思想、实事求是的指导方针；停止使用「以阶级斗争为纲」的口号，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策；实际上形成了以邓小平为核心的党的第二代中央领导集体。"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-3-1-g5","type":"choice","stem":"「中共十一届三中全会召开」发生于","answer":"A","explain":"本课时间轴：中共十一届三中全会召开（1978 年 12 月）。确定解放思想、实事求是的指导方针，把党和国家工作中心转移到经济建设上来，实行改革开放。其余三个时间是同一单元相邻课时的事件时间。","options":["1978 年 12 月","1978 年冬","1980 年","1984 年"],"difficulty":1,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-3-1-g6","type":"choice","stem":"下列考点中，属于「伟大的历史转折」的是","answer":"A","explain":"本课考点（重点）：中共十一届三中全会的伟大转折：冲破长期「左」的错误的严重束缚，确定了解放思想、实事求是的指导方针；停止使用「以阶级斗争为纲」的口号，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策；实际上形成了以邓小平为核心的党的第二代中央领导集体。其余三项是同一单元相邻课时的考点。","options":["中共十一届三中全会的伟大转折：冲破长期「左」的错误的严重束缚，确定了解放思想、实事求是的…","家庭联产承包责任制：在土地公有制的基础上，把土地长期承包给各家各户使用，实行家庭经营、自…","经济特区与对外开放格局：1980 年设立深圳、珠海、汕头、厦门四个经济特区，1988 年…","1992 年邓小平南方谈话与中共十四大：南方谈话进一步解放思想，强调「发展才是硬道理」，…"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]},{"id":"h8b-u3-q2","type":"choice","stem":"实行家庭联产承包责任制后，我国农村土地的所有权和经营权状况是","answer":"C","explain":"家庭联产承包责任制是在土地公有制的基础上改变经营管理方式，土地所有权仍归集体，农民通过承包获得经营权和收益，因而不是土地私有化。","options":["土地所有权和经营权都归农民","土地所有权归国家，经营权归农民","土地所有权归集体，农民获得承包经营权","土地所有权归农民，经营权归集体"],"tags":["家庭联产承包责任制","历史解释"]},{"id":"h8b-u3-q4","type":"choice","stem":"1980 年我国设立的经济特区中，被称为对外开放「窗口」的是","answer":"C","explain":"1980 年我国设立深圳、珠海、汕头、厦门四个经济特区，其中深圳从边陲小镇迅速发展为现代化城市，成为经济特区的代表和对外开放的「窗口」。","options":["珠海","汕头","深圳","厦门"],"tags":["经济特区","时空观念"]},{"id":"cat-8b-3-2-g2","type":"choice","stem":"下列关于「改革开放的起步」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","家庭联产承包责任制是在坚持土地公有制的前提下改变经营管理方式，没有改变土地公有性质，也不是土地私有化。","家庭联产承包责任制：在土地公有制的基础上，把土地长期承包给各家各户使用，实行家庭经营、自负盈亏。它激发了农民的劳动热情，带来农村生产力的大解放，农业生产和农民收入均有很大提高。"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-3-2-g5","type":"choice","stem":"「安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏」发生于","answer":"A","explain":"本课时间轴：安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏（1978 年冬）。家庭联产承包责任制由此逐步推广到全国农村。其余三个时间是同一单元相邻课时的事件时间。","options":["1978 年冬","1978 年 12 月","1984 年","1992 年"],"difficulty":1,"tags":["八年级下册","第三单元","本课练习"]},{"id":"h8b-u3-q3","type":"choice","stem":"明确提出建立社会主义市场经济体制目标的会议是","answer":"D","explain":"1992 年中共十四大明确提出建立社会主义市场经济体制的目标。同年邓小平南方谈话指出计划和市场都是经济手段，为这一目标提供了思想基础。","options":["中共十二大","中共十三大","中共十五大","中共十四大"],"tags":["十四大","时空观念"]},{"id":"cat-8b-3-3-g2","type":"choice","stem":"下列关于「改革开放和社会主义现代化建设的全…」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-3-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"伟大的历史转折；中共十一届三中全会的伟大转折：冲破长期「左」的错误的严重束缚，确定了解放思想、实事求是的指导方针；停止使用「以阶级斗争为纲」的口号，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策；实际上形成了以邓小平为核心的党的第二代中央领导集体。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-3-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1978 年 11 月，小岗村 18 户农民按下红手印，约定「交够国家的，留足集体的，剩下都是自己的」，拉开农村改革序幕。（《中国共产党简史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"改革开放的起步；家庭联产承包责任制：在土地公有制的基础上，把土地长期承包给各家各户使用，实行家庭经营、自负盈亏。它激发了农民的劳动热情，带来农村生产力的大解放，农业生产和农民收入均有很大提高。","explain":"材料出自《中国共产党简史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-8b-u4","title":"中国特色社会主义迈向21世纪 单元测试","subtitle":"八年级下册 · 第四单元","grade":"8b","tags":["八年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8b-u3-q1","type":"choice","stem":"中共十一届三中全会之所以被称为「新中国成立以来党的历史上具有深远意义的伟大转折」，主要是因为它","answer":"B","explain":"十一届三中全会冲破长期「左」的错误的严重束缚，确定解放思想、实事求是的指导方针，把工作中心转移到经济建设上来、实行改革开放，开启了改革开放和社会主义现代化建设新时期。建立社会主义市场经济体制的目标由 1992 年中共十四大提出。","options":["确立了毛泽东思想的指导地位","作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策","提出了建立社会主义市场经济体制的目标","宣布我国进入社会主义初级阶段"],"tags":["十一届三中全会","历史解释"]},{"id":"h8b-u3-q3","type":"choice","stem":"明确提出建立社会主义市场经济体制目标的会议是","answer":"D","explain":"1992 年中共十四大明确提出建立社会主义市场经济体制的目标。同年邓小平南方谈话指出计划和市场都是经济手段，为这一目标提供了思想基础。","options":["中共十二大","中共十三大","中共十五大","中共十四大"],"tags":["十四大","时空观念"]},{"id":"cat-8b-4-1-g2","type":"choice","stem":"下列关于「加快改革开放和社会主义现代化建设…」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-4-1-g7","type":"choice","stem":"关于「加快改革开放和社会主义现代化建设…」，下列表述正确的有\n① 中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开…\n② 改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中…\n③ 只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色…\n④ 认为家庭联产承包责任制是把土地分给农民个人所有。","answer":"A","explain":"①②③均取本课必背结论与考点；④错误——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」，正确表述应为：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["八年级下册","第四单元","本课练习"]},{"id":"h8b-u6-q6","type":"choice","stem":"改革开放以来我国人民生活水平大幅提高的根本原因是","answer":"C","explain":"社会生活变迁的根本原因是改革开放促进经济发展、生产力水平提高，为改善人民生活提供了物质基础；消费观念变化、科技进步是重要原因而非根本原因。","options":["人们消费观念的变化","科技进步改变了生活方式","改革开放促进了经济发展和生产力提高","国外商品大量进入中国市场"],"tags":["社会生活变迁","唯物史观"]},{"id":"cat-8b-4-2-g2","type":"choice","stem":"下列关于「中国特色社会主义事业取得新成就」的表述，错误的是","answer":"A","explain":"认为袁隆平培育成功籼型杂交水稻是在 20 世纪 90 年代——时间与人物必须一并记牢，材料题常以此考查「科技成就的年代定位」。正确表述：1973 年袁隆平成功培育出籼型杂交水稻，他被称为「杂交水稻之父」。","options":["认为袁隆平培育成功籼型杂交水稻是在 20 世纪 90 年代。","1973 年袁隆平成功培育出籼型杂交水稻，他被称为「杂交水稻之父」。","民族区域自治制度是我国的一项基本政治制度，保障了少数民族当家作主的权利，维护了民族团结和国家统一，为实现各民族共同繁荣奠定了基础。","「两弹一星」的研制成功，打破了帝国主义的核垄断，增强了我国的国防实力，极大提高了我国的国际地位；科技创新是综合国力竞争的决定性因素。"],"difficulty":2,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-4-2-g5","type":"choice","stem":"「中国政府对澳门恢复行使主权，澳门特别行政区成立」发生于","answer":"A","explain":"本课时间轴：中国政府对澳门恢复行使主权，澳门特别行政区成立（1999 年 12 月 20 日）。标志着中国人民在完成祖国统一大业的道路上又迈出了重要一步。其余三个时间是同一单元相邻课时的事件时间。","options":["1999 年 12 月 20 日","1992 年","1997 年","1964 年 10 月"],"difficulty":1,"tags":["八年级下册","第四单元","本课练习"]},{"id":"h8b-u5-q3","type":"choice","stem":"关于 1971 年中国在联合国合法席位的表述，正确的是","answer":"C","explain":"中国是联合国创始会员国和安理会常任理事国，1971 年第 26 届联大是「恢复」中华人民共和国在联合国的一切合法权利，并把台湾当局的代表驱逐出去。","options":["中国在这一年加入联合国","中国在这一年成为联合国安理会非常任理事国","第 26 届联大恢复中华人民共和国在联合国的一切合法权利","中国在这一年恢复了世界贸易组织成员地位"],"tags":["恢复联合国合法席位","历史解释"]},{"id":"h8b-u5-q4","type":"choice","stem":"中美关系开始走向正常化的标志是","answer":"B","explain":"1972 年 2 月尼克松访华，中美双方签署《联合公报》，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","options":["1971 年基辛格秘密访华","1972 年尼克松访华，中美双方签署《联合公报》","1972 年中日两国正式建立外交关系","1979 年中美正式建立外交关系"],"tags":["中美关系","时空观念"]},{"id":"h8b-u5-q5","type":"choice","stem":"1972 年中日两国正式建立外交关系，其直接推动因素是","answer":"B","explain":"1972 年中美关系开始走向正常化，直接推动了中日建交。中国恢复联合国合法席位（1971 年）有利于打开外交新局面，但不是中日建交的直接推动因素。","options":["中国恢复在联合国的合法席位","中美关系开始走向正常化","万隆会议的召开","和平共处五项原则的提出"],"tags":["中日建交","历史解释"]},{"id":"cat-8b-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1997 年 9 月在北京召开，把邓小平理论确立为党的指导思想，提出社会主义初级阶段的基本纲领。（中共十五大报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"加快改革开放和社会主义现代化建设步伐；1992 年邓小平南方谈话与中共十四大：南方谈话进一步解放思想，强调「发展才是硬道理」，指出计划和市场都是经济手段；中共十四大明确提出建立社会主义市场经济体制的目标。","explain":"材料出自中共十五大报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h8b-u6-m1-q2","type":"short","stem":"（2）据材料二、三，说明科技进步与人民生活变化的关系，并分析改革开放后人民生活水平提高的原因。（6 分）","answer":"关系：科技进步推动生产力发展，为改善人民生活提供物质基础；科技成就（如杂交水稻、青蒿素）直接造福人民、保障人民健康，科技进步也改变了人们的出行与通信方式。原因：①实行改革开放，经济快速发展，生产力水平提高，这是根本原因；②实行家庭联产承包责任制等经济体制改革，调动了生产积极性；③科技进步与商品供应日益丰富；④国家重视改善民生，人民生活水平和消费观念不断变化。","explain":"","tags":["社会生活变迁","历史解释"],"rubric":["答出「科技进步推动生产力发展、提供物质基础」","答出「科技成就直接造福人民健康／改变生活方式」","答出「改革开放、经济发展是根本原因」","答出「经济体制改革调动生产积极性」","答出「消费观念变化／国家重视民生」"]}]},{"id":"hp-8b-u5","title":"在新形势下坚持和发展中国特色社会主义 单元测试","subtitle":"八年级下册 · 第五单元","grade":"8b","tags":["八年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8b-u3-q1","type":"choice","stem":"中共十一届三中全会之所以被称为「新中国成立以来党的历史上具有深远意义的伟大转折」，主要是因为它","answer":"B","explain":"十一届三中全会冲破长期「左」的错误的严重束缚，确定解放思想、实事求是的指导方针，把工作中心转移到经济建设上来、实行改革开放，开启了改革开放和社会主义现代化建设新时期。建立社会主义市场经济体制的目标由 1992 年中共十四大提出。","options":["确立了毛泽东思想的指导地位","作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策","提出了建立社会主义市场经济体制的目标","宣布我国进入社会主义初级阶段"],"tags":["十一届三中全会","历史解释"]},{"id":"h8b-u3-q2","type":"choice","stem":"实行家庭联产承包责任制后，我国农村土地的所有权和经营权状况是","answer":"C","explain":"家庭联产承包责任制是在土地公有制的基础上改变经营管理方式，土地所有权仍归集体，农民通过承包获得经营权和收益，因而不是土地私有化。","options":["土地所有权和经营权都归农民","土地所有权归国家，经营权归农民","土地所有权归集体，农民获得承包经营权","土地所有权归农民，经营权归集体"],"tags":["家庭联产承包责任制","历史解释"]},{"id":"h8b-u3-q3","type":"choice","stem":"明确提出建立社会主义市场经济体制目标的会议是","answer":"D","explain":"1992 年中共十四大明确提出建立社会主义市场经济体制的目标。同年邓小平南方谈话指出计划和市场都是经济手段，为这一目标提供了思想基础。","options":["中共十二大","中共十三大","中共十五大","中共十四大"],"tags":["十四大","时空观念"]},{"id":"cat-8b-5-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中共十一届三中全会召开\n② 安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏\n③ 深圳、珠海、汕头、厦门设立经济特区\n④ 开放大连、天津、青岛、上海、广州等 14 个沿海…","answer":"A","explain":"按时间顺序应为：①中共十一届三中全会召开（1978 年 12 月）→②安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏（1978 年冬）→③深圳、珠海、汕头、厦门设立经济特区（1980 年）→④开放大连、天津、青岛、上海、广州等 14 个沿海港口城市（1984 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-5-1-g2","type":"choice","stem":"下列关于「开始全面建设小康社会」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"h8b-u3-q5","type":"choice","stem":"2021 年我国取得的重大成就是","answer":"D","explain":"2021 年中国共产党成立 100 周年，我国全面建成小康社会，历史性地解决了绝对贫困问题，实现了第一个百年奋斗目标。加入世界贸易组织是 2001 年，建成社会主义现代化强国是本世纪中叶的目标。","options":["加入世界贸易组织","建成社会主义现代化强国","基本实现社会主义现代化","全面建成小康社会，实现第一个百年奋斗目标"],"tags":["新时代","家国情怀"]},{"id":"h8b-u3-q6","type":"choice","stem":"把习近平新时代中国特色社会主义思想确立为党的指导思想的会议是","answer":"B","explain":"2017 年中共十九大把习近平新时代中国特色社会主义思想确立为党的指导思想；中共十八大以来，中国特色社会主义进入新时代；中共二十大提出以中国式现代化全面推进中华民族伟大复兴。","options":["中共十八大","中共十九大","中共二十大","中共十八届三中全会"],"tags":["中共十九大","理论体系"]},{"id":"cat-8b-5-2-g2","type":"choice","stem":"下列关于「夺取全面建设小康社会新胜利」的表述，错误的是","answer":"A","explain":"认为我国已经建成社会主义现代化强国——「全面建成小康社会」与「全面建成社会主义现代化强国」阶段不同，表述不能互换。正确表述：2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","options":["认为我国已经建成社会主义现代化强国。","2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-5-2-g7","type":"choice","stem":"关于「夺取全面建设小康社会新胜利」，下列表述正确的有\n① 中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开…\n② 改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中…\n③ 只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色…\n④ 认为我国已经建成社会主义现代化强国。","answer":"A","explain":"①②③均取本课必背结论与考点；④错误——「全面建成小康社会」与「全面建成社会主义现代化强国」阶段不同，表述不能互换，正确表述应为：2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["八年级下册","第五单元","本课练习"]},{"id":"h8b-u5-q4","type":"choice","stem":"中美关系开始走向正常化的标志是","answer":"B","explain":"1972 年 2 月尼克松访华，中美双方签署《联合公报》，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","options":["1971 年基辛格秘密访华","1972 年尼克松访华，中美双方签署《联合公报》","1972 年中日两国正式建立外交关系","1979 年中美正式建立外交关系"],"tags":["中美关系","时空观念"]},{"id":"cat-8b-5-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：十六大提出，要在本世纪头二十年，集中力量全面建设惠及十几亿人口的更高水平的小康社会。（中共十六大报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"开始全面建设小康社会；中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"材料出自中共十六大报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-5-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼顾。（中共十八大报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"夺取全面建设小康社会新胜利；中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"材料出自中共十八大报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-8b-u6","title":"中国特色社会主义进入新时代 单元测试","subtitle":"八年级下册 · 第六单元","grade":"8b","tags":["八年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 7 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8b-u3-q6","type":"choice","stem":"把习近平新时代中国特色社会主义思想确立为党的指导思想的会议是","answer":"B","explain":"2017 年中共十九大把习近平新时代中国特色社会主义思想确立为党的指导思想；中共十八大以来，中国特色社会主义进入新时代；中共二十大提出以中国式现代化全面推进中华民族伟大复兴。","options":["中共十八大","中共十九大","中共二十大","中共十八届三中全会"],"tags":["中共十九大","理论体系"]},{"id":"cat-8b-6-1-g2","type":"choice","stem":"下列关于「擘画中国梦宏伟蓝图」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。","中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。"],"difficulty":2,"tags":["八年级下册","第六单元","本课练习"]},{"id":"cat-8b-6-1-g5","type":"choice","stem":"「中共十八大召开」发生于","answer":"A","explain":"本课时间轴：中共十八大召开（2012 年）。十八大以来，中国特色社会主义进入新时代。其余三个时间是同一单元相邻课时的事件时间。","options":["2012 年","2017 年","2021 年","2022 年"],"difficulty":1,"tags":["八年级下册","第六单元","本课练习"]},{"id":"cat-8b-6-1-g7","type":"choice","stem":"关于「擘画中国梦宏伟蓝图」，下列表述正确的有\n① 改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中…\n② 中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要…\n③ 中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表…\n④ 认为家庭联产承包责任制是把土地分给农民个人所有。","answer":"A","explain":"①②③均取本课必背结论与考点；④错误——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」，正确表述应为：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["八年级下册","第六单元","本课练习"]},{"id":"h8b-u3-q5","type":"choice","stem":"2021 年我国取得的重大成就是","answer":"D","explain":"2021 年中国共产党成立 100 周年，我国全面建成小康社会，历史性地解决了绝对贫困问题，实现了第一个百年奋斗目标。加入世界贸易组织是 2001 年，建成社会主义现代化强国是本世纪中叶的目标。","options":["加入世界贸易组织","建成社会主义现代化强国","基本实现社会主义现代化","全面建成小康社会，实现第一个百年奋斗目标"],"tags":["新时代","家国情怀"]},{"id":"cat-8b-6-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中共十八大召开\n② 中共十九大召开，把习近平新时代中国特色社会主义思…\n③ 中国共产党成立 100 周年，我国全面建成小康社…\n④ 中共二十大召开","answer":"A","explain":"按时间顺序应为：①中共十八大召开（2012 年）→②中共十九大召开，把习近平新时代中国特色社会主义思想确立为党的指导思想（2017 年）→③中国共产党成立 100 周年，我国全面建成小康社会，实现第一个百年奋斗目标（2021 年）→④中共二十大召开（2022 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第六单元","本课练习"]},{"id":"cat-8b-6-2-g2","type":"choice","stem":"下列关于「（课题以新版教材实际编排为准）」的表述，错误的是","answer":"A","explain":"认为我国已经建成社会主义现代化强国——「全面建成小康社会」与「全面建成社会主义现代化强国」阶段不同，表述不能互换。正确表述：2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","options":["认为我国已经建成社会主义现代化强国。","2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。","中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。"],"difficulty":2,"tags":["八年级下册","第六单元","本课练习"]},{"id":"cat-8b-6-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：实现中华民族伟大复兴，是近代以来中华民族最伟大的梦想，基本内涵是国家富强、民族振兴、人民幸福。（习近平《在参观〈复兴之路〉展览时的讲话》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"擘画中国梦宏伟蓝图；中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"材料出自习近平《在参观〈复兴之路〉展览时的讲话》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-6-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：2013 年提出精准扶贫，到 2020 年底，现行标准下 9899 万农村贫困人口全部脱贫，832 个贫困县全部摘帽。（《中国共产党简史》；全国脱贫攻坚总结表彰大会）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"（课题以新版教材实际编排为准）；中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"材料出自《中国共产党简史》；全国脱贫攻坚总结表彰大会。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9a-u1","title":"古代亚非文明 单元测试","subtitle":"九年级上册 · 第一单元","grade":"9a","tags":["九年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"h9a-u1-q5","type":"choice","stem":"古埃及金字塔的用途是","answer":"B","explain":"金字塔是古埃及国王的陵墓，其中胡夫金字塔规模最大。它是古埃及文明的象征，反映了古埃及社会经济发展的较高水平和国王的无限权力。","options":["神庙，用于祭祀神灵","国王（法老）的陵墓","天文观测台","抵御外敌的军事堡垒"],"tags":["金字塔","史料实证"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 古埃及初步实现统一\n③ 古埃及大规模修建金字塔（胡夫金字塔规模最大）","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②古埃及初步实现统一（约公元前 3100 年）→③古埃及大规模修建金字塔（胡夫金字塔规模最大）（约公元前 2600 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-1-g2","type":"choice","stem":"下列关于「古代埃及」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》刻写用的文字说成象形文字——两河流域 = 楔形文字，尼罗河流域 = 象形文字，这是最容易被调换的一组搭配。正确表述：《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","options":["把《汉谟拉比法典》刻写用的文字说成象形文字。","《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明**大河流域是早期文明的共同摇篮**。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9a-u1-q2","type":"choice","stem":"迄今已知世界上第一部较为完整的成文法典是","answer":"A","explain":"公元前 18 世纪，古巴比伦王国国王汉谟拉比为维护奴隶主阶级的利益制定了《汉谟拉比法典》，刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。","options":["《汉谟拉比法典》","《十二铜表法》","《罗马民法大全》","《拿破仑法典》"],"tags":["《汉谟拉比法典》","时空观念"]},{"id":"cat-9a-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 两河流域实现初步统一\n③ 汉谟拉比统一两河流域中下游，定都巴比伦","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②两河流域实现初步统一（约公元前 24 世纪）→③汉谟拉比统一两河流域中下游，定都巴比伦（公元前 18 世纪）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g2","type":"choice","stem":"下列关于「古代两河流域」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》说成「世界上第一部成文法典」——限定语是得分点：少了「已知」「较为完整」，就不符合史实——苏美尔人早有成文法，只是不如它完整地保存下来。正确表述：它是「迄今**已知**世界上第一部较为完整的成文法典」。","options":["把《汉谟拉比法典》说成「世界上第一部成文法典」。","它是「迄今**已知**世界上第一部较为完整的成文法典」。","古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","《汉谟拉比法典》刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g3","type":"choice","stem":"下列结论中，属于「古代两河流域」的是","answer":"A","explain":"本课结论：古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明**大河流域是早期文明的共同摇篮**。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。","佛教于公元前 1 世纪（西汉末年）经中亚传入中国，说明**古代亚非文明之间的交流早于新航路开辟**，文明从来不是彼此隔绝的。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9a-u1-q3","type":"choice","stem":"古印度种姓制度中，掌管祭祀、被视为最高等级的是","answer":"A","explain":"种姓制度第一等级是婆罗门，掌管祭祀；第二等级是刹帝利，掌管军政大权；第三等级是吠舍，从事农业、畜牧业和商业；第四等级是首陀罗。","options":["婆罗门","刹帝利","吠舍","首陀罗"],"tags":["种姓制度","历史解释"]},{"id":"cat-9a-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：胡夫金字塔约建于公元前 2600 年，原高约 146 米，底边约 230 米，由约 230 万块巨石砌成，是现存最大的金字塔。（吴于廑、齐世荣《世界史·古代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"古代埃及；金字塔是古埃及国王（法老）的陵墓，是古埃及文明的象征，反映了古埃及社会经济发展的较高水平和国王的无限权力。","explain":"材料出自吴于廑、齐世荣《世界史·古代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h9a-u1-m1-q1","type":"short","stem":"（1）材料一反映出《汉谟拉比法典》具有什么特点？该法典有怎样的历史地位？（4 分）","answer":"特点：实行「同态复仇」原则（以眼还眼、以牙还牙）；对不同社会等级的人处罚标准不同，严格维护奴隶主阶级的利益。历史地位：它是迄今已知世界上第一部较为完整的成文法典，表明人类社会的法制传统源远流长，是古巴比伦王国留给人类的宝贵文化遗产。","explain":"","tags":["《汉谟拉比法典》","史料实证"],"rubric":["答出「同态复仇」或以眼还眼、以牙还牙","答出维护奴隶主阶级利益或等级之间不平等","答出「迄今已知世界上第一部较为完整的成文法典」","答出法制传统源远流长或重要的文化遗产"]}]},{"id":"hp-9a-u2","title":"古代欧洲文明 单元测试","subtitle":"九年级上册 · 第二单元","grade":"9a","tags":["九年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9a-u2-q1","type":"choice","stem":"伯里克利主政时期，雅典的民主政治发展到高峰。雅典民主政治的实质是","answer":"B","explain":"雅典的成年男性公民才有权参加公民大会、担任公职；妇女、奴隶和外邦人被排斥在外，因此它本质上是奴隶主阶级的民主，具有明显的阶级局限性。","options":["全体雅典居民的民主","成年男性公民的民主，即奴隶主阶级的民主","全体自由民的民主","妇女与奴隶同样享有权利的民主"],"tags":["雅典民主","历史解释"]},{"id":"h9a-u2-q4","type":"choice","stem":"对亚历山大东征的评价，最恰当的是","answer":"B","explain":"东征使东方人民饱受掠夺、奴役之苦，但在客观上打通了东西方交通，促进了东西方文化的大交汇，因此要一分为二地评价。C 项是布匿战争的结果，D 项是伯里克利时期的成就。","options":["只是一场侵略战争，没有任何积极作用","给东方人民带来巨大灾难，但客观上促进了东西方文化的大交汇","使罗马成为整个地中海地区的霸主","使希腊的民主政治发展到高峰"],"tags":["亚历山大东征","历史解释"]},{"id":"h9a-u2-q6","type":"choice","stem":"下列希腊罗马古典文化成就与其所属文明的搭配，错误的一项是","answer":"D","explain":"《天方夜谭》（《一千零一夜》）是阿拉伯文学的瑰宝，属于阿拉伯文化，与古罗马无关。儒略历由罗马统治者凯撒命人以古埃及太阳历为蓝本编制。","options":["《荷马史诗》——古希腊","帕特农神庙——古希腊","儒略历——古罗马","《天方夜谭》——古罗马"],"tags":["古典文化","史料实证"]},{"id":"cat-9a-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 罗马城邦在意大利半岛中部的台伯河畔逐渐兴起\n② 希腊出现众多城邦，最著名的是雅典和斯巴达\n③ 伯里克利主政时期，雅典奴隶制民主政治发展到高峰\n④ 亚历山大开始东征","answer":"A","explain":"按时间顺序应为：①罗马城邦在意大利半岛中部的台伯河畔逐渐兴起（约公元前 1000 年）→②希腊出现众多城邦，最著名的是雅典和斯巴达（公元前 8 世纪）→③伯里克利主政时期，雅典奴隶制民主政治发展到高峰（公元前 5 世纪后半期）→④亚历山大开始东征（公元前 334 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-1-g2","type":"choice","stem":"下列关于「希腊城邦和亚历山大帝国」的表述，错误的是","answer":"A","explain":"认为雅典的民主政治是全体雅典居民（或全体自由民）的民主——选择题常把「公民」偷换成「居民」「自由民」。记住：雅典的「公民」是一个有严格条件限制的群体。正确表述：雅典只有成年男性公民享有政治权利；妇女、奴隶、外邦人都被排斥在外。","options":["认为雅典的民主政治是全体雅典居民（或全体自由民）的民主。","雅典只有成年男性公民享有政治权利；妇女、奴隶、外邦人都被排斥在外。","雅典民主政治是**成年男性公民**的民主，是奴隶主阶级的民主，妇女、奴隶、外邦人没有任何政治权利；它既是雅典繁荣的重要原因，也埋下了直接民主容易导致权力滥用的隐患。","希腊是西方文明的**源头**，罗马是希腊文化的**继承者与传播者**，二者共同构成西方古典文明。"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-1-g3","type":"choice","stem":"下列结论中，属于「希腊城邦和亚历山大帝国」的是","answer":"A","explain":"本课结论：雅典民主政治是**成年男性公民**的民主，是奴隶主阶级的民主，妇女、奴隶、外邦人没有任何政治权利；它既是雅典繁荣的重要原因，也埋下了直接民主容易导致权力滥用的隐患。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["雅典民主政治是**成年男性公民**的民主，是奴隶主阶级的民主，妇女、奴隶、外邦人没有任何政治权利；它既是雅典繁荣的重要原因，也埋下了直接民主容易导致权力滥用的隐患。","希腊是西方文明的**源头**，罗马是希腊文化的**继承者与传播者**，二者共同构成西方古典文明。","罗马法的发展体现了「从习惯法到成文法、从公民法到万民法」的进步，是欧洲法学的渊源，对近代欧洲乃至世界法律体系影响深远。","中外联动：公元前 221 年秦朝建立统一的中央集权帝国，同期罗马还在共和国阶段；到公元 2 世纪罗马帝国全盛时，中国正值东汉，两大帝国通过丝绸之路有了间接的经济文化交流（东汉时「大秦王安敦」遣使来华）。"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"h9a-u2-q2","type":"choice","stem":"罗马共和国时期，掌握国家决策权的机构是","answer":"B","explain":"罗马共和国时期，国家统治的决策权掌握在由贵族组成的元老院手中；两名权力相等的执政官主持日常政务，公民大会是形式上的最高权力机关。","options":["执政官","元老院","公民大会","保民官"],"tags":["罗马共和国","历史解释"]},{"id":"h9a-u2-q3","type":"choice","stem":"被称为罗马法制建设第一步、后世罗马法典乃至欧洲法学渊源的文献是","answer":"B","explain":"公元前 450 年左右，罗马颁布了刻在 12 块青铜板上的《十二铜表法》，使量刑定罪有了成文依据，是罗马法制建设的第一步，也是后世罗马法典乃至欧洲法学的渊源。","options":["《汉谟拉比法典》","《十二铜表法》","《罗马民法大全》","《拿破仑法典》"],"tags":["《十二铜表法》","时空观念"]},{"id":"h9a-u2-q5","type":"choice","stem":"公元前 27 年，罗马发生的重要事件是","answer":"B","explain":"公元前 27 年，屋大维开始独揽国家大权，采用「元首制」的统治形式，罗马帝国由此建立。共和国建立是公元前 509 年，帝国分裂是 395 年。","options":["建立共和国","屋大维开始独揽国家大权，罗马帝国建立","帝国分裂为东西两部分","灭掉迦太基"],"tags":["罗马帝国","时空观念"]},{"id":"cat-9a-2-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 罗马城邦在意大利半岛中部的台伯河畔逐渐兴起\n② 罗马建立共和国\n③ 罗马颁布《十二铜表法》\n④ 亚历山大开始东征","answer":"A","explain":"按时间顺序应为：①罗马城邦在意大利半岛中部的台伯河畔逐渐兴起（约公元前 1000 年）→②罗马建立共和国（公元前 509 年）→③罗马颁布《十二铜表法》（公元前 450 年左右）→④亚历山大开始东征（公元前 334 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"h9a-u2-m1-q1","type":"short","stem":"（1）材料一中伯里克利所说的「全体公民」实际上指哪些人？据此说明雅典民主政治的实质。（5 分）","answer":"实际指成年男性公民。雅典的妇女、奴隶和外邦人被排斥在公民之外，没有任何政治权利，不能参加公民大会，也不能担任公职。因此雅典的民主政治只是成年男性公民的民主，是奴隶主阶级的民主，具有明显的阶级性和局限性，而不是全体居民的民主。","explain":"","tags":["雅典民主","史料实证"],"rubric":["答出「成年男性公民」","答出妇女、奴隶、外邦人无权","答出「奴隶主阶级的民主」","答出民主的范围狭小或具有局限性"]},{"id":"h9a-u2-m1-q2","type":"short","stem":"（2）依据材料三，指出亚历山大东征对东西方文化交流产生的影响，并说明应如何全面评价亚历山大东征。（5 分）","answer":"影响：亚历山大东征建立了地跨欧亚非三洲的大帝国，沿途建立的城市成为希腊文化传播的中心，把希腊的雕塑、戏剧、哲学传到东方，也把东方的天文、数学知识带回希腊世界，促进了东西方文化的大交汇。全面评价：一方面，东征是侵略战争，给东方人民带来了巨大灾难（掠夺财富、奴役人民、屠杀反抗者）；另一方面，东征在客观上打通了东西方交通，促进了东西方经济文化的交流，因此要一分为二地评价。","explain":"","tags":["亚历山大东征","历史解释"],"rubric":["答出东征促进东西方文化交汇","答出希腊文化东传或东方文化西传的具体表现","答出东征的侵略性与给东方人民带来的灾难","答出「一分为二」的评价方法"]}]},{"id":"hp-9a-u3","title":"封建时代的欧洲 单元测试","subtitle":"九年级上册 · 第三单元","grade":"9a","tags":["九年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9a-u3-q1","type":"choice","stem":"西欧封君封臣制得以形成的纽带是","answer":"B","explain":"8 世纪前期，法兰克王国改革土地分封形式，不再无偿赏赐土地，受到封地的人必须提供兵役服务，封君封臣制由此形成，其纽带是土地的封赐。","options":["血缘关系","土地的封赐","共同的宗教信仰","军功的大小"],"tags":["封君封臣制","历史解释"]},{"id":"h9a-u3-q6","type":"choice","stem":"843 年查理曼帝国一分为三，后来逐渐形成三个国家的雏形，它们是","answer":"B","explain":"843 年查理曼帝国一分为三，此后逐渐形成德意志、法兰西、意大利三个国家的雏形，这是今日欧洲政治版图的源头之一。","options":["英国、法国、德国","德意志、法兰西、意大利","西班牙、葡萄牙、意大利","英国、荷兰、法国"],"tags":["查理曼帝国","时空观念"]},{"id":"cat-9a-3-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 基督教产生于罗马帝国统治下的巴勒斯坦地区\n② 罗马皇帝将基督教确定为国教\n③ 日耳曼人建立法兰克王国，克洛维是建立者\n④ 法兰克王国改革土地分封形式，实行有条件的土地分封…","answer":"A","explain":"按时间顺序应为：①基督教产生于罗马帝国统治下的巴勒斯坦地区（1 世纪）→②罗马皇帝将基督教确定为国教（4 世纪末）→③日耳曼人建立法兰克王国，克洛维是建立者（481 年）→④法兰克王国改革土地分封形式，实行有条件的土地分封（查理·马特改革）（8 世纪前期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-1-g2","type":"choice","stem":"下列关于「基督教的兴起和法兰克王国」的表述，错误的是","answer":"A","explain":"把西欧封君封臣制与西周分封制完全等同，认为两者都是「层层分封、天子统辖所有诸侯」——两者形式相似、实质不同，比较题必须先分清纽带（土地 / 血缘）与关系特点。正确表述：西欧的封君封臣关系是逐级双向的，有「我的附庸的附庸，不是我的附庸」之说，带契约色彩；西周分封制以血缘宗法为纽带，周天子是天下共主。","options":["把西欧封君封臣制与西周分封制完全等同，认为两者都是「层层分封、天子统辖所有诸侯」。","西欧的封君封臣关系是逐级双向的，有「我的附庸的附庸，不是我的附庸」之说，带契约色彩；西周分封制以血缘宗法为纽带，周天子是天下共主。","中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。","封君封臣制以土地为纽带、以契约为约束，与西周以血缘宗法为纽带的分封制有明显区别，但两者都造成了地方势力的膨胀与王权的相对软弱。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-1-g3","type":"choice","stem":"下列结论中，属于「基督教的兴起和法兰克王国」的是","answer":"A","explain":"本课结论：中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。","城市与大学是中世纪西欧社会的「异质因素」：它们孕育了市民阶层与早期资产阶级，是后来文艺复兴、新航路开辟与资产阶级革命的社会基础。","中外联动：同一时期中国正处于唐宋时期，城市经济繁荣、市民生活丰富，但中国城市始终处在中央集权的行政体系之下，没有像西欧城市那样争取到自治权，这是理解中西历史走向差异的一个重要视角。","拜占庭帝国保存并发展了罗马法，还保存了大量古希腊、古罗马典籍，对东西方文化交流起了桥梁作用；1453 年帝国灭亡后，许多学者携带古典典籍西逃，客观上推动了西欧文艺复兴。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"h9a-u3-q2","type":"choice","stem":"下列关于西欧庄园的表述，正确的是","answer":"B","explain":"西欧庄园是一个独立的自给自足的经济和政治单位，居民有自由农民和缺少自由的农奴；庄园法庭由领主或其管家主持，领主在庄园内拥有较大权力。","options":["庄园以商品经济为主，产品主要面向市场","庄园是一个独立的自给自足的经济和政治单位","庄园完全由国王直接管理，领主没有权力","庄园里的居民全部是自由农民"],"tags":["西欧庄园","历史解释"]},{"id":"h9a-u3-q3","type":"choice","stem":"中世纪西欧城市居民争取自由和自治权最常用的手段是","answer":"A","explain":"城市居民常用的手段是金钱赎买和武力斗争，法国琅城人民起义争取自治就是典型事例。取得自治权的城市，市民可以自由经商、免交赋税、选举市政官员。","options":["金钱赎买和武力斗争","由议会立法授予","向教皇请愿","依靠庄园法庭判决"],"tags":["中世纪城市","历史解释"]},{"id":"h9a-u3-q5","type":"choice","stem":"被称为「中世纪最美好的花朵」的是","answer":"C","explain":"12 世纪西欧大学兴起，巴黎大学、牛津大学等先后出现，大学享有免赋税特权、司法特权和教育自主权，因此被称为「中世纪最美好的花朵」。","options":["庄园的兴起","城市的兴起","大学的兴起","骑士制度的形成"],"tags":["大学兴起","历史解释"]},{"id":"cat-9a-3-2-g2","type":"choice","stem":"下列关于「西欧庄园」的表述，错误的是","answer":"A","explain":"认为庄园法庭只维护领主的利益，与农民毫无关系——「从材料中概括庄园法庭的作用」这类题，只写一面就会丢掉另一半分值。正确表述：庄园法庭主要维护领主利益，但也起到限制领主专横、维护庄园公共秩序的作用，农民可以依据习惯法在法庭上维护自己的某些权益。","options":["认为庄园法庭只维护领主的利益，与农民毫无关系。","庄园法庭主要维护领主利益，但也起到限制领主专横、维护庄园公共秩序的作用，农民可以依据习惯法在法庭上维护自己的某些权益。","中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。","西欧庄园是一个独立的自给自足的经济和政治单位：土地分为领主的直领地和农民的份地，居民有自由农民和缺少自由的农奴，庄园法庭起着维护庄园秩序的作用。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-2-g3","type":"choice","stem":"下列结论中，属于「西欧庄园」的是","answer":"A","explain":"本课结论：中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。","封君封臣制以土地为纽带、以契约为约束，与西周以血缘宗法为纽带的分封制有明显区别，但两者都造成了地方势力的膨胀与王权的相对软弱。","城市与大学是中世纪西欧社会的「异质因素」：它们孕育了市民阶层与早期资产阶级，是后来文艺复兴、新航路开辟与资产阶级革命的社会基础。","中外联动：同一时期中国正处于唐宋时期，城市经济繁荣、市民生活丰富，但中国城市始终处在中央集权的行政体系之下，没有像西欧城市那样争取到自治权，这是理解中西历史走向差异的一个重要视角。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：封君授予封臣土地，封臣效忠并服兵役，形成层层分封的等级制度，有「我的附庸的附庸不是我的附庸」之说。（2024 部编版九上第 7 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"基督教的兴起和法兰克王国；封君封臣制以土地的封赐为纽带，封君要保护封臣，封臣要效忠封君、服兵役、提供金钱等；其特点是等级森严、权利与义务交织，带有一定的契约意义。","explain":"材料出自2024 部编版九上第 7 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h9a-u3-m1-q2","type":"short","stem":"（2）依据材料二、三，说明西欧庄园与城市各有什么特点，并结合所学指出城市兴起对欧洲历史发展的影响。（6 分）","answer":"庄园的特点：是一个独立的自给自足的经济和政治单位，土地分为领主直领地和农民份地，农民要为领主无偿劳动，庄园法庭负责维护庄园秩序并惩罚违法行为。城市的特点：居民通过金钱赎买和武力斗争争取自由和自治，市民可以自由经商、免交赋税、选举市政官员。影响：城市工商业的发展使市民阶层逐渐形成并壮大，从中分化出富裕的大手工业作坊主、银行家等，成为早期的资产阶级，为文艺复兴的兴起和资本主义的产生准备了条件。","explain":"","tags":["西欧庄园","中世纪城市","历史解释"],"rubric":["答出庄园自给自足、分为直领地与份地","答出庄园法庭的作用","答出城市争取自由和自治的方式","答出市民阶层壮大","答出早期资产阶级出现","答出为文艺复兴或资本主义兴起准备条件"]}]},{"id":"hp-9a-u4","title":"封建时代的亚洲国家 单元测试","subtitle":"九年级上册 · 第四单元","grade":"9a","tags":["九年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9a-u4-q1","type":"choice","stem":"646 年，日本效仿中国唐朝的典章制度进行改革，这次改革史称","answer":"B","explain":"646 年（大化年间），日本孝德天皇推行改革，史称大化改新，主要是效仿唐朝的典章制度，使日本发展成为一个中央集权制的封建国家。","options":["明治维新","大化改新","农奴制改革","幕府改革"],"tags":["大化改新","时空观念"]},{"id":"h9a-u4-q2","type":"choice","stem":"大化改新最重要的历史意义是","answer":"B","explain":"大化改新使日本建立了以天皇为中心的中央集权制度，由奴隶社会向封建社会过渡，发展成为一个中央集权制的封建国家。C 项是明治维新的作用。","options":["使日本实现了国家统一","使日本发展成为一个中央集权制的封建国家","使日本走上了资本主义发展道路","使日本摆脱了外族的侵略"],"tags":["大化改新","历史解释"]},{"id":"h9a-u4-q3","type":"choice","stem":"12 世纪晚期，日本进入幕府统治时期，国家的实际权力掌握在","answer":"B","explain":"12 世纪晚期，源赖朝获得「征夷大将军」称号，设幕府于镰仓，日本从此进入长达近 700 年的幕府统治时期，幕府将军实际掌握国家大权，天皇成为象征。","options":["天皇手中","幕府将军手中","武士手中","大名手中"],"tags":["幕府统治","历史解释"]},{"id":"cat-9a-4-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 大和政权基本统一日本\n② 日本孝德天皇推行大化改新，效仿唐朝典章制度进行改…\n③ 大化改新后日本继续派遣遣唐使，中日交流频繁\n④ 源赖朝获得「征夷大将军」称号，在镰仓设幕府","answer":"A","explain":"按时间顺序应为：①大和政权基本统一日本（5 世纪）→②日本孝德天皇推行大化改新，效仿唐朝典章制度进行改革（646 年）→③大化改新后日本继续派遣遣唐使，中日交流频繁（7 世纪末—8 世纪初）→④源赖朝获得「征夷大将军」称号，在镰仓设幕府（12 世纪晚期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"cat-9a-4-1-g2","type":"choice","stem":"下列关于「古代日本」的表述，错误的是","answer":"A","explain":"把大化改新与明治维新混为一谈——两者都是日本历史上的关键改革，但时代、学习对象与性质完全不同，这是中日改革比较题的基本前提。正确表述：大化改新发生在 646 年，学习的是中国唐朝的典章制度，使日本成为中央集权制的封建国家；明治维新发生在 1868 年，学习的是欧美，使日本走上资本主义道路。","options":["把大化改新与明治维新混为一谈。","大化改新发生在 646 年，学习的是中国唐朝的典章制度，使日本成为中央集权制的封建国家；明治维新发生在 1868 年，学习的是欧美，使日本走上资本主义道路。","大化改新是一次**自上而下的、以中国唐朝制度为蓝本**的改革，说明隋唐制度在东亚具有强大的示范效应，也说明**善于学习和吸收外来先进文化是一个国家走向强盛的重要原因**。","中日联动：从大化改新学习唐朝，到近代日本明治维新学习西方，日本历史上两次大规模学习外来文化的成败，常与中国近代的洋务运动合并考查。"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"cat-9a-4-1-g3","type":"choice","stem":"下列结论中，属于「古代日本」的是","answer":"A","explain":"本课结论：大化改新是一次**自上而下的、以中国唐朝制度为蓝本**的改革，说明隋唐制度在东亚具有强大的示范效应，也说明**善于学习和吸收外来先进文化是一个国家走向强盛的重要原因**。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["大化改新是一次**自上而下的、以中国唐朝制度为蓝本**的改革，说明隋唐制度在东亚具有强大的示范效应，也说明**善于学习和吸收外来先进文化是一个国家走向强盛的重要原因**。","宗教在特定历史条件下可以成为统一的政治力量：伊斯兰教打破了阿拉伯半岛的部落界限，为半岛统一和帝国建立提供了精神纽带。","阿拉伯人是东西方文化交流的桥梁：他们把中国的造纸术、指南针、火药和印度的数字、棉花、食糖传入欧洲，为欧洲的社会进步提供了重要条件。","中外联动：中国与阿拉伯（唐代称「大食」）通过陆上与海上丝绸之路往来密切，651 年阿拉伯遣使来华；中国的四大发明中有三项经阿拉伯人西传，这是理解「中国古代科技对世界的影响」的关键史实。"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"h9a-u4-q4","type":"choice","stem":"622 年，穆罕默德迁往麦地那建立穆斯林公社，这一年被定为","answer":"A","explain":"622 年穆罕默德迁往麦地那建立穆斯林公社，这一年被定为伊斯兰教历元年。阿拉伯半岛基本统一是在 632 年穆罕默德病逝时。","options":["伊斯兰教历元年","阿拉伯帝国建立之年","阿拉伯半岛统一之年","《古兰经》成书之年"],"tags":["伊斯兰教","时空观念"]},{"id":"h9a-u4-q5","type":"choice","stem":"今天世界各国通用的「阿拉伯数字」最早由哪一地区的人发明","answer":"B","explain":"阿拉伯数字最早由古印度人发明，阿拉伯人加以改造并传播到欧洲，因此被称为「阿拉伯数字」，这体现了阿拉伯人在东西方文化交流中的桥梁作用。","options":["阿拉伯人","古印度人","古埃及人","古希腊人"],"tags":["阿拉伯文化","史料实证"]},{"id":"h9a-u4-q6","type":"choice","stem":"中国的造纸术、指南针、火药等重大发明由阿拉伯人传入欧洲，这说明阿拉伯人","answer":"B","explain":"阿拉伯人把中国的造纸术、指南针、火药和印度的棉花、食糖等传入欧洲，同时保存并传播古希腊典籍，起到了东西方文化交流桥梁的作用。","options":["是这些发明的发明者","是东西方文化交流的桥梁","建立了横跨欧亚非三洲的帝国","创立了伊斯兰教"],"tags":["阿拉伯文化","中外交流"]},{"id":"cat-9a-4-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 穆罕默德迁往麦地那，建立穆斯林公社\n② 穆罕默德率穆斯林占领麦加\n③ 穆罕默德病逝，阿拉伯半岛基本统一\n④ 阿拉伯帝国成为横跨欧亚非三洲的大帝国","answer":"A","explain":"按时间顺序应为：①穆罕默德迁往麦地那，建立穆斯林公社（622 年）→②穆罕默德率穆斯林占领麦加（630 年）→③穆罕默德病逝，阿拉伯半岛基本统一（632 年）→④阿拉伯帝国成为横跨欧亚非三洲的大帝国（8 世纪中期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"h9a-u4-m1-q1","type":"short","stem":"（1）依据材料一，概括大化改新在经济和政治方面的措施，并说明这次改革使日本发生了怎样的变化。（6 分）","answer":"经济措施：废除皇室和贵族的私有土地与部民，收归国家所有，成为公地、公民；国家定期把土地分给公民耕种并收取赋税（类似唐朝的均田制与租庸调制）。政治措施：废除世袭贵族统治制度，建立以天皇为中心的中央集权制度，中央和地方官吏由国家任免。变化：大化改新使日本由奴隶社会向封建社会过渡，发展成为一个中央集权制的封建国家。","explain":"","tags":["大化改新","历史解释"],"rubric":["答出收土地与部民为公地、公民","答出定期分地收税","答出中央集权、官吏由国家任免","答出废除世袭贵族统治制度","答出成为中央集权制的封建国家"]},{"id":"cat-9a-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：646 年，孝德天皇颁布改新诏书，仿唐朝制度，实行班田收授法、租庸调制，建立中央集权国家。（《日本书纪》；2024 部编版九上第 11 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"古代日本；大化改新的内容：政治上建立以天皇为中心的中央集权制度，地方设国、郡、里，官吏由国家任免；经济上把土地和部民收归国有，成为公地、公民，国家定期把土地分给公民耕种并收取赋税。","explain":"材料出自《日本书纪》；2024 部编版九上第 11 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9a-u5","title":"走向近代 单元测试","subtitle":"九年级上册 · 第五单元","grade":"9a","tags":["九年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9a-u5-q1","type":"choice","stem":"文艺复兴的核心思想是","answer":"A","explain":"文艺复兴的核心思想是人文主义，即肯定人的价值与尊严，提倡发扬人的个性、追求现世的幸福，反对教会神权对人的束缚。理性主义是启蒙运动的核心。","options":["人文主义","理性主义","禁欲主义","重商主义"],"tags":["文艺复兴","历史解释"]},{"id":"h9a-u5-q2","type":"choice","stem":"文艺复兴的实质是","answer":"B","explain":"文艺复兴采取复兴古代希腊罗马文化的形式，实质是新兴资产阶级的思想文化解放运动，它反对的是教会的神权束缚而非宗教信仰本身。","options":["古希腊罗马文化的简单复兴","新兴资产阶级的思想文化解放运动","一场反宗教的社会运动","教会内部的一次改革"],"tags":["文艺复兴","唯物史观"]},{"id":"h9a-u5-q3","type":"choice","stem":"1492 年率船队横渡大西洋、到达美洲的航海家是","answer":"C","explain":"1492 年哥伦布率船队横渡大西洋，到达今天的巴哈马群岛一带，他误以为自己到达的是印度，因此称当地居民为「印第安人」。","options":["迪亚士","达·伽马","哥伦布","麦哲伦"],"tags":["新航路开辟","时空观念"]},{"id":"cat-9a-5-1-g2","type":"choice","stem":"下列关于「西欧经济和社会的发展」的表述，错误的是","answer":"A","explain":"认为文艺复兴是反对宗教、否定基督教——材料题常问「文艺复兴为什么被称为『复兴』」，标准答法是：它以复兴古代希腊罗马文化为形式，实质是新兴资产阶级的思想解放运动。正确表述：文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","options":["认为文艺复兴是反对宗教、否定基督教。","文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-1-g3","type":"choice","stem":"下列结论中，属于「西欧经济和社会的发展」的是","answer":"A","explain":"本课结论：文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。","新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-2-g2","type":"choice","stem":"下列关于「文艺复兴运动」的表述，错误的是","answer":"A","explain":"认为文艺复兴是反对宗教、否定基督教——材料题常问「文艺复兴为什么被称为『复兴』」，标准答法是：它以复兴古代希腊罗马文化为形式，实质是新兴资产阶级的思想解放运动。正确表述：文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","options":["认为文艺复兴是反对宗教、否定基督教。","文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-2-g3","type":"choice","stem":"下列结论中，属于「文艺复兴运动」的是","answer":"A","explain":"本课结论：文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"h9a-u5-q4","type":"choice","stem":"首次完成环球航行、证明地球是圆的的航海活动是","answer":"C","explain":"1519—1522 年，麦哲伦船队完成人类首次环球航行，证明了地球是圆的。麦哲伦本人在途中死于菲律宾，船队由其他人带领返回西班牙。","options":["迪亚士到达好望角","达·伽马到达印度","麦哲伦船队 1519—1522 年的环球航行","哥伦布到达美洲"],"tags":["新航路开辟","时空观念"]},{"id":"h9a-u5-q5","type":"choice","stem":"新航路开辟最重要的世界性影响是","answer":"B","explain":"新航路开辟以后，欧洲与亚洲、非洲、美洲之间的交通日益密切，世界开始连为一个整体，世界市场逐渐形成，这是它最重要的世界性影响。此后欧洲的贸易中心由地中海沿岸转移到大西洋沿岸。","options":["使欧洲人发现了美洲大陆","使世界开始连为一个整体，世界市场逐渐形成","使中国的丝绸传入欧洲","使意大利成为世界贸易的中心"],"tags":["新航路开辟","历史解释"]},{"id":"cat-9a-5-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 迪亚士到达非洲南端的好望角\n② 哥伦布到达美洲（今巴哈马群岛一带）\n③ 达·伽马率船队绕过好望角到达印度\n④ 麦哲伦船队完成环球航行","answer":"A","explain":"按时间顺序应为：①迪亚士到达非洲南端的好望角（1487 年）→②哥伦布到达美洲（今巴哈马群岛一带）（1492 年）→③达·伽马率船队绕过好望角到达印度（1497—1498 年）→④麦哲伦船队完成环球航行（1519—1522 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：富裕农民租种领主土地，雇佣少地或无地农民耕种，产品面向市场，具有资本主义生产特征。（2024 部编版九上第 13 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"西欧经济和社会的发展；租地农场与手工工场的出现，使西欧农村与手工业生产组织逐渐资本主义化，富裕农民与市民阶层成为新的社会力量。","explain":"材料出自2024 部编版九上第 13 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9a-5-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：文艺复兴不是古典文化的简单复兴，而是新兴资产阶级在思想文化领域发动的反封建运动。（吴于廑、齐世荣《世界史·近代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"文艺复兴运动；文艺复兴以人文主义为核心思想，肯定人的价值与尊严，提倡发扬人的个性、追求现世的幸福，反对教会神权对人的束缚。","explain":"材料出自吴于廑、齐世荣《世界史·近代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9a-u6","title":"资本主义制度的初步确立 单元测试","subtitle":"九年级上册 · 第六单元","grade":"9a","tags":["九年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9a-u6-q1","type":"choice","stem":"英国资产阶级革命结束的标志是","answer":"B","explain":"1688 年，英国议会邀请荷兰执政威廉和玛丽共同入主英国，推翻复辟的斯图亚特王朝，史称「光荣革命」，标志英国资产阶级革命结束。1689 年《权利法案》的颁布则标志着君主立宪制的确立。","options":["1649 年查理一世被处死","1688 年的「光荣革命」","1689 年《权利法案》的颁布","1660 年斯图亚特王朝复辟"],"tags":["英国革命","时空观念"]},{"id":"h9a-u6-q2","type":"choice","stem":"1689 年《权利法案》的颁布，使英国确立的政治制度是","answer":"B","explain":"《权利法案》以法律形式限制国王的权力，议会成为国家权力的中心，君主立宪制的资产阶级统治在英国开始确立起来。","options":["君主专制","君主立宪制","民主共和制","联邦制"],"tags":["《权利法案》","制度创新"]},{"id":"h9a-u6-q4","type":"choice","stem":"1787 年美国宪法确立的重要原则是","answer":"B","explain":"1787 年美国宪法确立了联邦制以及立法（国会）、行政（总统）、司法（最高法院）三权分立、相互制衡的原则，是世界上第一部资产阶级成文宪法。但它没有废除奴隶制，也没有给妇女、印第安人和黑人奴隶平等的权利。","options":["君主立宪","三权分立、相互制衡","中央集权与地方分权并重","议会至上"],"tags":["1787 年宪法","制度创新"]},{"id":"cat-9a-6-1-g2","type":"choice","stem":"下列关于「君主立宪制的英国」的表述，错误的是","answer":"A","explain":"认为英国资产阶级革命后确立了共和制——「君主立宪」与「共和」是两种政体。英国曾短暂建立共和国（1649—1660），但最终确立的是君主立宪制，这个曲折过程本身也是常考点。正确表述：英国确立的是君主立宪制：国王仍然存在，但权力受议会和法律限制，议会成为国家权力的中心。","options":["认为英国资产阶级革命后确立了共和制。","英国确立的是君主立宪制：国王仍然存在，但权力受议会和法律限制，议会成为国家权力的中心。","英美法三国资产阶级革命都以法律文献的形式把革命成果固定下来（英国《权利法案》、美国 1787 年宪法、法国《人权宣言》与《拿破仑法典》），说明**用法律确立制度是近代政治文明的重要特征**。","英国确立的是**君主立宪制**（保留国王、议会掌权），美国确立的是**联邦共和制**（没有国王、总统由选举产生），法国大革命则彻底摧毁了君主专制——三国选择了不同的政体，但都建立了资产阶级的统治。"],"difficulty":2,"tags":["九年级上册","第六单元","本课练习"]},{"id":"h9a-u6-q3","type":"choice","stem":"标志着美国诞生的历史事件是","answer":"B","explain":"1776 年 7 月 4 日，《独立宣言》发表，宣告北美 13 个殖民地脱离英国独立，标志着美国的诞生。来克星顿枪声是独立战争爆发的标志，萨拉托加大捷是转折点。","options":["来克星顿枪声","1776 年 7 月 4 日《独立宣言》的发表","萨拉托加大捷","1787 年宪法的制定"],"tags":["《独立宣言》","时空观念"]},{"id":"h9a-u6-q6","type":"choice","stem":"《拿破仑法典》的历史地位主要在于","answer":"B","explain":"1804 年拿破仑颁布《拿破仑法典》，它体现了自由平等和私有财产神圣不可侵犯的原则，成为许多国家民法的参照蓝本。A 项是 1787 年美国宪法，C 项是《权利法案》，D 项是《独立宣言》。","options":["是世界上第一部资产阶级成文宪法","体现了自由平等和私有财产神圣不可侵犯的原则，成为许多国家民法的参照蓝本","以法律形式限制了国王的权力","宣告北美殖民地脱离英国独立"],"tags":["拿破仑法典","制度创新"]},{"id":"cat-9a-6-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 来克星顿枪声，北美独立战争爆发\n② 《独立宣言》发表，宣告北美 13 个殖民地独立\n③ 美国制定宪法，确立联邦制与三权分立","answer":"A","explain":"按时间顺序应为：①来克星顿枪声，北美独立战争爆发（1775 年）→②《独立宣言》发表，宣告北美 13 个殖民地独立（1776 年 7 月 4 日）→③美国制定宪法，确立联邦制与三权分立（1787 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第六单元","本课练习"]},{"id":"cat-9a-6-2-g2","type":"choice","stem":"下列关于「美国的独立」的表述，错误的是","answer":"A","explain":"把《独立宣言》与 1787 年宪法的意义弄混——前者解决「独立」，后者解决「建国后怎么治理」，是前后相承的两个环节。正确表述：1776 年《独立宣言》宣告北美 13 个殖民地独立，标志美国的诞生；1787 年宪法确立了美国的联邦制与三权分立的政治体制。","options":["把《独立宣言》与 1787 年宪法的意义弄混。","1776 年《独立宣言》宣告北美 13 个殖民地独立，标志美国的诞生；1787 年宪法确立了美国的联邦制与三权分立的政治体制。","英美法三国资产阶级革命都以法律文献的形式把革命成果固定下来（英国《权利法案》、美国 1787 年宪法、法国《人权宣言》与《拿破仑法典》），说明**用法律确立制度是近代政治文明的重要特征**。","1689 年《权利法案》以法律形式明确限制国王的权力，君主立宪制的资产阶级统治在英国开始确立起来。"],"difficulty":2,"tags":["九年级上册","第六单元","本课练习"]},{"id":"h9a-u6-q5","type":"choice","stem":"法国大革命开始的标志是","answer":"B","explain":"1789 年 7 月 14 日，巴黎人民攻占巴士底狱，法国大革命由此开始。此后制宪议会颁布《人权宣言》，1792 年法国建立共和国。","options":["1789 年 5 月三级会议的召开","1789 年 7 月 14 日巴黎人民攻占巴士底狱","《人权宣言》的颁布","1793 年路易十六被处死"],"tags":["法国大革命","时空观念"]},{"id":"cat-9a-6-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 5 月三级会议召开，7 月 14 日巴黎人民攻占…\n② 法国建立共和国、处死路易十六，雅各宾派专政，17…\n③ 拿破仑建立法兰西第一帝国，颁布《拿破仑法典》\n④ 拿破仑远征俄国失败，1815 年滑铁卢战役失败，…","answer":"A","explain":"按时间顺序应为：①5 月三级会议召开，7 月 14 日巴黎人民攻占巴士底狱，法国大革命开始（1789 年）→②法国建立共和国、处死路易十六，雅各宾派专政，1794 年热月政变革命结束（1792—1794 年）→③拿破仑建立法兰西第一帝国，颁布《拿破仑法典》（1804 年）→④拿破仑远征俄国失败，1815 年滑铁卢战役失败，帝国终结（1812—1815 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第六单元","本课练习"]},{"id":"cat-9a-6-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：规定国王不得随意废止法律、不得征税、不得在和平时期维持常备军，保障议会言论自由和定期集会，限制王权。（《权利法案》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"君主立宪制的英国；1689 年《权利法案》以法律形式明确限制国王的权力，君主立宪制的资产阶级统治在英国开始确立起来。","explain":"材料出自《权利法案》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9a-6-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：由杰斐逊起草，宣布人人生而平等，享有生命权、自由权和追求幸福的权利，宣告北美 13 个殖民地脱离英国独立。（《独立宣言》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"美国的独立；1689 年《权利法案》以法律形式明确限制国王的权力，君主立宪制的资产阶级统治在英国开始确立起来。","explain":"材料出自《独立宣言》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9a-u7","title":"工业革命和国际共产主义运动的兴起 单元测试","subtitle":"九年级上册 · 第七单元","grade":"9a","tags":["九年级上册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9a-u7-q1","type":"choice","stem":"第一次工业革命开始的标志是","answer":"B","explain":"18 世纪 60 年代，纺织工人哈格里夫斯发明珍妮纺纱机，标志着第一次工业革命的开始；瓦特改良蒸汽机在 1785 年以后被用作纺织部门的动力机，是工业革命的重要标志。","options":["瓦特改良蒸汽机","哈格里夫斯发明珍妮纺纱机","史蒂芬孙设计蒸汽机车","富尔顿发明汽船"],"tags":["工业革命","时空观念"]},{"id":"h9a-u7-q2","type":"choice","stem":"第一次工业革命中，把人类带入「蒸汽时代」的最重要发明是","answer":"B","explain":"瓦特改良的蒸汽机在 1785 年以后被用作纺织部门的动力机，摆脱了工厂对河流水力条件的依赖，蒸汽机的广泛应用使人类进入「蒸汽时代」。","options":["珍妮纺纱机","瓦特改良的蒸汽机","水力织布机","汽船"],"tags":["工业革命","历史解释"]},{"id":"cat-9a-7-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 哈格里夫斯发明珍妮纺纱机，工业革命开始\n② 瓦特改良的蒸汽机被用作纺织部门的动力机\n③ 富尔顿发明汽船；史蒂芬孙设计的蒸汽机车试车成功\n④ 英国率先完成工业革命，成为世界上第一个工业国家（…","answer":"A","explain":"按时间顺序应为：①哈格里夫斯发明珍妮纺纱机，工业革命开始（18 世纪 60 年代）→②瓦特改良的蒸汽机被用作纺织部门的动力机（1785 年以后）→③富尔顿发明汽船；史蒂芬孙设计的蒸汽机车试车成功（1807 年、1825 年）→④英国率先完成工业革命，成为世界上第一个工业国家（「世界工厂」）（19 世纪中期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"cat-9a-7-1-g2","type":"choice","stem":"下列关于「第一次工业革命」的表述，错误的是","answer":"A","explain":"把工业革命的开始标志说成「瓦特改良蒸汽机」——「开始标志」与「重要标志」是两个不同的表述，考卷上常以此设陷阱。正确表述：工业革命开始的标志是 18 世纪 60 年代哈格里夫斯发明珍妮纺纱机；瓦特改良的蒸汽机在 1785 年以后被用作纺织部门的动力机，是工业革命的重要标志，把人类带入「蒸汽时代」。","options":["把工业革命的开始标志说成「瓦特改良蒸汽机」。","工业革命开始的标志是 18 世纪 60 年代哈格里夫斯发明珍妮纺纱机；瓦特改良的蒸汽机在 1785 年以后被用作纺织部门的动力机，是工业革命的重要标志，把人类带入「蒸汽时代」。","工业革命是**生产技术的革命，也是社会关系的革命**：机器生产取代手工劳动，工厂制度确立，工业资产阶级与工业无产阶级成为近代社会的两大阶级。","工业革命首先发生在英国不是偶然的，而是政治制度、市场、资本、劳动力、技术等多种因素共同作用的结果，其中**君主立宪制的确立提供了政治前提，广阔的海外市场和殖民掠夺提供了资本与市场**。"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"h9a-u7-q3","type":"choice","stem":"1848 年《共产党宣言》的发表，标志着","answer":"B","explain":"1848 年，马克思、恩格斯为共产主义者同盟起草的《共产党宣言》发表，标志着马克思主义的诞生，从此国际工人运动有了科学理论的指导。","options":["国际工人协会的成立","马克思主义的诞生","巴黎公社的建立","第一个无产阶级政权的建立"],"tags":["《共产党宣言》","时空观念"]},{"id":"h9a-u7-q4","type":"choice","stem":"巴黎公社在世界历史上的重要地位是","answer":"A","explain":"1871 年 3 月 28 日巴黎公社成立，这是世界历史上第一个无产阶级政权，是无产阶级建立政权的第一次伟大尝试，但只存在了两个多月就失败了，并未改变法国的社会性质。","options":["世界上第一个无产阶级政权","第一个社会主义国家","国际工人运动的第一个组织","第一次取得胜利的社会主义革命"],"tags":["巴黎公社","历史解释"]},{"id":"cat-9a-7-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 《共产党宣言》发表，标志马克思主义的诞生\n② 巴黎公社成立，这是世界历史上第一个无产阶级政权\n③ 第一国际（国际工人协会）成立","answer":"A","explain":"按时间顺序应为：①《共产党宣言》发表，标志马克思主义的诞生（1848 年）→②巴黎公社成立，这是世界历史上第一个无产阶级政权（1871 年）→③第一国际（国际工人协会）成立（1864 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"cat-9a-7-2-g2","type":"choice","stem":"下列关于「马克思主义的诞生和国际共产主义运…」的表述，错误的是","answer":"A","explain":"认为巴黎公社推翻了法国的资本主义制度、建立了社会主义国家——要准确使用「第一次伟大尝试」这一表述，不能夸大为「建立起社会主义制度」。正确表述：巴黎公社只存在了两个多月（1871 年 3 月 28 日—5 月底），是无产阶级建立政权的第一次伟大尝试，最终失败，并未改变法国的社会性质。","options":["认为巴黎公社推翻了法国的资本主义制度、建立了社会主义国家。","巴黎公社只存在了两个多月（1871 年 3 月 28 日—5 月底），是无产阶级建立政权的第一次伟大尝试，最终失败，并未改变法国的社会性质。","马克思主义的诞生是工业革命后资本主义矛盾发展的必然结果：工业无产阶级的壮大与工人运动的兴起，为科学社会主义理论提供了阶级基础。","1848 年《共产党宣言》的发表标志着马克思主义的诞生，从此国际工人运动有了科学理论的指导。"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"cat-9a-7-2-g3","type":"choice","stem":"下列结论中，属于「马克思主义的诞生和国际共产主义运…」的是","answer":"A","explain":"本课结论：马克思主义的诞生是工业革命后资本主义矛盾发展的必然结果：工业无产阶级的壮大与工人运动的兴起，为科学社会主义理论提供了阶级基础。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["马克思主义的诞生是工业革命后资本主义矛盾发展的必然结果：工业无产阶级的壮大与工人运动的兴起，为科学社会主义理论提供了阶级基础。","工业革命是**生产技术的革命，也是社会关系的革命**：机器生产取代手工劳动，工厂制度确立，工业资产阶级与工业无产阶级成为近代社会的两大阶级。","工业革命首先发生在英国不是偶然的，而是政治制度、市场、资本、劳动力、技术等多种因素共同作用的结果，其中**君主立宪制的确立提供了政治前提，广阔的海外市场和殖民掠夺提供了资本与市场**。","中外联动：英国完成工业革命的时期（19 世纪中期）正是中国被坚船利炮打开国门的时期。1840 年鸦片战争后，中国一步步沦为半殖民地半封建社会；此后洋务运动学习西方的器物技术，正是对工业文明冲击的被动回应——**中国的近代化是在西方工业文明的冲击下被迫启动的**。"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"cat-9a-7-3-g2","type":"choice","stem":"下列关于「活动课 唱响《国际歌》」的表述，错误的是","answer":"A","explain":"认为巴黎公社推翻了法国的资本主义制度、建立了社会主义国家——要准确使用「第一次伟大尝试」这一表述，不能夸大为「建立起社会主义制度」。正确表述：巴黎公社只存在了两个多月（1871 年 3 月 28 日—5 月底），是无产阶级建立政权的第一次伟大尝试，最终失败，并未改变法国的社会性质。","options":["认为巴黎公社推翻了法国的资本主义制度、建立了社会主义国家。","巴黎公社只存在了两个多月（1871 年 3 月 28 日—5 月底），是无产阶级建立政权的第一次伟大尝试，最终失败，并未改变法国的社会性质。","工业革命是**生产技术的革命，也是社会关系的革命**：机器生产取代手工劳动，工厂制度确立，工业资产阶级与工业无产阶级成为近代社会的两大阶级。","工业革命首先发生在英国不是偶然的，而是政治制度、市场、资本、劳动力、技术等多种因素共同作用的结果，其中**君主立宪制的确立提供了政治前提，广阔的海外市场和殖民掠夺提供了资本与市场**。"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"h9a-u7-m1-q2","type":"short","stem":"（2）依据材料二，说明工业革命与鸦片战争之间的关系，并据此谈谈你的认识。（6 分）","answer":"关系：19 世纪中期英国率先完成工业革命，急需广阔的商品市场和原料产地。为了打开中国市场、倾销工业品并掠夺原料，英国于 1840 年发动鸦片战争，强迫清政府签订《南京条约》。鸦片战争是中国近代史的开端，中国开始沦为半殖民地半封建社会。认识：工业革命使西方国家的实力远强于中国，落后就要挨打；闭关锁国只会导致落后；中国必须顺应世界潮流，学习先进的制度与技术（如后来的洋务运动），才能摆脱被动挨打的局面。","explain":"","tags":["工业革命","中外联动"],"rubric":["答出英国完成工业革命需要市场与原料","答出为打开中国市场而发动鸦片战争","答出中国开始沦为半殖民地半封建社会","答出「落后就要挨打」或闭关锁国导致落后","答出要顺应潮流、学习先进制度与技术"]},{"id":"cat-9a-7-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1785 年，瓦特改良的蒸汽机投入使用，为工厂提供稳定动力，推动机器大工业发展。（吴于廑、齐世荣《世界史·近代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"第一次工业革命；第一次工业革命首先从英国的棉纺织业开始，18 世纪 60 年代珍妮纺纱机的发明标志着工业革命的开始，瓦特改良的蒸汽机使人类进入「蒸汽时代」。","explain":"材料出自吴于廑、齐世荣《世界史·近代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第七单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9b-u1","title":"殖民地人民的反抗与资本主义制度的扩展 单元测试","subtitle":"九年级下册 · 第一单元","grade":"9b","tags":["九年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9b-u1-q1","type":"choice","stem":"19 世纪，印度爆发了反抗英国殖民统治的民族大起义，其杰出领导人是","answer":"B","explain":"1857—1859 年印度民族大起义反抗英国殖民统治，章西女王是杰出代表。玻利瓦尔是拉美独立运动领袖，甘地领导的是 20 世纪的印度非暴力不合作运动，凯末尔领导的是土耳其革命。","options":["玻利瓦尔","章西女王","甘地","凯末尔"],"tags":["印度民族大起义","时空观念"]},{"id":"cat-9b-1-1-g2","type":"choice","stem":"下列关于「殖民地人民的反抗战争」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","19 世纪中期，资本主义制度在世界范围内确立和扩展：俄国靠自上而下的改革，美国靠内战，日本靠明治维新——**方式不同，方向一致**。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-1-g5","type":"choice","stem":"「拉丁美洲独立运动兴起」发生于","answer":"A","explain":"本课时间轴：拉丁美洲独立运动兴起（19 世纪初）。玻利瓦尔解放哥伦比亚、委内瑞拉、厄瓜多尔等地，圣马丁领导阿根廷、智利、秘鲁的独立运动；1804 年海地独立揭开序幕（拉美第一个独立国家）。其余三个时间是同一单元相邻课时的事件时间。","options":["19 世纪初","1861 年","1861—1865 年","1871 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-1-g6","type":"choice","stem":"下列考点中，属于「殖民地人民的反抗战争」的是","answer":"A","explain":"本课考点（重点）：拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。其余三项是同一单元相邻课时的考点。","options":["拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，18…","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买…","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废…","19 世纪中期资本主义制度的扩展：俄国（1861 年改革）、美国（内战）、日本（明治维新…"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h9b-u1-q2","type":"choice","stem":"1861 年，俄国沙皇亚历山大二世签署废除农奴制的法令。这项改革的性质是","answer":"B","explain":"改革由沙皇政府自上而下推行，使农奴获得人身自由、为资本主义发展提供了自由劳动力与市场，因此是自上而下的资产阶级性质的改革；但它保留了大量封建残余，不是「彻底」废除封建制度。","options":["自下而上的农民起义","自上而下的资产阶级性质的改革","无产阶级社会主义革命","彻底废除封建制度的民主革命"],"tags":["俄国农奴制改革","历史解释"]},{"id":"cat-9b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 俄国农奴制改革\n② 美国南北战争\n③ 德意志帝国成立（普法战争后）","answer":"A","explain":"按时间顺序应为：①俄国农奴制改革（1861 年）→②美国南北战争（1861—1865 年）→③德意志帝国成立（普法战争后）（1871 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-2-g2","type":"choice","stem":"下列关于「俄国的改革」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-2-g5","type":"choice","stem":"「俄国农奴制改革」发生于","answer":"A","explain":"本课时间轴：俄国农奴制改革（1861 年）。沙皇亚历山大二世签署废除农奴制的法令：农奴获得人身自由，可通过赎买获得份地——俄国历史上的重要转折点。其余三个时间是同一单元相邻课时的事件时间。","options":["1861 年","19 世纪初","1857—1859 年","1861—1865 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h9b-u1-q3","type":"choice","stem":"美国南北战争爆发前，南北方矛盾斗争的焦点是","answer":"B","explain":"南北两种经济制度（北方资本主义工商业与南方种植园奴隶制经济）的矛盾日益尖锐，焦点是奴隶制的存废问题；林肯当选总统成为战争爆发的导火线。","options":["关税税率的高低","奴隶制的存废问题","西部领土的扩张方向","总统选举的方式"],"tags":["美国内战","历史解释"]},{"id":"h9b-u1-q4","type":"choice","stem":"使美国南北战争的战局发生扭转、为北方军队提供雄厚兵源的文件是","answer":"B","explain":"1862 年林肯颁布《宅地法》和《解放黑人奴隶宣言》，宣言宣布叛乱各州奴隶永远获得自由，黑人踊跃参军，扭转了战局。《独立宣言》《1787 年宪法》均为美国独立战争时期的文件。","options":["《独立宣言》","《解放黑人奴隶宣言》","《人权宣言》","1787 年美国宪法"],"tags":["美国内战","史料实证"]},{"id":"cat-9b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：玻利瓦尔率军解放委内瑞拉、哥伦比亚、厄瓜多尔、秘鲁等地，被誉为「解放者」；圣马丁解放阿根廷、智利、秘鲁。（吴于廑、齐世荣《世界史·近代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"殖民地人民的反抗战争；拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。","explain":"材料出自吴于廑、齐世荣《世界史·近代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：农奴获得人身自由，有权拥有财产、从事工商活动；地主不得买卖农奴；农奴可赎买份地，但须支付高额赎金。（《1861 年法令》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"俄国的改革；俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。","explain":"材料出自《1861 年法令》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9b-u2","title":"第二次工业革命和近代科学文化 单元测试","subtitle":"九年级下册 · 第二单元","grade":"9b","tags":["九年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9b-u2-q1","type":"choice","stem":"第二次工业革命中，作为新能源被广泛应用、使人类进入「电气时代」的是","answer":"B","explain":"第二次工业革命以电力的广泛应用为标志，电动机、发电机等的发明使电力进入生产与生活领域，人类进入「电气时代」。煤炭是第一次工业革命的主要能源。","options":["煤炭","电力","水力","风能"],"tags":["第二次工业革命","时空观念"]},{"id":"h9b-u2-q2","type":"choice","stem":"1879 年研制出耐用碳丝白炽灯泡、一生取得千余项发明专利，被誉为「发明大王」的是","answer":"B","explain":"爱迪生 1879 年发明耐用的白炽灯泡，被誉为「发明大王」。本茨制造出内燃机汽车，莱特兄弟制成飞机，诺贝尔发明现代炸药。","options":["本茨","爱迪生","莱特兄弟","诺贝尔"],"tags":["第二次工业革命","历史人物"]},{"id":"h9b-u2-q4","type":"choice","stem":"19 世纪末 20 世纪初，主要资本主义国家出现垄断组织。其根本原因是","answer":"B","explain":"垄断组织是第二次工业革命中生产力迅速发展、生产和资本高度集中的结果。国家全面干预经济是二战后（罗斯福新政开创）的新变化，不是垄断组织产生的原因。","options":["第一次工业革命的完成","第二次工业革命推动生产力发展、生产和资本日益高度集中","列强加紧对外殖民扩张","国家全面干预经济生活"],"tags":["垄断组织","唯物史观"]},{"id":"h9b-u2-q6","type":"choice","stem":"与第一次工业革命相比，第二次工业革命最突出的特点是","answer":"B","explain":"第二次工业革命中科学与技术紧密结合，各种新发明迅速应用于生产，这是它最突出的特点。A、C、D 都是第一次工业革命的特点，其中 D 是第一次工业革命的标志。","options":["主要靠工匠的实践经验与发明创造","科学研究与工业生产紧密结合，科学技术迅速应用于生产","首先发生在英国，然后扩展到其他国家","以蒸汽机的广泛使用为标志"],"tags":["第二次工业革命","横向比较"]},{"id":"cat-9b-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 第二次工业革命开始\n② 爱迪生发明耐用碳丝白炽灯泡\n③ 本茨制造出内燃机驱动的汽车\n④ 莱特兄弟制成的飞机试飞成功","answer":"A","explain":"按时间顺序应为：①第二次工业革命开始（19 世纪 70 年代）→②爱迪生发明耐用碳丝白炽灯泡（1879 年）→③本茨制造出内燃机驱动的汽车（1885 年）→④莱特兄弟制成的飞机试飞成功（1903 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第二单元","本课练习"]},{"id":"cat-9b-2-1-g2","type":"choice","stem":"下列关于「第二次工业革命」的表述，错误的是","answer":"A","explain":"把两次工业革命的标志性成果弄反：认为第二次工业革命以蒸汽机的广泛使用为标志——两次革命的标志、能源、时代名称是最常设的对应类陷阱，要成对记：「一蒸二电」。正确表述：第一次工业革命以蒸汽机的广泛使用为标志，人类进入「蒸汽时代」；第二次工业革命以电力的广泛应用为标志，人类进入「电气时代」。","options":["把两次工业革命的标志性成果弄反：认为第二次工业革命以蒸汽机的广泛使用为标志。","第一次工业革命以蒸汽机的广泛使用为标志，人类进入「蒸汽时代」；第二次工业革命以电力的广泛应用为标志，人类进入「电气时代」。","科学技术是第一生产力：第二次工业革命中科学与技术紧密结合，电力等新能源的应用使生产力获得飞跃式发展。","帝国主义国家政治经济发展不平衡是第一次世界大战的根本原因——这是「第二次工业革命」与「一战」之间最重要的一条因果链。"],"difficulty":2,"tags":["九年级下册","第二单元","本课练习"]},{"id":"h9b-u2-q3","type":"choice","stem":"1859 年出版《物种起源》、提出生物进化论、打破神学创世说的科学家是","answer":"B","explain":"1859 年英国科学家达尔文出版《物种起源》，提出生物进化论，打破了神学创世说。牛顿建立经典力学体系，门捷列夫发现元素周期律。","options":["牛顿","达尔文","门捷列夫","爱因斯坦"],"tags":["近代科学","历史解释"]},{"id":"cat-9b-2-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 牛顿发表《自然哲学的数学原理》\n② 达尔文出版《物种起源》\n③ 俄国化学家门捷列夫发现元素周期律\n④ 第二次工业革命开始","answer":"A","explain":"按时间顺序应为：①牛顿发表《自然哲学的数学原理》（1687 年）→②达尔文出版《物种起源》（1859 年）→③俄国化学家门捷列夫发现元素周期律（1869 年）→④第二次工业革命开始（19 世纪 70 年代）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第二单元","本课练习"]},{"id":"cat-9b-2-2-g2","type":"choice","stem":"下列关于「工业化国家的社会变化」的表述，错误的是","answer":"A","explain":"把两次工业革命的标志性成果弄反：认为第二次工业革命以蒸汽机的广泛使用为标志——两次革命的标志、能源、时代名称是最常设的对应类陷阱，要成对记：「一蒸二电」。正确表述：第一次工业革命以蒸汽机的广泛使用为标志，人类进入「蒸汽时代」；第二次工业革命以电力的广泛应用为标志，人类进入「电气时代」。","options":["把两次工业革命的标志性成果弄反：认为第二次工业革命以蒸汽机的广泛使用为标志。","第一次工业革命以蒸汽机的广泛使用为标志，人类进入「蒸汽时代」；第二次工业革命以电力的广泛应用为标志，人类进入「电气时代」。","科学技术是第一生产力：第二次工业革命中科学与技术紧密结合，电力等新能源的应用使生产力获得飞跃式发展。","垄断是生产力发展的结果：生产与资本高度集中 → 垄断组织 → 主要资本主义国家进入帝国主义阶段，列强加紧瓜分世界。"],"difficulty":2,"tags":["九年级下册","第二单元","本课练习"]},{"id":"h9b-u2-q5","type":"choice","stem":"被列宁称为「俄国革命的镜子」的作家及其代表作是","answer":"B","explain":"俄国作家列夫·托尔斯泰著有《战争与和平》《安娜·卡列尼娜》《复活》，列宁称他为「俄国革命的镜子」；巴尔扎克是法国作家，其《人间喜剧》被称为法国社会的「百科全书」。","options":["巴尔扎克《人间喜剧》","列夫·托尔斯泰《战争与和平》","莎士比亚《哈姆雷特》","但丁《神曲》"],"tags":["近代文学","历史人物"]},{"id":"h9b-u2-m1-q1","type":"short","stem":"（1）依据材料一，指出第二次工业革命中出现的两种新能源，并说明电力广泛应用使人类进入了什么时代？（4 分）","answer":"新能源：电力；石油（随内燃机的创制而得到广泛开采和使用）。电力广泛应用于生产与生活领域，人类由此进入「电气时代」。","explain":"","tags":["第二次工业革命","史料实证"],"rubric":["答出电力","答出石油（或内燃机）","答出「电气时代」","表述完整、指向第二次工业革命"]},{"id":"cat-9b-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1866 年西门子发明发电机，1879 年爱迪生发明耐用白炽灯泡，电力广泛用于照明、动力和通讯。（吴于廑、齐世荣《世界史·近代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"第二次工业革命；第二次工业革命的成就与标志：19 世纪 70 年代开始，以电力的广泛应用为标志，还包括内燃机与新交通工具（汽车、飞机）、化学工业和新材料、新通讯手段的发明，人类进入「电气时代」。","explain":"材料出自吴于廑、齐世荣《世界史·近代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9b-u3","title":"第一次世界大战和战后初期的世界 单元测试","subtitle":"九年级下册 · 第三单元","grade":"9b","tags":["九年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9b-u3-q1","type":"choice","stem":"第一次世界大战爆发的根本原因是","answer":"B","explain":"根本原因是帝国主义国家政治经济发展不平衡，后起的帝国主义国家要求重新瓜分世界，与老牌殖民国家矛盾激化。萨拉热窝事件是导火线，两大军事集团的形成是具体条件。","options":["萨拉热窝事件的发生","帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权","三国同盟与三国协约的形成","塞尔维亚与奥匈帝国的领土争端"],"tags":["第一次世界大战","唯物史观"]},{"id":"cat-9b-3-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 三国同盟形成\n② 三国协约形成\n③ 萨拉热窝事件\n④ 凡尔登战役","answer":"A","explain":"按时间顺序应为：①三国同盟形成（1882 年）→②三国协约形成（1907 年）→③萨拉热窝事件（1914 年 6 月）→④凡尔登战役（1916 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-1-g2","type":"choice","stem":"下列关于「第一次世界大战」的表述，错误的是","answer":"A","explain":"把萨拉热窝事件说成第一次世界大战爆发的根本原因——「根本原因—导火线」的区分是最高频的失分点，凡遇「根本」二字都要往经济与制度矛盾上想。正确表述：萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","options":["把萨拉热窝事件说成第一次世界大战爆发的根本原因。","萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","第一次世界大战是一场非正义的帝国主义掠夺战争，给人类带来空前灾难；战争没有解决列强之间的矛盾，反而为新的战争埋下祸根。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-1-g3","type":"choice","stem":"下列结论中，属于「第一次世界大战」的是","answer":"A","explain":"本课结论：第一次世界大战是一场非正义的帝国主义掠夺战争，给人类带来空前灾难；战争没有解决列强之间的矛盾，反而为新的战争埋下祸根。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["第一次世界大战是一场非正义的帝国主义掠夺战争，给人类带来空前灾难；战争没有解决列强之间的矛盾，反而为新的战争埋下祸根。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。","十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。","政策必须立足国情、实事求是：新经济政策利用市场和商品货币关系恢复经济，是在坚持社会主义方向前提下的成功探索。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"h9b-u3-q4","type":"choice","stem":"1922 年华盛顿会议上签署的《九国公约》，其实际作用是","answer":"B","explain":"《九国公约》名义上尊重中国的主权、独立与领土完整，实际上使中国回到被几个帝国主义国家共同支配的局面。确立欧洲统治秩序的是《凡尔赛条约》，列强矛盾也不可能因此消除。","options":["使中国收回了全部主权","使中国回到被几个帝国主义国家共同支配的局面","确立了欧洲的统治秩序","彻底消除了列强之间的矛盾"],"tags":["华盛顿会议","历史解释"]},{"id":"cat-9b-3-2-g2","type":"choice","stem":"下列关于「一战后的国际关系」的表述，错误的是","answer":"A","explain":"认为《凡尔赛条约》是战胜国与被战胜国之间的公平条约——评价条约要抓住「分赃」二字，并联系中国外交失败与五四运动。正确表述：它是战胜国重新瓜分世界的条约：对德国索取巨额赔款、分割领土，对中国极不公平（把德国在山东的特权转让给日本），激化了矛盾，埋下新的战争祸根。","options":["认为《凡尔赛条约》是战胜国与被战胜国之间的公平条约。","它是战胜国重新瓜分世界的条约：对德国索取巨额赔款、分割领土，对中国极不公平（把德国在山东的特权转让给日本），激化了矛盾，埋下新的战争祸根。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。","凡尔赛—华盛顿体系：巴黎和会签订《凡尔赛条约》，华盛顿会议签订《九国公约》，确立了战后帝国主义在欧洲、西亚、非洲和亚太地区的统治秩序；但它不可能消除帝国主义国家之间的矛盾，反而埋下新的战争祸根。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-2-g3","type":"choice","stem":"下列结论中，属于「一战后的国际关系」的是","answer":"A","explain":"本课结论：「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。","十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。","政策必须立足国情、实事求是：新经济政策利用市场和商品货币关系恢复经济，是在坚持社会主义方向前提下的成功探索。","民族解放运动必须与本国国情相适应：甘地走非暴力不合作道路，凯末尔走武装斗争与世俗化改革道路，都推动了民族民主运动的发展。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-2-g5","type":"choice","stem":"「巴黎和会与《凡尔赛条约》」发生于","answer":"A","explain":"本课时间轴：巴黎和会与《凡尔赛条约》（1919 年 1—6 月）。战胜国重新瓜分世界；把德国在中国山东的特权转让给日本，中国外交失败，引发五四运动。其余三个时间是同一单元相邻课时的事件时间。","options":["1919 年 1—6 月","1882 年","1907 年","1914 年 6 月"],"difficulty":1,"tags":["九年级下册","第三单元","本课练习"]},{"id":"h9b-u3-q6","type":"choice","stem":"人类历史上第一次胜利的社会主义革命是","answer":"C","explain":"1917 年俄国十月革命建立了世界上第一个无产阶级专政的国家，是人类历史上第一次胜利的社会主义革命，开辟了人类历史的新纪元。","options":["英国资产阶级革命","法国大革命","俄国十月革命","美国独立战争"],"tags":["十月革命","历史解释"]},{"id":"cat-9b-3-3-g2","type":"choice","stem":"下列关于「列宁与十月革命」的表述，错误的是","answer":"A","explain":"认为十月革命结束了一战——两个 1918 年的事件时间接近，容易混为一谈。正确表述：十月革命后苏俄退出一战（1918 年 3 月签订和约），但一战直到 1918 年 11 月德国投降才结束。","options":["认为十月革命结束了一战。","十月革命后苏俄退出一战（1918 年 3 月签订和约），但一战直到 1918 年 11 月德国投降才结束。","十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。","第一次世界大战的影响：给人类带来空前灾难（30 多个国家、15 亿人口卷入，伤亡 3000 多万人）；削弱了帝国主义和殖民主义力量；促进了殖民地半殖民地民族解放运动的发展；促成俄国十月革命；欧洲衰落、美日崛起，世界格局发生变化。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1914 年 6 月 28 日，奥匈帝国皇储斐迪南大公夫妇在萨拉热窝被塞尔维亚青年普林西普刺杀，成为一战导火索。（吴于廑、齐世荣《世界史·现代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"第一次世界大战；第一次世界大战爆发的原因、导火线与性质：根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权；两大军事集团（三国同盟与三国协约）的形成使战争一触即发；导火线是 1914 年萨拉热窝事件。性质是一场非正义的帝国主义掠夺战争（塞尔维亚为民族独立而战具有正义性）。","explain":"材料出自吴于廑、齐世荣《世界史·现代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-3-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：重划德国疆界，德国失去全部海外殖民地，限制军备，承担巨额赔款，德国国内普遍不满。（《凡尔赛条约》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"一战后的国际关系；凡尔赛—华盛顿体系：巴黎和会签订《凡尔赛条约》，华盛顿会议签订《九国公约》，确立了战后帝国主义在欧洲、西亚、非洲和亚太地区的统治秩序；但它不可能消除帝国主义国家之间的矛盾，反而埋下新的战争祸根。","explain":"材料出自《凡尔赛条约》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9b-u4","title":"资本主义经济大危机和第二次世界大战 单元测试","subtitle":"九年级下册 · 第四单元","grade":"9b","tags":["九年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9b-u4-q1","type":"choice","stem":"1929—1933 年资本主义世界经济大危机的特点不包括","answer":"D","explain":"这次经济大危机的特点是涉及范围特别广、持续时间比较长、破坏性特别大。它从美国开始，迅速波及整个资本主义世界，并非只在英国发生。","options":["涉及范围特别广","持续时间比较长","破坏性特别大","只在英国一国发生"],"tags":["经济大危机","历史解释"]},{"id":"h9b-u4-q2","type":"choice","stem":"罗斯福新政的中心措施是","answer":"B","explain":"新政的中心措施是对工业的调整，通过《全国工业复兴法》加强国家对工业的计划指导。整顿金融、调整农业、以工代赈都是新政的重要措施，但不是中心措施。","options":["整顿金融体系","对工业的调整（《全国工业复兴法》）","调整农业政策","推行「以工代赈」，兴办公共工程"],"tags":["罗斯福新政","历史解释"]},{"id":"cat-9b-4-1-g2","type":"choice","stem":"下列关于「资本主义经济大危机」的表述，错误的是","answer":"A","explain":"认为罗斯福新政是社会主义性质的改革——判断改革性质看「是否改变社会制度」：新政不改变私有制与资产阶级统治，因此不是社会主义改革。正确表述：新政是在不改变资本主义制度前提下的自我调整：运用国家力量干预经济，目的是维护资本主义统治、缓解危机。","options":["认为罗斯福新政是社会主义性质的改革。","新政是在不改变资本主义制度前提下的自我调整：运用国家力量干预经济，目的是维护资本主义统治、缓解危机。","罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。","1929—1933 年经济大危机的特点与根源：特点是涉及范围特别广、持续时间比较长、破坏性特别大（整个资本主义世界的工业产量下降 1/3 以上，失业工人超过 3000 万）。根源是资本主义制度的基本矛盾，即生产社会化与生产资料私人占有之间的矛盾。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-1-g3","type":"choice","stem":"下列结论中，属于「资本主义经济大危机」的是","answer":"A","explain":"本课结论：罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。","世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","中国是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。","第二次世界大战改变了世界格局：欧洲衰落、美苏崛起，雅尔塔体系取代凡尔赛—华盛顿体系，战后又演变为美苏对峙的两极格局。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"h9b-u4-q6","type":"choice","stem":"1938 年，英、法、德、意四国首脑在没有捷克斯洛伐克代表参加的情况下，把苏台德区割让给德国。这一事件说明","answer":"A","explain":"慕尼黑会议把捷克斯洛伐克的苏台德区割让给德国，是绥靖政策达到顶峰的标志，助长了法西斯的侵略野心，加速了第二次世界大战的爆发。","options":["绥靖政策达到顶峰，加速了二战的爆发","法西斯国家的侵略被彻底制止","世界反法西斯同盟已经形成","德国的侵略野心得到有效遏制"],"tags":["慕尼黑会议","历史解释"]},{"id":"cat-9b-4-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 希特勒出任德国总理，德国建立法西斯专政\n② 日本军部法西斯专政建立\n③ 慕尼黑会议","answer":"A","explain":"按时间顺序应为：①希特勒出任德国总理，德国建立法西斯专政（1933 年）→②日本军部法西斯专政建立（1936 年）→③慕尼黑会议（1938 年 9 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-2-g2","type":"choice","stem":"下列关于「法西斯国家的侵略扩张」的表述，错误的是","answer":"A","explain":"认为绥靖政策从慕尼黑会议开始——「开始」与「顶峰」是两问，慕尼黑会议是顶峰而非起点。正确表述：绥靖政策在 20 世纪 30 年代逐步推行（如纵容日本侵占中国东北、纵容意大利侵略埃塞俄比亚、纵容德国吞并奥地利），其顶峰是 1938 年 9 月的慕尼黑会议。","options":["认为绥靖政策从慕尼黑会议开始。","绥靖政策在 20 世纪 30 年代逐步推行（如纵容日本侵占中国东北、纵容意大利侵略埃塞俄比亚、纵容德国吞并奥地利），其顶峰是 1938 年 9 月的慕尼黑会议。","世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","中国是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-2-g3","type":"choice","stem":"下列结论中，属于「法西斯国家的侵略扩张」的是","answer":"A","explain":"本课结论：世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。","第二次世界大战改变了世界格局：欧洲衰落、美苏崛起，雅尔塔体系取代凡尔赛—华盛顿体系，战后又演变为美苏对峙的两极格局。","中国是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"h9b-u4-q4","type":"choice","stem":"世界反法西斯同盟正式形成的标志是","answer":"B","explain":"1942 年 1 月 1 日，美、英、苏、中等 26 国签署《联合国家宣言》，标志世界反法西斯同盟正式形成。雅尔塔会议是 1945 年召开的战后安排会议，诺曼底登陆开辟欧洲第二战场，斯大林格勒战役是二战的转折点。","options":["雅尔塔会议的召开","1942 年 1 月 1 日《联合国家宣言》的签署","诺曼底登陆的成功","斯大林格勒战役的胜利"],"tags":["世界反法西斯同盟","时空观念"]},{"id":"h9b-u4-q5","type":"choice","stem":"第二次世界大战的转折点是","answer":"B","explain":"斯大林格勒战役（1942 年 7 月—1943 年 2 月）是苏德战场的转折点，也是第二次世界大战的转折点。诺曼底登陆开辟了欧洲第二战场，雅尔塔会议是战后的安排会议。","options":["莫斯科保卫战","斯大林格勒战役","诺曼底登陆","雅尔塔会议"],"tags":["第二次世界大战","历史解释"]},{"id":"cat-9b-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：通过《紧急银行法》《农业调整法》《全国工业复兴法》等，加强国家对经济的干预和指导，缓解危机。（2024 部编版九下第 13 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"资本主义经济大危机；1929—1933 年经济大危机的特点与根源：特点是涉及范围特别广、持续时间比较长、破坏性特别大（整个资本主义世界的工业产量下降 1/3 以上，失业工人超过 3000 万）。根源是资本主义制度的基本矛盾，即生产社会化与生产资料私人占有之间的矛盾。","explain":"材料出自2024 部编版九下第 13 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-4-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1938 年 9 月，英、法、德、意四国首脑在慕尼黑签订协定，把捷克斯洛伐克的苏台德地区割让给德国，捷方未参会。（吴于廑、齐世荣《世界史·现代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"法西斯国家的侵略扩张；二战的性质与影响：二战是世界范围内反法西斯的正义战争；它彻底粉碎了法西斯主义和军国主义通过战争称霸世界的野心，给人类带来空前灾难（先后有 60 多个国家和地区、20 亿以上人口卷入，死亡 5000 多万人）；战后欧洲衰落、美苏崛起，形成美苏对峙的两极格局；促进了民族解放运动的发展和科学技术的进步。","explain":"材料出自吴于廑、齐世荣《世界史·现代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9b-u5","title":"第二次世界大战后的世界变化 单元测试","subtitle":"九年级下册 · 第五单元","grade":"9b","tags":["九年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9b-u5-q1","type":"choice","stem":"标志着美苏冷战开始的事件是","answer":"A","explain":"1947 年 3 月杜鲁门在国会发表演说，公开宣称要「遏制」共产主义，杜鲁门主义的出台标志美苏冷战开始。马歇尔计划是冷战在经济上的表现，北约与华约的成立标志两极格局最终形成。","options":["1947 年杜鲁门主义的出台","1947 年马歇尔计划的提出","1949 年北大西洋公约组织的成立","1955 年华沙条约组织的成立"],"tags":["冷战","时空观念"]},{"id":"h9b-u5-q2","type":"choice","stem":"标志着以美苏为首的两大集团对峙局面（两极格局）最终形成的事件是","answer":"C","explain":"1949 年北约成立后，1955 年苏联与东欧 7 国成立华沙条约组织，以美苏为首的两大集团对峙局面最终形成，两极格局由此确立。","options":["1949 年德国分裂","1949 年北约成立","1955 年华约成立","1962 年古巴导弹危机"],"tags":["两极格局","时空观念"]},{"id":"cat-9b-5-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杜鲁门主义出台，冷战开始\n② 马歇尔计划提出\n③ 德国分裂为联邦德国和民主德国\n④ 华沙条约组织成立，两极格局最终形成","answer":"A","explain":"按时间顺序应为：①杜鲁门主义出台，冷战开始（1947 年 3 月）→②马歇尔计划提出（1947 年 6 月）→③德国分裂为联邦德国和民主德国（1949 年）→④华沙条约组织成立，两极格局最终形成（1955 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-1-g2","type":"choice","stem":"下列关于「冷战的发生与两极格局的形成」的表述，错误的是","answer":"A","explain":"认为冷战开始的标志是马歇尔计划的提出或北约的成立——「冷战开始」与「两极格局形成」是两件事，两个时间点必须分别对应，不能互换。正确表述：1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","options":["认为冷战开始的标志是马歇尔计划的提出或北约的成立。","1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","世界格局多极化趋势在冷战结束后加速发展；和平与发展是当今时代的主题，各国应加强合作、共同发展。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-1-g3","type":"choice","stem":"下列结论中，属于「冷战的发生与两极格局的形成」的是","answer":"A","explain":"本课结论：冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。","苏联解体、东欧剧变说明苏联模式的失败，社会主义运动遭受严重挫折；但中国特色社会主义的成功证明社会主义制度具有强大的生命力——改革必须坚持正确方向、立足本国国情。","改革必须坚持正确方向、立足国情：戈尔巴乔夫改革背离社会主义方向、放弃党的领导，最终导致国家解体；中国改革开放坚持党的领导与社会主义道路，取得巨大成就。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"h9b-u5-q5","type":"choice","stem":"在欧洲共同体的基础上成立、1993 年正式诞生的欧洲区域一体化组织是","answer":"B","explain":"1951 年成立欧洲煤钢共同体，1967 年成立欧洲共同体，1993 年在欧共体基础上成立欧洲联盟，欧洲一体化进程加快。北约与华约是军事政治集团。","options":["欧洲煤钢共同体","欧洲联盟","北大西洋公约组织","华沙条约组织"],"tags":["欧洲联合","时空观念"]},{"id":"cat-9b-5-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 欧洲走向联合：欧洲煤钢共同体成立，欧洲共同体成立\n② 日本经济持续高速发展\n③ 欧洲联盟成立","answer":"A","explain":"按时间顺序应为：①欧洲走向联合：欧洲煤钢共同体成立，欧洲共同体成立（1951 年、1967 年）→②日本经济持续高速发展（20 世纪 60—70 年代）→③欧洲联盟成立（1993 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-2-g2","type":"choice","stem":"下列关于「二战后资本主义国家的变化」的表述，错误的是","answer":"A","explain":"认为冷战开始的标志是马歇尔计划的提出或北约的成立——「冷战开始」与「两极格局形成」是两件事，两个时间点必须分别对应，不能互换。正确表述：1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","options":["认为冷战开始的标志是马歇尔计划的提出或北约的成立。","1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-2-g3","type":"choice","stem":"下列结论中，属于「二战后资本主义国家的变化」的是","answer":"A","explain":"本课结论：冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","世界格局多极化趋势在冷战结束后加速发展；和平与发展是当今时代的主题，各国应加强合作、共同发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。","苏联解体、东欧剧变说明苏联模式的失败，社会主义运动遭受严重挫折；但中国特色社会主义的成功证明社会主义制度具有强大的生命力——改革必须坚持正确方向、立足本国国情。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"h9b-u5-q3","type":"choice","stem":"苏联解体的根本原因是","answer":"B","explain":"根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；直接原因是戈尔巴乔夫改革失败，西方「和平演变」与东欧剧变是外部因素。","options":["西方国家的「和平演变」","高度集中的政治经济体制的弊端长期得不到纠正","戈尔巴乔夫个人的错误决策","东欧剧变的冲击"],"tags":["苏联解体","唯物史观"]},{"id":"h9b-u5-m1-q2","type":"short","stem":"（2）综合三则材料并结合所学，说明冷战的主要表现，并分析苏联解体的原因及影响。（6 分）","answer":"主要表现：政治上出台杜鲁门主义；经济上推行马歇尔计划，援助西欧；军事上 1949 年成立北大西洋公约组织，1955 年苏联等国成立华沙条约组织，形成两大集团对峙，两极格局最终形成；1949 年德国分裂，欧洲成为冷战的重点地区。苏联解体的原因：根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；直接原因是戈尔巴乔夫改革失败；外部原因是西方国家的「和平演变」。影响：标志冷战结束、两极格局终结，世界格局向多极化方向发展；社会主义运动遭受严重挫折，但中国特色社会主义的成功证明社会主义制度具有强大的生命力。","explain":"","tags":["冷战","苏联解体","历史解释"],"rubric":["政治：杜鲁门主义","经济：马歇尔计划","军事：北约与华约的成立（两极格局最终形成）","苏联解体根本原因：高度集中的政治经济体制弊端长期得不到纠正","影响：冷战结束、两极格局终结、多极化趋势加强"]},{"id":"cat-9b-5-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1947 年 3 月，美国总统杜鲁门在国会演说中提出遏制共产主义的主张，被视为冷战开始的标志。（吴于廑、齐世荣《世界史·现代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"冷战的发生与两极格局的形成；冷战的含义、开始标志与主要表现：冷战是二战后以美国和苏联为首的两大集团之间既非战争又非和平的对峙与竞争状态。1947 年 3 月杜鲁门主义的出台标志冷战开始；主要表现是政治上杜鲁门主义、经济上马歇尔计划、军事上北约与华约的成立，1949 年德国分裂是欧洲冷战的焦点。","explain":"材料出自吴于廑、齐世荣《世界史·现代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9b-u6","title":"当代世界的主要发展趋势 单元测试","subtitle":"九年级下册 · 第六单元","grade":"9b","tags":["九年级下册","单元测试","本课同步"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"单元测试"},{"k":"题量","v":"选择题 10 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"45 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9b-u6-q3","type":"choice","stem":"1971 年，第 26 届联合国大会通过决议，恢复中华人民共和国在联合国的一切合法权利。这最能说明","answer":"B","explain":"中国是联合国创始会员国和安理会常任理事国，1971 年是恢复合法席位，反映中国国际地位不断提高。多极化是发展趋势，不能说格局已经形成。","options":["中国开始成为联合国的会员国","中国的国际地位不断提高","联合国已被中国所控制","世界多极化格局已经形成"],"tags":["联合国","中国与世界"]},{"id":"h9b-u6-q4","type":"choice","stem":"对经济全球化，下列认识正确的是","answer":"B","explain":"经济全球化是一把「双刃剑」：促进世界经济发展与交流，也加剧了不平等与风险传递。它是不可逆转的趋势，各国应积极参与、趋利避害，同时维护国家主权与经济安全。","options":["经济全球化只有利于发达国家，发展中国家应拒绝参与","经济全球化是不可逆转的趋势，既是机遇也是挑战，应趋利避害","经济全球化已使各国发展水平趋于一致","经济全球化意味着国家主权可以放弃"],"tags":["经济全球化","历史解释"]},{"id":"h9b-u6-q5","type":"choice","stem":"冷战结束后，世界格局的发展趋势是","answer":"B","explain":"苏联解体后两极格局终结，美国成为唯一超级大国，欧盟、日本、俄罗斯、中国等多个力量中心崛起，世界呈现「一超多强」局面，多极化趋势不断加强，但新的世界格局尚未最终形成。","options":["两极格局进一步加强","呈现「一超多强」局面，多极化趋势不断加强","多极化格局已经完全形成","世界重新回到殖民体系"],"tags":["多极化","时空观念"]},{"id":"cat-9b-6-1-g2","type":"choice","stem":"下列关于「当代世界发展的基本特点」的表述，错误的是","answer":"A","explain":"认为世界多极化格局已经形成——「趋势」不等于「已形成」，这类绝对化表述通常判错。正确表述：多极化是发展趋势，当前仍呈现「一超多强」局面，新的世界格局尚未最终形成。","options":["认为世界多极化格局已经形成。","多极化是发展趋势，当前仍呈现「一超多强」局面，新的世界格局尚未最终形成。","经济全球化是不可逆转的趋势，但要趋利避害：既要积极参与国际合作与竞争，又要增强自主创新能力、维护国家经济安全。","世界多极化趋势有利于遏制霸权主义和强权政治、维护世界和平与稳定；中国是推动世界多极化、维护世界和平的重要力量。"],"difficulty":2,"tags":["九年级下册","第六单元","本课练习"]},{"id":"h9b-u6-q6","type":"choice","stem":"面对气候变化、恐怖主义等全球性问题，中国为全球治理贡献的方案是","answer":"A","explain":"中国提出构建人类命运共同体理念，倡导各国共商共建共享、合作应对全球性问题，为全球治理贡献了中国智慧和中国方案，与霸权主义、贸易保护主义的做法根本不同。","options":["构建人类命运共同体","推行霸权主义和强权政治","实行贸易保护主义","退出国际组织，单独应对"],"tags":["人类命运共同体","家国情怀"]},{"id":"cat-9b-6-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 联合国正式成立\n② 中国恢复在联合国的合法席位\n③ 世界贸易组织成立\n④ 中国提出构建人类命运共同体理念","answer":"A","explain":"按时间顺序应为：①联合国正式成立（1945 年 10 月 24 日）→②中国恢复在联合国的合法席位（1971 年 10 月）→③世界贸易组织成立（1995 年 1 月 1 日）→④中国提出构建人类命运共同体理念（2013 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第六单元","本课练习"]},{"id":"cat-9b-6-2-g2","type":"choice","stem":"下列关于「和平发展合作共赢的历史潮流」的表述，错误的是","answer":"A","explain":"认为中国是 1971 年才加入联合国的——「加入」与「恢复合法席位」含义完全不同，是常见的表述类失分点。正确表述：中国是联合国的创始会员国和安理会常任理事国；1971 年第 26 届联大是恢复中华人民共和国在联合国的一切合法权利。","options":["认为中国是 1971 年才加入联合国的。","中国是联合国的创始会员国和安理会常任理事国；1971 年第 26 届联大是恢复中华人民共和国在联合国的一切合法权利。","面对全球性问题，各国应加强合作、共商共建共享；构建人类命运共同体是中国为全球治理贡献的方案，体现了中国的大国担当。","联合国的宗旨与作用：1945 年 10 月 24 日成立，宗旨是维护国际和平与安全、促进国际合作。它在维护世界和平、缓和国际紧张局势、解决地区冲突、促进国际合作等方面发挥了积极作用；但曾一度被大国操纵，作用受到制约。中国是联合国创始会员国和安理会常任理事国，1971 年恢复在联合国的合法席位，成为维护世界和平与发展的重要力量。"],"difficulty":2,"tags":["九年级下册","第六单元","本课练习"]},{"id":"h9b-u6-q1","type":"choice","stem":"世界贸易组织正式成立于","answer":"C","explain":"世界贸易组织于 1995 年 1 月 1 日正式成立，取代关税与贸易总协定。1945 年是联合国成立的时间，1971 年中国恢复在联合国的合法席位，2001 年 12 月中国正式加入世界贸易组织。","options":["1945 年","1971 年","1995 年 1 月 1 日","2001 年 12 月"],"tags":["世界贸易组织","时空观念"]},{"id":"h9b-u6-q2","type":"choice","stem":"中国正式加入世界贸易组织的时间是","answer":"D","explain":"2001 年 12 月，中国正式加入世界贸易组织，主动融入经济全球化的进程，促进了中国经济发展，也为世界经济增长作出了贡献。","options":["1971 年","1978 年","1995 年","2001 年"],"tags":["世界贸易组织","中国与世界"]},{"id":"cat-9b-6-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 联合国正式成立\n② 中国恢复在联合国的合法席位\n③ 苏联解体后世界朝多极化方向发展\n④ 世界贸易组织成立","answer":"A","explain":"按时间顺序应为：①联合国正式成立（1945 年 10 月 24 日）→②中国恢复在联合国的合法席位（1971 年 10 月）→③苏联解体后世界朝多极化方向发展（1991 年）→④世界贸易组织成立（1995 年 1 月 1 日）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第六单元","本课练习"]},{"id":"h9b-u6-m1-q2","type":"short","stem":"（2）依据材料二、三并结合所学，说明经济全球化的表现与影响，以及中国应如何应对。（6 分）","answer":"表现：国际贸易和国际投资迅速增长，跨国公司的影响增大，生产活动的全球化分工日益明显。影响：经济全球化促进了世界经济的发展和科技、文化的交流，为发展中国家提供了引进资金、技术和先进管理经验的机会；但全球化由发达国家主导，发展中国家在国际竞争中处于不利地位，经济风险（如金融危机）也会迅速传递。应对：经济全球化是不可逆转的趋势，中国应顺应潮流、趋利避害——坚持对外开放，积极参与国际经济合作与竞争（如加入世界贸易组织），增强自主创新能力，维护国家经济安全；同时推动建立公正合理的国际经济新秩序，加强国际合作，共同应对全球性问题，倡导构建人类命运共同体。","explain":"","tags":["经济全球化","全球治理","历史解释"],"rubric":["表现：国际贸易与投资增长、跨国公司影响增大","积极影响：促进世界经济发展与科技文化交流","消极影响：发达国家主导，发展中国家处于不利地位","应对：趋利避害、坚持对外开放、维护国家经济安全","应对：推动国际经济新秩序、构建人类命运共同体"]},{"id":"cat-9b-6-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：美国、欧盟、日本、俄罗斯、中国等力量中心相互制约，世界格局呈现「一超多强」并朝多极化发展。（2024 部编版九下第 20 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"当代世界发展的基本特点；经济全球化：20 世纪 90 年代以来趋势加速。表现是国际贸易和国际投资迅速增长、跨国公司影响增大、生产活动的全球化分工日益明显。影响：促进了世界经济发展和科技文化交流，为发展中国家提供引进资金技术的机会；但全球化由发达国家主导，发展中国家在国际竞争中处于不利地位，经济风险也会迅速传递。","explain":"材料出自2024 部编版九下第 20 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-7a-cross","title":"七年级上册 跨单元测试","subtitle":"七年级上册 · 全册跨单元","grade":"7a","tags":["七年级上册","跨单元测试","综合"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"跨单元测试"},{"k":"题量","v":"选择题 16 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u1-q1","type":"choice","stem":"我国境内目前已知最早的古人类之一，距今约 170 万年，其化石发现于今云南省的是","answer":"A","explain":"元谋人发现于云南元谋，距今约 170 万年，是我国境内目前已知最早的古人类之一。","options":["元谋人","北京人","山顶洞人","半坡人"],"tags":["史前时期","时空观念"]},{"id":"h7a-u2-q1","type":"choice","stem":"「大道之行也，天下为公，选贤与能……今大道既隐，天下为家。」「天下为家」开始于","answer":"B","explain":"启继承禹的王位，世袭制代替禅让制，「公天下」变为「家天下」。","options":["禹建立夏朝","启继承王位","汤灭夏建商","武王伐纣"],"tags":["世袭制","历史解释"]},{"id":"h7a-u3-q1","type":"choice","stem":"秦朝在地方上推行的、对后世影响最深远的制度是","answer":"B","explain":"郡县制下郡县长官由皇帝直接任免、不世袭，开创了此后两千多年的中央集权地方行政制度。行省制是元朝，科举制是隋朝。","options":["分封制","郡县制","行省制","科举制"],"tags":["郡县制","制度创新"]},{"id":"h7a-u4-q1","type":"choice","stem":"为三国鼎立局面形成奠定基础的战役是","answer":"B","explain":"208 年赤壁之战中孙刘联军打败曹操，为三国鼎立局面的形成奠定基础。官渡之战为曹操统一北方奠定基础。","options":["官渡之战","赤壁之战","淝水之战","巨鹿之战"],"tags":["赤壁之战","时空观念"]},{"id":"cat-7a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 元谋人生活在云南元谋\n② 北京人生活在周口店\n③ 山顶洞人","answer":"A","explain":"按时间顺序应为：①元谋人生活在云南元谋（约 170 万年前）→②北京人生活在周口店（约 70 万—20 万年前）→③山顶洞人（约 3 万年前）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7a-u2-q2","type":"choice","stem":"「封建亲戚，以藩屏周」反映的西周制度是","answer":"B","explain":"分封制把土地和人民分给宗亲、功臣，让他们建立诸侯国，起到拱卫王室的作用。","options":["禅让制","分封制","郡县制","世袭制"],"tags":["分封制","史料实证"]},{"id":"cat-7a-3-1-g2","type":"choice","stem":"下列关于「秦统一中国」的表述，错误的是","answer":"A","explain":"把「推恩令」与「分封制」混为一谈——它表面是「恩」，实质是削藩，材料题常问「高明之处」。正确表述：推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","options":["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","秦朝巩固统一的措施：皇帝制、三公九卿、郡县制；统一文字（小篆）、货币（圆形方孔半两钱）、度量衡；修长城、开灵渠。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-4-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 官渡之战\n② 赤壁之战\n③ 曹丕称帝建魏，定都洛阳","answer":"A","explain":"按时间顺序应为：①官渡之战（200 年）→②赤壁之战（208 年）→③曹丕称帝建魏，定都洛阳（220 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-1-1-g2","type":"choice","stem":"下列关于「远古时期的人类活动」的表述，错误的是","answer":"A","explain":"认为北京人会人工取火——这是最常见的混淆点，选项常把两者对调。正确表述：北京人会使用天然火并保存火种；人工取火是山顶洞人。","options":["认为北京人会人工取火。","北京人会使用天然火并保存火种；人工取火是山顶洞人。","中华文明的起源具有**本土性**（元谋人、北京人一脉相承）与**多元一体**（黄河流域、长江流域等多点并发）两大特征。","北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 禹建立夏朝\n② 武王伐纣，牧野之战后建立西周\n③ 犬戎攻破镐京，西周灭亡","answer":"A","explain":"按时间顺序应为：①禹建立夏朝（约公元前 2070 年）→②武王伐纣，牧野之战后建立西周（公元前 1046 年）→③犬戎攻破镐京，西周灭亡（公元前 771 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-3-1-g3","type":"choice","stem":"下列结论中，属于「秦统一中国」的是","answer":"A","explain":"本课结论：秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-4-1-g2","type":"choice","stem":"下列关于「三国鼎立」的表述，错误的是","answer":"A","explain":"认为赤壁之战使曹操统一了全国——官渡之战与赤壁之战的结果、意义最容易被调换。正确表述：赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","options":["认为赤壁之战使曹操统一了全国。","赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"cat-7a-2-1-g2","type":"choice","stem":"下列关于「夏商西周王朝的更替」的表述，错误的是","answer":"A","explain":"把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」——制度与朝代配对是最常设的陷阱，答题前先想「哪个朝代」。正确表述：分封制是西周的制度；夏朝是世袭制王朝。","options":["把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」。","分封制是西周的制度；夏朝是世袭制王朝。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","夏朝是我国历史上第一个王朝，世袭制代替禅让制，「公天下」变为「家天下」。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"h7a-u3-q2","type":"choice","stem":"汉武帝采纳主父偃建议颁布「推恩令」，其高明之处在于","answer":"B","explain":"推恩令让诸侯王的子弟分封土地，封国越分越小，中央集权得到加强，且避免了激化矛盾。","options":["直接剥夺诸侯王的封地","使诸侯国越分越小，不费兵卒削弱了诸侯势力","以武力镇压诸侯叛乱","废除分封，全面推行郡县"],"tags":["推恩令","历史解释"]},{"id":"cat-7a-4-1-g3","type":"choice","stem":"下列结论中，属于「三国鼎立」的是","answer":"A","explain":"本课结论：分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","文化成就与时代相关：战乱与民族交融时期，宗教艺术（石窟）与书法艺术特别兴盛。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"h7a-u1-m1-q1","type":"short","stem":"（1）材料一中的灰烬层能说明北京人已经掌握了什么技能？这一发现有何意义？（4 分）","answer":"说明北京人已经会使用火并能够保存火种。意义：火的使用改善了生存条件（烧烤食物、照明、取暖、驱赶野兽），是人类进化过程中的重大进步；周口店遗址是研究人类起源的直接证据。","explain":"","tags":["史料实证","史前时期"],"rubric":["答出「使用火、保存火种」","答出火的作用（取暖/熟食/驱兽任一点）","答出遗址的史料价值"]},{"id":"cat-7a-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1921 年安特生、师丹斯基在北京周口店龙骨山发现遗址；1929 年 12 月裴文中发掘出第一个完整的北京人头盖骨化石。此后陆续发现 40 多个个体的人骨化石。（中国社会科学院考古研究所《北京人遗址》相关记述）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"远古时期的人类活动；北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。","explain":"材料出自中国社会科学院考古研究所《北京人遗址》相关记述。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-7b-cross","title":"七年级下册 跨单元测试","subtitle":"七年级下册 · 全册跨单元","grade":"7b","tags":["七年级下册","跨单元测试","综合"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"跨单元测试"},{"k":"题量","v":"选择题 16 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7b-u1-q1","type":"choice","stem":"605 年起下令开凿大运河，以洛阳为中心、北抵涿郡、南至余杭的皇帝是","answer":"B","explain":"大运河由隋炀帝下令开凿（605 年起），以洛阳为中心，北抵涿郡，南至余杭，是古代世界上最长的运河。隋文帝的功绩是统一全国、创立三省六部制与分科考试选官。","options":["隋文帝","隋炀帝","唐高祖","唐玄宗"],"tags":["大运河","时空观念"]},{"id":"h7b-u2-q1","type":"choice","stem":"宋太祖「杯酒释兵权」，并推行重文轻武的政策，其主要目的是","answer":"B","explain":"宋太祖吸取唐末以来武将专权、藩镇割据的教训，通过解除禁军将领兵权、重用文臣等办法防止武将专权，加强中央集权。其结果是军队战斗力有所削弱、财政负担加重。","options":["提高军队的战斗力","防止武将专权，加强中央集权","减轻农民的赋税负担","增加国家的财政收入"],"tags":["重文轻武","中央集权"]},{"id":"h7b-u3-q6","type":"choice","stem":"清朝雍正帝设立、使君主专制进一步强化的机构是","answer":"C","explain":"雍正帝时设立军机处，军机大臣只是跪受笔录、传达皇帝的旨意，君主专制进一步强化。锦衣卫、东厂是明朝的特务机构。","options":["中书省","内阁","军机处","锦衣卫"],"tags":["军机处","君主专制"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"cat-7b-2-1-g2","type":"choice","stem":"下列关于「北宋的政治」的表述，错误的是","answer":"A","explain":"认为经济重心南移完成于唐朝——「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。正确表述：经济重心南移**从唐朝中期开始，到南宋时最后完成**。","options":["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-3-1-g2","type":"choice","stem":"下列关于「明朝的统治」的表述，错误的是","answer":"A","explain":"认为郑和下西洋是为了开拓海外殖民地、发展海外贸易——它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。正确表述：郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","options":["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","明朝强化皇权：中央废除丞相和中书省，权力分给六部；地方废除行省，设立三司；设锦衣卫、东厂等特务机构；实行八股取士。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"h7b-u1-q6","type":"choice","stem":"关于五代十国，下列说法正确的是","answer":"A","explain":"五代十国是唐末藩镇割据局面的延续。北方政权更迭频繁、战乱不断；南方相对安定，经济得到发展；统一始终是历史发展的必然趋势。","options":["五代十国是唐末以来藩镇割据局面的延续","五代十国时期南方经济遭到严重破坏","五代十国都是由少数民族建立的政权","五代十国时期全国长期处于统一状态"],"tags":["五代十国","历史解释"]},{"id":"cat-7b-2-1-g3","type":"choice","stem":"下列结论中，属于「北宋的政治」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-3-1-g3","type":"choice","stem":"下列结论中，属于「明朝的统治」的是","answer":"A","explain":"本课结论：明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杨坚夺取北周政权，建立隋朝，定都长安\n② 隋炀帝下令开凿大运河\n③ 设置进士科，科举制正式确立\n④ 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","answer":"A","explain":"按时间顺序应为：①杨坚夺取北周政权，建立隋朝，定都长安（581 年）→②隋炀帝下令开凿大运河（605 年起）→③设置进士科，科举制正式确立（隋炀帝时）→④隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-2-1-g5","type":"choice","stem":"「赵匡胤建立北宋，定都东京（今河南开封）」发生于","answer":"A","explain":"本课时间轴：赵匡胤建立北宋，定都东京（今河南开封）（960 年）。赵匡胤即宋太祖；他「杯酒释兵权」，解除禁军将领的兵权，推行重文轻武政策。其余三个时间是同一单元相邻课时的事件时间。","options":["960 年","1005 年","1038 年","1115 年"],"difficulty":1,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-3-1-g5","type":"choice","stem":"「朱元璋建立明朝，定都应天府（今江苏南京）」发生于","answer":"A","explain":"本课时间轴：朱元璋建立明朝，定都应天府（今江苏南京）（1368 年）。朱元璋即明太祖；同年明军攻占大都，元朝在全国的统治结束。其余三个时间是同一单元相邻课时的事件时间。","options":["1368 年","16 世纪中期","1553 年","1616 年"],"difficulty":1,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-1-1-g2","type":"choice","stem":"下列关于「隋朝统一与灭亡」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h7b-u2-q2","type":"choice","stem":"宋辽之间保持长时间的和平局面，开始于","answer":"B","explain":"1005 年宋辽订立澶渊之盟，北宋每年给辽岁币，此后很长时间里宋辽保持了和平局面，边境贸易发展。","options":["北宋建立","澶渊之盟的订立","靖康之变","宋金议和"],"tags":["澶渊之盟","时空观念"]},{"id":"h7b-u3-q2","type":"choice","stem":"郑和下西洋最远到达的地区是","answer":"B","explain":"1405—1433 年郑和七次下西洋，到达亚非三十多个国家和地区，最远到达非洲东海岸和红海沿岸，是世界航海史上的空前壮举。","options":["印度半岛南端","非洲东海岸和红海沿岸","波斯湾沿岸","美洲西海岸"],"tags":["郑和下西洋","时空观念"]},{"id":"cat-7b-1-1-g3","type":"choice","stem":"下列结论中，属于「隋朝统一与灭亡」的是","answer":"A","explain":"本课结论：科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：永济渠（洛阳至涿郡）、通济渠（洛阳至淮水）、邗沟（淮水至江都入长江）、江南河（长江至余杭），沟通海河、黄河、淮河、长江、钱塘江五大水系。（《隋书·食货志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"隋朝统一与灭亡；隋朝的制度创新与统一：结束分裂、实现统一，创立科举制与三省六部制，开凿大运河，为唐朝的繁荣奠定了基础。","explain":"材料出自《隋书·食货志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h7b-u1-m1-q2","type":"short","stem":"（2）材料二、三分别反映了唐太宗怎样的治国做法？这些做法与「贞观之治」的出现有何关系？（5 分）","answer":"材料二反映唐太宗重视百姓、以民为本，注意减轻百姓负担（这是吸取隋亡教训的结果）；材料三反映他重视科举取士、笼络人才、扩大统治基础。关系：正因为唐太宗减轻赋税徭役、虚心纳谏、知人善任，并进一步完善三省六部制与科举制，才使政治比较清明、经济得到恢复和发展、社会秩序安定、国力增强，从而出现了「贞观之治」的局面。","explain":"","tags":["贞观之治","历史解释"],"rubric":["材料二：以民为本、重视百姓（减轻负担）","材料三：重视科举取士、重用人才","答出措施与治世之间的因果对应","答出贞观之治的表现（政治清明/经济发展/社会安定）"]}]},{"id":"hp-8a-cross","title":"八年级上册 跨单元测试","subtitle":"八年级上册 · 全册跨单元","grade":"8a","tags":["八年级上册","跨单元测试","综合"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"跨单元测试"},{"k":"题量","v":"选择题 16 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8a-u1-q1","type":"choice","stem":"英国发动鸦片战争的根本原因是","answer":"B","explain":"鸦片战争是英国资本主义发展的必然结果：工业革命后英国急需商品市场和原料产地。虎门销烟只是英国发动战争的借口，即直接原因。","options":["林则徐在虎门销烟","英国为打开中国市场、推销工业品并掠夺原料","清政府闭关自守、禁止通商","中英两国贸易长期不平衡"],"tags":["鸦片战争","历史解释"]},{"id":"h8a-u2-q1","type":"choice","stem":"洋务运动「只学习西方技术而不改变封建制度」，导致其最终破产。标志其破产的事件是","answer":"B","explain":"1895 年初威海卫战役中北洋舰队全军覆没，甲午战争中国战败，宣告了洋务运动的破产，也说明单靠引进技术不能救中国。","options":["太平天国运动失败","甲午中日战争中国战败、北洋舰队全军覆没","《辛丑条约》的签订","戊戌变法失败"],"tags":["洋务运动","历史解释"]},{"id":"h8a-u3-q1","type":"choice","stem":"孙中山提出的三民主义中，对应同盟会纲领「创立民国」的是","answer":"B","explain":"民族主义对应「驱除鞑虏，恢复中华」，民权主义对应「创立民国」，民生主义对应「平均地权」。民权主义是三民主义的核心。","options":["民族主义","民权主义","民生主义","民主主义"],"tags":["三民主义","历史解释"]},{"id":"h8a-u4-q1","type":"choice","stem":"新文化运动开始的标志是","answer":"B","explain":"1915 年陈独秀在上海创办《青年杂志》（自第二卷起改名《新青年》），标志新文化运动开始。《天演论》是维新变法的思想武器。","options":["严复译述《天演论》","陈独秀在上海创办《青年杂志》","五四运动爆发","中共一大召开"],"tags":["新文化运动","时空观念"]},{"id":"h8a-u5-q1","type":"choice","stem":"标志国共第一次合作正式建立的事件是","answer":"B","explain":"1924 年 1 月国民党一大召开，把旧三民主义发展为新三民主义，确立联俄、联共、扶助农工三大政策，标志国共第一次合作正式建立。黄埔军校创办是合作的成果。","options":["中共三大的召开","国民党一大在广州召开","黄埔军校创办","北伐战争开始"],"tags":["国共合作","时空观念"]},{"id":"h8a-u6-q1","type":"choice","stem":"中国人民抗日战争的起点，也是中国局部抗战开始的事件是","answer":"A","explain":"1931 年九一八事变是中国人民抗日战争的起点，中国人民的局部抗战由此开始；1937 年七七事变标志全民族抗战开始。","options":["九一八事变","华北事变","七七事变","八一三事变"],"tags":["九一八事变","时空观念"]},{"id":"h8a-u7-q1","type":"choice","stem":"1945 年毛泽东赴重庆谈判的主要目的是","answer":"A","explain":"毛泽东赴重庆谈判是为了尽一切可能争取和平、避免内战，同时揭穿蒋介石假和平真内战的阴谋，教育人民、争取政治上的主动。","options":["争取和平民主，揭穿蒋介石假和平真内战的阴谋","与国民党共同建立联合政府","争取美国对中共的支持","拖延时间准备内战"],"tags":["重庆谈判","历史解释"]},{"id":"h8a-u1-q2","type":"choice","stem":"《南京条约》的各项内容中，最能反映英国打开中国市场、便利经济侵略意图的是","answer":"C","explain":"五口通商打开了中国大门，协定关税破坏了中国关税自主权，使列强可以低价倾销商品、掠夺原料，最能体现其经济侵略意图。割地赔款是政治与财政层面的侵害。","options":["割香港岛给英国","赔款 2100 万银元","开放五处通商口岸并协定关税","英军占领广州"],"tags":["南京条约","史料实证"]},{"id":"h8a-u2-q3","type":"choice","stem":"「法者天下之公器也，变者天下之公理也」的提出者，也是戊戌变法主要领导人之一的是","answer":"B","explain":"此语出自梁启超《变法通议》。梁启超与康有为是维新变法的主要领导人，严复译述《天演论》宣传进化论，李鸿章是洋务派代表。","options":["李鸿章","梁启超","严复","孙中山"],"tags":["戊戌变法","历史解释"]},{"id":"h8a-u3-q2","type":"choice","stem":"辛亥革命爆发的标志性事件是","answer":"B","explain":"1911 年 10 月 10 日武昌起义爆发，各省纷纷响应，清朝统治迅速崩溃。因 1911 年为农历辛亥年，故称辛亥革命。","options":["黄花岗起义","武昌起义","中华民国成立","《中华民国临时约法》颁布"],"tags":["武昌起义","时空观念"]},{"id":"h8a-u4-q2","type":"choice","stem":"五四运动爆发的导火线是","answer":"B","explain":"1919 年巴黎和会拒绝中国正当要求，竟将德国在山东的特权转让给日本，消息传回国内直接引发五四运动。","options":["日本提出「二十一条」","巴黎和会上中国外交的失败","北洋政府镇压学生游行","中国共产党号召反帝反封建"],"tags":["五四运动","历史解释"]},{"id":"h8a-u5-q3","type":"choice","stem":"1927 年秋收起义受挫后，毛泽东率部队向井冈山进军，其深远意义在于","answer":"B","explain":"秋收起义受挫后转向农村，创建井冈山革命根据地，开辟了农村包围城市、武装夺取政权的道路，这是马克思主义与中国国情相结合的正确道路。","options":["完成了北伐战争的任务","开创了农村包围城市、武装夺取政权的革命道路","促成了国共第二次合作","建立了中华苏维埃共和国"],"tags":["井冈山道路","历史解释"]},{"id":"h8a-u6-q2","type":"choice","stem":"西安事变和平解决的最重要意义是","answer":"B","explain":"西安事变的和平解决，标志着十年内战基本结束，抗日民族统一战线初步形成，成为扭转时局的关键。","options":["迫使蒋介石放弃了反共立场","标志十年内战基本结束，抗日民族统一战线初步形成","使红军获得了合法地位","标志抗日战争的胜利"],"tags":["西安事变","历史解释"]},{"id":"h8a-u7-q2","type":"choice","stem":"全面内战爆发的标志是","answer":"B","explain":"1946 年 6 月，国民党军队 20 多万人进攻中原解放区，标志着全面内战爆发。进攻延安与挺进大别山都发生在 1947 年。","options":["《双十协定》被撕毁","1946 年 6 月国民党军队进攻中原解放区","国民党军队进攻延安","刘邓大军挺进大别山"],"tags":["全面内战","时空观念"]},{"id":"cat-8a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 林则徐在广东虎门销烟\n② 鸦片战争\n③ 中英《南京条约》签订","answer":"A","explain":"按时间顺序应为：①林则徐在广东虎门销烟（1839 年 6 月）→②鸦片战争（1840 年 6 月—1842 年 8 月）→③中英《南京条约》签订（1842 年 8 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-2-1-g2","type":"choice","stem":"下列关于「洋务运动和边疆危机」的表述，错误的是","answer":"A","explain":"认为洋务运动是中国近代史的开端——「近代史」讲社会性质变化，「近代化」讲向工业化、民主化迈进，两个概念必须分清。正确表述：中国近代史的开端是鸦片战争；洋务运动是中国**近代化**的开端。","options":["认为洋务运动是中国近代史的开端。","中国近代史的开端是鸦片战争；洋务运动是中国**近代化**的开端。","近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","洋务运动：以「自强」「求富」为口号，创办安庆内军械所、江南机器制造总局、福州船政局等军事工业和轮船招商局、开平煤矿、汉阳铁厂、湖北织布局等民用企业，筹建北洋舰队等新式海陆军。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"h8a-u1-m1-q1","type":"short","stem":"（1）依据材料一，说明林则徐主张禁烟的原因；结合所学指出虎门销烟的意义。（4 分）","answer":"原因：鸦片大量输入使中国白银外流、财政困难（「无可以充饷之银」），并严重摧残吸食者的体质，军队战斗力削弱（「无可以御敌之兵」），危及清朝统治。意义：虎门销烟是中国人民禁烟斗争的伟大胜利，显示了中华民族反抗外来侵略的坚强意志，林则徐是当之无愧的民族英雄。","explain":"","tags":["虎门销烟","史料实证"],"rubric":["答出白银外流、财政困难","答出兵弱、摧残体质","答出禁烟斗争的伟大胜利","答出反抗侵略的坚强意志/民族英雄"]},{"id":"h8a-u1-m1-q2","type":"short","stem":"（2）依据材料二，指出《南京条约》中破坏中国关税自主权的条款，并结合材料三说明鸦片战争对中国社会性质的影响。（6 分）","answer":"条款：英商进出口货物应纳税款必须经过双方协议（协定关税）。影响：中国的领土完整和主权遭到破坏，开始沦为半殖民地；封建经济逐步解体，被卷入资本主义世界市场，开始沦为半封建。总之，鸦片战争后中国开始沦为半殖民地半封建社会，鸦片战争成为中国近代史的开端。","explain":"","tags":["南京条约","半殖民地半封建社会"],"rubric":["答出协定关税","答出领土、主权遭到破坏","答出封建经济开始解体","答出开始沦为半殖民地半封建社会","答出是中国近代史的开端"]}]},{"id":"hp-8b-cross","title":"八年级下册 跨单元测试","subtitle":"八年级下册 · 全册跨单元","grade":"8b","tags":["八年级下册","跨单元测试","综合"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"跨单元测试"},{"k":"题量","v":"选择题 16 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8b-u1-q1","type":"choice","stem":"标志着中国人民从此站起来了、成为国家的主人的历史事件是","answer":"B","explain":"1949 年 10 月 1 日开国大典宣告中华人民共和国中央人民政府成立，中国人民从此站起来了，成为国家的主人。政协会议是成立前的筹备，西藏和平解放与抗美援朝是新中国成立后巩固政权的措施。","options":["中国人民政治协商会议第一届全体会议召开","开国大典，中华人民共和国成立","西藏和平解放","抗美援朝战争取得胜利"],"tags":["新中国成立","时空观念"]},{"id":"h8b-u2-q4","type":"choice","stem":"被称为「探索建设社会主义道路的良好开端」的会议是","answer":"D","explain":"1956 年召开的中共八大正确分析了国内主要矛盾，提出集中力量发展社会生产力，是探索建设社会主义道路的良好开端。","options":["中共七大","第一届全国人民代表大会","中共十一届三中全会","中共八大"],"tags":["中共八大","历史解释"]},{"id":"h8b-u3-q1","type":"choice","stem":"中共十一届三中全会之所以被称为「新中国成立以来党的历史上具有深远意义的伟大转折」，主要是因为它","answer":"B","explain":"十一届三中全会冲破长期「左」的错误的严重束缚，确定解放思想、实事求是的指导方针，把工作中心转移到经济建设上来、实行改革开放，开启了改革开放和社会主义现代化建设新时期。建立社会主义市场经济体制的目标由 1992 年中共十四大提出。","options":["确立了毛泽东思想的指导地位","作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策","提出了建立社会主义市场经济体制的目标","宣布我国进入社会主义初级阶段"],"tags":["十一届三中全会","历史解释"]},{"id":"h8b-u3-q3","type":"choice","stem":"明确提出建立社会主义市场经济体制目标的会议是","answer":"D","explain":"1992 年中共十四大明确提出建立社会主义市场经济体制的目标。同年邓小平南方谈话指出计划和市场都是经济手段，为这一目标提供了思想基础。","options":["中共十二大","中共十三大","中共十五大","中共十四大"],"tags":["十四大","时空观念"]},{"id":"h8b-u3-q2","type":"choice","stem":"实行家庭联产承包责任制后，我国农村土地的所有权和经营权状况是","answer":"C","explain":"家庭联产承包责任制是在土地公有制的基础上改变经营管理方式，土地所有权仍归集体，农民通过承包获得经营权和收益，因而不是土地私有化。","options":["土地所有权和经营权都归农民","土地所有权归国家，经营权归农民","土地所有权归集体，农民获得承包经营权","土地所有权归农民，经营权归集体"],"tags":["家庭联产承包责任制","历史解释"]},{"id":"h8b-u3-q6","type":"choice","stem":"把习近平新时代中国特色社会主义思想确立为党的指导思想的会议是","answer":"B","explain":"2017 年中共十九大把习近平新时代中国特色社会主义思想确立为党的指导思想；中共十八大以来，中国特色社会主义进入新时代；中共二十大提出以中国式现代化全面推进中华民族伟大复兴。","options":["中共十八大","中共十九大","中共二十大","中共十八届三中全会"],"tags":["中共十九大","理论体系"]},{"id":"h8b-u1-q5","type":"choice","stem":"1949 年 9 月，中国人民政治协商会议第一届全体会议通过的、在 1954 年宪法颁布前起临时宪法作用的文件是","answer":"B","explain":"《共同纲领》是在 1954 年宪法颁布前起临时宪法作用的文件；1954 年宪法是我国第一部社会主义类型的宪法；《土地改革法》是 1950 年颁布的。","options":["《中华民国临时约法》","《中国人民政治协商会议共同纲领》","《中华人民共和国宪法》","《中华人民共和国土地改革法》"],"tags":["共同纲领","史料实证"]},{"id":"h8b-u2-q5","type":"choice","stem":"「大跃进」和人民公社化运动给我们的最主要教训是","answer":"C","explain":"这两次失误反映了人民群众迫切改变落后面貌的愿望，但急于求成、忽视客观经济规律，造成 1959—1961 年国民经济严重困难。教训是必须从国情出发、实事求是、按客观经济规律办事。","options":["必须以阶级斗争为纲","必须优先发展重工业","必须从国情出发，按客观经济规律办事","必须加快生产资料公有化的速度"],"tags":["大跃进","唯物史观"]},{"id":"cat-8b-3-1-g2","type":"choice","stem":"下列关于「伟大的历史转折」的表述，错误的是","answer":"A","explain":"把十一届三中全会的意义说成「标志我国进入社会主义社会」——两个时间点、两种表述，是选择题最常见的错项组合。正确表述：我国进入社会主义初级阶段以 1956 年三大改造基本完成为标志；十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折。","options":["把十一届三中全会的意义说成「标志我国进入社会主义社会」。","我国进入社会主义初级阶段以 1956 年三大改造基本完成为标志；十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","中共十一届三中全会的伟大转折：冲破长期「左」的错误的严重束缚，确定了解放思想、实事求是的指导方针；停止使用「以阶级斗争为纲」的口号，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策；实际上形成了以邓小平为核心的党的第二代中央领导集体。"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-4-1-g2","type":"choice","stem":"下列关于「加快改革开放和社会主义现代化建设…」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-5-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中共十一届三中全会召开\n② 安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏\n③ 深圳、珠海、汕头、厦门设立经济特区\n④ 开放大连、天津、青岛、上海、广州等 14 个沿海…","answer":"A","explain":"按时间顺序应为：①中共十一届三中全会召开（1978 年 12 月）→②安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏（1978 年冬）→③深圳、珠海、汕头、厦门设立经济特区（1980 年）→④开放大连、天津、青岛、上海、广州等 14 个沿海港口城市（1984 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-6-1-g2","type":"choice","stem":"下列关于「擘画中国梦宏伟蓝图」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。","中国特色社会主义进入新时代，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。"],"difficulty":2,"tags":["八年级下册","第六单元","本课练习"]},{"id":"cat-8b-1-1-g2","type":"choice","stem":"下列关于「中华人民共和国成立」的表述，错误的是","answer":"A","explain":"把《共同纲领》说成 1954 年宪法——「起临时宪法作用的文件」不等于「宪法」，这是两句不同的话。正确表述：1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","options":["把《共同纲领》说成 1954 年宪法。","1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利，中国人民从此站起来了，成为国家的主人，中国历史从此揭开了新的篇章。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 「大跃进」和农村人民公社化运动在全国展开\n② 实行「调整、巩固、充实、提高」的八字方针，调整国…\n③ 「文化大革命」","answer":"A","explain":"按时间顺序应为：①「大跃进」和农村人民公社化运动在全国展开（1958 年）→②实行「调整、巩固、充实、提高」的八字方针，调整国民经济（1961—1965 年）→③「文化大革命」（1966—1976 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"cat-8b-3-1-g5","type":"choice","stem":"「中共十一届三中全会召开」发生于","answer":"A","explain":"本课时间轴：中共十一届三中全会召开（1978 年 12 月）。确定解放思想、实事求是的指导方针，把党和国家工作中心转移到经济建设上来，实行改革开放。其余三个时间是同一单元相邻课时的事件时间。","options":["1978 年 12 月","1978 年冬","1980 年","1984 年"],"difficulty":1,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-4-1-g7","type":"choice","stem":"关于「加快改革开放和社会主义现代化建设…」，下列表述正确的有\n① 中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开…\n② 改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中…\n③ 只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色…\n④ 认为家庭联产承包责任制是把土地分给农民个人所有。","answer":"A","explain":"①②③均取本课必背结论与考点；④错误——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」，正确表述应为：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：五星红旗由曾联松设计；《义勇军进行曲》由田汉作词、聂耳作曲，原为电影《风云儿女》主题歌，1949 年被定为代国歌。（《中华人民共和国史》；2024 部编版八下第 1 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"中华人民共和国成立；1949 年 10 月 1 日的开国大典，标志着中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利。","explain":"材料出自《中华人民共和国史》；2024 部编版八下第 1 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h8b-u1-m1-q2","type":"short","stem":"（2）据材料二，土地改革废除的是什么制度、实行的是什么制度？据材料三并结合所学，说明土地改革的作用。（6 分）","answer":"废除地主阶级封建剥削的土地所有制，实行农民的土地所有制。作用：彻底摧毁了我国延续两千多年的封建土地制度，消灭了地主阶级；农民翻了身，成为土地的主人，人民政权更加巩固；大大解放了农村生产力，农业生产迅速恢复和发展，为国家工业化建设准备了条件。","explain":"","tags":["土地改革","历史解释"],"rubric":["答出「废除地主阶级封建剥削的土地所有制」","答出「实行农民的土地所有制」","答出「摧毁封建土地制度、消灭地主阶级」","答出「农民成为土地的主人／巩固人民政权」","答出「解放农村生产力／为国家工业化准备条件」"]}]},{"id":"hp-9a-cross","title":"九年级上册 跨单元测试","subtitle":"九年级上册 · 全册跨单元","grade":"9a","tags":["九年级上册","跨单元测试","综合"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"跨单元测试"},{"k":"题量","v":"选择题 16 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"h9a-u2-q1","type":"choice","stem":"伯里克利主政时期，雅典的民主政治发展到高峰。雅典民主政治的实质是","answer":"B","explain":"雅典的成年男性公民才有权参加公民大会、担任公职；妇女、奴隶和外邦人被排斥在外，因此它本质上是奴隶主阶级的民主，具有明显的阶级局限性。","options":["全体雅典居民的民主","成年男性公民的民主，即奴隶主阶级的民主","全体自由民的民主","妇女与奴隶同样享有权利的民主"],"tags":["雅典民主","历史解释"]},{"id":"h9a-u3-q1","type":"choice","stem":"西欧封君封臣制得以形成的纽带是","answer":"B","explain":"8 世纪前期，法兰克王国改革土地分封形式，不再无偿赏赐土地，受到封地的人必须提供兵役服务，封君封臣制由此形成，其纽带是土地的封赐。","options":["血缘关系","土地的封赐","共同的宗教信仰","军功的大小"],"tags":["封君封臣制","历史解释"]},{"id":"h9a-u4-q1","type":"choice","stem":"646 年，日本效仿中国唐朝的典章制度进行改革，这次改革史称","answer":"B","explain":"646 年（大化年间），日本孝德天皇推行改革，史称大化改新，主要是效仿唐朝的典章制度，使日本发展成为一个中央集权制的封建国家。","options":["明治维新","大化改新","农奴制改革","幕府改革"],"tags":["大化改新","时空观念"]},{"id":"h9a-u5-q1","type":"choice","stem":"文艺复兴的核心思想是","answer":"A","explain":"文艺复兴的核心思想是人文主义，即肯定人的价值与尊严，提倡发扬人的个性、追求现世的幸福，反对教会神权对人的束缚。理性主义是启蒙运动的核心。","options":["人文主义","理性主义","禁欲主义","重商主义"],"tags":["文艺复兴","历史解释"]},{"id":"h9a-u6-q1","type":"choice","stem":"英国资产阶级革命结束的标志是","answer":"B","explain":"1688 年，英国议会邀请荷兰执政威廉和玛丽共同入主英国，推翻复辟的斯图亚特王朝，史称「光荣革命」，标志英国资产阶级革命结束。1689 年《权利法案》的颁布则标志着君主立宪制的确立。","options":["1649 年查理一世被处死","1688 年的「光荣革命」","1689 年《权利法案》的颁布","1660 年斯图亚特王朝复辟"],"tags":["英国革命","时空观念"]},{"id":"h9a-u7-q1","type":"choice","stem":"第一次工业革命开始的标志是","answer":"B","explain":"18 世纪 60 年代，纺织工人哈格里夫斯发明珍妮纺纱机，标志着第一次工业革命的开始；瓦特改良蒸汽机在 1785 年以后被用作纺织部门的动力机，是工业革命的重要标志。","options":["瓦特改良蒸汽机","哈格里夫斯发明珍妮纺纱机","史蒂芬孙设计蒸汽机车","富尔顿发明汽船"],"tags":["工业革命","时空观念"]},{"id":"h9a-u1-q5","type":"choice","stem":"古埃及金字塔的用途是","answer":"B","explain":"金字塔是古埃及国王的陵墓，其中胡夫金字塔规模最大。它是古埃及文明的象征，反映了古埃及社会经济发展的较高水平和国王的无限权力。","options":["神庙，用于祭祀神灵","国王（法老）的陵墓","天文观测台","抵御外敌的军事堡垒"],"tags":["金字塔","史料实证"]},{"id":"h9a-u2-q4","type":"choice","stem":"对亚历山大东征的评价，最恰当的是","answer":"B","explain":"东征使东方人民饱受掠夺、奴役之苦，但在客观上打通了东西方交通，促进了东西方文化的大交汇，因此要一分为二地评价。C 项是布匿战争的结果，D 项是伯里克利时期的成就。","options":["只是一场侵略战争，没有任何积极作用","给东方人民带来巨大灾难，但客观上促进了东西方文化的大交汇","使罗马成为整个地中海地区的霸主","使希腊的民主政治发展到高峰"],"tags":["亚历山大东征","历史解释"]},{"id":"h9a-u3-q6","type":"choice","stem":"843 年查理曼帝国一分为三，后来逐渐形成三个国家的雏形，它们是","answer":"B","explain":"843 年查理曼帝国一分为三，此后逐渐形成德意志、法兰西、意大利三个国家的雏形，这是今日欧洲政治版图的源头之一。","options":["英国、法国、德国","德意志、法兰西、意大利","西班牙、葡萄牙、意大利","英国、荷兰、法国"],"tags":["查理曼帝国","时空观念"]},{"id":"h9a-u4-q2","type":"choice","stem":"大化改新最重要的历史意义是","answer":"B","explain":"大化改新使日本建立了以天皇为中心的中央集权制度，由奴隶社会向封建社会过渡，发展成为一个中央集权制的封建国家。C 项是明治维新的作用。","options":["使日本实现了国家统一","使日本发展成为一个中央集权制的封建国家","使日本走上了资本主义发展道路","使日本摆脱了外族的侵略"],"tags":["大化改新","历史解释"]},{"id":"h9a-u5-q2","type":"choice","stem":"文艺复兴的实质是","answer":"B","explain":"文艺复兴采取复兴古代希腊罗马文化的形式，实质是新兴资产阶级的思想文化解放运动，它反对的是教会的神权束缚而非宗教信仰本身。","options":["古希腊罗马文化的简单复兴","新兴资产阶级的思想文化解放运动","一场反宗教的社会运动","教会内部的一次改革"],"tags":["文艺复兴","唯物史观"]},{"id":"h9a-u6-q2","type":"choice","stem":"1689 年《权利法案》的颁布，使英国确立的政治制度是","answer":"B","explain":"《权利法案》以法律形式限制国王的权力，议会成为国家权力的中心，君主立宪制的资产阶级统治在英国开始确立起来。","options":["君主专制","君主立宪制","民主共和制","联邦制"],"tags":["《权利法案》","制度创新"]},{"id":"h9a-u7-q2","type":"choice","stem":"第一次工业革命中，把人类带入「蒸汽时代」的最重要发明是","answer":"B","explain":"瓦特改良的蒸汽机在 1785 年以后被用作纺织部门的动力机，摆脱了工厂对河流水力条件的依赖，蒸汽机的广泛应用使人类进入「蒸汽时代」。","options":["珍妮纺纱机","瓦特改良的蒸汽机","水力织布机","汽船"],"tags":["工业革命","历史解释"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"h9a-u2-q6","type":"choice","stem":"下列希腊罗马古典文化成就与其所属文明的搭配，错误的一项是","answer":"D","explain":"《天方夜谭》（《一千零一夜》）是阿拉伯文学的瑰宝，属于阿拉伯文化，与古罗马无关。儒略历由罗马统治者凯撒命人以古埃及太阳历为蓝本编制。","options":["《荷马史诗》——古希腊","帕特农神庙——古希腊","儒略历——古罗马","《天方夜谭》——古罗马"],"tags":["古典文化","史料实证"]},{"id":"cat-9a-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：胡夫金字塔约建于公元前 2600 年，原高约 146 米，底边约 230 米，由约 230 万块巨石砌成，是现存最大的金字塔。（吴于廑、齐世荣《世界史·古代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"古代埃及；金字塔是古埃及国王（法老）的陵墓，是古埃及文明的象征，反映了古埃及社会经济发展的较高水平和国王的无限权力。","explain":"材料出自吴于廑、齐世荣《世界史·古代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h9a-u1-m1-q1","type":"short","stem":"（1）材料一反映出《汉谟拉比法典》具有什么特点？该法典有怎样的历史地位？（4 分）","answer":"特点：实行「同态复仇」原则（以眼还眼、以牙还牙）；对不同社会等级的人处罚标准不同，严格维护奴隶主阶级的利益。历史地位：它是迄今已知世界上第一部较为完整的成文法典，表明人类社会的法制传统源远流长，是古巴比伦王国留给人类的宝贵文化遗产。","explain":"","tags":["《汉谟拉比法典》","史料实证"],"rubric":["答出「同态复仇」或以眼还眼、以牙还牙","答出维护奴隶主阶级利益或等级之间不平等","答出「迄今已知世界上第一部较为完整的成文法典」","答出法制传统源远流长或重要的文化遗产"]}]},{"id":"hp-9b-cross","title":"九年级下册 跨单元测试","subtitle":"九年级下册 · 全册跨单元","grade":"9b","tags":["九年级下册","跨单元测试","综合"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"跨单元测试"},{"k":"题量","v":"选择题 16 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9b-u1-q1","type":"choice","stem":"19 世纪，印度爆发了反抗英国殖民统治的民族大起义，其杰出领导人是","answer":"B","explain":"1857—1859 年印度民族大起义反抗英国殖民统治，章西女王是杰出代表。玻利瓦尔是拉美独立运动领袖，甘地领导的是 20 世纪的印度非暴力不合作运动，凯末尔领导的是土耳其革命。","options":["玻利瓦尔","章西女王","甘地","凯末尔"],"tags":["印度民族大起义","时空观念"]},{"id":"h9b-u2-q1","type":"choice","stem":"第二次工业革命中，作为新能源被广泛应用、使人类进入「电气时代」的是","answer":"B","explain":"第二次工业革命以电力的广泛应用为标志，电动机、发电机等的发明使电力进入生产与生活领域，人类进入「电气时代」。煤炭是第一次工业革命的主要能源。","options":["煤炭","电力","水力","风能"],"tags":["第二次工业革命","时空观念"]},{"id":"h9b-u3-q1","type":"choice","stem":"第一次世界大战爆发的根本原因是","answer":"B","explain":"根本原因是帝国主义国家政治经济发展不平衡，后起的帝国主义国家要求重新瓜分世界，与老牌殖民国家矛盾激化。萨拉热窝事件是导火线，两大军事集团的形成是具体条件。","options":["萨拉热窝事件的发生","帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权","三国同盟与三国协约的形成","塞尔维亚与奥匈帝国的领土争端"],"tags":["第一次世界大战","唯物史观"]},{"id":"h9b-u4-q1","type":"choice","stem":"1929—1933 年资本主义世界经济大危机的特点不包括","answer":"D","explain":"这次经济大危机的特点是涉及范围特别广、持续时间比较长、破坏性特别大。它从美国开始，迅速波及整个资本主义世界，并非只在英国发生。","options":["涉及范围特别广","持续时间比较长","破坏性特别大","只在英国一国发生"],"tags":["经济大危机","历史解释"]},{"id":"h9b-u5-q1","type":"choice","stem":"标志着美苏冷战开始的事件是","answer":"A","explain":"1947 年 3 月杜鲁门在国会发表演说，公开宣称要「遏制」共产主义，杜鲁门主义的出台标志美苏冷战开始。马歇尔计划是冷战在经济上的表现，北约与华约的成立标志两极格局最终形成。","options":["1947 年杜鲁门主义的出台","1947 年马歇尔计划的提出","1949 年北大西洋公约组织的成立","1955 年华沙条约组织的成立"],"tags":["冷战","时空观念"]},{"id":"h9b-u6-q3","type":"choice","stem":"1971 年，第 26 届联合国大会通过决议，恢复中华人民共和国在联合国的一切合法权利。这最能说明","answer":"B","explain":"中国是联合国创始会员国和安理会常任理事国，1971 年是恢复合法席位，反映中国国际地位不断提高。多极化是发展趋势，不能说格局已经形成。","options":["中国开始成为联合国的会员国","中国的国际地位不断提高","联合国已被中国所控制","世界多极化格局已经形成"],"tags":["联合国","中国与世界"]},{"id":"cat-9b-1-1-g2","type":"choice","stem":"下列关于「殖民地人民的反抗战争」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","19 世纪中期，资本主义制度在世界范围内确立和扩展：俄国靠自上而下的改革，美国靠内战，日本靠明治维新——**方式不同，方向一致**。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h9b-u2-q2","type":"choice","stem":"1879 年研制出耐用碳丝白炽灯泡、一生取得千余项发明专利，被誉为「发明大王」的是","answer":"B","explain":"爱迪生 1879 年发明耐用的白炽灯泡，被誉为「发明大王」。本茨制造出内燃机汽车，莱特兄弟制成飞机，诺贝尔发明现代炸药。","options":["本茨","爱迪生","莱特兄弟","诺贝尔"],"tags":["第二次工业革命","历史人物"]},{"id":"cat-9b-3-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 三国同盟形成\n② 三国协约形成\n③ 萨拉热窝事件\n④ 凡尔登战役","answer":"A","explain":"按时间顺序应为：①三国同盟形成（1882 年）→②三国协约形成（1907 年）→③萨拉热窝事件（1914 年 6 月）→④凡尔登战役（1916 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"h9b-u4-q2","type":"choice","stem":"罗斯福新政的中心措施是","answer":"B","explain":"新政的中心措施是对工业的调整，通过《全国工业复兴法》加强国家对工业的计划指导。整顿金融、调整农业、以工代赈都是新政的重要措施，但不是中心措施。","options":["整顿金融体系","对工业的调整（《全国工业复兴法》）","调整农业政策","推行「以工代赈」，兴办公共工程"],"tags":["罗斯福新政","历史解释"]},{"id":"h9b-u5-q2","type":"choice","stem":"标志着以美苏为首的两大集团对峙局面（两极格局）最终形成的事件是","answer":"C","explain":"1949 年北约成立后，1955 年苏联与东欧 7 国成立华沙条约组织，以美苏为首的两大集团对峙局面最终形成，两极格局由此确立。","options":["1949 年德国分裂","1949 年北约成立","1955 年华约成立","1962 年古巴导弹危机"],"tags":["两极格局","时空观念"]},{"id":"h9b-u6-q4","type":"choice","stem":"对经济全球化，下列认识正确的是","answer":"B","explain":"经济全球化是一把「双刃剑」：促进世界经济发展与交流，也加剧了不平等与风险传递。它是不可逆转的趋势，各国应积极参与、趋利避害，同时维护国家主权与经济安全。","options":["经济全球化只有利于发达国家，发展中国家应拒绝参与","经济全球化是不可逆转的趋势，既是机遇也是挑战，应趋利避害","经济全球化已使各国发展水平趋于一致","经济全球化意味着国家主权可以放弃"],"tags":["经济全球化","历史解释"]},{"id":"cat-9b-1-1-g5","type":"choice","stem":"「拉丁美洲独立运动兴起」发生于","answer":"A","explain":"本课时间轴：拉丁美洲独立运动兴起（19 世纪初）。玻利瓦尔解放哥伦比亚、委内瑞拉、厄瓜多尔等地，圣马丁领导阿根廷、智利、秘鲁的独立运动；1804 年海地独立揭开序幕（拉美第一个独立国家）。其余三个时间是同一单元相邻课时的事件时间。","options":["19 世纪初","1861 年","1861—1865 年","1871 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h9b-u2-q4","type":"choice","stem":"19 世纪末 20 世纪初，主要资本主义国家出现垄断组织。其根本原因是","answer":"B","explain":"垄断组织是第二次工业革命中生产力迅速发展、生产和资本高度集中的结果。国家全面干预经济是二战后（罗斯福新政开创）的新变化，不是垄断组织产生的原因。","options":["第一次工业革命的完成","第二次工业革命推动生产力发展、生产和资本日益高度集中","列强加紧对外殖民扩张","国家全面干预经济生活"],"tags":["垄断组织","唯物史观"]},{"id":"cat-9b-3-1-g2","type":"choice","stem":"下列关于「第一次世界大战」的表述，错误的是","answer":"A","explain":"把萨拉热窝事件说成第一次世界大战爆发的根本原因——「根本原因—导火线」的区分是最高频的失分点，凡遇「根本」二字都要往经济与制度矛盾上想。正确表述：萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","options":["把萨拉热窝事件说成第一次世界大战爆发的根本原因。","萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","第一次世界大战是一场非正义的帝国主义掠夺战争，给人类带来空前灾难；战争没有解决列强之间的矛盾，反而为新的战争埋下祸根。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-4-1-g2","type":"choice","stem":"下列关于「资本主义经济大危机」的表述，错误的是","answer":"A","explain":"认为罗斯福新政是社会主义性质的改革——判断改革性质看「是否改变社会制度」：新政不改变私有制与资产阶级统治，因此不是社会主义改革。正确表述：新政是在不改变资本主义制度前提下的自我调整：运用国家力量干预经济，目的是维护资本主义统治、缓解危机。","options":["认为罗斯福新政是社会主义性质的改革。","新政是在不改变资本主义制度前提下的自我调整：运用国家力量干预经济，目的是维护资本主义统治、缓解危机。","罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。","1929—1933 年经济大危机的特点与根源：特点是涉及范围特别广、持续时间比较长、破坏性特别大（整个资本主义世界的工业产量下降 1/3 以上，失业工人超过 3000 万）。根源是资本主义制度的基本矛盾，即生产社会化与生产资料私人占有之间的矛盾。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：玻利瓦尔率军解放委内瑞拉、哥伦比亚、厄瓜多尔、秘鲁等地，被誉为「解放者」；圣马丁解放阿根廷、智利、秘鲁。（吴于廑、齐世荣《世界史·近代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"殖民地人民的反抗战争；拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。","explain":"材料出自吴于廑、齐世荣《世界史·近代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：农奴获得人身自由，有权拥有财产、从事工商活动；地主不得买卖农奴；农奴可赎买份地，但须支付高额赎金。（《1861 年法令》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"俄国的改革；俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。","explain":"材料出自《1861 年法令》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-7a-mid","title":"七年级上册 期中测试","subtitle":"七年级上册 · 期中","grade":"7a","tags":["七年级上册","期中测试","阶段检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期中测试"},{"k":"题量","v":"选择题 20 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u1-q1","type":"choice","stem":"我国境内目前已知最早的古人类之一，距今约 170 万年，其化石发现于今云南省的是","answer":"A","explain":"元谋人发现于云南元谋，距今约 170 万年，是我国境内目前已知最早的古人类之一。","options":["元谋人","北京人","山顶洞人","半坡人"],"tags":["史前时期","时空观念"]},{"id":"cat-7a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 元谋人生活在云南元谋\n② 北京人生活在周口店\n③ 山顶洞人","answer":"A","explain":"按时间顺序应为：①元谋人生活在云南元谋（约 170 万年前）→②北京人生活在周口店（约 70 万—20 万年前）→③山顶洞人（约 3 万年前）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-1-1-g2","type":"choice","stem":"下列关于「远古时期的人类活动」的表述，错误的是","answer":"A","explain":"认为北京人会人工取火——这是最常见的混淆点，选项常把两者对调。正确表述：北京人会使用天然火并保存火种；人工取火是山顶洞人。","options":["认为北京人会人工取火。","北京人会使用天然火并保存火种；人工取火是山顶洞人。","中华文明的起源具有**本土性**（元谋人、北京人一脉相承）与**多元一体**（黄河流域、长江流域等多点并发）两大特征。","北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"cat-7a-1-2-g2","type":"choice","stem":"下列关于「原始农业与史前社会」的表述，错误的是","answer":"A","explain":"把河姆渡与半坡的农作物写反——记「南稻北粟」，与「南干栏北半地穴」一起记。正确表述：河姆渡→水稻（南方）；半坡→粟（北方）。","options":["把河姆渡与半坡的农作物写反。","河姆渡→水稻（南方）；半坡→粟（北方）。","生产力决定生活方式：种植水稻需要水田 → 长江流域的干栏式建筑；种植粟、气候干燥 → 黄河流域的半地穴式房屋。","原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-1-2-g5","type":"choice","stem":"「河姆渡文化（长江流域）」发生于","answer":"A","explain":"本课时间轴：河姆渡文化（长江流域）（约 7000 年前）。种植水稻、干栏式建筑、木结构水井。其余三个时间是同一单元相邻课时的事件时间。","options":["约 7000 年前","约 170 万年前","约 70 万—20 万年前","约 3 万年前"],"difficulty":1,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7a-u1-q3","type":"choice","stem":"良渚古城与陶寺古城的考古发现，最主要的价值在于","answer":"B","explain":"两处古城都出现城市、阶级分化与王权，是中华文明五千多年历史的实证，也说明中华文明本土起源、多元一体。","options":["证明中华文明是由西方传入的","为中华文明五千多年历史提供实证","说明我国最早的文字出现在长江流域","证明夏朝是我国第一个王朝"],"tags":["文明起源","家国情怀"]},{"id":"h7a-u1-q4","type":"choice","stem":"「禅让」制下，部落联盟首领产生的方式是","answer":"B","explain":"尧舜禹时期通过推举贤能者继位，称为禅让。父死子继的世袭制自夏启开始。","options":["父死子继","推举贤能者","以战功决定","由占卜决定"],"tags":["禅让制","历史解释"]},{"id":"cat-7a-1-3-g2","type":"choice","stem":"下列关于「中华文明的起源」的表述，错误的是","answer":"A","explain":"把尧舜禹的「禅让」说成世袭——「公天下」到「家天下」的转折点是夏朝建立，不是尧舜时期。正确表述：禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","options":["把尧舜禹的「禅让」说成世袭。","禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","考古发现是研究史前历史的**唯一可靠依据**；传说（炎黄、尧舜禹）需要考古材料印证，不能当作信史。","良渚、陶寺古城的意义：证明中国在距今约 5000 多年已出现早期国家与文明。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7a-u2-q1","type":"choice","stem":"「大道之行也，天下为公，选贤与能……今大道既隐，天下为家。」「天下为家」开始于","answer":"B","explain":"启继承禹的王位，世袭制代替禅让制，「公天下」变为「家天下」。","options":["禹建立夏朝","启继承王位","汤灭夏建商","武王伐纣"],"tags":["世袭制","历史解释"]},{"id":"h7a-u2-q2","type":"choice","stem":"「封建亲戚，以藩屏周」反映的西周制度是","answer":"B","explain":"分封制把土地和人民分给宗亲、功臣，让他们建立诸侯国，起到拱卫王室的作用。","options":["禅让制","分封制","郡县制","世袭制"],"tags":["分封制","史料实证"]},{"id":"cat-7a-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 禹建立夏朝\n② 武王伐纣，牧野之战后建立西周\n③ 犬戎攻破镐京，西周灭亡","answer":"A","explain":"按时间顺序应为：①禹建立夏朝（约公元前 2070 年）→②武王伐纣，牧野之战后建立西周（公元前 1046 年）→③犬戎攻破镐京，西周灭亡（公元前 771 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-1-g2","type":"choice","stem":"下列关于「夏商西周王朝的更替」的表述，错误的是","answer":"A","explain":"把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」——制度与朝代配对是最常设的陷阱，答题前先想「哪个朝代」。正确表述：分封制是西周的制度；夏朝是世袭制王朝。","options":["把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」。","分封制是西周的制度；夏朝是世袭制王朝。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","夏朝是我国历史上第一个王朝，世袭制代替禅让制，「公天下」变为「家天下」。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-1-g3","type":"choice","stem":"下列结论中，属于「夏商西周王朝的更替」的是","answer":"A","explain":"本课结论：分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","评价变法要一分为二：商鞅变法使秦国富强，但严刑峻法也激化了社会矛盾。","百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"h7a-u2-q5","type":"choice","stem":"春秋战国时期出现「百家争鸣」局面的根本原因是","answer":"B","explain":"根本原因是生产力发展带来的社会大变革：经济基础变化引起上层建筑与思想的变动。其余选项是重要条件而非根本原因。","options":["各诸侯国竞相招揽人才","铁制农具和牛耕的推广，社会生产力提高","私学兴起，学术下移","周王室衰微，诸侯争霸"],"tags":["百家争鸣","唯物史观"]},{"id":"cat-7a-2-2-g2","type":"choice","stem":"下列关于「动荡变化中的春秋时期」的表述，错误的是","answer":"A","explain":"把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」——制度与朝代配对是最常设的陷阱，答题前先想「哪个朝代」。正确表述：分封制是西周的制度；夏朝是世袭制王朝。","options":["把夏朝建立说成「公元前 2070 年禹建立夏朝，实行分封制」。","分封制是西周的制度；夏朝是世袭制王朝。","生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-2-g3","type":"choice","stem":"下列结论中，属于「动荡变化中的春秋时期」的是","answer":"A","explain":"本课结论：生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["生产力是变革的根本动力：铁制农具与牛耕的推广 → 井田制瓦解 → 各国变法 → 封建制度确立。","分封制的「双刃剑」：初期巩固统治，后期诸侯割据，为春秋战国的分裂埋下伏笔。","评价变法要一分为二：商鞅变法使秦国富强，但严刑峻法也激化了社会矛盾。","百家争鸣是中国古代第一次思想文化高峰，奠定了此后两千多年思想文化的基础。"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-2-g5","type":"choice","stem":"「春秋时期」发生于","answer":"A","explain":"本课时间轴：春秋时期（公元前 770—前 476 年）。铁制农具与牛耕出现；王室衰微，诸侯争霸。其余三个时间是同一单元相邻课时的事件时间。","options":["公元前 770—前 476 年","约公元前 2070 年","公元前 1046 年","公元前 771 年"],"difficulty":1,"tags":["七年级上册","第二单元","本课练习"]},{"id":"h7a-u2-q4","type":"choice","stem":"商鞅变法中最能体现「社会转型」的措施是","answer":"C","explain":"废除井田制、承认土地私有，标志着土地制度由奴隶制向封建制转变，最能体现社会转型。","options":["奖励耕织","确立县制","废除井田制，允许土地自由买卖","统一度量衡"],"tags":["商鞅变法","唯物史观"]},{"id":"cat-7a-2-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 武王伐纣，牧野之战后建立西周\n② 春秋时期\n③ 战国时期","answer":"A","explain":"按时间顺序应为：①武王伐纣，牧野之战后建立西周（公元前 1046 年）→②春秋时期（公元前 770—前 476 年）→③战国时期（公元前 475—前 221 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"h7a-u1-m1-q1","type":"short","stem":"（1）材料一中的灰烬层能说明北京人已经掌握了什么技能？这一发现有何意义？（4 分）","answer":"说明北京人已经会使用火并能够保存火种。意义：火的使用改善了生存条件（烧烤食物、照明、取暖、驱赶野兽），是人类进化过程中的重大进步；周口店遗址是研究人类起源的直接证据。","explain":"","tags":["史料实证","史前时期"],"rubric":["答出「使用火、保存火种」","答出火的作用（取暖/熟食/驱兽任一点）","答出遗址的史料价值"]},{"id":"cat-7a-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1921 年安特生、师丹斯基在北京周口店龙骨山发现遗址；1929 年 12 月裴文中发掘出第一个完整的北京人头盖骨化石。此后陆续发现 40 多个个体的人骨化石。（中国社会科学院考古研究所《北京人遗址》相关记述）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"远古时期的人类活动；北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。","explain":"材料出自中国社会科学院考古研究所《北京人遗址》相关记述。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-7a-fin","title":"七年级上册 期末测试","subtitle":"七年级上册 · 期末","grade":"7a","tags":["七年级上册","期末测试","全册检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期末测试"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"90 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u3-q3","type":"choice","stem":"标志今新疆地区正式归属中央政权管辖的事件是","answer":"C","explain":"公元前 60 年西汉设置西域都护，标志西域正式归属中央政权管辖。","options":["张骞第一次出使西域","丝绸之路的开通","公元前 60 年西汉设置西域都护","班超经营西域"],"tags":["西域都护","时空观念"]},{"id":"cat-7a-3-3-g2","type":"choice","stem":"下列关于「西汉建立和“文景之治”」的表述，错误的是","answer":"A","explain":"认为西域都护设置于东汉——时间点是最爱设的陷阱，要记「前 60 年、西汉」。正确表述：公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","options":["认为西域都护设置于东汉。","公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-3-g3","type":"choice","stem":"下列结论中，属于「西汉建立和“文景之治”」的是","answer":"A","explain":"本课结论：大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-3-g5","type":"choice","stem":"「刘邦建立西汉，定都长安」发生于","answer":"A","explain":"本课时间轴：刘邦建立西汉，定都长安（公元前 202 年）。吸取秦亡教训，推行休养生息政策。其余三个时间是同一单元相邻课时的事件时间。","options":["公元前 202 年","公元前 221 年","公元前 213—前 212 年","公元前 209 年"],"difficulty":1,"tags":["七年级上册","第三单元","本课练习"]},{"id":"h7a-u3-q2","type":"choice","stem":"汉武帝采纳主父偃建议颁布「推恩令」，其高明之处在于","answer":"B","explain":"推恩令让诸侯王的子弟分封土地，封国越分越小，中央集权得到加强，且避免了激化矛盾。","options":["直接剥夺诸侯王的封地","使诸侯国越分越小，不费兵卒削弱了诸侯势力","以武力镇压诸侯叛乱","废除分封，全面推行郡县"],"tags":["推恩令","历史解释"]},{"id":"cat-7a-3-4-g2","type":"choice","stem":"下列关于「大一统王朝的巩固」的表述，错误的是","answer":"A","explain":"把「推恩令」与「分封制」混为一谈——它表面是「恩」，实质是削藩，材料题常问「高明之处」。正确表述：推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","options":["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","汉武帝的大一统：颁「推恩令」削弱诸侯王；「罢黜百家，尊崇儒术」确立儒家学说的正统地位；盐铁官营、统一铸币；北击匈奴（卫青、霍去病）。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-4-g3","type":"choice","stem":"下列结论中，属于「大一统王朝的巩固」的是","answer":"A","explain":"本课结论：大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"h7a-u3-q1","type":"choice","stem":"秦朝在地方上推行的、对后世影响最深远的制度是","answer":"B","explain":"郡县制下郡县长官由皇帝直接任免、不世袭，开创了此后两千多年的中央集权地方行政制度。行省制是元朝，科举制是隋朝。","options":["分封制","郡县制","行省制","科举制"],"tags":["郡县制","制度创新"]},{"id":"cat-7a-3-5-g2","type":"choice","stem":"下列关于「东汉的兴衰」的表述，错误的是","answer":"A","explain":"把「推恩令」与「分封制」混为一谈——它表面是「恩」，实质是削藩，材料题常问「高明之处」。正确表述：推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","options":["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-5-g3","type":"choice","stem":"下列结论中，属于「东汉的兴衰」的是","answer":"A","explain":"本课结论：秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-6-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 刘邦建立西汉，定都长安\n② 汉武帝在位（前 141—前 87）\n③ 张骞两次出使西域\n④ 西汉设置西域都护","answer":"A","explain":"按时间顺序应为：①刘邦建立西汉，定都长安（公元前 202 年）→②汉武帝在位（前 141—前 87）（公元前 2 世纪末）→③张骞两次出使西域（公元前 138 年、前 119 年）→④西汉设置西域都护（公元前 60 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-6-g2","type":"choice","stem":"下列关于「丝绸之路的开通与经营西域」的表述，错误的是","answer":"A","explain":"认为西域都护设置于东汉——时间点是最爱设的陷阱，要记「前 60 年、西汉」。正确表述：公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","options":["认为西域都护设置于东汉。","公元前 60 年西汉设置西域都护，这是西域正式归属中央政权管辖的标志。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。","丝绸之路：长安 → 河西走廊 → 西域 → 中亚 → 欧洲；汉武帝时开通，张骞两次出使西域是关键。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-6-g3","type":"choice","stem":"下列结论中，属于「丝绸之路的开通与经营西域」的是","answer":"A","explain":"本课结论：丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"h7a-u3-q4","type":"choice","stem":"下列著作中，被称为我国第一部纪传体通史的是","answer":"B","explain":"《史记》由司马迁撰写，记述从黄帝到汉武帝时期的历史，是我国第一部纪传体通史。《资治通鉴》是编年体。","options":["《春秋》","《史记》","《汉书》","《资治通鉴》"],"tags":["司马迁","文化成就"]},{"id":"cat-7a-3-7-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 秦灭六国，嬴政称「始皇帝」，定都咸阳\n② 焚书坑儒\n③ 陈胜、吴广在大泽乡起义\n④ 刘邦建立西汉，定都长安","answer":"A","explain":"按时间顺序应为：①秦灭六国，嬴政称「始皇帝」，定都咸阳（公元前 221 年）→②焚书坑儒（公元前 213—前 212 年）→③陈胜、吴广在大泽乡起义（公元前 209 年）→④刘邦建立西汉，定都长安（公元前 202 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-7-g2","type":"choice","stem":"下列关于「秦汉时期的科技与文化」的表述，错误的是","answer":"A","explain":"把「推恩令」与「分封制」混为一谈——它表面是「恩」，实质是削藩，材料题常问「高明之处」。正确表述：推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","options":["把「推恩令」与「分封制」混为一谈。","推恩令是让诸侯王的封地分给子弟，越分越小，目的是削弱诸侯、加强中央集权。","秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"cat-7a-3-7-g3","type":"choice","stem":"下列结论中，属于「秦汉时期的科技与文化」的是","answer":"A","explain":"本课结论：秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["秦朝的制度创新影响深远：郡县制与中央集权体制为历代沿用，「百代都行秦政法」。","「得民心者得天下」：秦以暴政速亡，汉以休养生息而兴，是材料题最常提炼的认识。","大一统包括政治、经济、思想、军事四个方面，汉武帝的举措使西汉进入鼎盛时期。","丝绸之路是双向的：中国的丝绸、冶铁技术西传，西域的物产、乐器、宗教艺术东来。"],"difficulty":2,"tags":["七年级上册","第三单元","本课练习"]},{"id":"h7a-u4-q1","type":"choice","stem":"为三国鼎立局面形成奠定基础的战役是","answer":"B","explain":"208 年赤壁之战中孙刘联军打败曹操，为三国鼎立局面的形成奠定基础。官渡之战为曹操统一北方奠定基础。","options":["官渡之战","赤壁之战","淝水之战","巨鹿之战"],"tags":["赤壁之战","时空观念"]},{"id":"cat-7a-4-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 官渡之战\n② 赤壁之战\n③ 曹丕称帝建魏，定都洛阳","answer":"A","explain":"按时间顺序应为：①官渡之战（200 年）→②赤壁之战（208 年）→③曹丕称帝建魏，定都洛阳（220 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-1-g2","type":"choice","stem":"下列关于「三国鼎立」的表述，错误的是","answer":"A","explain":"认为赤壁之战使曹操统一了全国——官渡之战与赤壁之战的结果、意义最容易被调换。正确表述：赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","options":["认为赤壁之战使曹操统一了全国。","赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-1-g3","type":"choice","stem":"下列结论中，属于「三国鼎立」的是","answer":"A","explain":"本课结论：分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","文化成就与时代相关：战乱与民族交融时期，宗教艺术（石窟）与书法艺术特别兴盛。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"h7a-u4-q2","type":"choice","stem":"北魏孝文帝改革措施中，最能体现民族交融的是","answer":"B","explain":"语言、服饰、姓氏与婚姻的汉化直接促进了鲜卑族与汉族的交融；迁都洛阳是为改革创造条件。","options":["迁都洛阳","说汉语、穿汉服、改汉姓、与汉族通婚","奖励军功","实行均田制"],"tags":["孝文帝改革","民族交融"]},{"id":"h7a-u4-q3","type":"choice","stem":"魏晋南北朝时期江南地区得到开发的最主要原因是","answer":"B","explain":"北人南迁带来了劳动力与先进的生产技术，是江南开发最主要的原因，其余是重要条件。","options":["江南自然条件优越","北方人口大量南迁，带来劳动力和先进技术","南方统治者重视农业","南方战乱较少"],"tags":["江南开发","唯物史观"]},{"id":"cat-7a-4-2-g2","type":"choice","stem":"下列关于「西晋的短暂统一和北方各族的内迁」的表述，错误的是","answer":"A","explain":"认为赤壁之战使曹操统一了全国——官渡之战与赤壁之战的结果、意义最容易被调换。正确表述：赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","options":["认为赤壁之战使曹操统一了全国。","赤壁之战曹操战败，为三国鼎立局面的形成奠定基础；曹操只统一了北方。","分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-4-2-g3","type":"choice","stem":"下列结论中，属于「西晋的短暂统一和北方各族的内迁」的是","answer":"A","explain":"本课结论：分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["分裂中孕育统一因素：民族交融与江南开发，为隋朝统一与隋唐繁荣创造了条件。","人口迁移是经济格局变化的重要推手：北人南迁 → 江南开发 → 经济重心南移的开端。","改革要顺应历史趋势：孝文帝改革顺应了民族交融的趋势，因此成效显著。","文化成就与时代相关：战乱与民族交融时期，宗教艺术（石窟）与书法艺术特别兴盛。"],"difficulty":2,"tags":["七年级上册","第四单元","本课练习"]},{"id":"cat-7a-3-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：陈胜称王后逐渐脱离群众，用人不当，内部离心；起义军缺乏统一指挥和稳固根据地，终被秦军各个击破。陈胜于公元前 208 年被部下庄贾杀害。（《史记·陈涉世家》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"秦末农民大起义；秦亡的原因与启示：赋税徭役沉重、刑法严苛、秦二世更加残暴 → 农民起义。启示：治国要爱惜民力。","explain":"材料出自《史记·陈涉世家》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7a-3-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：汉初田租由「十五税一」减至「三十税一」，文帝一度全免田租；徭役由每年一月减为三年一月。（《汉书·食货志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"西汉建立和“文景之治”；秦亡的原因与启示：赋税徭役沉重、刑法严苛、秦二世更加残暴 → 农民起义。启示：治国要爱惜民力。","explain":"材料出自《汉书·食货志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7a-3-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：规定诸侯王除嫡长子继承王位外，可将封地分给其他子弟为列侯，由皇帝制定封号。诸侯国越分越小，中央直辖郡县扩大，不费一兵一卒削弱了王国势力。（《史记·平津侯主父列传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"大一统王朝的巩固；汉武帝的大一统：颁「推恩令」削弱诸侯王；「罢黜百家，尊崇儒术」确立儒家学说的正统地位；盐铁官营、统一铸币；北击匈奴（卫青、霍去病）。","explain":"材料出自《史记·平津侯主父列传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-7b-mid","title":"七年级下册 期中测试","subtitle":"七年级下册 · 期中","grade":"7b","tags":["七年级下册","期中测试","阶段检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期中测试"},{"k":"题量","v":"选择题 20 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7b-u1-q1","type":"choice","stem":"605 年起下令开凿大运河，以洛阳为中心、北抵涿郡、南至余杭的皇帝是","answer":"B","explain":"大运河由隋炀帝下令开凿（605 年起），以洛阳为中心，北抵涿郡，南至余杭，是古代世界上最长的运河。隋文帝的功绩是统一全国、创立三省六部制与分科考试选官。","options":["隋文帝","隋炀帝","唐高祖","唐玄宗"],"tags":["大运河","时空观念"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"h7b-u1-q6","type":"choice","stem":"关于五代十国，下列说法正确的是","answer":"A","explain":"五代十国是唐末藩镇割据局面的延续。北方政权更迭频繁、战乱不断；南方相对安定，经济得到发展；统一始终是历史发展的必然趋势。","options":["五代十国是唐末以来藩镇割据局面的延续","五代十国时期南方经济遭到严重破坏","五代十国都是由少数民族建立的政权","五代十国时期全国长期处于统一状态"],"tags":["五代十国","历史解释"]},{"id":"cat-7b-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杨坚夺取北周政权，建立隋朝，定都长安\n② 隋炀帝下令开凿大运河\n③ 设置进士科，科举制正式确立\n④ 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","answer":"A","explain":"按时间顺序应为：①杨坚夺取北周政权，建立隋朝，定都长安（581 年）→②隋炀帝下令开凿大运河（605 年起）→③设置进士科，科举制正式确立（隋炀帝时）→④隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g2","type":"choice","stem":"下列关于「隋朝统一与灭亡」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g3","type":"choice","stem":"下列结论中，属于「隋朝统一与灭亡」的是","answer":"A","explain":"本课结论：科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h7b-u1-q4","type":"choice","stem":"唐太宗说「舟所以比人君，水所以比黎庶，水能载舟，亦能覆舟」，这说明他","answer":"B","explain":"唐太宗从隋朝因暴政速亡的教训中认识到百姓的力量，因此减轻赋税徭役、推行有利于生产恢复的政策，这才有「贞观之治」。","options":["主张严刑峻法以驾驭臣下","注意吸取隋亡教训，爱惜民力","主张大力开疆拓土","主张抑制商业发展"],"tags":["贞观之治","家国情怀"]},{"id":"cat-7b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安\n② 唐太宗统治时期，出现「贞观之治」\n③ 玄奘西行天竺取经，后口述成《大唐西域记》\n④ 唐太宗把文成公主嫁给吐蕃赞普松赞干布","answer":"A","explain":"按时间顺序应为：①隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）→②唐太宗统治时期，出现「贞观之治」（627—649 年）→③玄奘西行天竺取经，后口述成《大唐西域记》（唐太宗时）→④唐太宗把文成公主嫁给吐蕃赞普松赞干布（641 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-2-g2","type":"choice","stem":"下列关于「唐朝建立与“贞观之治”」的表述，错误的是","answer":"A","explain":"把科举制的创立说成唐朝，或认为进士科是唐太宗设立的——「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。正确表述：科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","options":["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-2-g3","type":"choice","stem":"下列结论中，属于「唐朝建立与“贞观之治”」的是","answer":"A","explain":"本课结论：隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-3-g2","type":"choice","stem":"下列关于「“开元盛世”」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-3-g3","type":"choice","stem":"下列结论中，属于「“开元盛世”」的是","answer":"A","explain":"本课结论：隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-3-g5","type":"choice","stem":"「唐玄宗统治前期，出现「开元盛世」」发生于","answer":"A","explain":"本课时间轴：唐玄宗统治前期，出现「开元盛世」（713—741 年）。任用姚崇、宋璟等贤臣，整顿吏治、发展生产，唐朝进入鼎盛时期。其余三个时间是同一单元相邻课时的事件时间。","options":["713—741 年","581 年","605 年起","隋炀帝时"],"difficulty":1,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h7b-u1-q5","type":"choice","stem":"唐朝由盛转衰的转折点是","answer":"B","explain":"755—763 年的安史之乱使唐朝国势由盛转衰，此后中央权力衰微、藩镇割据。黄巢起义给唐朝统治以致命打击；907 年朱温建立后梁，唐朝灭亡。","options":["黄巢起义","安史之乱","藩镇割据","朱温建立后梁"],"tags":["安史之乱","历史解释"]},{"id":"cat-7b-1-4-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 安史之乱\n② 黄巢起义\n③ 朱温建立后梁，唐朝灭亡，五代十国开始","answer":"A","explain":"按时间顺序应为：①安史之乱（755—763 年）→②黄巢起义（875—884 年）→③朱温建立后梁，唐朝灭亡，五代十国开始（907 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-4-g2","type":"choice","stem":"下列关于「安史之乱与唐朝衰亡」的表述，错误的是","answer":"A","explain":"认为安史之乱直接导致唐朝灭亡——「转折点」与「终点」是两个概念，材料题问「由盛转衰的标志」时不要答成 907 年。正确表述：安史之乱使唐朝由盛转衰，形成藩镇割据；唐朝灭亡是 907 年朱温建立后梁。","options":["认为安史之乱直接导致唐朝灭亡。","安史之乱使唐朝由盛转衰，形成藩镇割据；唐朝灭亡是 907 年朱温建立后梁。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","安史之乱（755—763）是唐朝由盛转衰的转折点：唐玄宗后期贪图享乐、任用奸臣，节度使权力膨胀，社会矛盾尖锐，最终酿成叛乱；此后中央权力衰微、藩镇割据。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-4-g3","type":"choice","stem":"下列结论中，属于「安史之乱与唐朝衰亡」的是","answer":"A","explain":"本课结论：安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h7b-u1-q3","type":"choice","stem":"为中日文化交流作出突出贡献，六次东渡并在日本主持修建唐招提寺的僧人是","answer":"B","explain":"鉴真六次东渡日本，传授佛经、传播中华文化，主持修建唐招提寺。玄奘西行天竺取经并口述成《大唐西域记》；法显是东晋僧人。","options":["玄奘","鉴真","法显","一行"],"tags":["鉴真东渡","中外交流"]},{"id":"cat-7b-1-5-g2","type":"choice","stem":"下列关于「隋唐时期的民族交往与交融」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","唐朝的民族交往：641 年文成公主入藏与松赞干布和亲，唐中宗时金城公主入藏；唐蕃订立盟约、互通使节；唐朝还册封回纥、南诏等少数民族首领。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-5-g3","type":"choice","stem":"下列结论中，属于「隋唐时期的民族交往与交融」的是","answer":"A","explain":"本课结论：隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：永济渠（洛阳至涿郡）、通济渠（洛阳至淮水）、邗沟（淮水至江都入长江）、江南河（长江至余杭），沟通海河、黄河、淮河、长江、钱塘江五大水系。（《隋书·食货志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"隋朝统一与灭亡；隋朝的制度创新与统一：结束分裂、实现统一，创立科举制与三省六部制，开凿大运河，为唐朝的繁荣奠定了基础。","explain":"材料出自《隋书·食货志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h7b-u1-m1-q2","type":"short","stem":"（2）材料二、三分别反映了唐太宗怎样的治国做法？这些做法与「贞观之治」的出现有何关系？（5 分）","answer":"材料二反映唐太宗重视百姓、以民为本，注意减轻百姓负担（这是吸取隋亡教训的结果）；材料三反映他重视科举取士、笼络人才、扩大统治基础。关系：正因为唐太宗减轻赋税徭役、虚心纳谏、知人善任，并进一步完善三省六部制与科举制，才使政治比较清明、经济得到恢复和发展、社会秩序安定、国力增强，从而出现了「贞观之治」的局面。","explain":"","tags":["贞观之治","历史解释"],"rubric":["材料二：以民为本、重视百姓（减轻负担）","材料三：重视科举取士、重用人才","答出措施与治世之间的因果对应","答出贞观之治的表现（政治清明/经济发展/社会安定）"]}]},{"id":"hp-7b-fin","title":"七年级下册 期末测试","subtitle":"七年级下册 · 期末","grade":"7b","tags":["七年级下册","期末测试","全册检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期末测试"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"90 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"cat-7b-2-4-g2","type":"choice","stem":"下列关于「元朝的建立与统一」的表述，错误的是","answer":"A","explain":"认为行省制度始于唐朝或宋朝——「郡县制（秦）—行省制（元）」是两条必须分清的行政制度线索。正确表述：行省制度开始于元朝，是我国省级行政区划的开端。","options":["认为行省制度始于唐朝或宋朝。","行省制度开始于元朝，是我国省级行政区划的开端。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。","元朝的统一与制度：1271 年忽必烈改国号为元，1279 年完成统一；在地方推行行省制度（我国省级行政区划的开端）；设宣政院管辖西藏，设澎湖巡检司管辖澎湖和琉球。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-4-g3","type":"choice","stem":"下列结论中，属于「元朝的建立与统一」的是","answer":"A","explain":"本课结论：元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"h7b-u2-q3","type":"choice","stem":"世界上最早的纸币「交子」出现的时间和地区是","answer":"A","explain":"北宋前期，四川地区出现「交子」，这是世界上最早的纸币，反映了宋代商品经济的繁荣。","options":["北宋前期的四川地区","唐朝中期的江南地区","南宋时期的临安","元朝的大都"],"tags":["交子","宋代经济"]},{"id":"h7b-u2-q5","type":"choice","stem":"我国经济重心南移最后完成于","answer":"C","explain":"经济重心南移从唐朝中期开始，到南宋时最后完成，南方成为全国的经济重心，出现「苏湖熟，天下足」的局面。","options":["唐朝中期","北宋","南宋","元朝"],"tags":["经济重心南移","时空观念"]},{"id":"cat-7b-2-5-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 忽必烈改国号为元，次年定都大都；1279 年完成…\n② 经济重心南移完成\n③ 四川地区出现「交子」","answer":"A","explain":"按时间顺序应为：①忽必烈改国号为元，次年定都大都；1279 年完成全国统一（1271 年）→②经济重心南移完成（南宋时）→③四川地区出现「交子」（北宋前期）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-5-g2","type":"choice","stem":"下列关于「辽宋夏金元时期经济的繁荣」的表述，错误的是","answer":"A","explain":"认为经济重心南移完成于唐朝——「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。正确表述：经济重心南移**从唐朝中期开始，到南宋时最后完成**。","options":["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-5-g3","type":"choice","stem":"下列结论中，属于「辽宋夏金元时期经济的繁荣」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"h7b-u2-q1","type":"choice","stem":"宋太祖「杯酒释兵权」，并推行重文轻武的政策，其主要目的是","answer":"B","explain":"宋太祖吸取唐末以来武将专权、藩镇割据的教训，通过解除禁军将领兵权、重用文臣等办法防止武将专权，加强中央集权。其结果是军队战斗力有所削弱、财政负担加重。","options":["提高军队的战斗力","防止武将专权，加强中央集权","减轻农民的赋税负担","增加国家的财政收入"],"tags":["重文轻武","中央集权"]},{"id":"h7b-u2-q2","type":"choice","stem":"宋辽之间保持长时间的和平局面，开始于","answer":"B","explain":"1005 年宋辽订立澶渊之盟，北宋每年给辽岁币，此后很长时间里宋辽保持了和平局面，边境贸易发展。","options":["北宋建立","澶渊之盟的订立","靖康之变","宋金议和"],"tags":["澶渊之盟","时空观念"]},{"id":"cat-7b-2-6-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 赵匡胤建立北宋，定都东京（今河南开封）\n② 宋辽订立「澶渊之盟」\n③ 党项族首领元昊称帝，建立西夏\n④ 宋神宗任用王安石主持变法","answer":"A","explain":"按时间顺序应为：①赵匡胤建立北宋，定都东京（今河南开封）（960 年）→②宋辽订立「澶渊之盟」（1005 年）→③党项族首领元昊称帝，建立西夏（1038 年）→④宋神宗任用王安石主持变法（1069 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-6-g2","type":"choice","stem":"下列关于「辽宋夏金元时期的对外交流」的表述，错误的是","answer":"A","explain":"认为经济重心南移完成于唐朝——「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。正确表述：经济重心南移**从唐朝中期开始，到南宋时最后完成**。","options":["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-6-g3","type":"choice","stem":"下列结论中，属于「辽宋夏金元时期的对外交流」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-7-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 赵匡胤建立北宋，定都东京（今河南开封）\n② 宋辽订立「澶渊之盟」\n③ 党项族首领元昊称帝，建立西夏\n④ 宋神宗任用王安石主持变法","answer":"A","explain":"按时间顺序应为：①赵匡胤建立北宋，定都东京（今河南开封）（960 年）→②宋辽订立「澶渊之盟」（1005 年）→③党项族首领元昊称帝，建立西夏（1038 年）→④宋神宗任用王安石主持变法（1069 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-7-g2","type":"choice","stem":"下列关于「辽宋夏金元时期的科技与文化」的表述，错误的是","answer":"A","explain":"认为经济重心南移完成于唐朝——「开始」与「完成」是两个步骤；材料中出现「苏湖熟，天下足」一般指向南宋。正确表述：经济重心南移**从唐朝中期开始，到南宋时最后完成**。","options":["认为经济重心南移完成于唐朝。","经济重心南移**从唐朝中期开始，到南宋时最后完成**。","辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"cat-7b-2-7-g3","type":"choice","stem":"下列结论中，属于「辽宋夏金元时期的科技与文化」的是","answer":"A","explain":"本课结论：辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["辽宋夏金元时期的时代特征是**民族关系发展**（政权并立、和战交替、民族交融）与**社会变化**（经济重心南移完成、商品经济繁荣、市民生活丰富）。","两宋与少数民族政权的关系以和平往来为主流：澶渊之盟、宋夏和议、宋金和议虽带有屈辱色彩，但客观上促进了边境贸易与民族交融。","经济重心南移的因果链：北方战乱与人口南迁（带来劳动力与先进技术）＋南方自然条件优越、社会相对安定 → 南方经济发展 → 南宋时经济重心南移完成，出现「国家根本，仰给东南」的局面。","元朝的行省制度是我国省级行政区划的开端；宣政院与澎湖巡检司的设置说明西藏、台湾地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第二单元","本课练习"]},{"id":"h7b-u3-q6","type":"choice","stem":"清朝雍正帝设立、使君主专制进一步强化的机构是","answer":"C","explain":"雍正帝时设立军机处，军机大臣只是跪受笔录、传达皇帝的旨意，君主专制进一步强化。锦衣卫、东厂是明朝的特务机构。","options":["中书省","内阁","军机处","锦衣卫"],"tags":["军机处","君主专制"]},{"id":"cat-7b-3-1-g2","type":"choice","stem":"下列关于「明朝的统治」的表述，错误的是","answer":"A","explain":"认为郑和下西洋是为了开拓海外殖民地、发展海外贸易——它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。正确表述：郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","options":["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","明朝强化皇权：中央废除丞相和中书省，权力分给六部；地方废除行省，设立三司；设锦衣卫、东厂等特务机构；实行八股取士。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-1-g3","type":"choice","stem":"下列结论中，属于「明朝的统治」的是","answer":"A","explain":"本课结论：明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-1-g5","type":"choice","stem":"「朱元璋建立明朝，定都应天府（今江苏南京）」发生于","answer":"A","explain":"本课时间轴：朱元璋建立明朝，定都应天府（今江苏南京）（1368 年）。朱元璋即明太祖；同年明军攻占大都，元朝在全国的统治结束。其余三个时间是同一单元相邻课时的事件时间。","options":["1368 年","16 世纪中期","1553 年","1616 年"],"difficulty":1,"tags":["七年级下册","第三单元","本课练习"]},{"id":"h7b-u3-q2","type":"choice","stem":"郑和下西洋最远到达的地区是","answer":"B","explain":"1405—1433 年郑和七次下西洋，到达亚非三十多个国家和地区，最远到达非洲东海岸和红海沿岸，是世界航海史上的空前壮举。","options":["印度半岛南端","非洲东海岸和红海沿岸","波斯湾沿岸","美洲西海岸"],"tags":["郑和下西洋","时空观念"]},{"id":"cat-7b-3-2-g2","type":"choice","stem":"下列关于「明朝的对外关系」的表述，错误的是","answer":"A","explain":"认为郑和下西洋是为了开拓海外殖民地、发展海外贸易——它与新航路开辟的殖民扩张有本质区别，材料题常要求比较二者的「目的与结果」。正确表述：郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","options":["认为郑和下西洋是为了开拓海外殖民地、发展海外贸易。","郑和下西洋的主要目的是宣扬国威、加强与海外各国的联系，属于和平的友好交往，不计经济效益。","对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","对外交往的方式决定结果：郑和下西洋是和平友好的往来，新航路开辟伴随殖民掠夺与资本主义发展；不同的动机带来了不同的历史结局。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-2-g3","type":"choice","stem":"下列结论中，属于「明朝的对外关系」的是","answer":"A","explain":"本课结论：对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["对外开放带来繁荣，闭关锁国导致落后：郑和下西洋展示了明朝的国力与和平交往的愿望，而清朝只留广州一处通商，使中国与世界隔绝，逐渐落后于世界潮流。","明清时期君主专制空前强化：明朝废丞相、设三司与厂卫并以八股取士，清朝设军机处、大兴文字狱，皇权不断强化，但也禁锢了思想、阻碍了社会进步。","统一多民族国家在明清时期得到巩固和发展：台湾府的设置、驻藏大臣的设置、伊犁将军的设置，使中央政府对台湾、西藏、新疆的管辖更加有效，也说明这些地区自古以来就是中国领土的一部分。","明清科技具有「总结性」而缺乏创新性：《本草纲目》《天工开物》《农政全书》都是对传统医药、农业与手工业经验的总结，而同一时期的欧洲正走向近代科学。"],"difficulty":2,"tags":["七年级下册","第三单元","本课练习"]},{"id":"cat-7b-3-2-g5","type":"choice","stem":"「戚继光率「戚家军」抗倭，东南沿海的倭患基本平息」发生于","answer":"A","explain":"本课时间轴：戚继光率「戚家军」抗倭，东南沿海的倭患基本平息（16 世纪中期）。戚继光先后在台州、福建、广东大败倭寇，是我国历史上的民族英雄。其余三个时间是同一单元相邻课时的事件时间。","options":["16 世纪中期","1368 年","明太祖、明成祖时","1616 年"],"difficulty":1,"tags":["七年级下册","第三单元","本课练习"]},{"id":"h7b-u3-q1","type":"choice","stem":"明朝废除丞相、撤销中书省，把权力分给六部，这一措施的主要作用是","answer":"A","explain":"废除丞相后，六部直接对皇帝负责，君主专制大大加强，但也使皇帝政务负担加重。","options":["加强了君主专制","削弱了皇权","提高了地方的自主权","形成了内阁制"],"tags":["明朝皇权强化","制度创新"]},{"id":"h7b-u3-q3","type":"choice","stem":"清朝设置台湾府，隶属福建省，此事发生在","answer":"C","explain":"1662 年郑成功从荷兰殖民者手中收复台湾；1684 年清朝设置台湾府，隶属福建省，加强了中央政府对台湾的管辖。","options":["1662 年","1683 年","1684 年","1689 年"],"tags":["台湾府","边疆管辖"]},{"id":"cat-7b-2-5-g4","type":"short","stem":"阅读材料，回答问题。\n材料：北宋前期，四川地区出现「交子」，是世界上最早的纸币；南宋发行「会子」。（《宋史·食货志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"辽宋夏金元时期经济的繁荣；经济重心南移的完成：从唐朝中期开始的经济重心南移，到南宋时最后完成。原因是北方战乱、人口南迁带来劳动力与先进技术，南方自然条件优越、社会相对安定，统治者重视生产。","explain":"材料出自《宋史·食货志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-2-6-g4","type":"short","stem":"阅读材料，回答问题。\n材料：意大利旅行家马可·波罗约 1275 年到达元朝大都，在中国游历十七年，回国后口述成《马可·波罗行纪》，激起欧洲人对东方的向往。（《马可·波罗行纪》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"辽宋夏金元时期的对外交流；经济重心南移的完成：从唐朝中期开始的经济重心南移，到南宋时最后完成。原因是北方战乱、人口南迁带来劳动力与先进技术，南方自然条件优越、社会相对安定，统治者重视生产。","explain":"材料出自《马可·波罗行纪》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-2-7-g4","type":"short","stem":"阅读材料，回答问题。\n材料：北宋庆历年间，毕昇用胶泥刻字，每字一印，火烧令坚，排版印刷，比雕版印刷更省时省料。沈括在《梦溪笔谈》中详细记录了这一工艺。（沈括《梦溪笔谈》卷十八）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"辽宋夏金元时期的科技与文化；宋元科技成就：北宋匠人毕昇发明活字印刷术，指南针（罗盘）应用于航海，火药在宋元时期广泛用于军事；三大发明由阿拉伯人传入欧洲，推动了欧洲社会的变革。","explain":"材料出自沈括《梦溪笔谈》卷十八。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-8a-mid","title":"八年级上册 期中测试","subtitle":"八年级上册 · 期中","grade":"8a","tags":["八年级上册","期中测试","阶段检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期中测试"},{"k":"题量","v":"选择题 20 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8a-u1-q1","type":"choice","stem":"英国发动鸦片战争的根本原因是","answer":"B","explain":"鸦片战争是英国资本主义发展的必然结果：工业革命后英国急需商品市场和原料产地。虎门销烟只是英国发动战争的借口，即直接原因。","options":["林则徐在虎门销烟","英国为打开中国市场、推销工业品并掠夺原料","清政府闭关自守、禁止通商","中英两国贸易长期不平衡"],"tags":["鸦片战争","历史解释"]},{"id":"h8a-u1-q2","type":"choice","stem":"《南京条约》的各项内容中，最能反映英国打开中国市场、便利经济侵略意图的是","answer":"C","explain":"五口通商打开了中国大门，协定关税破坏了中国关税自主权，使列强可以低价倾销商品、掠夺原料，最能体现其经济侵略意图。割地赔款是政治与财政层面的侵害。","options":["割香港岛给英国","赔款 2100 万银元","开放五处通商口岸并协定关税","英军占领广州"],"tags":["南京条约","史料实证"]},{"id":"cat-8a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 林则徐在广东虎门销烟\n② 鸦片战争\n③ 中英《南京条约》签订","answer":"A","explain":"按时间顺序应为：①林则徐在广东虎门销烟（1839 年 6 月）→②鸦片战争（1840 年 6 月—1842 年 8 月）→③中英《南京条约》签订（1842 年 8 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-1-g2","type":"choice","stem":"下列关于「鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。","列强侵华的核心目的是把中国变成其商品市场和原料产地；《南京条约》中的**协定关税**破坏中国关税自主权，便利了列强的经济侵略。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8a-u1-q3","type":"choice","stem":"1860 年焚毁圆明园的侵略者是","answer":"B","explain":"第二次鸦片战争中，1860 年 10 月英法联军攻入北京，抢劫并焚毁了圆明园。八国联军侵华是 1900 年的事。","options":["英国军队","英法联军","八国联军","日本军队"],"tags":["第二次鸦片战争","时空观念"]},{"id":"cat-8a-1-2-g2","type":"choice","stem":"下列关于「第二次鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-2-g5","type":"choice","stem":"「第二次鸦片战争」发生于","answer":"A","explain":"本课时间轴：第二次鸦片战争（1856 年 10 月—1860 年 10 月）。英法联军发动，是鸦片战争的继续和扩大；1858 年《天津条约》。其余三个时间是同一单元相邻课时的事件时间。","options":["1856 年 10 月—1860 年 10 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-2-g6","type":"choice","stem":"下列考点中，属于「第二次鸦片战争」的是","answer":"A","explain":"本课考点（重点）：第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联军 1860 年所为。其余三项是同一单元相邻课时的考点。","options":["第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联…","鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战…","《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、…","鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8a-u1-q4","type":"choice","stem":"太平天国运动中，标志其由盛转衰的事件是","answer":"C","explain":"1856 年的天京事变是太平天国领导集团内讧，使其由盛转衰；1864 年天京陷落标志运动失败。","options":["金田起义","定都天京","天京事变","天京陷落"],"tags":["太平天国运动","时空观念"]},{"id":"cat-8a-1-3-g2","type":"choice","stem":"下列关于「太平天国运动」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-3-g5","type":"choice","stem":"「洪秀全在广西桂平金田村起义，建号太平天国」发生于","answer":"A","explain":"本课时间轴：洪秀全在广西桂平金田村起义，建号太平天国（1851 年 1 月）。1853 年攻占南京改名天京并定都，与清朝对峙。其余三个时间是同一单元相邻课时的事件时间。","options":["1851 年 1 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8a-1-3-g6","type":"choice","stem":"下列考点中，属于「太平天国运动」的是","answer":"A","explain":"本课考点（重点）：太平天国运动：金田起义（1851）—定都天京（1853）—《天朝田亩制度》—天京事变（1856，由盛转衰）—天京陷落（1864）；它沉重打击了清朝统治和外国侵略势力，但农民阶级不能领导中国革命取得胜利。其余三项是同一单元相邻课时的考点。","options":["太平天国运动：金田起义（1851）—定都天京（1853）—《天朝田亩制度》—天京事变（1…","鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战…","《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、…","鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8a-u2-q1","type":"choice","stem":"洋务运动「只学习西方技术而不改变封建制度」，导致其最终破产。标志其破产的事件是","answer":"B","explain":"1895 年初威海卫战役中北洋舰队全军覆没，甲午战争中国战败，宣告了洋务运动的破产，也说明单靠引进技术不能救中国。","options":["太平天国运动失败","甲午中日战争中国战败、北洋舰队全军覆没","《辛丑条约》的签订","戊戌变法失败"],"tags":["洋务运动","历史解释"]},{"id":"h8a-u2-q3","type":"choice","stem":"「法者天下之公器也，变者天下之公理也」的提出者，也是戊戌变法主要领导人之一的是","answer":"B","explain":"此语出自梁启超《变法通议》。梁启超与康有为是维新变法的主要领导人，严复译述《天演论》宣传进化论，李鸿章是洋务派代表。","options":["李鸿章","梁启超","严复","孙中山"],"tags":["戊戌变法","历史解释"]},{"id":"cat-8a-2-1-g2","type":"choice","stem":"下列关于「洋务运动和边疆危机」的表述，错误的是","answer":"A","explain":"认为洋务运动是中国近代史的开端——「近代史」讲社会性质变化，「近代化」讲向工业化、民主化迈进，两个概念必须分清。正确表述：中国近代史的开端是鸦片战争；洋务运动是中国**近代化**的开端。","options":["认为洋务运动是中国近代史的开端。","中国近代史的开端是鸦片战争；洋务运动是中国**近代化**的开端。","近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","洋务运动：以「自强」「求富」为口号，创办安庆内军械所、江南机器制造总局、福州船政局等军事工业和轮船招商局、开平煤矿、汉阳铁厂、湖北织布局等民用企业，筹建北洋舰队等新式海陆军。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-1-g3","type":"choice","stem":"下列结论中，属于「洋务运动和边疆危机」的是","answer":"A","explain":"本课结论：近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["近代化探索由表及里：洋务运动学**技术**，戊戌变法学**制度**，一层比一层深入；但地主阶级和资产阶级维新派都无法改变中国的命运。","甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。","《马关条约》允许日本在通商口岸开设工厂，标志列强对华侵略**由以商品输出为主转向以资本输出为主**，中国的民族危机空前严重。","改革要顺应历史潮流并依靠可靠的力量：戊戌变法失败说明**资产阶级改良道路在中国行不通**，这为后来辛亥革命用暴力推翻清政府提供了历史教训。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"h8a-u2-q2","type":"choice","stem":"标志列强对华经济侵略由以商品输出为主转向以资本输出为主的不平等条约条款是","answer":"B","explain":"允许在通商口岸开设工厂，意味着列强可以直接利用中国的原料和劳动力进行生产，是资本输出的典型方式，故《马关条约》是这一转变的标志。","options":["《南京条约》中的协定关税","《马关条约》中允许日本在通商口岸开设工厂","《辛丑条约》中的巨额赔款","《北京条约》中的增开天津为商埠"],"tags":["马关条约","资本输出"]},{"id":"h8a-u2-q4","type":"choice","stem":"《辛丑条约》中，最能说明清政府已成为「洋人的朝廷」的条款是","answer":"C","explain":"「保证严禁人民参加反帝活动」意味着清政府由中国的政权机构变成列强镇压中国人民的工具，故称「洋人的朝廷」，标志中国完全陷入半殖民地半封建社会的深渊。","options":["赔款白银 4.5 亿两","划定北京东交民巷为使馆界","清政府保证严禁人民参加各种形式的反帝活动","拆毁大沽炮台"],"tags":["辛丑条约","历史解释"]},{"id":"cat-8a-2-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 甲午中日战争\n② 《马关条约》签订\n③ 康有为、梁启超等发起公车上书\n④ 《辛丑条约》签订","answer":"A","explain":"按时间顺序应为：①甲午中日战争（1894 年 7 月—1895 年 4 月）→②《马关条约》签订（1895 年 4 月）→③康有为、梁启超等发起公车上书（1895 年）→④《辛丑条约》签订（1901 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"cat-8a-2-2-g2","type":"choice","stem":"下列关于「甲午中日战争与列强瓜分中国狂潮」的表述，错误的是","answer":"A","explain":"认为北洋舰队是在黄海海战中全军覆没的——两场海战的结果最易互换，记「黄海海战失致远，威海卫之战全军覆没」。正确表述：黄海海战只是重创北洋舰队；1895 年初的威海卫战役中北洋舰队全军覆没，标志洋务运动的破产。","options":["认为北洋舰队是在黄海海战中全军覆没的。","黄海海战只是重创北洋舰队；1895 年初的威海卫战役中北洋舰队全军覆没，标志洋务运动的破产。","甲午战败与《马关条约》证明：**只学习西方技术而不改变腐朽的封建制度，不能使中国走上富强道路**。","《马关条约》允许日本在通商口岸开设工厂，标志列强对华侵略**由以商品输出为主转向以资本输出为主**，中国的民族危机空前严重。"],"difficulty":2,"tags":["八年级上册","第二单元","本课练习"]},{"id":"h8a-u1-m1-q1","type":"short","stem":"（1）依据材料一，说明林则徐主张禁烟的原因；结合所学指出虎门销烟的意义。（4 分）","answer":"原因：鸦片大量输入使中国白银外流、财政困难（「无可以充饷之银」），并严重摧残吸食者的体质，军队战斗力削弱（「无可以御敌之兵」），危及清朝统治。意义：虎门销烟是中国人民禁烟斗争的伟大胜利，显示了中华民族反抗外来侵略的坚强意志，林则徐是当之无愧的民族英雄。","explain":"","tags":["虎门销烟","史料实证"],"rubric":["答出白银外流、财政困难","答出兵弱、摧残体质","答出禁烟斗争的伟大胜利","答出反抗侵略的坚强意志/民族英雄"]},{"id":"h8a-u1-m1-q2","type":"short","stem":"（2）依据材料二，指出《南京条约》中破坏中国关税自主权的条款，并结合材料三说明鸦片战争对中国社会性质的影响。（6 分）","answer":"条款：英商进出口货物应纳税款必须经过双方协议（协定关税）。影响：中国的领土完整和主权遭到破坏，开始沦为半殖民地；封建经济逐步解体，被卷入资本主义世界市场，开始沦为半封建。总之，鸦片战争后中国开始沦为半殖民地半封建社会，鸦片战争成为中国近代史的开端。","explain":"","tags":["南京条约","半殖民地半封建社会"],"rubric":["答出协定关税","答出领土、主权遭到破坏","答出封建经济开始解体","答出开始沦为半殖民地半封建社会","答出是中国近代史的开端"]}]},{"id":"hp-8a-fin","title":"八年级上册 期末测试","subtitle":"八年级上册 · 期末","grade":"8a","tags":["八年级上册","期末测试","全册检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期末测试"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"90 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"cat-8a-4-1-g2","type":"choice","stem":"下列关于「五四运动」的表述，错误的是","answer":"A","explain":"把五四运动的导火线说成「二十一条」的签订——两件事都与日本侵略山东有关，但时间与性质不同，属高频陷阱。正确表述：导火线是 1919 年巴黎和会上中国外交的失败（列强将德国在山东的特权转让给日本）；「二十一条」是 1915 年日本提出、袁世凯接受的事件。","options":["把五四运动的导火线说成「二十一条」的签订。","导火线是 1919 年巴黎和会上中国外交的失败（列强将德国在山东的特权转让给日本）；「二十一条」是 1915 年日本提出、袁世凯接受的事件。","新文化运动是**中国近代史上一次伟大的思想解放运动**：它动摇了封建道德礼教的统治地位，使中国人民特别是青年知识分子的思想得到极大解放，为马克思主义在中国的传播创造了条件。","五四运动是**中国新民主主义革命的开端**：工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质，促进了马克思主义与中国工人运动的结合。"],"difficulty":2,"tags":["八年级上册","第四单元","本课练习"]},{"id":"h8a-u4-q1","type":"choice","stem":"新文化运动开始的标志是","answer":"B","explain":"1915 年陈独秀在上海创办《青年杂志》（自第二卷起改名《新青年》），标志新文化运动开始。《天演论》是维新变法的思想武器。","options":["严复译述《天演论》","陈独秀在上海创办《青年杂志》","五四运动爆发","中共一大召开"],"tags":["新文化运动","时空观念"]},{"id":"h8a-u4-q2","type":"choice","stem":"五四运动爆发的导火线是","answer":"B","explain":"1919 年巴黎和会拒绝中国正当要求，竟将德国在山东的特权转让给日本，消息传回国内直接引发五四运动。","options":["日本提出「二十一条」","巴黎和会上中国外交的失败","北洋政府镇压学生游行","中国共产党号召反帝反封建"],"tags":["五四运动","历史解释"]},{"id":"h8a-u4-q3","type":"choice","stem":"五四运动被称为中国新民主主义革命的开端，主要因为它","answer":"C","explain":"判断革命阶段的关键是领导阶级与指导思想。五四运动中工人阶级成为主力，运动具有彻底反帝反封建的性质，因此成为新民主主义革命的开端。","options":["取得了彻底胜利","由学生首先发起","工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质","建立了中国共产党"],"tags":["五四运动","唯物史观"]},{"id":"h8a-u4-q4","type":"choice","stem":"中共一大确定党的奋斗目标是","answer":"B","explain":"中共一大通过党的第一个纲领，确定党的名称为中国共产党，奋斗目标是推翻资产阶级政权，建立无产阶级专政，实现共产主义。A 项是中共二大提出的民主革命纲领的内容。","options":["打倒军阀、推翻国际帝国主义的压迫","推翻资产阶级政权，建立无产阶级专政，实现共产主义","联俄、联共、扶助农工","建立抗日民族统一战线"],"tags":["中共一大","历史解释"]},{"id":"h8a-u4-q5","type":"choice","stem":"第一次明确提出彻底的反帝反封建民主革命纲领的会议是","answer":"B","explain":"1922 年中共二大重申最高纲领，并第一次明确提出彻底的反帝反封建的民主革命纲领，为中国革命指明了方向。","options":["中共一大","中共二大","国民党一大","中共七大"],"tags":["中共二大","历史解释"]},{"id":"cat-8a-4-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 李大钊发表《庶民的胜利》《布尔什维主义的胜利》\n② 中共一大在上海召开，后转到浙江嘉兴南湖游船\n③ 京汉铁路工人大罢工","answer":"A","explain":"按时间顺序应为：①李大钊发表《庶民的胜利》《布尔什维主义的胜利》（1918 年）→②中共一大在上海召开，后转到浙江嘉兴南湖游船（1921 年 7 月）→③京汉铁路工人大罢工（1923 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第四单元","本课练习"]},{"id":"cat-8a-4-2-g2","type":"choice","stem":"下列关于「中国共产党诞生」的表述，错误的是","answer":"A","explain":"把新民主主义革命的开端记为中国共产党成立——两个结论都对，但对应不同事件，必须按设问区分。正确表述：新民主主义革命的开端是五四运动（1919 年）；中国共产党的成立使中国革命的面貌焕然一新。","options":["把新民主主义革命的开端记为中国共产党成立。","新民主主义革命的开端是五四运动（1919 年）；中国共产党的成立使中国革命的面貌焕然一新。","新文化运动是**中国近代史上一次伟大的思想解放运动**：它动摇了封建道德礼教的统治地位，使中国人民特别是青年知识分子的思想得到极大解放，为马克思主义在中国的传播创造了条件。","五四运动是**中国新民主主义革命的开端**：工人阶级登上政治舞台并发挥主力作用，具有彻底反帝反封建的性质，促进了马克思主义与中国工人运动的结合。"],"difficulty":2,"tags":["八年级上册","第四单元","本课练习"]},{"id":"h8a-u5-q1","type":"choice","stem":"标志国共第一次合作正式建立的事件是","answer":"B","explain":"1924 年 1 月国民党一大召开，把旧三民主义发展为新三民主义，确立联俄、联共、扶助农工三大政策，标志国共第一次合作正式建立。黄埔军校创办是合作的成果。","options":["中共三大的召开","国民党一大在广州召开","黄埔军校创办","北伐战争开始"],"tags":["国共合作","时空观念"]},{"id":"h8a-u5-q3","type":"choice","stem":"1927 年秋收起义受挫后，毛泽东率部队向井冈山进军，其深远意义在于","answer":"B","explain":"秋收起义受挫后转向农村，创建井冈山革命根据地，开辟了农村包围城市、武装夺取政权的道路，这是马克思主义与中国国情相结合的正确道路。","options":["完成了北伐战争的任务","开创了农村包围城市、武装夺取政权的革命道路","促成了国共第二次合作","建立了中华苏维埃共和国"],"tags":["井冈山道路","历史解释"]},{"id":"cat-8a-5-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 国民党一大在广州召开\n② 黄埔军校在广州创办\n③ 国民革命军出师北伐\n④ 四一二反革命政变，南京国民政府成立","answer":"A","explain":"按时间顺序应为：①国民党一大在广州召开（1924 年 1 月）→②黄埔军校在广州创办（1924 年 5 月）→③国民革命军出师北伐（1926 年）→④四一二反革命政变，南京国民政府成立（1927 年 4 月）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-1-g2","type":"choice","stem":"下列关于「国共合作与北伐战争」的表述，错误的是","answer":"A","explain":"认为北伐战争胜利了，国民革命就成功了——「北伐胜利」与「国民革命失败」两句话都对，指向不同层面，材料题常要求分别说明。正确表述：北伐战争取得了胜利进军、基本推翻北洋军阀统治；但 1927 年蒋介石、汪精卫相继叛变革命，国民革命最终失败。","options":["认为北伐战争胜利了，国民革命就成功了。","北伐战争取得了胜利进军、基本推翻北洋军阀统治；但 1927 年蒋介石、汪精卫相继叛变革命，国民革命最终失败。","**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。","第一次国共合作的成果：创办黄埔军校，培养革命军事政治人才；推动北伐战争胜利进军，基本推翻了北洋军阀的统治。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-1-g3","type":"choice","stem":"下列结论中，属于「国共合作与北伐战争」的是","answer":"A","explain":"本课结论：**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。","**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。","**遵义会议是党的历史上生死攸关的转折点**：它在危急关头挽救了党、挽救了红军、挽救了中国革命，是中国共产党从幼年走向成熟的标志。","**长征胜利使中国革命转危为安**：它保存了革命的基干力量，播下了革命种子，为开创抗日战争的新局面奠定了基础。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"h8a-u5-q2","type":"choice","stem":"南昌起义最重要的历史意义是","answer":"B","explain":"1927 年 8 月 1 日南昌起义打响武装反抗国民党反动统治的第一枪，是中国共产党独立领导武装斗争、创建人民军队的开始，故 8 月 1 日为建军节。","options":["建立了第一个农村革命根据地","打响武装反抗国民党反动统治的第一枪，是中国共产党创建人民军队的开始","开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位","使中国革命转危为安"],"tags":["南昌起义","历史解释"]},{"id":"cat-8a-5-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 南昌起义\n② 八七会议与秋收起义\n③ 井冈山会师，成立中国工农红军第四军","answer":"A","explain":"按时间顺序应为：①南昌起义（1927 年 8 月 1 日）→②八七会议与秋收起义（1927 年 8—9 月）→③井冈山会师，成立中国工农红军第四军（1928 年 4 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-2-g2","type":"choice","stem":"下列关于「毛泽东开辟井冈山道路」的表述，错误的是","answer":"A","explain":"把井冈山革命根据地与井冈山会师的时间、意义混在一起——「创建根据地」与「会师建军队」是两件事，时序题常设陷阱。正确表述：1927 年 10 月毛泽东创建井冈山革命根据地（第一个农村革命根据地）；1928 年 4 月井冈山会师成立红四军。","options":["把井冈山革命根据地与井冈山会师的时间、意义混在一起。","1927 年 10 月毛泽东创建井冈山革命根据地（第一个农村革命根据地）；1928 年 4 月井冈山会师成立红四军。","**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。","南昌起义的意义：打响武装反抗国民党反动统治的第一枪，是中国共产党独立领导武装斗争、创建人民军队的开始，8 月 1 日由此成为建军节。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"cat-8a-5-2-g3","type":"choice","stem":"下列结论中，属于「毛泽东开辟井冈山道路」的是","answer":"A","explain":"本课结论：**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["**中国共产党必须掌握革命武装**：大革命失败的教训使党认识到，没有人民的军队便没有人民的一切，南昌起义正是创建人民军队的开始。","**国共合作则两利、分裂则两伤**：第一次国共合作推动了北伐战争的胜利进军，合作破裂则使国民革命失败、内战再起。","**遵义会议是党的历史上生死攸关的转折点**：它在危急关头挽救了党、挽救了红军、挽救了中国革命，是中国共产党从幼年走向成熟的标志。","**长征胜利使中国革命转危为安**：它保存了革命的基干力量，播下了革命种子，为开创抗日战争的新局面奠定了基础。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"h8a-u5-q4","type":"choice","stem":"被称为「党的历史上生死攸关的转折点」的会议是","answer":"B","explain":"1935 年 1 月遵义会议开始确立以毛泽东同志为主要代表的马克思主义正确路线在党中央的领导地位，在危急关头挽救了党、挽救了红军、挽救了中国革命。","options":["八七会议","遵义会议","中共七大","中共二大"],"tags":["遵义会议","历史解释"]},{"id":"h8a-u5-q5","type":"choice","stem":"红军长征胜利结束的标志是","answer":"C","explain":"1936 年 10 月红军三大主力在甘肃会宁会师，标志长征胜利结束；1935 年 10 月中央红军到达吴起镇是中央红军长征的结束。","options":["1935 年 1 月遵义会议的召开","1935 年 10 月中央红军到达陕北吴起镇","1936 年 10 月红军三大主力在甘肃会宁会师","1937 年七七事变的爆发"],"tags":["长征","时空观念"]},{"id":"cat-8a-5-3-g2","type":"choice","stem":"下列关于「中国工农红军长征与遵义会议」的表述，错误的是","answer":"A","explain":"把长征结束的时间记成 1935 年——两个时间点分别对应「中央红军到达陕北」与「长征胜利结束」，注意题目问的是哪一个。正确表述：1935 年 10 月中央红军到达陕北吴起镇；1936 年 10 月红军三大主力在甘肃会宁会师，长征胜利结束。","options":["把长征结束的时间记成 1935 年。","1935 年 10 月中央红军到达陕北吴起镇；1936 年 10 月红军三大主力在甘肃会宁会师，长征胜利结束。","**遵义会议是党的历史上生死攸关的转折点**：它在危急关头挽救了党、挽救了红军、挽救了中国革命，是中国共产党从幼年走向成熟的标志。","**长征胜利使中国革命转危为安**：它保存了革命的基干力量，播下了革命种子，为开创抗日战争的新局面奠定了基础。"],"difficulty":2,"tags":["八年级上册","第五单元","本课练习"]},{"id":"h8a-u6-q1","type":"choice","stem":"中国人民抗日战争的起点，也是中国局部抗战开始的事件是","answer":"A","explain":"1931 年九一八事变是中国人民抗日战争的起点，中国人民的局部抗战由此开始；1937 年七七事变标志全民族抗战开始。","options":["九一八事变","华北事变","七七事变","八一三事变"],"tags":["九一八事变","时空观念"]},{"id":"h8a-u6-q2","type":"choice","stem":"西安事变和平解决的最重要意义是","answer":"B","explain":"西安事变的和平解决，标志着十年内战基本结束，抗日民族统一战线初步形成，成为扭转时局的关键。","options":["迫使蒋介石放弃了反共立场","标志十年内战基本结束，抗日民族统一战线初步形成","使红军获得了合法地位","标志抗日战争的胜利"],"tags":["西安事变","历史解释"]},{"id":"cat-8a-6-1-g2","type":"choice","stem":"下列关于「从九一八事变到西安事变」的表述，错误的是","answer":"A","explain":"把「中国人民抗日战争的起点」记为 1937 年七七事变——「起点」与「全民族抗战开始」是两个不同层级的结论，是高频易错点。正确表述：中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","options":["把「中国人民抗日战争的起点」记为 1937 年七七事变。","中国人民抗日战争的起点是 1931 年九一八事变，由此开始局部抗战；1937 年七七事变标志全民族抗战开始。","**全民族抗战是抗战胜利的根本保证**：国共合作建立抗日民族统一战线，正面战场与敌后战场相互配合，中华民族才第一次取得反侵略战争的完全胜利。","**中国共产党是全民族抗战的中流砥柱**：最早举起抗日旗帜、提出全面抗战路线、开辟敌后战场、坚持抗战、反对投降，为抗战胜利作出了决定性贡献。"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-1-g5","type":"choice","stem":"「九一八事变」发生于","answer":"A","explain":"本课时间轴：九一八事变（1931 年 9 月 18 日）。日本关东军炸毁南满铁路柳条湖段并进攻沈阳北大营；中国人民的局部抗战开始，这也是中国人民抗日战争的起点。其余三个时间是同一单元相邻课时的事件时间。","options":["1931 年 9 月 18 日","1936 年 12 月 12 日","1937 年 7 月 7 日","1937 年 12 月 13 日"],"difficulty":1,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-6-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 西安事变（双十二事变）\n② 七七事变（卢沟桥事变）\n③ 南京大屠杀","answer":"A","explain":"按时间顺序应为：①西安事变（双十二事变）（1936 年 12 月 12 日）→②七七事变（卢沟桥事变）（1937 年 7 月 7 日）→③南京大屠杀（1937 年 12 月 13 日）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第六单元","本课练习"]},{"id":"cat-8a-3-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1913 年 3 月，国民党代理理事长宋教仁在上海遇刺身亡，舆论普遍认为是袁世凯主谋，引发「二次革命」。（《北洋军阀史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"帝制复辟与军阀割据；辛亥革命的局限性：没有改变中国半殖民地半封建社会的性质，没有完成反帝反封建的革命任务，革命果实被袁世凯窃取。","explain":"材料出自《北洋军阀史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h8a-u4-m1-q1","type":"short","stem":"（1）材料一中的「两位先生」指什么？依据材料一并结合所学，说明新文化运动的作用。（5 分）","answer":"「两位先生」指民主与科学。作用：新文化运动动摇了封建道德礼教的统治地位，使中国人民特别是青年知识分子的思想得到极大解放；它提倡白话文，推动了文学革命与文化普及；为马克思主义在中国的传播和五四运动的爆发创造了条件。总起来说，它是一次伟大的思想解放运动。","explain":"","tags":["新文化运动","史料实证"],"rubric":["答出民主与科学","答出动摇封建道德礼教/解放思想","答出为马克思主义传播创造条件","答出是伟大的思想解放运动"]},{"id":"h8a-u4-m1-q2","type":"short","stem":"（2）材料二体现了五四运动的什么精神？结合材料三说明中国共产党成立后中国革命为什么「面貌焕然一新」。（6 分）","answer":"精神：材料二表现出誓死捍卫国家主权、不向侵略者低头的爱国主义精神，即五四精神，其核心是爱国主义（还包括进步、民主、科学）。「焕然一新」的原因：中国共产党以马克思主义为指导思想，有了科学理论的指导；中共一大确定了推翻资产阶级政权、实现共产主义的奋斗目标，中共二大又第一次明确提出彻底的反帝反封建的民主革命纲领，使中国革命有了明确方向；中国共产党代表工人阶级和广大人民利益，能够深入发动群众，从而开辟了与以往一切政治力量都不相同的革命道路。","explain":"","tags":["五四运动","中共成立"],"rubric":["答出爱国主义/五四精神","答出以马克思主义为指导","答出提出彻底的反帝反封建纲领","答出代表人民利益、发动群众","答出中国革命有了坚强领导核心"]}]},{"id":"hp-8b-mid","title":"八年级下册 期中测试","subtitle":"八年级下册 · 期中","grade":"8b","tags":["八年级下册","期中测试","阶段检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期中测试"},{"k":"题量","v":"选择题 20 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8b-u1-q1","type":"choice","stem":"标志着中国人民从此站起来了、成为国家的主人的历史事件是","answer":"B","explain":"1949 年 10 月 1 日开国大典宣告中华人民共和国中央人民政府成立，中国人民从此站起来了，成为国家的主人。政协会议是成立前的筹备，西藏和平解放与抗美援朝是新中国成立后巩固政权的措施。","options":["中国人民政治协商会议第一届全体会议召开","开国大典，中华人民共和国成立","西藏和平解放","抗美援朝战争取得胜利"],"tags":["新中国成立","时空观念"]},{"id":"h8b-u1-q5","type":"choice","stem":"1949 年 9 月，中国人民政治协商会议第一届全体会议通过的、在 1954 年宪法颁布前起临时宪法作用的文件是","answer":"B","explain":"《共同纲领》是在 1954 年宪法颁布前起临时宪法作用的文件；1954 年宪法是我国第一部社会主义类型的宪法；《土地改革法》是 1950 年颁布的。","options":["《中华民国临时约法》","《中国人民政治协商会议共同纲领》","《中华人民共和国宪法》","《中华人民共和国土地改革法》"],"tags":["共同纲领","史料实证"]},{"id":"cat-8b-1-1-g2","type":"choice","stem":"下列关于「中华人民共和国成立」的表述，错误的是","answer":"A","explain":"把《共同纲领》说成 1954 年宪法——「起临时宪法作用的文件」不等于「宪法」，这是两句不同的话。正确表述：1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","options":["把《共同纲领》说成 1954 年宪法。","1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利，中国人民从此站起来了，成为国家的主人，中国历史从此揭开了新的篇章。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-1-1-g5","type":"choice","stem":"「中国人民政治协商会议第一届全体会议在北平召开」发生于","answer":"A","explain":"本课时间轴：中国人民政治协商会议第一届全体会议在北平召开（1949 年 9 月）。通过《中国人民政治协商会议共同纲领》，起临时宪法作用；决定国旗为五星红旗、以《义勇军进行曲》为代国歌、首都为北京、采用公元纪年。其余三个时间是同一单元相邻课时的事件时间。","options":["1949 年 9 月","1950 年 6 月","1950 年 10 月","1951 年"],"difficulty":1,"tags":["八年级下册","第一单元","本课练习"]},{"id":"h8b-u1-q2","type":"choice","stem":"1951 年西藏和平解放的重要意义是","answer":"A","explain":"西藏和平解放使祖国大陆获得统一，各族人民实现了大团结。民族区域自治制度在 1954 年宪法中确立为一项基本政治制度；西藏自治区成立于 1965 年；台湾问题尚未解决，不能说「祖国获得完全统一」。","options":["祖国大陆获得统一，各族人民实现大团结","标志着祖国获得完全统一","标志着民族区域自治制度正式确立","西藏自治区正式成立"],"tags":["西藏和平解放","时空观念"]},{"id":"h8b-u1-q4","type":"choice","stem":"1950—1952 年底土地改革完成后，我国农村土地的所有权状况是","answer":"D","explain":"土地改革废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，土地归农民私有。土地归集体所有是 1953—1956 年农业合作化的结果。","options":["归国家所有","归集体所有","归地主与农民共同所有","归农民所有"],"tags":["土地改革","历史解释"]},{"id":"h8b-u1-q6","type":"choice","stem":"抗美援朝战争的胜利对中国最主要的影响是","answer":"D","explain":"抗美援朝战争的胜利打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。中国进入社会主义社会以 1956 年三大改造基本完成为标志，结束半殖民地半封建社会历史以新中国成立为标志。","options":["使中国完成了国家统一","使中国从此进入社会主义社会","结束了半殖民地半封建社会的历史","打破了美军不可战胜的神话，大大提高了我国的国际地位"],"tags":["抗美援朝","历史解释"]},{"id":"cat-8b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中央人民政府颁布《中华人民共和国土地改革法》，土…\n② 中国人民志愿军开赴朝鲜，抗美援朝战争开始\n③ 西藏和平解放\n④ 全国大陆基本上完成土地改革","answer":"A","explain":"按时间顺序应为：①中央人民政府颁布《中华人民共和国土地改革法》，土地改革在全国展开（1950 年 6 月）→②中国人民志愿军开赴朝鲜，抗美援朝战争开始（1950 年 10 月）→③西藏和平解放（1951 年）→④全国大陆基本上完成土地改革（1952 年底）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-1-2-g2","type":"choice","stem":"下列关于「巩固人民民主政权」的表述，错误的是","answer":"A","explain":"把抗美援朝战争开始的时间记成 1953 年——1950 年是「出兵」，1953 年是「停战」，两个时间点最容易被调换。正确表述：1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","options":["把抗美援朝战争开始的时间记成 1953 年。","1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。","土地改革彻底摧毁了在我国延续两千多年的封建土地制度，消灭了地主阶级，农民成为土地的主人，解放了农村生产力，为国家工业化建设准备了条件。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"h8b-u2-q2","type":"choice","stem":"1954 年《中华人民共和国宪法》的历史地位是","answer":"D","explain":"1954 年宪法是我国第一部社会主义类型的宪法，也是我国有史以来真正反映人民利益的宪法；起临时宪法作用的文件是 1949 年的《共同纲领》。","options":["我国第一部宪法性质的临时文件","我国第一部资产阶级民主主义宪法","我国第一部民族区域自治法","我国第一部社会主义类型的宪法"],"tags":["1954 年宪法","历史解释"]},{"id":"h8b-u2-q3","type":"choice","stem":"标志着社会主义基本制度在我国建立起来的事件是","answer":"A","explain":"1956 年底三大改造基本完成，实现了生产资料私有制向社会主义公有制的转变，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段。","options":["1956 年底三大改造基本完成","中华人民共和国成立","第一个五年计划超额完成","1954 年宪法的颁布"],"tags":["三大改造","历史解释"]},{"id":"h8b-u2-q4","type":"choice","stem":"被称为「探索建设社会主义道路的良好开端」的会议是","answer":"D","explain":"1956 年召开的中共八大正确分析了国内主要矛盾，提出集中力量发展社会生产力，是探索建设社会主义道路的良好开端。","options":["中共七大","第一届全国人民代表大会","中共十一届三中全会","中共八大"],"tags":["中共八大","历史解释"]},{"id":"cat-8b-1-3-g2","type":"choice","stem":"下列关于「社会主义制度建立」的表述，错误的是","answer":"A","explain":"把《共同纲领》与 1954 年宪法混为一谈——两者都是「宪法类」文件，但性质与地位不同，选择题常并列作选项。正确表述：1949 年《共同纲领》起临时宪法作用；1954 年宪法是我国第一部社会主义类型的宪法，以根本法形式确定了人民代表大会制度。","options":["把《共同纲领》与 1954 年宪法混为一谈。","1949 年《共同纲领》起临时宪法作用；1954 年宪法是我国第一部社会主义类型的宪法，以根本法形式确定了人民代表大会制度。","1956 年底三大改造基本完成，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段；社会主义制度的建立是中国历史上最深刻最伟大的社会变革，为当代中国一切发展进步奠定了根本政治前提和制度基础。","1954 年宪法是我国第一部社会主义类型的宪法，以国家根本法的形式确定了人民代表大会制度；人民代表大会制度是我国的根本政治制度。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"h8b-u5-q1","type":"choice","stem":"和平共处五项原则首次提出的时间和提出者是","answer":"A","explain":"1953 年 12 月周恩来在接见印度代表团时首次提出和平共处五项原则；1954 年周恩来访问印度、缅甸，双方一致同意以它作为指导相互关系的基本原则。","options":["1953 年 12 月，周恩来","1954 年，毛泽东","1955 年，周恩来","1971 年，周恩来"],"tags":["和平共处五项原则","时空观念"]},{"id":"h8b-u5-q2","type":"choice","stem":"在万隆会议上，周恩来提出的方针是","answer":"D","explain":"1955 年万隆会议是第一次没有殖民主义国家参加的亚非国际会议，周恩来提出「求同存异」的方针，促进了会议的圆满成功，促进了中国同亚非各国的团结与合作。","options":["独立自主","和平共处","一边倒","求同存异"],"tags":["万隆会议","历史解释"]},{"id":"h8b-u5-q5","type":"choice","stem":"1972 年中日两国正式建立外交关系，其直接推动因素是","answer":"B","explain":"1972 年中美关系开始走向正常化，直接推动了中日建交。中国恢复联合国合法席位（1971 年）有利于打开外交新局面，但不是中日建交的直接推动因素。","options":["中国恢复在联合国的合法席位","中美关系开始走向正常化","万隆会议的召开","和平共处五项原则的提出"],"tags":["中日建交","历史解释"]},{"id":"cat-8b-1-4-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 周恩来在接见印度代表团时首次提出和平共处五项原则\n② 中国第一次以世界五大国之一的身份参加日内瓦会议\n③ 万隆会议（第一次亚非会议）召开，周恩来提出「求同…","answer":"A","explain":"按时间顺序应为：①周恩来在接见印度代表团时首次提出和平共处五项原则（1953 年 12 月）→②中国第一次以世界五大国之一的身份参加日内瓦会议（1954 年）→③万隆会议（第一次亚非会议）召开，周恩来提出「求同存异」的方针（1955 年 4 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-8b-1-4-g2","type":"choice","stem":"下列关于「独立自主的和平外交」的表述，错误的是","answer":"A","explain":"认为和平共处五项原则是 1954 年首次提出的——「首次提出」与「共同倡导/确认」是两个时间点，最容易混。正确表述：1953 年 12 月周恩来在接见印度代表团时首次提出；1954 年周恩来访问印度、缅甸，双方一致同意以和平共处五项原则作为指导相互关系的基本原则。","options":["认为和平共处五项原则是 1954 年首次提出的。","1953 年 12 月周恩来在接见印度代表团时首次提出；1954 年周恩来访问印度、缅甸，双方一致同意以和平共处五项原则作为指导相互关系的基本原则。","和平共处五项原则标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生了深远影响。","中国始终奉行独立自主的和平外交政策，坚持走和平发展道路，推动构建人类命运共同体；国家实力是国际地位的基础，「弱国无外交」。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"h8b-u2-q5","type":"choice","stem":"「大跃进」和人民公社化运动给我们的最主要教训是","answer":"C","explain":"这两次失误反映了人民群众迫切改变落后面貌的愿望，但急于求成、忽视客观经济规律，造成 1959—1961 年国民经济严重困难。教训是必须从国情出发、实事求是、按客观经济规律办事。","options":["必须以阶级斗争为纲","必须优先发展重工业","必须从国情出发，按客观经济规律办事","必须加快生产资料公有化的速度"],"tags":["大跃进","唯物史观"]},{"id":"cat-8b-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 「大跃进」和农村人民公社化运动在全国展开\n② 实行「调整、巩固、充实、提高」的八字方针，调整国…\n③ 「文化大革命」","answer":"A","explain":"按时间顺序应为：①「大跃进」和农村人民公社化运动在全国展开（1958 年）→②实行「调整、巩固、充实、提高」的八字方针，调整国民经济（1961—1965 年）→③「文化大革命」（1966—1976 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级下册","第二单元","本课练习"]},{"id":"cat-8b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：五星红旗由曾联松设计；《义勇军进行曲》由田汉作词、聂耳作曲，原为电影《风云儿女》主题歌，1949 年被定为代国歌。（《中华人民共和国史》；2024 部编版八下第 1 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"中华人民共和国成立；1949 年 10 月 1 日的开国大典，标志着中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利。","explain":"材料出自《中华人民共和国史》；2024 部编版八下第 1 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h8b-u1-m1-q2","type":"short","stem":"（2）据材料二，土地改革废除的是什么制度、实行的是什么制度？据材料三并结合所学，说明土地改革的作用。（6 分）","answer":"废除地主阶级封建剥削的土地所有制，实行农民的土地所有制。作用：彻底摧毁了我国延续两千多年的封建土地制度，消灭了地主阶级；农民翻了身，成为土地的主人，人民政权更加巩固；大大解放了农村生产力，农业生产迅速恢复和发展，为国家工业化建设准备了条件。","explain":"","tags":["土地改革","历史解释"],"rubric":["答出「废除地主阶级封建剥削的土地所有制」","答出「实行农民的土地所有制」","答出「摧毁封建土地制度、消灭地主阶级」","答出「农民成为土地的主人／巩固人民政权」","答出「解放农村生产力／为国家工业化准备条件」"]}]},{"id":"hp-8b-fin","title":"八年级下册 期末测试","subtitle":"八年级下册 · 期末","grade":"8b","tags":["八年级下册","期末测试","全册检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期末测试"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"90 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h8b-u3-q3","type":"choice","stem":"明确提出建立社会主义市场经济体制目标的会议是","answer":"D","explain":"1992 年中共十四大明确提出建立社会主义市场经济体制的目标。同年邓小平南方谈话指出计划和市场都是经济手段，为这一目标提供了思想基础。","options":["中共十二大","中共十三大","中共十五大","中共十四大"],"tags":["十四大","时空观念"]},{"id":"cat-8b-3-3-g2","type":"choice","stem":"下列关于「改革开放和社会主义现代化建设的全…」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-3-3-g5","type":"choice","stem":"「开放大连、天津、青岛、上海、广州等 14 个沿海港口城市」发生于","answer":"A","explain":"本课时间轴：开放大连、天津、青岛、上海、广州等 14 个沿海港口城市（1984 年）。此后开辟沿海经济开放区，1990 年开发开放上海浦东。其余三个时间是同一单元相邻课时的事件时间。","options":["1984 年","1978 年 12 月","1978 年冬","1980 年"],"difficulty":1,"tags":["八年级下册","第三单元","本课练习"]},{"id":"h8b-u3-q1","type":"choice","stem":"中共十一届三中全会之所以被称为「新中国成立以来党的历史上具有深远意义的伟大转折」，主要是因为它","answer":"B","explain":"十一届三中全会冲破长期「左」的错误的严重束缚，确定解放思想、实事求是的指导方针，把工作中心转移到经济建设上来、实行改革开放，开启了改革开放和社会主义现代化建设新时期。建立社会主义市场经济体制的目标由 1992 年中共十四大提出。","options":["确立了毛泽东思想的指导地位","作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策","提出了建立社会主义市场经济体制的目标","宣布我国进入社会主义初级阶段"],"tags":["十一届三中全会","历史解释"]},{"id":"h8b-u3-q2","type":"choice","stem":"实行家庭联产承包责任制后，我国农村土地的所有权和经营权状况是","answer":"C","explain":"家庭联产承包责任制是在土地公有制的基础上改变经营管理方式，土地所有权仍归集体，农民通过承包获得经营权和收益，因而不是土地私有化。","options":["土地所有权和经营权都归农民","土地所有权归国家，经营权归农民","土地所有权归集体，农民获得承包经营权","土地所有权归农民，经营权归集体"],"tags":["家庭联产承包责任制","历史解释"]},{"id":"cat-8b-3-4-g2","type":"choice","stem":"下列关于「社会主义初级阶段基本路线」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第三单元","本课练习"]},{"id":"cat-8b-4-1-g2","type":"choice","stem":"下列关于「加快改革开放和社会主义现代化建设…」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-4-1-g7","type":"choice","stem":"关于「加快改革开放和社会主义现代化建设…」，下列表述正确的有\n① 中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开…\n② 改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中…\n③ 只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色…\n④ 认为家庭联产承包责任制是把土地分给农民个人所有。","answer":"A","explain":"①②③均取本课必背结论与考点；④错误——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」，正确表述应为：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["八年级下册","第四单元","本课练习"]},{"id":"h8b-u6-q6","type":"choice","stem":"改革开放以来我国人民生活水平大幅提高的根本原因是","answer":"C","explain":"社会生活变迁的根本原因是改革开放促进经济发展、生产力水平提高，为改善人民生活提供了物质基础；消费观念变化、科技进步是重要原因而非根本原因。","options":["人们消费观念的变化","科技进步改变了生活方式","改革开放促进了经济发展和生产力提高","国外商品大量进入中国市场"],"tags":["社会生活变迁","唯物史观"]},{"id":"cat-8b-4-2-g2","type":"choice","stem":"下列关于「中国特色社会主义事业取得新成就」的表述，错误的是","answer":"A","explain":"认为袁隆平培育成功籼型杂交水稻是在 20 世纪 90 年代——时间与人物必须一并记牢，材料题常以此考查「科技成就的年代定位」。正确表述：1973 年袁隆平成功培育出籼型杂交水稻，他被称为「杂交水稻之父」。","options":["认为袁隆平培育成功籼型杂交水稻是在 20 世纪 90 年代。","1973 年袁隆平成功培育出籼型杂交水稻，他被称为「杂交水稻之父」。","民族区域自治制度是我国的一项基本政治制度，保障了少数民族当家作主的权利，维护了民族团结和国家统一，为实现各民族共同繁荣奠定了基础。","「两弹一星」的研制成功，打破了帝国主义的核垄断，增强了我国的国防实力，极大提高了我国的国际地位；科技创新是综合国力竞争的决定性因素。"],"difficulty":2,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-4-2-g5","type":"choice","stem":"「中国政府对澳门恢复行使主权，澳门特别行政区成立」发生于","answer":"A","explain":"本课时间轴：中国政府对澳门恢复行使主权，澳门特别行政区成立（1999 年 12 月 20 日）。标志着中国人民在完成祖国统一大业的道路上又迈出了重要一步。其余三个时间是同一单元相邻课时的事件时间。","options":["1999 年 12 月 20 日","1992 年","1997 年","1964 年 10 月"],"difficulty":1,"tags":["八年级下册","第四单元","本课练习"]},{"id":"h8b-u5-q3","type":"choice","stem":"关于 1971 年中国在联合国合法席位的表述，正确的是","answer":"C","explain":"中国是联合国创始会员国和安理会常任理事国，1971 年第 26 届联大是「恢复」中华人民共和国在联合国的一切合法权利，并把台湾当局的代表驱逐出去。","options":["中国在这一年加入联合国","中国在这一年成为联合国安理会非常任理事国","第 26 届联大恢复中华人民共和国在联合国的一切合法权利","中国在这一年恢复了世界贸易组织成员地位"],"tags":["恢复联合国合法席位","历史解释"]},{"id":"h8b-u5-q4","type":"choice","stem":"中美关系开始走向正常化的标志是","answer":"B","explain":"1972 年 2 月尼克松访华，中美双方签署《联合公报》，美国承认只有一个中国、台湾是中国的一部分，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","options":["1971 年基辛格秘密访华","1972 年尼克松访华，中美双方签署《联合公报》","1972 年中日两国正式建立外交关系","1979 年中美正式建立外交关系"],"tags":["中美关系","时空观念"]},{"id":"h8b-u5-q5","type":"choice","stem":"1972 年中日两国正式建立外交关系，其直接推动因素是","answer":"B","explain":"1972 年中美关系开始走向正常化，直接推动了中日建交。中国恢复联合国合法席位（1971 年）有利于打开外交新局面，但不是中日建交的直接推动因素。","options":["中国恢复在联合国的合法席位","中美关系开始走向正常化","万隆会议的召开","和平共处五项原则的提出"],"tags":["中日建交","历史解释"]},{"id":"h8b-u5-q6","type":"choice","stem":"新时代中国特色大国外交倡导的重要理念是","answer":"A","explain":"新时代中国奉行独立自主的和平外交政策，提出共建「一带一路」倡议，推动构建人类命运共同体，积极参与全球治理，形成全方位、多层次、立体化的外交布局。","options":["构建人类命运共同体","文明冲突论","霸权稳定论","闭关自守"],"tags":["新时代外交","家国情怀"]},{"id":"cat-8b-4-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 周恩来在接见印度代表团时首次提出和平共处五项原则\n② 中国组建战略导弹部队（后称第二炮兵部队）\n③ 第 26 届联合国大会恢复中华人民共和国在联合国…\n④ 中日两国正式建立外交关系","answer":"A","explain":"按时间顺序应为：①周恩来在接见印度代表团时首次提出和平共处五项原则（1953 年 12 月）→②中国组建战略导弹部队（后称第二炮兵部队）（1966 年）→③第 26 届联合国大会恢复中华人民共和国在联合国的一切合法权利（1971 年 10 月）→④中日两国正式建立外交关系（1972 年 9 月）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-4-3-g2","type":"choice","stem":"下列关于「国防和外交工作新局面」的表述，错误的是","answer":"A","explain":"认为 1971 年中国「加入」联合国——表述差别决定得分：应为「恢复合法席位」，不是「加入」。正确表述：1971 年第 26 届联大恢复中华人民共和国在联合国的一切合法权利，中国是联合国创始会员国和安理会常任理事国。","options":["认为 1971 年中国「加入」联合国。","1971 年第 26 届联大恢复中华人民共和国在联合国的一切合法权利，中国是联合国创始会员国和安理会常任理事国。","和平共处五项原则标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生了深远影响。","1971 年恢复中华人民共和国在联合国的一切合法权利，是中国外交的重大胜利，也是广大发展中国家支持的结果；中国是联合国创始会员国和安理会常任理事国。"],"difficulty":2,"tags":["八年级下册","第四单元","本课练习"]},{"id":"cat-8b-5-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中共十一届三中全会召开\n② 安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏\n③ 深圳、珠海、汕头、厦门设立经济特区\n④ 开放大连、天津、青岛、上海、广州等 14 个沿海…","answer":"A","explain":"按时间顺序应为：①中共十一届三中全会召开（1978 年 12 月）→②安徽凤阳小岗村农民率先实行分田包干到户，自负盈亏（1978 年冬）→③深圳、珠海、汕头、厦门设立经济特区（1980 年）→④开放大连、天津、青岛、上海、广州等 14 个沿海港口城市（1984 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-5-1-g2","type":"choice","stem":"下列关于「开始全面建设小康社会」的表述，错误的是","answer":"A","explain":"认为家庭联产承包责任制是把土地分给农民个人所有——选择题常把「土地私有化」作为错项，材料题常问「改革后土地所有权有没有变化」。正确表述：它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","options":["认为家庭联产承包责任制是把土地分给农民个人所有。","它是在土地公有制的基础上改变经营管理方式，实行家庭经营、自负盈亏；土地所有权仍归集体，农民获得的是使用权和经营权。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"h8b-u3-q5","type":"choice","stem":"2021 年我国取得的重大成就是","answer":"D","explain":"2021 年中国共产党成立 100 周年，我国全面建成小康社会，历史性地解决了绝对贫困问题，实现了第一个百年奋斗目标。加入世界贸易组织是 2001 年，建成社会主义现代化强国是本世纪中叶的目标。","options":["加入世界贸易组织","建成社会主义现代化强国","基本实现社会主义现代化","全面建成小康社会，实现第一个百年奋斗目标"],"tags":["新时代","家国情怀"]},{"id":"h8b-u3-q6","type":"choice","stem":"把习近平新时代中国特色社会主义思想确立为党的指导思想的会议是","answer":"B","explain":"2017 年中共十九大把习近平新时代中国特色社会主义思想确立为党的指导思想；中共十八大以来，中国特色社会主义进入新时代；中共二十大提出以中国式现代化全面推进中华民族伟大复兴。","options":["中共十八大","中共十九大","中共二十大","中共十八届三中全会"],"tags":["中共十九大","理论体系"]},{"id":"cat-8b-5-2-g2","type":"choice","stem":"下列关于「夺取全面建设小康社会新胜利」的表述，错误的是","answer":"A","explain":"认为我国已经建成社会主义现代化强国——「全面建成小康社会」与「全面建成社会主义现代化强国」阶段不同，表述不能互换。正确表述：2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","options":["认为我国已经建成社会主义现代化强国。","2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开放和社会主义现代化建设新时期。","改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中华民族伟大复兴的关键一招。"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-5-2-g7","type":"choice","stem":"关于「夺取全面建设小康社会新胜利」，下列表述正确的有\n① 中共十一届三中全会是新中国成立以来党的历史上具有深远意义的伟大转折，开启了改革开…\n② 改革开放是决定当代中国命运的关键一招，也是决定实现「两个一百年」奋斗目标、实现中…\n③ 只有社会主义才能救中国，只有中国特色社会主义才能发展中国；只有坚持和发展中国特色…\n④ 认为我国已经建成社会主义现代化强国。","answer":"A","explain":"①②③均取本课必背结论与考点；④错误——「全面建成小康社会」与「全面建成社会主义现代化强国」阶段不同，表述不能互换，正确表述应为：2021 年我国全面建成小康社会、实现第一个百年奋斗目标；到 2035 年基本实现社会主义现代化，到本世纪中叶把我国建成社会主义现代化强国。","options":["①②③","①②④","①③④","②③④"],"difficulty":3,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-5-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 周恩来在接见印度代表团时首次提出和平共处五项原则\n② 中国组建战略导弹部队（后称第二炮兵部队）\n③ 第 26 届联合国大会恢复中华人民共和国在联合国…\n④ 中日两国正式建立外交关系","answer":"A","explain":"按时间顺序应为：①周恩来在接见印度代表团时首次提出和平共处五项原则（1953 年 12 月）→②中国组建战略导弹部队（后称第二炮兵部队）（1966 年）→③第 26 届联合国大会恢复中华人民共和国在联合国的一切合法权利（1971 年 10 月）→④中日两国正式建立外交关系（1972 年 9 月）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-5-3-g2","type":"choice","stem":"下列关于「推进国防军队建设和外交工作」的表述，错误的是","answer":"A","explain":"认为 1972 年中美签署《联合公报》就是中美建交——「开始走向正常化」与「正式建交」相隔七年，是高频错项。正确表述：1972 年尼克松访华、中美签署《联合公报》，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","options":["认为 1972 年中美签署《联合公报》就是中美建交。","1972 年尼克松访华、中美签署《联合公报》，中美关系开始走向正常化；1979 年 1 月中美正式建立外交关系。","和平共处五项原则标志着新中国外交政策的成熟，成为处理国与国之间相互关系的基本准则，在国际上产生了深远影响。","1971 年恢复中华人民共和国在联合国的一切合法权利，是中国外交的重大胜利，也是广大发展中国家支持的结果；中国是联合国创始会员国和安理会常任理事国。"],"difficulty":2,"tags":["八年级下册","第五单元","本课练习"]},{"id":"cat-8b-3-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：邓小平指出「计划多一点还是市场多一点，不是社会主义与资本主义的本质区别」，澄清了姓「资」姓「社」的困惑。（《邓小平文选》第三卷）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"改革开放和社会主义现代化建设的全面展开；1992 年邓小平南方谈话与中共十四大：南方谈话进一步解放思想，强调「发展才是硬道理」，指出计划和市场都是经济手段；中共十四大明确提出建立社会主义市场经济体制的目标。","explain":"材料出自《邓小平文选》第三卷。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-3-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：领导和团结全国各族人民，以经济建设为中心，坚持四项基本原则，坚持改革开放，自力更生，艰苦创业，为把我国建设成为富强、民主、文明的社会主义现代化国家而奋斗。（中共十三大报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"社会主义初级阶段基本路线；中国特色社会主义理论体系：邓小平理论（中共十五大确立为党的指导思想）、「三个代表」重要思想、科学发展观、习近平新时代中国特色社会主义思想（中共十九大确立为党的指导思想）。","explain":"材料出自中共十三大报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8b-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1997 年 9 月在北京召开，把邓小平理论确立为党的指导思想，提出社会主义初级阶段的基本纲领。（中共十五大报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"加快改革开放和社会主义现代化建设步伐；1992 年邓小平南方谈话与中共十四大：南方谈话进一步解放思想，强调「发展才是硬道理」，指出计划和市场都是经济手段；中共十四大明确提出建立社会主义市场经济体制的目标。","explain":"材料出自中共十五大报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9a-mid","title":"九年级上册 期中测试","subtitle":"九年级上册 · 期中","grade":"9a","tags":["九年级上册","期中测试","阶段检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期中测试"},{"k":"题量","v":"选择题 20 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"h9a-u1-q5","type":"choice","stem":"古埃及金字塔的用途是","answer":"B","explain":"金字塔是古埃及国王的陵墓，其中胡夫金字塔规模最大。它是古埃及文明的象征，反映了古埃及社会经济发展的较高水平和国王的无限权力。","options":["神庙，用于祭祀神灵","国王（法老）的陵墓","天文观测台","抵御外敌的军事堡垒"],"tags":["金字塔","史料实证"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 古埃及初步实现统一\n③ 古埃及大规模修建金字塔（胡夫金字塔规模最大）","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②古埃及初步实现统一（约公元前 3100 年）→③古埃及大规模修建金字塔（胡夫金字塔规模最大）（约公元前 2600 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-1-g2","type":"choice","stem":"下列关于「古代埃及」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》刻写用的文字说成象形文字——两河流域 = 楔形文字，尼罗河流域 = 象形文字，这是最容易被调换的一组搭配。正确表述：《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","options":["把《汉谟拉比法典》刻写用的文字说成象形文字。","《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明**大河流域是早期文明的共同摇篮**。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9a-u1-q2","type":"choice","stem":"迄今已知世界上第一部较为完整的成文法典是","answer":"A","explain":"公元前 18 世纪，古巴比伦王国国王汉谟拉比为维护奴隶主阶级的利益制定了《汉谟拉比法典》，刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。","options":["《汉谟拉比法典》","《十二铜表法》","《罗马民法大全》","《拿破仑法典》"],"tags":["《汉谟拉比法典》","时空观念"]},{"id":"cat-9a-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 两河流域实现初步统一\n③ 汉谟拉比统一两河流域中下游，定都巴比伦","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②两河流域实现初步统一（约公元前 24 世纪）→③汉谟拉比统一两河流域中下游，定都巴比伦（公元前 18 世纪）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g2","type":"choice","stem":"下列关于「古代两河流域」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》说成「世界上第一部成文法典」——限定语是得分点：少了「已知」「较为完整」，就不符合史实——苏美尔人早有成文法，只是不如它完整地保存下来。正确表述：它是「迄今**已知**世界上第一部较为完整的成文法典」。","options":["把《汉谟拉比法典》说成「世界上第一部成文法典」。","它是「迄今**已知**世界上第一部较为完整的成文法典」。","古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","《汉谟拉比法典》刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g3","type":"choice","stem":"下列结论中，属于「古代两河流域」的是","answer":"A","explain":"本课结论：古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明**大河流域是早期文明的共同摇篮**。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。","佛教于公元前 1 世纪（西汉末年）经中亚传入中国，说明**古代亚非文明之间的交流早于新航路开辟**，文明从来不是彼此隔绝的。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9a-u1-q3","type":"choice","stem":"古印度种姓制度中，掌管祭祀、被视为最高等级的是","answer":"A","explain":"种姓制度第一等级是婆罗门，掌管祭祀；第二等级是刹帝利，掌管军政大权；第三等级是吠舍，从事农业、畜牧业和商业；第四等级是首陀罗。","options":["婆罗门","刹帝利","吠舍","首陀罗"],"tags":["种姓制度","历史解释"]},{"id":"cat-9a-1-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 雅利安人进入南亚次大陆，逐渐建立国家\n② 乔达摩·悉达多（释迦牟尼）在古印度创立佛教\n③ 佛教经中亚传入中国（西汉末年）","answer":"A","explain":"按时间顺序应为：①雅利安人进入南亚次大陆，逐渐建立国家（约公元前 1500 年）→②乔达摩·悉达多（释迦牟尼）在古印度创立佛教（公元前 6 世纪）→③佛教经中亚传入中国（西汉末年）（公元前 1 世纪）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-3-g2","type":"choice","stem":"下列关于「古代印度」的表述，错误的是","answer":"A","explain":"把种姓制度与佛教的创立顺序记反，或认为佛教维护种姓制度——但要注意：佛教反对的是婆罗门特权，并不主张取消等级社会，其「忍耐顺从」的说教仍有利于统治者，所以后来得到统治者大力扶植。正确表述：种姓制度约在公元前 1500 年雅利安人进入南亚后逐渐形成，佛教创立于公元前 6 世纪，主张「众生平等」，是**反对**婆罗门特权的。","options":["把种姓制度与佛教的创立顺序记反，或认为佛教维护种姓制度。","种姓制度约在公元前 1500 年雅利安人进入南亚后逐渐形成，佛教创立于公元前 6 世纪，主张「众生平等」，是**反对**婆罗门特权的。","古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","佛教于公元前 1 世纪（西汉末年）经中亚传入中国，说明**古代亚非文明之间的交流早于新航路开辟**，文明从来不是彼此隔绝的。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9a-u2-q1","type":"choice","stem":"伯里克利主政时期，雅典的民主政治发展到高峰。雅典民主政治的实质是","answer":"B","explain":"雅典的成年男性公民才有权参加公民大会、担任公职；妇女、奴隶和外邦人被排斥在外，因此它本质上是奴隶主阶级的民主，具有明显的阶级局限性。","options":["全体雅典居民的民主","成年男性公民的民主，即奴隶主阶级的民主","全体自由民的民主","妇女与奴隶同样享有权利的民主"],"tags":["雅典民主","历史解释"]},{"id":"h9a-u2-q4","type":"choice","stem":"对亚历山大东征的评价，最恰当的是","answer":"B","explain":"东征使东方人民饱受掠夺、奴役之苦，但在客观上打通了东西方交通，促进了东西方文化的大交汇，因此要一分为二地评价。C 项是布匿战争的结果，D 项是伯里克利时期的成就。","options":["只是一场侵略战争，没有任何积极作用","给东方人民带来巨大灾难，但客观上促进了东西方文化的大交汇","使罗马成为整个地中海地区的霸主","使希腊的民主政治发展到高峰"],"tags":["亚历山大东征","历史解释"]},{"id":"h9a-u2-q6","type":"choice","stem":"下列希腊罗马古典文化成就与其所属文明的搭配，错误的一项是","answer":"D","explain":"《天方夜谭》（《一千零一夜》）是阿拉伯文学的瑰宝，属于阿拉伯文化，与古罗马无关。儒略历由罗马统治者凯撒命人以古埃及太阳历为蓝本编制。","options":["《荷马史诗》——古希腊","帕特农神庙——古希腊","儒略历——古罗马","《天方夜谭》——古罗马"],"tags":["古典文化","史料实证"]},{"id":"cat-9a-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 罗马城邦在意大利半岛中部的台伯河畔逐渐兴起\n② 希腊出现众多城邦，最著名的是雅典和斯巴达\n③ 伯里克利主政时期，雅典奴隶制民主政治发展到高峰\n④ 亚历山大开始东征","answer":"A","explain":"按时间顺序应为：①罗马城邦在意大利半岛中部的台伯河畔逐渐兴起（约公元前 1000 年）→②希腊出现众多城邦，最著名的是雅典和斯巴达（公元前 8 世纪）→③伯里克利主政时期，雅典奴隶制民主政治发展到高峰（公元前 5 世纪后半期）→④亚历山大开始东征（公元前 334 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-1-g2","type":"choice","stem":"下列关于「希腊城邦和亚历山大帝国」的表述，错误的是","answer":"A","explain":"认为雅典的民主政治是全体雅典居民（或全体自由民）的民主——选择题常把「公民」偷换成「居民」「自由民」。记住：雅典的「公民」是一个有严格条件限制的群体。正确表述：雅典只有成年男性公民享有政治权利；妇女、奴隶、外邦人都被排斥在外。","options":["认为雅典的民主政治是全体雅典居民（或全体自由民）的民主。","雅典只有成年男性公民享有政治权利；妇女、奴隶、外邦人都被排斥在外。","雅典民主政治是**成年男性公民**的民主，是奴隶主阶级的民主，妇女、奴隶、外邦人没有任何政治权利；它既是雅典繁荣的重要原因，也埋下了直接民主容易导致权力滥用的隐患。","希腊是西方文明的**源头**，罗马是希腊文化的**继承者与传播者**，二者共同构成西方古典文明。"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-1-g3","type":"choice","stem":"下列结论中，属于「希腊城邦和亚历山大帝国」的是","answer":"A","explain":"本课结论：雅典民主政治是**成年男性公民**的民主，是奴隶主阶级的民主，妇女、奴隶、外邦人没有任何政治权利；它既是雅典繁荣的重要原因，也埋下了直接民主容易导致权力滥用的隐患。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["雅典民主政治是**成年男性公民**的民主，是奴隶主阶级的民主，妇女、奴隶、外邦人没有任何政治权利；它既是雅典繁荣的重要原因，也埋下了直接民主容易导致权力滥用的隐患。","希腊是西方文明的**源头**，罗马是希腊文化的**继承者与传播者**，二者共同构成西方古典文明。","罗马法的发展体现了「从习惯法到成文法、从公民法到万民法」的进步，是欧洲法学的渊源，对近代欧洲乃至世界法律体系影响深远。","中外联动：公元前 221 年秦朝建立统一的中央集权帝国，同期罗马还在共和国阶段；到公元 2 世纪罗马帝国全盛时，中国正值东汉，两大帝国通过丝绸之路有了间接的经济文化交流（东汉时「大秦王安敦」遣使来华）。"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"h9a-u2-q2","type":"choice","stem":"罗马共和国时期，掌握国家决策权的机构是","answer":"B","explain":"罗马共和国时期，国家统治的决策权掌握在由贵族组成的元老院手中；两名权力相等的执政官主持日常政务，公民大会是形式上的最高权力机关。","options":["执政官","元老院","公民大会","保民官"],"tags":["罗马共和国","历史解释"]},{"id":"h9a-u2-q3","type":"choice","stem":"被称为罗马法制建设第一步、后世罗马法典乃至欧洲法学渊源的文献是","answer":"B","explain":"公元前 450 年左右，罗马颁布了刻在 12 块青铜板上的《十二铜表法》，使量刑定罪有了成文依据，是罗马法制建设的第一步，也是后世罗马法典乃至欧洲法学的渊源。","options":["《汉谟拉比法典》","《十二铜表法》","《罗马民法大全》","《拿破仑法典》"],"tags":["《十二铜表法》","时空观念"]},{"id":"cat-9a-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：胡夫金字塔约建于公元前 2600 年，原高约 146 米，底边约 230 米，由约 230 万块巨石砌成，是现存最大的金字塔。（吴于廑、齐世荣《世界史·古代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"古代埃及；金字塔是古埃及国王（法老）的陵墓，是古埃及文明的象征，反映了古埃及社会经济发展的较高水平和国王的无限权力。","explain":"材料出自吴于廑、齐世荣《世界史·古代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h9a-u1-m1-q1","type":"short","stem":"（1）材料一反映出《汉谟拉比法典》具有什么特点？该法典有怎样的历史地位？（4 分）","answer":"特点：实行「同态复仇」原则（以眼还眼、以牙还牙）；对不同社会等级的人处罚标准不同，严格维护奴隶主阶级的利益。历史地位：它是迄今已知世界上第一部较为完整的成文法典，表明人类社会的法制传统源远流长，是古巴比伦王国留给人类的宝贵文化遗产。","explain":"","tags":["《汉谟拉比法典》","史料实证"],"rubric":["答出「同态复仇」或以眼还眼、以牙还牙","答出维护奴隶主阶级利益或等级之间不平等","答出「迄今已知世界上第一部较为完整的成文法典」","答出法制传统源远流长或重要的文化遗产"]}]},{"id":"hp-9a-fin","title":"九年级上册 期末测试","subtitle":"九年级上册 · 期末","grade":"9a","tags":["九年级上册","期末测试","全册检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期末测试"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"90 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9a-u4-q3","type":"choice","stem":"12 世纪晚期，日本进入幕府统治时期，国家的实际权力掌握在","answer":"B","explain":"12 世纪晚期，源赖朝获得「征夷大将军」称号，设幕府于镰仓，日本从此进入长达近 700 年的幕府统治时期，幕府将军实际掌握国家大权，天皇成为象征。","options":["天皇手中","幕府将军手中","武士手中","大名手中"],"tags":["幕府统治","历史解释"]},{"id":"cat-9a-4-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 大和政权基本统一日本\n② 日本孝德天皇推行大化改新，效仿唐朝典章制度进行改…\n③ 大化改新后日本继续派遣遣唐使，中日交流频繁\n④ 源赖朝获得「征夷大将军」称号，在镰仓设幕府","answer":"A","explain":"按时间顺序应为：①大和政权基本统一日本（5 世纪）→②日本孝德天皇推行大化改新，效仿唐朝典章制度进行改革（646 年）→③大化改新后日本继续派遣遣唐使，中日交流频繁（7 世纪末—8 世纪初）→④源赖朝获得「征夷大将军」称号，在镰仓设幕府（12 世纪晚期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"cat-9a-4-1-g2","type":"choice","stem":"下列关于「古代日本」的表述，错误的是","answer":"A","explain":"把大化改新与明治维新混为一谈——两者都是日本历史上的关键改革，但时代、学习对象与性质完全不同，这是中日改革比较题的基本前提。正确表述：大化改新发生在 646 年，学习的是中国唐朝的典章制度，使日本成为中央集权制的封建国家；明治维新发生在 1868 年，学习的是欧美，使日本走上资本主义道路。","options":["把大化改新与明治维新混为一谈。","大化改新发生在 646 年，学习的是中国唐朝的典章制度，使日本成为中央集权制的封建国家；明治维新发生在 1868 年，学习的是欧美，使日本走上资本主义道路。","大化改新是一次**自上而下的、以中国唐朝制度为蓝本**的改革，说明隋唐制度在东亚具有强大的示范效应，也说明**善于学习和吸收外来先进文化是一个国家走向强盛的重要原因**。","中日联动：从大化改新学习唐朝，到近代日本明治维新学习西方，日本历史上两次大规模学习外来文化的成败，常与中国近代的洋务运动合并考查。"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"cat-9a-4-1-g3","type":"choice","stem":"下列结论中，属于「古代日本」的是","answer":"A","explain":"本课结论：大化改新是一次**自上而下的、以中国唐朝制度为蓝本**的改革，说明隋唐制度在东亚具有强大的示范效应，也说明**善于学习和吸收外来先进文化是一个国家走向强盛的重要原因**。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["大化改新是一次**自上而下的、以中国唐朝制度为蓝本**的改革，说明隋唐制度在东亚具有强大的示范效应，也说明**善于学习和吸收外来先进文化是一个国家走向强盛的重要原因**。","宗教在特定历史条件下可以成为统一的政治力量：伊斯兰教打破了阿拉伯半岛的部落界限，为半岛统一和帝国建立提供了精神纽带。","阿拉伯人是东西方文化交流的桥梁：他们把中国的造纸术、指南针、火药和印度的数字、棉花、食糖传入欧洲，为欧洲的社会进步提供了重要条件。","中外联动：中国与阿拉伯（唐代称「大食」）通过陆上与海上丝绸之路往来密切，651 年阿拉伯遣使来华；中国的四大发明中有三项经阿拉伯人西传，这是理解「中国古代科技对世界的影响」的关键史实。"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"h9a-u4-q4","type":"choice","stem":"622 年，穆罕默德迁往麦地那建立穆斯林公社，这一年被定为","answer":"A","explain":"622 年穆罕默德迁往麦地那建立穆斯林公社，这一年被定为伊斯兰教历元年。阿拉伯半岛基本统一是在 632 年穆罕默德病逝时。","options":["伊斯兰教历元年","阿拉伯帝国建立之年","阿拉伯半岛统一之年","《古兰经》成书之年"],"tags":["伊斯兰教","时空观念"]},{"id":"h9a-u4-q5","type":"choice","stem":"今天世界各国通用的「阿拉伯数字」最早由哪一地区的人发明","answer":"B","explain":"阿拉伯数字最早由古印度人发明，阿拉伯人加以改造并传播到欧洲，因此被称为「阿拉伯数字」，这体现了阿拉伯人在东西方文化交流中的桥梁作用。","options":["阿拉伯人","古印度人","古埃及人","古希腊人"],"tags":["阿拉伯文化","史料实证"]},{"id":"h9a-u4-q6","type":"choice","stem":"中国的造纸术、指南针、火药等重大发明由阿拉伯人传入欧洲，这说明阿拉伯人","answer":"B","explain":"阿拉伯人把中国的造纸术、指南针、火药和印度的棉花、食糖等传入欧洲，同时保存并传播古希腊典籍，起到了东西方文化交流桥梁的作用。","options":["是这些发明的发明者","是东西方文化交流的桥梁","建立了横跨欧亚非三洲的帝国","创立了伊斯兰教"],"tags":["阿拉伯文化","中外交流"]},{"id":"cat-9a-4-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 穆罕默德迁往麦地那，建立穆斯林公社\n② 穆罕默德率穆斯林占领麦加\n③ 穆罕默德病逝，阿拉伯半岛基本统一\n④ 阿拉伯帝国成为横跨欧亚非三洲的大帝国","answer":"A","explain":"按时间顺序应为：①穆罕默德迁往麦地那，建立穆斯林公社（622 年）→②穆罕默德率穆斯林占领麦加（630 年）→③穆罕默德病逝，阿拉伯半岛基本统一（632 年）→④阿拉伯帝国成为横跨欧亚非三洲的大帝国（8 世纪中期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"cat-9a-4-2-g2","type":"choice","stem":"下列关于「阿拉伯帝国」的表述，错误的是","answer":"A","explain":"认为「阿拉伯数字」是阿拉伯人发明的——这是一道高频陷阱题，考查的是「发明」与「传播」的区别。正确表述：阿拉伯数字最早由古印度人发明，阿拉伯人加以改造并传播到欧洲，因此被称为「阿拉伯数字」。","options":["认为「阿拉伯数字」是阿拉伯人发明的。","阿拉伯数字最早由古印度人发明，阿拉伯人加以改造并传播到欧洲，因此被称为「阿拉伯数字」。","大化改新是一次**自上而下的、以中国唐朝制度为蓝本**的改革，说明隋唐制度在东亚具有强大的示范效应，也说明**善于学习和吸收外来先进文化是一个国家走向强盛的重要原因**。","宗教在特定历史条件下可以成为统一的政治力量：伊斯兰教打破了阿拉伯半岛的部落界限，为半岛统一和帝国建立提供了精神纽带。"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"h9a-u5-q1","type":"choice","stem":"文艺复兴的核心思想是","answer":"A","explain":"文艺复兴的核心思想是人文主义，即肯定人的价值与尊严，提倡发扬人的个性、追求现世的幸福，反对教会神权对人的束缚。理性主义是启蒙运动的核心。","options":["人文主义","理性主义","禁欲主义","重商主义"],"tags":["文艺复兴","历史解释"]},{"id":"h9a-u5-q2","type":"choice","stem":"文艺复兴的实质是","answer":"B","explain":"文艺复兴采取复兴古代希腊罗马文化的形式，实质是新兴资产阶级的思想文化解放运动，它反对的是教会的神权束缚而非宗教信仰本身。","options":["古希腊罗马文化的简单复兴","新兴资产阶级的思想文化解放运动","一场反宗教的社会运动","教会内部的一次改革"],"tags":["文艺复兴","唯物史观"]},{"id":"h9a-u5-q3","type":"choice","stem":"1492 年率船队横渡大西洋、到达美洲的航海家是","answer":"C","explain":"1492 年哥伦布率船队横渡大西洋，到达今天的巴哈马群岛一带，他误以为自己到达的是印度，因此称当地居民为「印第安人」。","options":["迪亚士","达·伽马","哥伦布","麦哲伦"],"tags":["新航路开辟","时空观念"]},{"id":"cat-9a-5-1-g2","type":"choice","stem":"下列关于「西欧经济和社会的发展」的表述，错误的是","answer":"A","explain":"认为文艺复兴是反对宗教、否定基督教——材料题常问「文艺复兴为什么被称为『复兴』」，标准答法是：它以复兴古代希腊罗马文化为形式，实质是新兴资产阶级的思想解放运动。正确表述：文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","options":["认为文艺复兴是反对宗教、否定基督教。","文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-1-g3","type":"choice","stem":"下列结论中，属于「西欧经济和社会的发展」的是","answer":"A","explain":"本课结论：文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。","新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-2-g2","type":"choice","stem":"下列关于「文艺复兴运动」的表述，错误的是","answer":"A","explain":"认为文艺复兴是反对宗教、否定基督教——材料题常问「文艺复兴为什么被称为『复兴』」，标准答法是：它以复兴古代希腊罗马文化为形式，实质是新兴资产阶级的思想解放运动。正确表述：文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","options":["认为文艺复兴是反对宗教、否定基督教。","文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-2-g3","type":"choice","stem":"下列结论中，属于「文艺复兴运动」的是","answer":"A","explain":"本课结论：文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"h9a-u5-q4","type":"choice","stem":"首次完成环球航行、证明地球是圆的的航海活动是","answer":"C","explain":"1519—1522 年，麦哲伦船队完成人类首次环球航行，证明了地球是圆的。麦哲伦本人在途中死于菲律宾，船队由其他人带领返回西班牙。","options":["迪亚士到达好望角","达·伽马到达印度","麦哲伦船队 1519—1522 年的环球航行","哥伦布到达美洲"],"tags":["新航路开辟","时空观念"]},{"id":"h9a-u5-q5","type":"choice","stem":"新航路开辟最重要的世界性影响是","answer":"B","explain":"新航路开辟以后，欧洲与亚洲、非洲、美洲之间的交通日益密切，世界开始连为一个整体，世界市场逐渐形成，这是它最重要的世界性影响。此后欧洲的贸易中心由地中海沿岸转移到大西洋沿岸。","options":["使欧洲人发现了美洲大陆","使世界开始连为一个整体，世界市场逐渐形成","使中国的丝绸传入欧洲","使意大利成为世界贸易的中心"],"tags":["新航路开辟","历史解释"]},{"id":"cat-9a-5-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 迪亚士到达非洲南端的好望角\n② 哥伦布到达美洲（今巴哈马群岛一带）\n③ 达·伽马率船队绕过好望角到达印度\n④ 麦哲伦船队完成环球航行","answer":"A","explain":"按时间顺序应为：①迪亚士到达非洲南端的好望角（1487 年）→②哥伦布到达美洲（今巴哈马群岛一带）（1492 年）→③达·伽马率船队绕过好望角到达印度（1497—1498 年）→④麦哲伦船队完成环球航行（1519—1522 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-3-g2","type":"choice","stem":"下列关于「探寻新航路」的表述，错误的是","answer":"A","explain":"认为哥伦布到达了亚洲（印度），或把哥伦布与麦哲伦的贡献弄混——「印第安人」这一称呼就源于哥伦布的误判，这是记忆这条史实的一个抓手。正确表述：1492 年哥伦布到达美洲，他始终误以为是亚洲的印度；1519—1522 年麦哲伦船队完成环球航行，证明地球是圆的。","options":["认为哥伦布到达了亚洲（印度），或把哥伦布与麦哲伦的贡献弄混。","1492 年哥伦布到达美洲，他始终误以为是亚洲的印度；1519—1522 年麦哲伦船队完成环球航行，证明地球是圆的。","新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-3-g3","type":"choice","stem":"下列结论中，属于「探寻新航路」的是","answer":"A","explain":"本课结论：新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"h9a-u5-q6","type":"choice","stem":"在「三角贸易」中，欧洲殖民者从非洲运往美洲的主要是","answer":"B","explain":"三角贸易的路线是欧洲 → 非洲 → 美洲 → 欧洲：殖民者把廉价工业品运到非洲换取黑奴，再把黑奴运往美洲出卖，最后把美洲的金银和工业原料运回欧洲。黑奴贸易使非洲丧失了大量人口。","options":["廉价工业品","黑人奴隶","金银和工业原料","香料和瓷器"],"tags":["三角贸易","历史解释"]},{"id":"cat-9a-5-4-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 迪亚士到达非洲南端的好望角\n② 欧洲殖民者开始进行「三角贸易」，葡萄牙、西班牙最…\n③ 荷兰被称为「海上马车夫」；18 世纪英国成为最大…","answer":"A","explain":"按时间顺序应为：①迪亚士到达非洲南端的好望角（1487 年）→②欧洲殖民者开始进行「三角贸易」，葡萄牙、西班牙最早走上殖民扩张道路（16 世纪）→③荷兰被称为「海上马车夫」；18 世纪英国成为最大的殖民国家（17—18 世纪）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-4-g2","type":"choice","stem":"下列关于「早期殖民掠夺」的表述，错误的是","answer":"A","explain":"认为三角贸易中最先受害的是美洲，或把三角贸易的路线记成欧洲—美洲—非洲——顺序错了整道题的答案就会错，记忆口诀是「出欧入非，贩奴至美，载货回欧」。正确表述：三角贸易的路线是欧洲 → 非洲 → 美洲 → 欧洲：非洲丧失大量青壮年人口，美洲得到的是被贩卖的黑人奴隶。","options":["认为三角贸易中最先受害的是美洲，或把三角贸易的路线记成欧洲—美洲—非洲。","三角贸易的路线是欧洲 → 非洲 → 美洲 → 欧洲：非洲丧失大量青壮年人口，美洲得到的是被贩卖的黑人奴隶。","新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-4-g3","type":"choice","stem":"下列结论中，属于「早期殖民掠夺」的是","answer":"A","explain":"本课结论：新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["新航路开辟的最大影响是**世界开始连为一个整体**，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","文艺复兴的实质是**新兴资产阶级的思想文化解放运动**，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"h9a-u4-m1-q1","type":"short","stem":"（1）依据材料一，概括大化改新在经济和政治方面的措施，并说明这次改革使日本发生了怎样的变化。（6 分）","answer":"经济措施：废除皇室和贵族的私有土地与部民，收归国家所有，成为公地、公民；国家定期把土地分给公民耕种并收取赋税（类似唐朝的均田制与租庸调制）。政治措施：废除世袭贵族统治制度，建立以天皇为中心的中央集权制度，中央和地方官吏由国家任免。变化：大化改新使日本由奴隶社会向封建社会过渡，发展成为一个中央集权制的封建国家。","explain":"","tags":["大化改新","历史解释"],"rubric":["答出收土地与部民为公地、公民","答出定期分地收税","答出中央集权、官吏由国家任免","答出废除世袭贵族统治制度","答出成为中央集权制的封建国家"]},{"id":"cat-9a-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：646 年，孝德天皇颁布改新诏书，仿唐朝制度，实行班田收授法、租庸调制，建立中央集权国家。（《日本书纪》；2024 部编版九上第 11 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"古代日本；大化改新的内容：政治上建立以天皇为中心的中央集权制度，地方设国、郡、里，官吏由国家任免；经济上把土地和部民收归国有，成为公地、公民，国家定期把土地分给公民耕种并收取赋税。","explain":"材料出自《日本书纪》；2024 部编版九上第 11 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h9a-u4-m1-q2","type":"short","stem":"（2）材料二、三共同反映了什么历史现象？结合所学，说明阿拉伯人在世界文化发展中的作用。（6 分）","answer":"历史现象：不同文明之间通过使者往来、人员交流与商业贸易相互学习、彼此传播文化，文明交流是双向的。阿拉伯人的作用：阿拉伯人改造并传播了古印度人从 0 到 9 的计数法，形成今天通用的「阿拉伯数字」；把中国的造纸术、指南针、火药以及印度的棉花、食糖等传入欧洲；翻译并保存了大量古希腊的哲学与科学著作，后来又传回欧洲，为欧洲文化的发展提供了条件。因此阿拉伯人是东西方文化交流的桥梁。","explain":"","tags":["阿拉伯文化","中外交流"],"rubric":["答出文明之间相互交流、双向传播","答出派遣遣唐使或学习唐朝制度文化","答出阿拉伯数字的改造与传播","答出中国发明经阿拉伯人西传","答出保存传播古希腊典籍","答出「东西方文化交流的桥梁」"]}]},{"id":"hp-9b-mid","title":"九年级下册 期中测试","subtitle":"九年级下册 · 期中","grade":"9b","tags":["九年级下册","期中测试","阶段检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期中测试"},{"k":"题量","v":"选择题 20 题 · 材料题 2 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9b-u1-q1","type":"choice","stem":"19 世纪，印度爆发了反抗英国殖民统治的民族大起义，其杰出领导人是","answer":"B","explain":"1857—1859 年印度民族大起义反抗英国殖民统治，章西女王是杰出代表。玻利瓦尔是拉美独立运动领袖，甘地领导的是 20 世纪的印度非暴力不合作运动，凯末尔领导的是土耳其革命。","options":["玻利瓦尔","章西女王","甘地","凯末尔"],"tags":["印度民族大起义","时空观念"]},{"id":"cat-9b-1-1-g2","type":"choice","stem":"下列关于「殖民地人民的反抗战争」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","19 世纪中期，资本主义制度在世界范围内确立和扩展：俄国靠自上而下的改革，美国靠内战，日本靠明治维新——**方式不同，方向一致**。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-1-g5","type":"choice","stem":"「拉丁美洲独立运动兴起」发生于","answer":"A","explain":"本课时间轴：拉丁美洲独立运动兴起（19 世纪初）。玻利瓦尔解放哥伦比亚、委内瑞拉、厄瓜多尔等地，圣马丁领导阿根廷、智利、秘鲁的独立运动；1804 年海地独立揭开序幕（拉美第一个独立国家）。其余三个时间是同一单元相邻课时的事件时间。","options":["19 世纪初","1861 年","1861—1865 年","1871 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-1-g6","type":"choice","stem":"下列考点中，属于「殖民地人民的反抗战争」的是","answer":"A","explain":"本课考点（重点）：拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。其余三项是同一单元相邻课时的考点。","options":["拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，18…","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买…","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废…","19 世纪中期资本主义制度的扩展：俄国（1861 年改革）、美国（内战）、日本（明治维新…"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h9b-u1-q2","type":"choice","stem":"1861 年，俄国沙皇亚历山大二世签署废除农奴制的法令。这项改革的性质是","answer":"B","explain":"改革由沙皇政府自上而下推行，使农奴获得人身自由、为资本主义发展提供了自由劳动力与市场，因此是自上而下的资产阶级性质的改革；但它保留了大量封建残余，不是「彻底」废除封建制度。","options":["自下而上的农民起义","自上而下的资产阶级性质的改革","无产阶级社会主义革命","彻底废除封建制度的民主革命"],"tags":["俄国农奴制改革","历史解释"]},{"id":"cat-9b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 俄国农奴制改革\n② 美国南北战争\n③ 德意志帝国成立（普法战争后）","answer":"A","explain":"按时间顺序应为：①俄国农奴制改革（1861 年）→②美国南北战争（1861—1865 年）→③德意志帝国成立（普法战争后）（1871 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-2-g2","type":"choice","stem":"下列关于「俄国的改革」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-2-g5","type":"choice","stem":"「俄国农奴制改革」发生于","answer":"A","explain":"本课时间轴：俄国农奴制改革（1861 年）。沙皇亚历山大二世签署废除农奴制的法令：农奴获得人身自由，可通过赎买获得份地——俄国历史上的重要转折点。其余三个时间是同一单元相邻课时的事件时间。","options":["1861 年","19 世纪初","1857—1859 年","1861—1865 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h9b-u1-q3","type":"choice","stem":"美国南北战争爆发前，南北方矛盾斗争的焦点是","answer":"B","explain":"南北两种经济制度（北方资本主义工商业与南方种植园奴隶制经济）的矛盾日益尖锐，焦点是奴隶制的存废问题；林肯当选总统成为战争爆发的导火线。","options":["关税税率的高低","奴隶制的存废问题","西部领土的扩张方向","总统选举的方式"],"tags":["美国内战","历史解释"]},{"id":"h9b-u1-q4","type":"choice","stem":"使美国南北战争的战局发生扭转、为北方军队提供雄厚兵源的文件是","answer":"B","explain":"1862 年林肯颁布《宅地法》和《解放黑人奴隶宣言》，宣言宣布叛乱各州奴隶永远获得自由，黑人踊跃参军，扭转了战局。《独立宣言》《1787 年宪法》均为美国独立战争时期的文件。","options":["《独立宣言》","《解放黑人奴隶宣言》","《人权宣言》","1787 年美国宪法"],"tags":["美国内战","史料实证"]},{"id":"cat-9b-1-3-g2","type":"choice","stem":"下列关于「美国内战」的表述，错误的是","answer":"A","explain":"认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制——「根本原因」与「导火线」的区分是必考得分点，答题时要先答经济制度矛盾，再答导火线。正确表述：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","options":["认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制。","根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","林肯的贡献在于**维护了国家统一、废除了奴隶制**，为美国经济的迅速发展创造了条件；评价历史人物要看其是否推动社会进步、是否符合人民利益。","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废；林肯颁布《宅地法》和《解放黑人奴隶宣言》，1865 年北方取胜。意义：维护了国家统一，废除了奴隶制，为经济迅速发展创造了条件。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-3-g5","type":"choice","stem":"「美国南北战争」发生于","answer":"A","explain":"本课时间轴：美国南北战争（1861—1865 年）。根本原因是南北两种经济制度的矛盾（焦点是奴隶制的存废）；1861 年南方军队挑起内战，1865 年北方获胜。其余三个时间是同一单元相邻课时的事件时间。","options":["1861—1865 年","19 世纪初","1857—1859 年","1861 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h9b-u1-q5","type":"choice","stem":"日本明治维新措施中，属于政治方面、旨在加强中央集权的是","answer":"A","explain":"废藩置县废除了藩国、设置府县，由中央任命官员，加强了中央集权。殖产兴业属经济措施，征兵制属军事措施，文明开化属文化教育措施。","options":["废藩置县","殖产兴业，发展近代工业","实行征兵制，建立新式军队","提倡「文明开化」，发展教育"],"tags":["明治维新","制度创新"]},{"id":"cat-9b-1-4-g2","type":"choice","stem":"下列关于「日本明治维新」的表述，错误的是","answer":"A","explain":"把明治维新的「废藩置县」与「殖产兴业」混为一谈——材料题要求「按政治、经济、军事、文化分类概括措施」，混在一起就丢分。正确表述：废藩置县是政治措施（废除藩国、设置府县，加强中央集权）；殖产兴业是经济措施（引进西方技术、发展近代工业）。","options":["把明治维新的「废藩置县」与「殖产兴业」混为一谈。","废藩置县是政治措施（废除藩国、设置府县，加强中央集权）；殖产兴业是经济措施（引进西方技术、发展近代工业）。","19 世纪中期，资本主义制度在世界范围内确立和扩展：俄国靠自上而下的改革，美国靠内战，日本靠明治维新——**方式不同，方向一致**。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-4-g5","type":"choice","stem":"「日本明治维新开始」发生于","answer":"A","explain":"本课时间轴：日本明治维新开始（1868 年）。推翻幕府统治后，明治政府推行废藩置县、殖产兴业、征兵制、文明开化等改革，日本走上发展资本主义的道路。其余三个时间是同一单元相邻课时的事件时间。","options":["1868 年","19 世纪初","1857—1859 年","1861 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-4-g6","type":"choice","stem":"下列考点中，属于「日本明治维新」的是","answer":"A","explain":"本课考点（重点）：日本明治维新（1868 年起）：废藩置县（加强中央集权）、殖产兴业（引进西方技术、发展近代工业）、实行征兵制（建立新式军队）、提倡「文明开化」（发展教育）。使日本走上发展资本主义的道路，成为亚洲强国，但保留大量封建残余并走向对外扩张。其余三项是同一单元相邻课时的考点。","options":["日本明治维新（1868 年起）：废藩置县（加强中央集权）、殖产兴业（引进西方技术、发展近…","拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，18…","印度民族大起义（1857—1859）：反抗英国殖民统治，章西女王是杰出代表；起义失败，但…","玻利瓦尔、圣马丁、章西女王、亚历山大二世、林肯、明治天皇等历史人物及其主要贡献。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h9b-u2-q1","type":"choice","stem":"第二次工业革命中，作为新能源被广泛应用、使人类进入「电气时代」的是","answer":"B","explain":"第二次工业革命以电力的广泛应用为标志，电动机、发电机等的发明使电力进入生产与生活领域，人类进入「电气时代」。煤炭是第一次工业革命的主要能源。","options":["煤炭","电力","水力","风能"],"tags":["第二次工业革命","时空观念"]},{"id":"h9b-u2-q2","type":"choice","stem":"1879 年研制出耐用碳丝白炽灯泡、一生取得千余项发明专利，被誉为「发明大王」的是","answer":"B","explain":"爱迪生 1879 年发明耐用的白炽灯泡，被誉为「发明大王」。本茨制造出内燃机汽车，莱特兄弟制成飞机，诺贝尔发明现代炸药。","options":["本茨","爱迪生","莱特兄弟","诺贝尔"],"tags":["第二次工业革命","历史人物"]},{"id":"h9b-u2-q4","type":"choice","stem":"19 世纪末 20 世纪初，主要资本主义国家出现垄断组织。其根本原因是","answer":"B","explain":"垄断组织是第二次工业革命中生产力迅速发展、生产和资本高度集中的结果。国家全面干预经济是二战后（罗斯福新政开创）的新变化，不是垄断组织产生的原因。","options":["第一次工业革命的完成","第二次工业革命推动生产力发展、生产和资本日益高度集中","列强加紧对外殖民扩张","国家全面干预经济生活"],"tags":["垄断组织","唯物史观"]},{"id":"h9b-u2-q6","type":"choice","stem":"与第一次工业革命相比，第二次工业革命最突出的特点是","answer":"B","explain":"第二次工业革命中科学与技术紧密结合，各种新发明迅速应用于生产，这是它最突出的特点。A、C、D 都是第一次工业革命的特点，其中 D 是第一次工业革命的标志。","options":["主要靠工匠的实践经验与发明创造","科学研究与工业生产紧密结合，科学技术迅速应用于生产","首先发生在英国，然后扩展到其他国家","以蒸汽机的广泛使用为标志"],"tags":["第二次工业革命","横向比较"]},{"id":"cat-9b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：玻利瓦尔率军解放委内瑞拉、哥伦比亚、厄瓜多尔、秘鲁等地，被誉为「解放者」；圣马丁解放阿根廷、智利、秘鲁。（吴于廑、齐世荣《世界史·近代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"殖民地人民的反抗战争；拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。","explain":"材料出自吴于廑、齐世荣《世界史·近代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：农奴获得人身自由，有权拥有财产、从事工商活动；地主不得买卖农奴；农奴可赎买份地，但须支付高额赎金。（《1861 年法令》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"俄国的改革；俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。","explain":"材料出自《1861 年法令》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-9b-fin","title":"九年级下册 期末测试","subtitle":"九年级下册 · 期末","grade":"9b","tags":["九年级下册","期末测试","全册检测"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"期末测试"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"90 分钟"}]},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h9b-u3-q2","type":"choice","stem":"1914 年，奥匈帝国皇储夫妇被刺杀，这一事件成为第一次世界大战的","answer":"B","explain":"1914 年 6 月的萨拉热窝事件是第一次世界大战的导火线；大战的根本原因是帝国主义国家政治经济发展不平衡。","options":["根本原因","导火线（直接原因）","结束标志","转折点"],"tags":["萨拉热窝事件","时空观念"]},{"id":"h9b-u3-q3","type":"choice","stem":"1919 年，中国在巴黎和会上外交失败，德国在中国山东的特权被转让给日本。这一消息直接引发了","answer":"C","explain":"巴黎和会上中国外交失败的消息传回国内，直接引发 1919 年五四运动的爆发，五四运动标志着中国新民主主义革命的开端。","options":["洋务运动","戊戌变法","五四运动","新文化运动"],"tags":["巴黎和会","中外关联"]},{"id":"cat-9b-3-5-g2","type":"choice","stem":"下列关于「亚非拉民族民主运动的高涨」的表述，错误的是","answer":"A","explain":"把萨拉热窝事件说成第一次世界大战爆发的根本原因——「根本原因—导火线」的区分是最高频的失分点，凡遇「根本」二字都要往经济与制度矛盾上想。正确表述：萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","options":["把萨拉热窝事件说成第一次世界大战爆发的根本原因。","萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","民族解放运动必须与本国国情相适应：甘地走非暴力不合作道路，凯末尔走武装斗争与世俗化改革道路，都推动了民族民主运动的发展。","亚非拉的民族民主运动：印度甘地领导的非暴力不合作运动（1920 年起）打击了英国殖民统治；土耳其凯末尔革命（1919—1923）赢得民族独立并建立共和国；埃及华夫脱运动迫使英国有条件地承认埃及独立。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-5-g3","type":"choice","stem":"下列结论中，属于「亚非拉民族民主运动的高涨」的是","answer":"A","explain":"本课结论：民族解放运动必须与本国国情相适应：甘地走非暴力不合作道路，凯末尔走武装斗争与世俗化改革道路，都推动了民族民主运动的发展。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["民族解放运动必须与本国国情相适应：甘地走非暴力不合作道路，凯末尔走武装斗争与世俗化改革道路，都推动了民族民主运动的发展。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。","十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。","政策必须立足国情、实事求是：新经济政策利用市场和商品货币关系恢复经济，是在坚持社会主义方向前提下的成功探索。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"h9b-u4-q1","type":"choice","stem":"1929—1933 年资本主义世界经济大危机的特点不包括","answer":"D","explain":"这次经济大危机的特点是涉及范围特别广、持续时间比较长、破坏性特别大。它从美国开始，迅速波及整个资本主义世界，并非只在英国发生。","options":["涉及范围特别广","持续时间比较长","破坏性特别大","只在英国一国发生"],"tags":["经济大危机","历史解释"]},{"id":"h9b-u4-q2","type":"choice","stem":"罗斯福新政的中心措施是","answer":"B","explain":"新政的中心措施是对工业的调整，通过《全国工业复兴法》加强国家对工业的计划指导。整顿金融、调整农业、以工代赈都是新政的重要措施，但不是中心措施。","options":["整顿金融体系","对工业的调整（《全国工业复兴法》）","调整农业政策","推行「以工代赈」，兴办公共工程"],"tags":["罗斯福新政","历史解释"]},{"id":"cat-9b-4-1-g2","type":"choice","stem":"下列关于「资本主义经济大危机」的表述，错误的是","answer":"A","explain":"认为罗斯福新政是社会主义性质的改革——判断改革性质看「是否改变社会制度」：新政不改变私有制与资产阶级统治，因此不是社会主义改革。正确表述：新政是在不改变资本主义制度前提下的自我调整：运用国家力量干预经济，目的是维护资本主义统治、缓解危机。","options":["认为罗斯福新政是社会主义性质的改革。","新政是在不改变资本主义制度前提下的自我调整：运用国家力量干预经济，目的是维护资本主义统治、缓解危机。","罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。","1929—1933 年经济大危机的特点与根源：特点是涉及范围特别广、持续时间比较长、破坏性特别大（整个资本主义世界的工业产量下降 1/3 以上，失业工人超过 3000 万）。根源是资本主义制度的基本矛盾，即生产社会化与生产资料私人占有之间的矛盾。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-1-g3","type":"choice","stem":"下列结论中，属于「资本主义经济大危机」的是","answer":"A","explain":"本课结论：罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。","世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","中国是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。","第二次世界大战改变了世界格局：欧洲衰落、美苏崛起，雅尔塔体系取代凡尔赛—华盛顿体系，战后又演变为美苏对峙的两极格局。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"h9b-u4-q6","type":"choice","stem":"1938 年，英、法、德、意四国首脑在没有捷克斯洛伐克代表参加的情况下，把苏台德区割让给德国。这一事件说明","answer":"A","explain":"慕尼黑会议把捷克斯洛伐克的苏台德区割让给德国，是绥靖政策达到顶峰的标志，助长了法西斯的侵略野心，加速了第二次世界大战的爆发。","options":["绥靖政策达到顶峰，加速了二战的爆发","法西斯国家的侵略被彻底制止","世界反法西斯同盟已经形成","德国的侵略野心得到有效遏制"],"tags":["慕尼黑会议","历史解释"]},{"id":"cat-9b-4-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 希特勒出任德国总理，德国建立法西斯专政\n② 日本军部法西斯专政建立\n③ 慕尼黑会议","answer":"A","explain":"按时间顺序应为：①希特勒出任德国总理，德国建立法西斯专政（1933 年）→②日本军部法西斯专政建立（1936 年）→③慕尼黑会议（1938 年 9 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-2-g2","type":"choice","stem":"下列关于「法西斯国家的侵略扩张」的表述，错误的是","answer":"A","explain":"认为绥靖政策从慕尼黑会议开始——「开始」与「顶峰」是两问，慕尼黑会议是顶峰而非起点。正确表述：绥靖政策在 20 世纪 30 年代逐步推行（如纵容日本侵占中国东北、纵容意大利侵略埃塞俄比亚、纵容德国吞并奥地利），其顶峰是 1938 年 9 月的慕尼黑会议。","options":["认为绥靖政策从慕尼黑会议开始。","绥靖政策在 20 世纪 30 年代逐步推行（如纵容日本侵占中国东北、纵容意大利侵略埃塞俄比亚、纵容德国吞并奥地利），其顶峰是 1938 年 9 月的慕尼黑会议。","世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","中国是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-2-g3","type":"choice","stem":"下列结论中，属于「法西斯国家的侵略扩张」的是","answer":"A","explain":"本课结论：世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。","第二次世界大战改变了世界格局：欧洲衰落、美苏崛起，雅尔塔体系取代凡尔赛—华盛顿体系，战后又演变为美苏对峙的两极格局。","中国是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"h9b-u4-q4","type":"choice","stem":"世界反法西斯同盟正式形成的标志是","answer":"B","explain":"1942 年 1 月 1 日，美、英、苏、中等 26 国签署《联合国家宣言》，标志世界反法西斯同盟正式形成。雅尔塔会议是 1945 年召开的战后安排会议，诺曼底登陆开辟欧洲第二战场，斯大林格勒战役是二战的转折点。","options":["雅尔塔会议的召开","1942 年 1 月 1 日《联合国家宣言》的签署","诺曼底登陆的成功","斯大林格勒战役的胜利"],"tags":["世界反法西斯同盟","时空观念"]},{"id":"h9b-u4-q5","type":"choice","stem":"第二次世界大战的转折点是","answer":"B","explain":"斯大林格勒战役（1942 年 7 月—1943 年 2 月）是苏德战场的转折点，也是第二次世界大战的转折点。诺曼底登陆开辟了欧洲第二战场，雅尔塔会议是战后的安排会议。","options":["莫斯科保卫战","斯大林格勒战役","诺曼底登陆","雅尔塔会议"],"tags":["第二次世界大战","历史解释"]},{"id":"cat-9b-4-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 慕尼黑会议\n② 德国突袭波兰，英法对德宣战，第二次世界大战全面爆…\n③ 德国进攻苏联，苏德战争爆发\n④ 日本偷袭珍珠港，太平洋战争爆发","answer":"A","explain":"按时间顺序应为：①慕尼黑会议（1938 年 9 月）→②德国突袭波兰，英法对德宣战，第二次世界大战全面爆发（1939 年 9 月 1 日）→③德国进攻苏联，苏德战争爆发（1941 年 6 月 22 日）→④日本偷袭珍珠港，太平洋战争爆发（1941 年 12 月 7 日）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-3-g2","type":"choice","stem":"下列关于「第二次世界大战」的表述，错误的是","answer":"A","explain":"认为第二次世界大战全面爆发的标志是七七事变或德国进攻苏联——「全面爆发」与「中国全民族抗战开始」是两个不同层面的概念，材料题常把两者并置设陷阱。正确表述：1939 年 9 月 1 日德国突袭波兰、英法对德宣战，标志二战全面爆发；七七事变是中国全民族抗战的开始；1941 年苏德战争爆发标志二战规模扩大。","options":["认为第二次世界大战全面爆发的标志是七七事变或德国进攻苏联。","1939 年 9 月 1 日德国突袭波兰、英法对德宣战，标志二战全面爆发；七七事变是中国全民族抗战的开始；1941 年苏德战争爆发标志二战规模扩大。","世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","第二次世界大战改变了世界格局：欧洲衰落、美苏崛起，雅尔塔体系取代凡尔赛—华盛顿体系，战后又演变为美苏对峙的两极格局。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"h9b-u5-q1","type":"choice","stem":"标志着美苏冷战开始的事件是","answer":"A","explain":"1947 年 3 月杜鲁门在国会发表演说，公开宣称要「遏制」共产主义，杜鲁门主义的出台标志美苏冷战开始。马歇尔计划是冷战在经济上的表现，北约与华约的成立标志两极格局最终形成。","options":["1947 年杜鲁门主义的出台","1947 年马歇尔计划的提出","1949 年北大西洋公约组织的成立","1955 年华沙条约组织的成立"],"tags":["冷战","时空观念"]},{"id":"h9b-u5-q2","type":"choice","stem":"标志着以美苏为首的两大集团对峙局面（两极格局）最终形成的事件是","answer":"C","explain":"1949 年北约成立后，1955 年苏联与东欧 7 国成立华沙条约组织，以美苏为首的两大集团对峙局面最终形成，两极格局由此确立。","options":["1949 年德国分裂","1949 年北约成立","1955 年华约成立","1962 年古巴导弹危机"],"tags":["两极格局","时空观念"]},{"id":"cat-9b-5-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杜鲁门主义出台，冷战开始\n② 马歇尔计划提出\n③ 德国分裂为联邦德国和民主德国\n④ 华沙条约组织成立，两极格局最终形成","answer":"A","explain":"按时间顺序应为：①杜鲁门主义出台，冷战开始（1947 年 3 月）→②马歇尔计划提出（1947 年 6 月）→③德国分裂为联邦德国和民主德国（1949 年）→④华沙条约组织成立，两极格局最终形成（1955 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-1-g2","type":"choice","stem":"下列关于「冷战的发生与两极格局的形成」的表述，错误的是","answer":"A","explain":"认为冷战开始的标志是马歇尔计划的提出或北约的成立——「冷战开始」与「两极格局形成」是两件事，两个时间点必须分别对应，不能互换。正确表述：1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","options":["认为冷战开始的标志是马歇尔计划的提出或北约的成立。","1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","世界格局多极化趋势在冷战结束后加速发展；和平与发展是当今时代的主题，各国应加强合作、共同发展。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-1-g3","type":"choice","stem":"下列结论中，属于「冷战的发生与两极格局的形成」的是","answer":"A","explain":"本课结论：冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。","苏联解体、东欧剧变说明苏联模式的失败，社会主义运动遭受严重挫折；但中国特色社会主义的成功证明社会主义制度具有强大的生命力——改革必须坚持正确方向、立足本国国情。","改革必须坚持正确方向、立足国情：戈尔巴乔夫改革背离社会主义方向、放弃党的领导，最终导致国家解体；中国改革开放坚持党的领导与社会主义道路，取得巨大成就。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"h9b-u5-q5","type":"choice","stem":"在欧洲共同体的基础上成立、1993 年正式诞生的欧洲区域一体化组织是","answer":"B","explain":"1951 年成立欧洲煤钢共同体，1967 年成立欧洲共同体，1993 年在欧共体基础上成立欧洲联盟，欧洲一体化进程加快。北约与华约是军事政治集团。","options":["欧洲煤钢共同体","欧洲联盟","北大西洋公约组织","华沙条约组织"],"tags":["欧洲联合","时空观念"]},{"id":"cat-9b-5-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 欧洲走向联合：欧洲煤钢共同体成立，欧洲共同体成立\n② 日本经济持续高速发展\n③ 欧洲联盟成立","answer":"A","explain":"按时间顺序应为：①欧洲走向联合：欧洲煤钢共同体成立，欧洲共同体成立（1951 年、1967 年）→②日本经济持续高速发展（20 世纪 60—70 年代）→③欧洲联盟成立（1993 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-2-g2","type":"choice","stem":"下列关于「二战后资本主义国家的变化」的表述，错误的是","answer":"A","explain":"认为冷战开始的标志是马歇尔计划的提出或北约的成立——「冷战开始」与「两极格局形成」是两件事，两个时间点必须分别对应，不能互换。正确表述：1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","options":["认为冷战开始的标志是马歇尔计划的提出或北约的成立。","1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-2-g3","type":"choice","stem":"下列结论中，属于「二战后资本主义国家的变化」的是","answer":"A","explain":"本课结论：冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","世界格局多极化趋势在冷战结束后加速发展；和平与发展是当今时代的主题，各国应加强合作、共同发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。","苏联解体、东欧剧变说明苏联模式的失败，社会主义运动遭受严重挫折；但中国特色社会主义的成功证明社会主义制度具有强大的生命力——改革必须坚持正确方向、立足本国国情。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：通过《紧急银行法》《农业调整法》《全国工业复兴法》等，加强国家对经济的干预和指导，缓解危机。（2024 部编版九下第 13 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"资本主义经济大危机；1929—1933 年经济大危机的特点与根源：特点是涉及范围特别广、持续时间比较长、破坏性特别大（整个资本主义世界的工业产量下降 1/3 以上，失业工人超过 3000 万）。根源是资本主义制度的基本矛盾，即生产社会化与生产资料私人占有之间的矛盾。","explain":"材料出自2024 部编版九下第 13 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-4-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1938 年 9 月，英、法、德、意四国首脑在慕尼黑签订协定，把捷克斯洛伐克的苏台德地区割让给德国，捷方未参会。（吴于廑、齐世荣《世界史·现代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"法西斯国家的侵略扩张；二战的性质与影响：二战是世界范围内反法西斯的正义战争；它彻底粉碎了法西斯主义和军国主义通过战争称霸世界的野心，给人类带来空前灾难（先后有 60 多个国家和地区、20 亿以上人口卷入，死亡 5000 多万人）；战后欧洲衰落、美苏崛起，形成美苏对峙的两极格局；促进了民族解放运动的发展和科学技术的进步。","explain":"材料出自吴于廑、齐世荣《世界史·现代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h9b-u4-m1-q2","type":"short","stem":"（2）依据材料二、三并结合所学，概括世界反法西斯战争取得胜利的原因。（6 分）","answer":"①世界反法西斯同盟的建立，反法西斯国家互相配合、协同作战，是取得胜利的根本保证；②反法西斯战争是正义的战争，得到世界各国人民的广泛支持；③各国人民进行了英勇顽强的斗争、作出了巨大牺牲（如中国的全民族抗战、苏联的斯大林格勒战役、美国在太平洋战场的作战）；④斯大林格勒战役、诺曼底登陆等重大战役的胜利扭转了战局；⑤德意日法西斯发动的是侵略战争，失道寡助。此外，美国实行罗斯福新政增强了经济实力，也为反法西斯战争提供了重要的物质基础。","explain":"","tags":["第二次世界大战","历史解释"],"rubric":["世界反法西斯同盟的建立与协同作战（根本保证）","战争的性质是正义的反法西斯战争","各国人民的英勇斗争与巨大牺牲","重大战役扭转战局（斯大林格勒战役、诺曼底登陆）","法西斯侵略战争失道寡助（或美国国力增强提供物质基础）"]}]},{"id":"hp-mock-1","title":"广州中考历史模拟卷（第 1 套）","subtitle":"整卷模拟 · 选择题 25 题 + 材料题 3 题","grade":"all","tags":["中考模拟","第 1 套","整卷"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"中考模拟"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"组卷说明","text":"按广州中考历史卷面结构组卷：选择题覆盖六册，材料题取自各册重点课时。建议计时完成后再看解析。"},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u1-q1","type":"choice","stem":"我国境内目前已知最早的古人类之一，距今约 170 万年，其化石发现于今云南省的是","answer":"A","explain":"元谋人发现于云南元谋，距今约 170 万年，是我国境内目前已知最早的古人类之一。","options":["元谋人","北京人","山顶洞人","半坡人"],"tags":["史前时期","时空观念"]},{"id":"h7b-u1-q1","type":"choice","stem":"605 年起下令开凿大运河，以洛阳为中心、北抵涿郡、南至余杭的皇帝是","answer":"B","explain":"大运河由隋炀帝下令开凿（605 年起），以洛阳为中心，北抵涿郡，南至余杭，是古代世界上最长的运河。隋文帝的功绩是统一全国、创立三省六部制与分科考试选官。","options":["隋文帝","隋炀帝","唐高祖","唐玄宗"],"tags":["大运河","时空观念"]},{"id":"h8a-u1-q1","type":"choice","stem":"英国发动鸦片战争的根本原因是","answer":"B","explain":"鸦片战争是英国资本主义发展的必然结果：工业革命后英国急需商品市场和原料产地。虎门销烟只是英国发动战争的借口，即直接原因。","options":["林则徐在虎门销烟","英国为打开中国市场、推销工业品并掠夺原料","清政府闭关自守、禁止通商","中英两国贸易长期不平衡"],"tags":["鸦片战争","历史解释"]},{"id":"h8b-u1-q1","type":"choice","stem":"标志着中国人民从此站起来了、成为国家的主人的历史事件是","answer":"B","explain":"1949 年 10 月 1 日开国大典宣告中华人民共和国中央人民政府成立，中国人民从此站起来了，成为国家的主人。政协会议是成立前的筹备，西藏和平解放与抗美援朝是新中国成立后巩固政权的措施。","options":["中国人民政治协商会议第一届全体会议召开","开国大典，中华人民共和国成立","西藏和平解放","抗美援朝战争取得胜利"],"tags":["新中国成立","时空观念"]},{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"h9b-u1-q1","type":"choice","stem":"19 世纪，印度爆发了反抗英国殖民统治的民族大起义，其杰出领导人是","answer":"B","explain":"1857—1859 年印度民族大起义反抗英国殖民统治，章西女王是杰出代表。玻利瓦尔是拉美独立运动领袖，甘地领导的是 20 世纪的印度非暴力不合作运动，凯末尔领导的是土耳其革命。","options":["玻利瓦尔","章西女王","甘地","凯末尔"],"tags":["印度民族大起义","时空观念"]},{"id":"cat-7a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 元谋人生活在云南元谋\n② 北京人生活在周口店\n③ 山顶洞人","answer":"A","explain":"按时间顺序应为：①元谋人生活在云南元谋（约 170 万年前）→②北京人生活在周口店（约 70 万—20 万年前）→③山顶洞人（约 3 万年前）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"h8a-u1-q2","type":"choice","stem":"《南京条约》的各项内容中，最能反映英国打开中国市场、便利经济侵略意图的是","answer":"C","explain":"五口通商打开了中国大门，协定关税破坏了中国关税自主权，使列强可以低价倾销商品、掠夺原料，最能体现其经济侵略意图。割地赔款是政治与财政层面的侵害。","options":["割香港岛给英国","赔款 2100 万银元","开放五处通商口岸并协定关税","英军占领广州"],"tags":["南京条约","史料实证"]},{"id":"h8b-u1-q5","type":"choice","stem":"1949 年 9 月，中国人民政治协商会议第一届全体会议通过的、在 1954 年宪法颁布前起临时宪法作用的文件是","answer":"B","explain":"《共同纲领》是在 1954 年宪法颁布前起临时宪法作用的文件；1954 年宪法是我国第一部社会主义类型的宪法；《土地改革法》是 1950 年颁布的。","options":["《中华民国临时约法》","《中国人民政治协商会议共同纲领》","《中华人民共和国宪法》","《中华人民共和国土地改革法》"],"tags":["共同纲领","史料实证"]},{"id":"h9a-u1-q5","type":"choice","stem":"古埃及金字塔的用途是","answer":"B","explain":"金字塔是古埃及国王的陵墓，其中胡夫金字塔规模最大。它是古埃及文明的象征，反映了古埃及社会经济发展的较高水平和国王的无限权力。","options":["神庙，用于祭祀神灵","国王（法老）的陵墓","天文观测台","抵御外敌的军事堡垒"],"tags":["金字塔","史料实证"]},{"id":"cat-9b-1-1-g2","type":"choice","stem":"下列关于「殖民地人民的反抗战争」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","19 世纪中期，资本主义制度在世界范围内确立和扩展：俄国靠自上而下的改革，美国靠内战，日本靠明治维新——**方式不同，方向一致**。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-7a-1-1-g2","type":"choice","stem":"下列关于「远古时期的人类活动」的表述，错误的是","answer":"A","explain":"认为北京人会人工取火——这是最常见的混淆点，选项常把两者对调。正确表述：北京人会使用天然火并保存火种；人工取火是山顶洞人。","options":["认为北京人会人工取火。","北京人会使用天然火并保存火种；人工取火是山顶洞人。","中华文明的起源具有**本土性**（元谋人、北京人一脉相承）与**多元一体**（黄河流域、长江流域等多点并发）两大特征。","北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7b-u1-q6","type":"choice","stem":"关于五代十国，下列说法正确的是","answer":"A","explain":"五代十国是唐末藩镇割据局面的延续。北方政权更迭频繁、战乱不断；南方相对安定，经济得到发展；统一始终是历史发展的必然趋势。","options":["五代十国是唐末以来藩镇割据局面的延续","五代十国时期南方经济遭到严重破坏","五代十国都是由少数民族建立的政权","五代十国时期全国长期处于统一状态"],"tags":["五代十国","历史解释"]},{"id":"cat-8a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 林则徐在广东虎门销烟\n② 鸦片战争\n③ 中英《南京条约》签订","answer":"A","explain":"按时间顺序应为：①林则徐在广东虎门销烟（1839 年 6 月）→②鸦片战争（1840 年 6 月—1842 年 8 月）→③中英《南京条约》签订（1842 年 8 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-1-g2","type":"choice","stem":"下列关于「中华人民共和国成立」的表述，错误的是","answer":"A","explain":"把《共同纲领》说成 1954 年宪法——「起临时宪法作用的文件」不等于「宪法」，这是两句不同的话。正确表述：1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","options":["把《共同纲领》说成 1954 年宪法。","1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利，中国人民从此站起来了，成为国家的主人，中国历史从此揭开了新的篇章。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9b-1-1-g5","type":"choice","stem":"「拉丁美洲独立运动兴起」发生于","answer":"A","explain":"本课时间轴：拉丁美洲独立运动兴起（19 世纪初）。玻利瓦尔解放哥伦比亚、委内瑞拉、厄瓜多尔等地，圣马丁领导阿根廷、智利、秘鲁的独立运动；1804 年海地独立揭开序幕（拉美第一个独立国家）。其余三个时间是同一单元相邻课时的事件时间。","options":["19 世纪初","1861 年","1861—1865 年","1871 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"cat-7b-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杨坚夺取北周政权，建立隋朝，定都长安\n② 隋炀帝下令开凿大运河\n③ 设置进士科，科举制正式确立\n④ 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","answer":"A","explain":"按时间顺序应为：①杨坚夺取北周政权，建立隋朝，定都长安（581 年）→②隋炀帝下令开凿大运河（605 年起）→③设置进士科，科举制正式确立（隋炀帝时）→④隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-1-g2","type":"choice","stem":"下列关于「鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。","列强侵华的核心目的是把中国变成其商品市场和原料产地；《南京条约》中的**协定关税**破坏中国关税自主权，便利了列强的经济侵略。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-1-g5","type":"choice","stem":"「中国人民政治协商会议第一届全体会议在北平召开」发生于","answer":"A","explain":"本课时间轴：中国人民政治协商会议第一届全体会议在北平召开（1949 年 9 月）。通过《中国人民政治协商会议共同纲领》，起临时宪法作用；决定国旗为五星红旗、以《义勇军进行曲》为代国歌、首都为北京、采用公元纪年。其余三个时间是同一单元相邻课时的事件时间。","options":["1949 年 9 月","1950 年 6 月","1950 年 10 月","1951 年"],"difficulty":1,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-9a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 古埃及初步实现统一\n③ 古埃及大规模修建金字塔（胡夫金字塔规模最大）","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②古埃及初步实现统一（约公元前 3100 年）→③古埃及大规模修建金字塔（胡夫金字塔规模最大）（约公元前 2600 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9b-1-1-g6","type":"choice","stem":"下列考点中，属于「殖民地人民的反抗战争」的是","answer":"A","explain":"本课考点（重点）：拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。其余三项是同一单元相邻课时的考点。","options":["拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，18…","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买…","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废…","19 世纪中期资本主义制度的扩展：俄国（1861 年改革）、美国（内战）、日本（明治维新…"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-7a-1-2-g2","type":"choice","stem":"下列关于「原始农业与史前社会」的表述，错误的是","answer":"A","explain":"把河姆渡与半坡的农作物写反——记「南稻北粟」，与「南干栏北半地穴」一起记。正确表述：河姆渡→水稻（南方）；半坡→粟（北方）。","options":["把河姆渡与半坡的农作物写反。","河姆渡→水稻（南方）；半坡→粟（北方）。","生产力决定生活方式：种植水稻需要水田 → 长江流域的干栏式建筑；种植粟、气候干燥 → 黄河流域的半地穴式房屋。","原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7a-u1-m1-q1","type":"short","stem":"（1）材料一中的灰烬层能说明北京人已经掌握了什么技能？这一发现有何意义？（4 分）","answer":"说明北京人已经会使用火并能够保存火种。意义：火的使用改善了生存条件（烧烤食物、照明、取暖、驱赶野兽），是人类进化过程中的重大进步；周口店遗址是研究人类起源的直接证据。","explain":"","tags":["史料实证","史前时期"],"rubric":["答出「使用火、保存火种」","答出火的作用（取暖/熟食/驱兽任一点）","答出遗址的史料价值"]},{"id":"cat-7b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：永济渠（洛阳至涿郡）、通济渠（洛阳至淮水）、邗沟（淮水至江都入长江）、江南河（长江至余杭），沟通海河、黄河、淮河、长江、钱塘江五大水系。（《隋书·食货志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"隋朝统一与灭亡；隋朝的制度创新与统一：结束分裂、实现统一，创立科举制与三省六部制，开凿大运河，为唐朝的繁荣奠定了基础。","explain":"材料出自《隋书·食货志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h8a-u1-m1-q1","type":"short","stem":"（1）依据材料一，说明林则徐主张禁烟的原因；结合所学指出虎门销烟的意义。（4 分）","answer":"原因：鸦片大量输入使中国白银外流、财政困难（「无可以充饷之银」），并严重摧残吸食者的体质，军队战斗力削弱（「无可以御敌之兵」），危及清朝统治。意义：虎门销烟是中国人民禁烟斗争的伟大胜利，显示了中华民族反抗外来侵略的坚强意志，林则徐是当之无愧的民族英雄。","explain":"","tags":["虎门销烟","史料实证"],"rubric":["答出白银外流、财政困难","答出兵弱、摧残体质","答出禁烟斗争的伟大胜利","答出反抗侵略的坚强意志/民族英雄"]}]},{"id":"hp-mock-2","title":"广州中考历史模拟卷（第 2 套）","subtitle":"整卷模拟 · 选择题 25 题 + 材料题 3 题","grade":"all","tags":["中考模拟","第 2 套","整卷"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"中考模拟"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"组卷说明","text":"按广州中考历史卷面结构组卷：选择题覆盖六册，材料题取自各册重点课时。建议计时完成后再看解析。"},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"cat-7a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 元谋人生活在云南元谋\n② 北京人生活在周口店\n③ 山顶洞人","answer":"A","explain":"按时间顺序应为：①元谋人生活在云南元谋（约 170 万年前）→②北京人生活在周口店（约 70 万—20 万年前）→③山顶洞人（约 3 万年前）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"h8a-u1-q2","type":"choice","stem":"《南京条约》的各项内容中，最能反映英国打开中国市场、便利经济侵略意图的是","answer":"C","explain":"五口通商打开了中国大门，协定关税破坏了中国关税自主权，使列强可以低价倾销商品、掠夺原料，最能体现其经济侵略意图。割地赔款是政治与财政层面的侵害。","options":["割香港岛给英国","赔款 2100 万银元","开放五处通商口岸并协定关税","英军占领广州"],"tags":["南京条约","史料实证"]},{"id":"h8b-u1-q5","type":"choice","stem":"1949 年 9 月，中国人民政治协商会议第一届全体会议通过的、在 1954 年宪法颁布前起临时宪法作用的文件是","answer":"B","explain":"《共同纲领》是在 1954 年宪法颁布前起临时宪法作用的文件；1954 年宪法是我国第一部社会主义类型的宪法；《土地改革法》是 1950 年颁布的。","options":["《中华民国临时约法》","《中国人民政治协商会议共同纲领》","《中华人民共和国宪法》","《中华人民共和国土地改革法》"],"tags":["共同纲领","史料实证"]},{"id":"h9a-u1-q5","type":"choice","stem":"古埃及金字塔的用途是","answer":"B","explain":"金字塔是古埃及国王的陵墓，其中胡夫金字塔规模最大。它是古埃及文明的象征，反映了古埃及社会经济发展的较高水平和国王的无限权力。","options":["神庙，用于祭祀神灵","国王（法老）的陵墓","天文观测台","抵御外敌的军事堡垒"],"tags":["金字塔","史料实证"]},{"id":"cat-9b-1-1-g2","type":"choice","stem":"下列关于「殖民地人民的反抗战争」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","19 世纪中期，资本主义制度在世界范围内确立和扩展：俄国靠自上而下的改革，美国靠内战，日本靠明治维新——**方式不同，方向一致**。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-7a-1-1-g2","type":"choice","stem":"下列关于「远古时期的人类活动」的表述，错误的是","answer":"A","explain":"认为北京人会人工取火——这是最常见的混淆点，选项常把两者对调。正确表述：北京人会使用天然火并保存火种；人工取火是山顶洞人。","options":["认为北京人会人工取火。","北京人会使用天然火并保存火种；人工取火是山顶洞人。","中华文明的起源具有**本土性**（元谋人、北京人一脉相承）与**多元一体**（黄河流域、长江流域等多点并发）两大特征。","北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7b-u1-q6","type":"choice","stem":"关于五代十国，下列说法正确的是","answer":"A","explain":"五代十国是唐末藩镇割据局面的延续。北方政权更迭频繁、战乱不断；南方相对安定，经济得到发展；统一始终是历史发展的必然趋势。","options":["五代十国是唐末以来藩镇割据局面的延续","五代十国时期南方经济遭到严重破坏","五代十国都是由少数民族建立的政权","五代十国时期全国长期处于统一状态"],"tags":["五代十国","历史解释"]},{"id":"cat-8a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 林则徐在广东虎门销烟\n② 鸦片战争\n③ 中英《南京条约》签订","answer":"A","explain":"按时间顺序应为：①林则徐在广东虎门销烟（1839 年 6 月）→②鸦片战争（1840 年 6 月—1842 年 8 月）→③中英《南京条约》签订（1842 年 8 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-1-g2","type":"choice","stem":"下列关于「中华人民共和国成立」的表述，错误的是","answer":"A","explain":"把《共同纲领》说成 1954 年宪法——「起临时宪法作用的文件」不等于「宪法」，这是两句不同的话。正确表述：1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","options":["把《共同纲领》说成 1954 年宪法。","1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利，中国人民从此站起来了，成为国家的主人，中国历史从此揭开了新的篇章。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9b-1-1-g5","type":"choice","stem":"「拉丁美洲独立运动兴起」发生于","answer":"A","explain":"本课时间轴：拉丁美洲独立运动兴起（19 世纪初）。玻利瓦尔解放哥伦比亚、委内瑞拉、厄瓜多尔等地，圣马丁领导阿根廷、智利、秘鲁的独立运动；1804 年海地独立揭开序幕（拉美第一个独立国家）。其余三个时间是同一单元相邻课时的事件时间。","options":["19 世纪初","1861 年","1861—1865 年","1871 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q1","type":"choice","stem":"我国境内目前已知最早的古人类之一，距今约 170 万年，其化石发现于今云南省的是","answer":"A","explain":"元谋人发现于云南元谋，距今约 170 万年，是我国境内目前已知最早的古人类之一。","options":["元谋人","北京人","山顶洞人","半坡人"],"tags":["史前时期","时空观念"]},{"id":"cat-7b-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杨坚夺取北周政权，建立隋朝，定都长安\n② 隋炀帝下令开凿大运河\n③ 设置进士科，科举制正式确立\n④ 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","answer":"A","explain":"按时间顺序应为：①杨坚夺取北周政权，建立隋朝，定都长安（581 年）→②隋炀帝下令开凿大运河（605 年起）→③设置进士科，科举制正式确立（隋炀帝时）→④隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-1-g2","type":"choice","stem":"下列关于「鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。","列强侵华的核心目的是把中国变成其商品市场和原料产地；《南京条约》中的**协定关税**破坏中国关税自主权，便利了列强的经济侵略。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-1-g5","type":"choice","stem":"「中国人民政治协商会议第一届全体会议在北平召开」发生于","answer":"A","explain":"本课时间轴：中国人民政治协商会议第一届全体会议在北平召开（1949 年 9 月）。通过《中国人民政治协商会议共同纲领》，起临时宪法作用；决定国旗为五星红旗、以《义勇军进行曲》为代国歌、首都为北京、采用公元纪年。其余三个时间是同一单元相邻课时的事件时间。","options":["1949 年 9 月","1950 年 6 月","1950 年 10 月","1951 年"],"difficulty":1,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-9a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 古埃及初步实现统一\n③ 古埃及大规模修建金字塔（胡夫金字塔规模最大）","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②古埃及初步实现统一（约公元前 3100 年）→③古埃及大规模修建金字塔（胡夫金字塔规模最大）（约公元前 2600 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9b-1-1-g6","type":"choice","stem":"下列考点中，属于「殖民地人民的反抗战争」的是","answer":"A","explain":"本课考点（重点）：拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。其余三项是同一单元相邻课时的考点。","options":["拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，18…","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买…","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废…","19 世纪中期资本主义制度的扩展：俄国（1861 年改革）、美国（内战）、日本（明治维新…"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"cat-7b-1-1-g2","type":"choice","stem":"下列关于「隋朝统一与灭亡」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h8a-u1-q3","type":"choice","stem":"1860 年焚毁圆明园的侵略者是","answer":"B","explain":"第二次鸦片战争中，1860 年 10 月英法联军攻入北京，抢劫并焚毁了圆明园。八国联军侵华是 1900 年的事。","options":["英国军队","英法联军","八国联军","日本军队"],"tags":["第二次鸦片战争","时空观念"]},{"id":"h8b-u1-q1","type":"choice","stem":"标志着中国人民从此站起来了、成为国家的主人的历史事件是","answer":"B","explain":"1949 年 10 月 1 日开国大典宣告中华人民共和国中央人民政府成立，中国人民从此站起来了，成为国家的主人。政协会议是成立前的筹备，西藏和平解放与抗美援朝是新中国成立后巩固政权的措施。","options":["中国人民政治协商会议第一届全体会议召开","开国大典，中华人民共和国成立","西藏和平解放","抗美援朝战争取得胜利"],"tags":["新中国成立","时空观念"]},{"id":"cat-9a-1-1-g2","type":"choice","stem":"下列关于「古代埃及」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》刻写用的文字说成象形文字——两河流域 = 楔形文字，尼罗河流域 = 象形文字，这是最容易被调换的一组搭配。正确表述：《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","options":["把《汉谟拉比法典》刻写用的文字说成象形文字。","《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明**大河流域是早期文明的共同摇篮**。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q2","type":"choice","stem":"1861 年，俄国沙皇亚历山大二世签署废除农奴制的法令。这项改革的性质是","answer":"B","explain":"改革由沙皇政府自上而下推行，使农奴获得人身自由、为资本主义发展提供了自由劳动力与市场，因此是自上而下的资产阶级性质的改革；但它保留了大量封建残余，不是「彻底」废除封建制度。","options":["自下而上的农民起义","自上而下的资产阶级性质的改革","无产阶级社会主义革命","彻底废除封建制度的民主革命"],"tags":["俄国农奴制改革","历史解释"]},{"id":"cat-7a-1-2-g2","type":"choice","stem":"下列关于「原始农业与史前社会」的表述，错误的是","answer":"A","explain":"把河姆渡与半坡的农作物写反——记「南稻北粟」，与「南干栏北半地穴」一起记。正确表述：河姆渡→水稻（南方）；半坡→粟（北方）。","options":["把河姆渡与半坡的农作物写反。","河姆渡→水稻（南方）；半坡→粟（北方）。","生产力决定生活方式：种植水稻需要水田 → 长江流域的干栏式建筑；种植粟、气候干燥 → 黄河流域的半地穴式房屋。","原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1921 年安特生、师丹斯基在北京周口店龙骨山发现遗址；1929 年 12 月裴文中发掘出第一个完整的北京人头盖骨化石。此后陆续发现 40 多个个体的人骨化石。（中国社会科学院考古研究所《北京人遗址》相关记述）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"远古时期的人类活动；北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。","explain":"材料出自中国社会科学院考古研究所《北京人遗址》相关记述。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h7b-u1-m1-q2","type":"short","stem":"（2）材料二、三分别反映了唐太宗怎样的治国做法？这些做法与「贞观之治」的出现有何关系？（5 分）","answer":"材料二反映唐太宗重视百姓、以民为本，注意减轻百姓负担（这是吸取隋亡教训的结果）；材料三反映他重视科举取士、笼络人才、扩大统治基础。关系：正因为唐太宗减轻赋税徭役、虚心纳谏、知人善任，并进一步完善三省六部制与科举制，才使政治比较清明、经济得到恢复和发展、社会秩序安定、国力增强，从而出现了「贞观之治」的局面。","explain":"","tags":["贞观之治","历史解释"],"rubric":["材料二：以民为本、重视百姓（减轻负担）","材料三：重视科举取士、重用人才","答出措施与治世之间的因果对应","答出贞观之治的表现（政治清明/经济发展/社会安定）"]},{"id":"h8a-u1-m1-q2","type":"short","stem":"（2）依据材料二，指出《南京条约》中破坏中国关税自主权的条款，并结合材料三说明鸦片战争对中国社会性质的影响。（6 分）","answer":"条款：英商进出口货物应纳税款必须经过双方协议（协定关税）。影响：中国的领土完整和主权遭到破坏，开始沦为半殖民地；封建经济逐步解体，被卷入资本主义世界市场，开始沦为半封建。总之，鸦片战争后中国开始沦为半殖民地半封建社会，鸦片战争成为中国近代史的开端。","explain":"","tags":["南京条约","半殖民地半封建社会"],"rubric":["答出协定关税","答出领土、主权遭到破坏","答出封建经济开始解体","答出开始沦为半殖民地半封建社会","答出是中国近代史的开端"]}]},{"id":"hp-mock-3","title":"广州中考历史模拟卷（第 3 套）","subtitle":"整卷模拟 · 选择题 25 题 + 材料题 3 题","grade":"all","tags":["中考模拟","第 3 套","整卷"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"中考模拟"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"组卷说明","text":"按广州中考历史卷面结构组卷：选择题覆盖六册，材料题取自各册重点课时。建议计时完成后再看解析。"},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"cat-7a-1-1-g2","type":"choice","stem":"下列关于「远古时期的人类活动」的表述，错误的是","answer":"A","explain":"认为北京人会人工取火——这是最常见的混淆点，选项常把两者对调。正确表述：北京人会使用天然火并保存火种；人工取火是山顶洞人。","options":["认为北京人会人工取火。","北京人会使用天然火并保存火种；人工取火是山顶洞人。","中华文明的起源具有**本土性**（元谋人、北京人一脉相承）与**多元一体**（黄河流域、长江流域等多点并发）两大特征。","北京人的发现与特征：会使用天然火、群体生活，是研究人类起源的直接证据。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7b-u1-q6","type":"choice","stem":"关于五代十国，下列说法正确的是","answer":"A","explain":"五代十国是唐末藩镇割据局面的延续。北方政权更迭频繁、战乱不断；南方相对安定，经济得到发展；统一始终是历史发展的必然趋势。","options":["五代十国是唐末以来藩镇割据局面的延续","五代十国时期南方经济遭到严重破坏","五代十国都是由少数民族建立的政权","五代十国时期全国长期处于统一状态"],"tags":["五代十国","历史解释"]},{"id":"cat-8a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 林则徐在广东虎门销烟\n② 鸦片战争\n③ 中英《南京条约》签订","answer":"A","explain":"按时间顺序应为：①林则徐在广东虎门销烟（1839 年 6 月）→②鸦片战争（1840 年 6 月—1842 年 8 月）→③中英《南京条约》签订（1842 年 8 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-1-g2","type":"choice","stem":"下列关于「中华人民共和国成立」的表述，错误的是","answer":"A","explain":"把《共同纲领》说成 1954 年宪法——「起临时宪法作用的文件」不等于「宪法」，这是两句不同的话。正确表述：1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","options":["把《共同纲领》说成 1954 年宪法。","1949 年《共同纲领》起临时宪法作用；1954 年第一届全国人民代表大会第一次会议通过的宪法，是我国第一部社会主义类型的宪法。","中华人民共和国成立，标志着中国新民主主义革命取得了伟大胜利，中国人民从此站起来了，成为国家的主人，中国历史从此揭开了新的篇章。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9b-1-1-g5","type":"choice","stem":"「拉丁美洲独立运动兴起」发生于","answer":"A","explain":"本课时间轴：拉丁美洲独立运动兴起（19 世纪初）。玻利瓦尔解放哥伦比亚、委内瑞拉、厄瓜多尔等地，圣马丁领导阿根廷、智利、秘鲁的独立运动；1804 年海地独立揭开序幕（拉美第一个独立国家）。其余三个时间是同一单元相邻课时的事件时间。","options":["19 世纪初","1861 年","1861—1865 年","1871 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q1","type":"choice","stem":"我国境内目前已知最早的古人类之一，距今约 170 万年，其化石发现于今云南省的是","answer":"A","explain":"元谋人发现于云南元谋，距今约 170 万年，是我国境内目前已知最早的古人类之一。","options":["元谋人","北京人","山顶洞人","半坡人"],"tags":["史前时期","时空观念"]},{"id":"cat-7b-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杨坚夺取北周政权，建立隋朝，定都长安\n② 隋炀帝下令开凿大运河\n③ 设置进士科，科举制正式确立\n④ 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","answer":"A","explain":"按时间顺序应为：①杨坚夺取北周政权，建立隋朝，定都长安（581 年）→②隋炀帝下令开凿大运河（605 年起）→③设置进士科，科举制正式确立（隋炀帝时）→④隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-1-g2","type":"choice","stem":"下列关于「鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。","列强侵华的核心目的是把中国变成其商品市场和原料产地；《南京条约》中的**协定关税**破坏中国关税自主权，便利了列强的经济侵略。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-1-g5","type":"choice","stem":"「中国人民政治协商会议第一届全体会议在北平召开」发生于","answer":"A","explain":"本课时间轴：中国人民政治协商会议第一届全体会议在北平召开（1949 年 9 月）。通过《中国人民政治协商会议共同纲领》，起临时宪法作用；决定国旗为五星红旗、以《义勇军进行曲》为代国歌、首都为北京、采用公元纪年。其余三个时间是同一单元相邻课时的事件时间。","options":["1949 年 9 月","1950 年 6 月","1950 年 10 月","1951 年"],"difficulty":1,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-9a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 古埃及初步实现统一\n③ 古埃及大规模修建金字塔（胡夫金字塔规模最大）","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②古埃及初步实现统一（约公元前 3100 年）→③古埃及大规模修建金字塔（胡夫金字塔规模最大）（约公元前 2600 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9b-1-1-g6","type":"choice","stem":"下列考点中，属于「殖民地人民的反抗战争」的是","answer":"A","explain":"本课考点（重点）：拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。其余三项是同一单元相邻课时的考点。","options":["拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，18…","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买…","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废…","19 世纪中期资本主义制度的扩展：俄国（1861 年改革）、美国（内战）、日本（明治维新…"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"cat-7b-1-1-g2","type":"choice","stem":"下列关于「隋朝统一与灭亡」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h8a-u1-q3","type":"choice","stem":"1860 年焚毁圆明园的侵略者是","answer":"B","explain":"第二次鸦片战争中，1860 年 10 月英法联军攻入北京，抢劫并焚毁了圆明园。八国联军侵华是 1900 年的事。","options":["英国军队","英法联军","八国联军","日本军队"],"tags":["第二次鸦片战争","时空观念"]},{"id":"h8b-u1-q1","type":"choice","stem":"标志着中国人民从此站起来了、成为国家的主人的历史事件是","answer":"B","explain":"1949 年 10 月 1 日开国大典宣告中华人民共和国中央人民政府成立，中国人民从此站起来了，成为国家的主人。政协会议是成立前的筹备，西藏和平解放与抗美援朝是新中国成立后巩固政权的措施。","options":["中国人民政治协商会议第一届全体会议召开","开国大典，中华人民共和国成立","西藏和平解放","抗美援朝战争取得胜利"],"tags":["新中国成立","时空观念"]},{"id":"cat-9a-1-1-g2","type":"choice","stem":"下列关于「古代埃及」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》刻写用的文字说成象形文字——两河流域 = 楔形文字，尼罗河流域 = 象形文字，这是最容易被调换的一组搭配。正确表述：《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","options":["把《汉谟拉比法典》刻写用的文字说成象形文字。","《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明**大河流域是早期文明的共同摇篮**。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q2","type":"choice","stem":"1861 年，俄国沙皇亚历山大二世签署废除农奴制的法令。这项改革的性质是","answer":"B","explain":"改革由沙皇政府自上而下推行，使农奴获得人身自由、为资本主义发展提供了自由劳动力与市场，因此是自上而下的资产阶级性质的改革；但它保留了大量封建残余，不是「彻底」废除封建制度。","options":["自下而上的农民起义","自上而下的资产阶级性质的改革","无产阶级社会主义革命","彻底废除封建制度的民主革命"],"tags":["俄国农奴制改革","历史解释"]},{"id":"cat-7a-1-2-g2","type":"choice","stem":"下列关于「原始农业与史前社会」的表述，错误的是","answer":"A","explain":"把河姆渡与半坡的农作物写反——记「南稻北粟」，与「南干栏北半地穴」一起记。正确表述：河姆渡→水稻（南方）；半坡→粟（北方）。","options":["把河姆渡与半坡的农作物写反。","河姆渡→水稻（南方）；半坡→粟（北方）。","生产力决定生活方式：种植水稻需要水田 → 长江流域的干栏式建筑；种植粟、气候干燥 → 黄河流域的半地穴式房屋。","原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g3","type":"choice","stem":"下列结论中，属于「隋朝统一与灭亡」的是","answer":"A","explain":"本课结论：科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-2-g2","type":"choice","stem":"下列关于「第二次鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q2","type":"choice","stem":"1951 年西藏和平解放的重要意义是","answer":"A","explain":"西藏和平解放使祖国大陆获得统一，各族人民实现了大团结。民族区域自治制度在 1954 年宪法中确立为一项基本政治制度；西藏自治区成立于 1965 年；台湾问题尚未解决，不能说「祖国获得完全统一」。","options":["祖国大陆获得统一，各族人民实现大团结","标志着祖国获得完全统一","标志着民族区域自治制度正式确立","西藏自治区正式成立"],"tags":["西藏和平解放","时空观念"]},{"id":"h9a-u1-q2","type":"choice","stem":"迄今已知世界上第一部较为完整的成文法典是","answer":"A","explain":"公元前 18 世纪，古巴比伦王国国王汉谟拉比为维护奴隶主阶级的利益制定了《汉谟拉比法典》，刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。","options":["《汉谟拉比法典》","《十二铜表法》","《罗马民法大全》","《拿破仑法典》"],"tags":["《汉谟拉比法典》","时空观念"]},{"id":"cat-9b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 俄国农奴制改革\n② 美国南北战争\n③ 德意志帝国成立（普法战争后）","answer":"A","explain":"按时间顺序应为：①俄国农奴制改革（1861 年）→②美国南北战争（1861—1865 年）→③德意志帝国成立（普法战争后）（1871 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-7a-1-2-g5","type":"choice","stem":"「河姆渡文化（长江流域）」发生于","answer":"A","explain":"本课时间轴：河姆渡文化（长江流域）（约 7000 年前）。种植水稻、干栏式建筑、木结构水井。其余三个时间是同一单元相邻课时的事件时间。","options":["约 7000 年前","约 170 万年前","约 70 万—20 万年前","约 3 万年前"],"difficulty":1,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：河姆渡人生活在长江下游，距今约 7000 年。遗址发现大量木构件和榫卯结构，说明当时已建造底层架空、防潮通风的干栏式房屋。遗址还出土炭化稻谷、骨耜和猪纹陶钵。（浙江省文物考古研究所《河姆渡遗址》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"原始农业与史前社会；原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。","explain":"材料出自浙江省文物考古研究所《河姆渡遗址》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：中书省起草诏令，门下省审议，尚书省执行，下设吏、户、礼、兵、刑、工六部，分工明确、相互牵制。（《新唐书·百官志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"唐朝建立与“贞观之治”；科举制：隋文帝时开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝进一步完善（唐太宗增加考试科目，武则天创立殿试和武举，唐玄宗把诗赋作为考试内容）。","explain":"材料出自《新唐书·百官志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：在林则徐主持下，于海滩挖池，先注海水，再投入鸦片，撒入生石灰搅拌，鸦片随潮水冲入大海。历时 23 天，销毁鸦片 110 多万千克。（《清史稿·林则徐传》；2024 部编版八上第 1 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"鸦片战争；鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战争的借口（直接原因）。","explain":"材料出自《清史稿·林则徐传》；2024 部编版八上第 1 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-mock-4","title":"广州中考历史模拟卷（第 4 套）","subtitle":"整卷模拟 · 选择题 25 题 + 材料题 3 题","grade":"all","tags":["中考模拟","第 4 套","整卷"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"中考模拟"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"组卷说明","text":"按广州中考历史卷面结构组卷：选择题覆盖六册，材料题取自各册重点课时。建议计时完成后再看解析。"},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u1-q1","type":"choice","stem":"我国境内目前已知最早的古人类之一，距今约 170 万年，其化石发现于今云南省的是","answer":"A","explain":"元谋人发现于云南元谋，距今约 170 万年，是我国境内目前已知最早的古人类之一。","options":["元谋人","北京人","山顶洞人","半坡人"],"tags":["史前时期","时空观念"]},{"id":"cat-7b-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杨坚夺取北周政权，建立隋朝，定都长安\n② 隋炀帝下令开凿大运河\n③ 设置进士科，科举制正式确立\n④ 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安","answer":"A","explain":"按时间顺序应为：①杨坚夺取北周政权，建立隋朝，定都长安（581 年）→②隋炀帝下令开凿大运河（605 年起）→③设置进士科，科举制正式确立（隋炀帝时）→④隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-1-g2","type":"choice","stem":"下列关于「鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。","列强侵华的核心目的是把中国变成其商品市场和原料产地；《南京条约》中的**协定关税**破坏中国关税自主权，便利了列强的经济侵略。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-1-g5","type":"choice","stem":"「中国人民政治协商会议第一届全体会议在北平召开」发生于","answer":"A","explain":"本课时间轴：中国人民政治协商会议第一届全体会议在北平召开（1949 年 9 月）。通过《中国人民政治协商会议共同纲领》，起临时宪法作用；决定国旗为五星红旗、以《义勇军进行曲》为代国歌、首都为北京、采用公元纪年。其余三个时间是同一单元相邻课时的事件时间。","options":["1949 年 9 月","1950 年 6 月","1950 年 10 月","1951 年"],"difficulty":1,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-9a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 古埃及初步实现统一\n③ 古埃及大规模修建金字塔（胡夫金字塔规模最大）","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②古埃及初步实现统一（约公元前 3100 年）→③古埃及大规模修建金字塔（胡夫金字塔规模最大）（约公元前 2600 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9b-1-1-g6","type":"choice","stem":"下列考点中，属于「殖民地人民的反抗战争」的是","answer":"A","explain":"本课考点（重点）：拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。其余三项是同一单元相邻课时的考点。","options":["拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，18…","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买…","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废…","19 世纪中期资本主义制度的扩展：俄国（1861 年改革）、美国（内战）、日本（明治维新…"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"cat-7b-1-1-g2","type":"choice","stem":"下列关于「隋朝统一与灭亡」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h8a-u1-q3","type":"choice","stem":"1860 年焚毁圆明园的侵略者是","answer":"B","explain":"第二次鸦片战争中，1860 年 10 月英法联军攻入北京，抢劫并焚毁了圆明园。八国联军侵华是 1900 年的事。","options":["英国军队","英法联军","八国联军","日本军队"],"tags":["第二次鸦片战争","时空观念"]},{"id":"h8b-u1-q1","type":"choice","stem":"标志着中国人民从此站起来了、成为国家的主人的历史事件是","answer":"B","explain":"1949 年 10 月 1 日开国大典宣告中华人民共和国中央人民政府成立，中国人民从此站起来了，成为国家的主人。政协会议是成立前的筹备，西藏和平解放与抗美援朝是新中国成立后巩固政权的措施。","options":["中国人民政治协商会议第一届全体会议召开","开国大典，中华人民共和国成立","西藏和平解放","抗美援朝战争取得胜利"],"tags":["新中国成立","时空观念"]},{"id":"cat-9a-1-1-g2","type":"choice","stem":"下列关于「古代埃及」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》刻写用的文字说成象形文字——两河流域 = 楔形文字，尼罗河流域 = 象形文字，这是最容易被调换的一组搭配。正确表述：《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","options":["把《汉谟拉比法典》刻写用的文字说成象形文字。","《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明**大河流域是早期文明的共同摇篮**。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q2","type":"choice","stem":"1861 年，俄国沙皇亚历山大二世签署废除农奴制的法令。这项改革的性质是","answer":"B","explain":"改革由沙皇政府自上而下推行，使农奴获得人身自由、为资本主义发展提供了自由劳动力与市场，因此是自上而下的资产阶级性质的改革；但它保留了大量封建残余，不是「彻底」废除封建制度。","options":["自下而上的农民起义","自上而下的资产阶级性质的改革","无产阶级社会主义革命","彻底废除封建制度的民主革命"],"tags":["俄国农奴制改革","历史解释"]},{"id":"cat-7a-1-2-g2","type":"choice","stem":"下列关于「原始农业与史前社会」的表述，错误的是","answer":"A","explain":"把河姆渡与半坡的农作物写反——记「南稻北粟」，与「南干栏北半地穴」一起记。正确表述：河姆渡→水稻（南方）；半坡→粟（北方）。","options":["把河姆渡与半坡的农作物写反。","河姆渡→水稻（南方）；半坡→粟（北方）。","生产力决定生活方式：种植水稻需要水田 → 长江流域的干栏式建筑；种植粟、气候干燥 → 黄河流域的半地穴式房屋。","原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g3","type":"choice","stem":"下列结论中，属于「隋朝统一与灭亡」的是","answer":"A","explain":"本课结论：科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-2-g2","type":"choice","stem":"下列关于「第二次鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q2","type":"choice","stem":"1951 年西藏和平解放的重要意义是","answer":"A","explain":"西藏和平解放使祖国大陆获得统一，各族人民实现了大团结。民族区域自治制度在 1954 年宪法中确立为一项基本政治制度；西藏自治区成立于 1965 年；台湾问题尚未解决，不能说「祖国获得完全统一」。","options":["祖国大陆获得统一，各族人民实现大团结","标志着祖国获得完全统一","标志着民族区域自治制度正式确立","西藏自治区正式成立"],"tags":["西藏和平解放","时空观念"]},{"id":"h9a-u1-q2","type":"choice","stem":"迄今已知世界上第一部较为完整的成文法典是","answer":"A","explain":"公元前 18 世纪，古巴比伦王国国王汉谟拉比为维护奴隶主阶级的利益制定了《汉谟拉比法典》，刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。","options":["《汉谟拉比法典》","《十二铜表法》","《罗马民法大全》","《拿破仑法典》"],"tags":["《汉谟拉比法典》","时空观念"]},{"id":"cat-9b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 俄国农奴制改革\n② 美国南北战争\n③ 德意志帝国成立（普法战争后）","answer":"A","explain":"按时间顺序应为：①俄国农奴制改革（1861 年）→②美国南北战争（1861—1865 年）→③德意志帝国成立（普法战争后）（1871 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-7a-1-2-g5","type":"choice","stem":"「河姆渡文化（长江流域）」发生于","answer":"A","explain":"本课时间轴：河姆渡文化（长江流域）（约 7000 年前）。种植水稻、干栏式建筑、木结构水井。其余三个时间是同一单元相邻课时的事件时间。","options":["约 7000 年前","约 170 万年前","约 70 万—20 万年前","约 3 万年前"],"difficulty":1,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"cat-8a-1-2-g5","type":"choice","stem":"「第二次鸦片战争」发生于","answer":"A","explain":"本课时间轴：第二次鸦片战争（1856 年 10 月—1860 年 10 月）。英法联军发动，是鸦片战争的继续和扩大；1858 年《天津条约》。其余三个时间是同一单元相邻课时的事件时间。","options":["1856 年 10 月—1860 年 10 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q4","type":"choice","stem":"1950—1952 年底土地改革完成后，我国农村土地的所有权状况是","answer":"D","explain":"土地改革废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，土地归农民私有。土地归集体所有是 1953—1956 年农业合作化的结果。","options":["归国家所有","归集体所有","归地主与农民共同所有","归农民所有"],"tags":["土地改革","历史解释"]},{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"cat-9b-1-2-g2","type":"choice","stem":"下列关于「俄国的改革」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q3","type":"choice","stem":"良渚古城与陶寺古城的考古发现，最主要的价值在于","answer":"B","explain":"两处古城都出现城市、阶级分化与王权，是中华文明五千多年历史的实证，也说明中华文明本土起源、多元一体。","options":["证明中华文明是由西方传入的","为中华文明五千多年历史提供实证","说明我国最早的文字出现在长江流域","证明夏朝是我国第一个王朝"],"tags":["文明起源","家国情怀"]},{"id":"h7a-u1-m1-q2","type":"short","stem":"（2）依据材料二、三，说明良渚古城为什么被视为已进入文明社会的证据。（4 分）","answer":"良渚古城有宫殿区与内外城，说明已经出现城市；大型水利系统说明有组织大规模公共工程的能力和王权；随葬玉器的规格差异反映出阶级分化。以上都与材料三「城市、阶级分化、王权与国家」的判断标准相符。","explain":"","tags":["文明起源","史料实证"],"rubric":["指出城市/宫殿区","指出水利工程与组织能力","指出玉器反映阶级分化","对应文明判断标准"]},{"id":"cat-7b-1-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：唐高祖时始铸「开元通宝」，结束以重量命名钱币的传统，开创「通宝」钱制，影响后世千年。（《旧唐书·食货志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"“开元盛世”；科举制：隋文帝时开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝进一步完善（唐太宗增加考试科目，武则天创立殿试和武举，唐玄宗把诗赋作为考试内容）。","explain":"材料出自《旧唐书·食货志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1860 年 10 月，英法联军闯入圆明园，掠夺文物珍宝，并纵火焚烧，大火三日不熄。（《清史稿·文宗本纪》；2024 部编版八上第 2 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"第二次鸦片战争；第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联军 1860 年所为。","explain":"材料出自《清史稿·文宗本纪》；2024 部编版八上第 2 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-mock-5","title":"广州中考历史模拟卷（第 5 套）","subtitle":"整卷模拟 · 选择题 25 题 + 材料题 3 题","grade":"all","tags":["中考模拟","第 5 套","整卷"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"中考模拟"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"组卷说明","text":"按广州中考历史卷面结构组卷：选择题覆盖六册，材料题取自各册重点课时。建议计时完成后再看解析。"},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"cat-7b-1-1-g2","type":"choice","stem":"下列关于「隋朝统一与灭亡」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h8a-u1-q3","type":"choice","stem":"1860 年焚毁圆明园的侵略者是","answer":"B","explain":"第二次鸦片战争中，1860 年 10 月英法联军攻入北京，抢劫并焚毁了圆明园。八国联军侵华是 1900 年的事。","options":["英国军队","英法联军","八国联军","日本军队"],"tags":["第二次鸦片战争","时空观念"]},{"id":"h8b-u1-q1","type":"choice","stem":"标志着中国人民从此站起来了、成为国家的主人的历史事件是","answer":"B","explain":"1949 年 10 月 1 日开国大典宣告中华人民共和国中央人民政府成立，中国人民从此站起来了，成为国家的主人。政协会议是成立前的筹备，西藏和平解放与抗美援朝是新中国成立后巩固政权的措施。","options":["中国人民政治协商会议第一届全体会议召开","开国大典，中华人民共和国成立","西藏和平解放","抗美援朝战争取得胜利"],"tags":["新中国成立","时空观念"]},{"id":"cat-9a-1-1-g2","type":"choice","stem":"下列关于「古代埃及」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》刻写用的文字说成象形文字——两河流域 = 楔形文字，尼罗河流域 = 象形文字，这是最容易被调换的一组搭配。正确表述：《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","options":["把《汉谟拉比法典》刻写用的文字说成象形文字。","《汉谟拉比法典》用**楔形文字**刻写；象形文字是古埃及人创造的。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明**大河流域是早期文明的共同摇篮**。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q2","type":"choice","stem":"1861 年，俄国沙皇亚历山大二世签署废除农奴制的法令。这项改革的性质是","answer":"B","explain":"改革由沙皇政府自上而下推行，使农奴获得人身自由、为资本主义发展提供了自由劳动力与市场，因此是自上而下的资产阶级性质的改革；但它保留了大量封建残余，不是「彻底」废除封建制度。","options":["自下而上的农民起义","自上而下的资产阶级性质的改革","无产阶级社会主义革命","彻底废除封建制度的民主革命"],"tags":["俄国农奴制改革","历史解释"]},{"id":"cat-7a-1-2-g2","type":"choice","stem":"下列关于「原始农业与史前社会」的表述，错误的是","answer":"A","explain":"把河姆渡与半坡的农作物写反——记「南稻北粟」，与「南干栏北半地穴」一起记。正确表述：河姆渡→水稻（南方）；半坡→粟（北方）。","options":["把河姆渡与半坡的农作物写反。","河姆渡→水稻（南方）；半坡→粟（北方）。","生产力决定生活方式：种植水稻需要水田 → 长江流域的干栏式建筑；种植粟、气候干燥 → 黄河流域的半地穴式房屋。","原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g3","type":"choice","stem":"下列结论中，属于「隋朝统一与灭亡」的是","answer":"A","explain":"本课结论：科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-2-g2","type":"choice","stem":"下列关于「第二次鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q2","type":"choice","stem":"1951 年西藏和平解放的重要意义是","answer":"A","explain":"西藏和平解放使祖国大陆获得统一，各族人民实现了大团结。民族区域自治制度在 1954 年宪法中确立为一项基本政治制度；西藏自治区成立于 1965 年；台湾问题尚未解决，不能说「祖国获得完全统一」。","options":["祖国大陆获得统一，各族人民实现大团结","标志着祖国获得完全统一","标志着民族区域自治制度正式确立","西藏自治区正式成立"],"tags":["西藏和平解放","时空观念"]},{"id":"h9a-u1-q2","type":"choice","stem":"迄今已知世界上第一部较为完整的成文法典是","answer":"A","explain":"公元前 18 世纪，古巴比伦王国国王汉谟拉比为维护奴隶主阶级的利益制定了《汉谟拉比法典》，刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。","options":["《汉谟拉比法典》","《十二铜表法》","《罗马民法大全》","《拿破仑法典》"],"tags":["《汉谟拉比法典》","时空观念"]},{"id":"cat-9b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 俄国农奴制改革\n② 美国南北战争\n③ 德意志帝国成立（普法战争后）","answer":"A","explain":"按时间顺序应为：①俄国农奴制改革（1861 年）→②美国南北战争（1861—1865 年）→③德意志帝国成立（普法战争后）（1871 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-7a-1-2-g5","type":"choice","stem":"「河姆渡文化（长江流域）」发生于","answer":"A","explain":"本课时间轴：河姆渡文化（长江流域）（约 7000 年前）。种植水稻、干栏式建筑、木结构水井。其余三个时间是同一单元相邻课时的事件时间。","options":["约 7000 年前","约 170 万年前","约 70 万—20 万年前","约 3 万年前"],"difficulty":1,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"cat-8a-1-2-g5","type":"choice","stem":"「第二次鸦片战争」发生于","answer":"A","explain":"本课时间轴：第二次鸦片战争（1856 年 10 月—1860 年 10 月）。英法联军发动，是鸦片战争的继续和扩大；1858 年《天津条约》。其余三个时间是同一单元相邻课时的事件时间。","options":["1856 年 10 月—1860 年 10 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q4","type":"choice","stem":"1950—1952 年底土地改革完成后，我国农村土地的所有权状况是","answer":"D","explain":"土地改革废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，土地归农民私有。土地归集体所有是 1953—1956 年农业合作化的结果。","options":["归国家所有","归集体所有","归地主与农民共同所有","归农民所有"],"tags":["土地改革","历史解释"]},{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"cat-9b-1-2-g2","type":"choice","stem":"下列关于「俄国的改革」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q3","type":"choice","stem":"良渚古城与陶寺古城的考古发现，最主要的价值在于","answer":"B","explain":"两处古城都出现城市、阶级分化与王权，是中华文明五千多年历史的实证，也说明中华文明本土起源、多元一体。","options":["证明中华文明是由西方传入的","为中华文明五千多年历史提供实证","说明我国最早的文字出现在长江流域","证明夏朝是我国第一个王朝"],"tags":["文明起源","家国情怀"]},{"id":"h7b-u1-q4","type":"choice","stem":"唐太宗说「舟所以比人君，水所以比黎庶，水能载舟，亦能覆舟」，这说明他","answer":"B","explain":"唐太宗从隋朝因暴政速亡的教训中认识到百姓的力量，因此减轻赋税徭役、推行有利于生产恢复的政策，这才有「贞观之治」。","options":["主张严刑峻法以驾驭臣下","注意吸取隋亡教训，爱惜民力","主张大力开疆拓土","主张抑制商业发展"],"tags":["贞观之治","家国情怀"]},{"id":"cat-8a-1-2-g6","type":"choice","stem":"下列考点中，属于「第二次鸦片战争」的是","answer":"A","explain":"本课考点（重点）：第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联军 1860 年所为。其余三项是同一单元相邻课时的考点。","options":["第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联…","鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战…","《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、…","鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q5","type":"choice","stem":"1949 年 9 月，中国人民政治协商会议第一届全体会议通过的、在 1954 年宪法颁布前起临时宪法作用的文件是","answer":"B","explain":"《共同纲领》是在 1954 年宪法颁布前起临时宪法作用的文件；1954 年宪法是我国第一部社会主义类型的宪法；《土地改革法》是 1950 年颁布的。","options":["《中华民国临时约法》","《中国人民政治协商会议共同纲领》","《中华人民共和国宪法》","《中华人民共和国土地改革法》"],"tags":["共同纲领","史料实证"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9b-1-2-g5","type":"choice","stem":"「俄国农奴制改革」发生于","answer":"A","explain":"本课时间轴：俄国农奴制改革（1861 年）。沙皇亚历山大二世签署废除农奴制的法令：农奴获得人身自由，可通过赎买获得份地——俄国历史上的重要转折点。其余三个时间是同一单元相邻课时的事件时间。","options":["1861 年","19 世纪初","1857—1859 年","1861—1865 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q4","type":"choice","stem":"「禅让」制下，部落联盟首领产生的方式是","answer":"B","explain":"尧舜禹时期通过推举贤能者继位，称为禅让。父死子继的世袭制自夏启开始。","options":["父死子继","推举贤能者","以战功决定","由占卜决定"],"tags":["禅让制","历史解释"]},{"id":"cat-7a-1-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：良渚古城位于浙江杭州余杭，距今约 5300—4300 年。古城外围有规模宏大的水利系统，由 11 条坝体组成，是中国已知最早的大型水利工程之一。2019 年良渚古城遗址列入《世界遗产名录》。（联合国教科文组织世界遗产中心；浙江省文物考古研究所）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"中华文明的起源；良渚、陶寺古城的意义：证明中国在距今约 5000 多年已出现早期国家与文明。","explain":"材料出自联合国教科文组织世界遗产中心；浙江省文物考古研究所。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-1-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：756 年唐玄宗逃往蜀中，行至马嵬驿，禁军哗变，杀死杨国忠，逼玄宗缢死杨贵妃。（《旧唐书·杨贵妃传》；《资治通鉴》卷二一八）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"安史之乱与唐朝衰亡；安史之乱（755—763）是唐朝由盛转衰的转折点：唐玄宗后期贪图享乐、任用奸臣，节度使权力膨胀，社会矛盾尖锐，最终酿成叛乱；此后中央权力衰微、藩镇割据。","explain":"材料出自《旧唐书·杨贵妃传》；《资治通鉴》卷二一八。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-1-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：主张按人口平均分配土地，「凡天下田，天下人同耕」，具有强烈的反封建色彩，但绝对平均主义无法实现。（《天朝田亩制度》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"太平天国运动；太平天国运动：金田起义（1851）—定都天京（1853）—《天朝田亩制度》—天京事变（1856，由盛转衰）—天京陷落（1864）；它沉重打击了清朝统治和外国侵略势力，但农民阶级不能领导中国革命取得胜利。","explain":"材料出自《天朝田亩制度》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-mock-6","title":"广州中考历史模拟卷（第 6 套）","subtitle":"整卷模拟 · 选择题 25 题 + 材料题 3 题","grade":"all","tags":["中考模拟","第 6 套","整卷"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"中考模拟"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"组卷说明","text":"按广州中考历史卷面结构组卷：选择题覆盖六册，材料题取自各册重点课时。建议计时完成后再看解析。"},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"cat-7a-1-2-g2","type":"choice","stem":"下列关于「原始农业与史前社会」的表述，错误的是","answer":"A","explain":"把河姆渡与半坡的农作物写反——记「南稻北粟」，与「南干栏北半地穴」一起记。正确表述：河姆渡→水稻（南方）；半坡→粟（北方）。","options":["把河姆渡与半坡的农作物写反。","河姆渡→水稻（南方）；半坡→粟（北方）。","生产力决定生活方式：种植水稻需要水田 → 长江流域的干栏式建筑；种植粟、气候干燥 → 黄河流域的半地穴式房屋。","原始农业的出现：河姆渡（长江流域，水稻、干栏式）与半坡（黄河流域，粟、半地穴式）的差异，说明**自然环境影响生产与生活方式**。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7b-1-1-g3","type":"choice","stem":"下列结论中，属于「隋朝统一与灭亡」的是","answer":"A","explain":"本课结论：科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","唐朝对外交往既有「走出去」（鉴真东渡、玄奘西行），也有「引进来」（遣唐使来华、吸收外来文化），共同体现了**对外开放与兼容并包**的胸襟。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-2-g2","type":"choice","stem":"下列关于「第二次鸦片战争」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q2","type":"choice","stem":"1951 年西藏和平解放的重要意义是","answer":"A","explain":"西藏和平解放使祖国大陆获得统一，各族人民实现了大团结。民族区域自治制度在 1954 年宪法中确立为一项基本政治制度；西藏自治区成立于 1965 年；台湾问题尚未解决，不能说「祖国获得完全统一」。","options":["祖国大陆获得统一，各族人民实现大团结","标志着祖国获得完全统一","标志着民族区域自治制度正式确立","西藏自治区正式成立"],"tags":["西藏和平解放","时空观念"]},{"id":"h9a-u1-q2","type":"choice","stem":"迄今已知世界上第一部较为完整的成文法典是","answer":"A","explain":"公元前 18 世纪，古巴比伦王国国王汉谟拉比为维护奴隶主阶级的利益制定了《汉谟拉比法典》，刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。","options":["《汉谟拉比法典》","《十二铜表法》","《罗马民法大全》","《拿破仑法典》"],"tags":["《汉谟拉比法典》","时空观念"]},{"id":"cat-9b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 俄国农奴制改革\n② 美国南北战争\n③ 德意志帝国成立（普法战争后）","answer":"A","explain":"按时间顺序应为：①俄国农奴制改革（1861 年）→②美国南北战争（1861—1865 年）→③德意志帝国成立（普法战争后）（1871 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-7a-1-2-g5","type":"choice","stem":"「河姆渡文化（长江流域）」发生于","answer":"A","explain":"本课时间轴：河姆渡文化（长江流域）（约 7000 年前）。种植水稻、干栏式建筑、木结构水井。其余三个时间是同一单元相邻课时的事件时间。","options":["约 7000 年前","约 170 万年前","约 70 万—20 万年前","约 3 万年前"],"difficulty":1,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"cat-8a-1-2-g5","type":"choice","stem":"「第二次鸦片战争」发生于","answer":"A","explain":"本课时间轴：第二次鸦片战争（1856 年 10 月—1860 年 10 月）。英法联军发动，是鸦片战争的继续和扩大；1858 年《天津条约》。其余三个时间是同一单元相邻课时的事件时间。","options":["1856 年 10 月—1860 年 10 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q4","type":"choice","stem":"1950—1952 年底土地改革完成后，我国农村土地的所有权状况是","answer":"D","explain":"土地改革废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，土地归农民私有。土地归集体所有是 1953—1956 年农业合作化的结果。","options":["归国家所有","归集体所有","归地主与农民共同所有","归农民所有"],"tags":["土地改革","历史解释"]},{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"cat-9b-1-2-g2","type":"choice","stem":"下列关于「俄国的改革」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"h7b-u1-q4","type":"choice","stem":"唐太宗说「舟所以比人君，水所以比黎庶，水能载舟，亦能覆舟」，这说明他","answer":"B","explain":"唐太宗从隋朝因暴政速亡的教训中认识到百姓的力量，因此减轻赋税徭役、推行有利于生产恢复的政策，这才有「贞观之治」。","options":["主张严刑峻法以驾驭臣下","注意吸取隋亡教训，爱惜民力","主张大力开疆拓土","主张抑制商业发展"],"tags":["贞观之治","家国情怀"]},{"id":"cat-8a-1-2-g6","type":"choice","stem":"下列考点中，属于「第二次鸦片战争」的是","answer":"A","explain":"本课考点（重点）：第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联军 1860 年所为。其余三项是同一单元相邻课时的考点。","options":["第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联…","鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战…","《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、…","鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q5","type":"choice","stem":"1949 年 9 月，中国人民政治协商会议第一届全体会议通过的、在 1954 年宪法颁布前起临时宪法作用的文件是","answer":"B","explain":"《共同纲领》是在 1954 年宪法颁布前起临时宪法作用的文件；1954 年宪法是我国第一部社会主义类型的宪法；《土地改革法》是 1950 年颁布的。","options":["《中华民国临时约法》","《中国人民政治协商会议共同纲领》","《中华人民共和国宪法》","《中华人民共和国土地改革法》"],"tags":["共同纲领","史料实证"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9b-1-2-g5","type":"choice","stem":"「俄国农奴制改革」发生于","answer":"A","explain":"本课时间轴：俄国农奴制改革（1861 年）。沙皇亚历山大二世签署废除农奴制的法令：农奴获得人身自由，可通过赎买获得份地——俄国历史上的重要转折点。其余三个时间是同一单元相邻课时的事件时间。","options":["1861 年","19 世纪初","1857—1859 年","1861—1865 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q3","type":"choice","stem":"良渚古城与陶寺古城的考古发现，最主要的价值在于","answer":"B","explain":"两处古城都出现城市、阶级分化与王权，是中华文明五千多年历史的实证，也说明中华文明本土起源、多元一体。","options":["证明中华文明是由西方传入的","为中华文明五千多年历史提供实证","说明我国最早的文字出现在长江流域","证明夏朝是我国第一个王朝"],"tags":["文明起源","家国情怀"]},{"id":"cat-7b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安\n② 唐太宗统治时期，出现「贞观之治」\n③ 玄奘西行天竺取经，后口述成《大唐西域记》\n④ 唐太宗把文成公主嫁给吐蕃赞普松赞干布","answer":"A","explain":"按时间顺序应为：①隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）→②唐太宗统治时期，出现「贞观之治」（627—649 年）→③玄奘西行天竺取经，后口述成《大唐西域记》（唐太宗时）→④唐太宗把文成公主嫁给吐蕃赞普松赞干布（641 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h8a-u1-q4","type":"choice","stem":"太平天国运动中，标志其由盛转衰的事件是","answer":"C","explain":"1856 年的天京事变是太平天国领导集团内讧，使其由盛转衰；1864 年天京陷落标志运动失败。","options":["金田起义","定都天京","天京事变","天京陷落"],"tags":["太平天国运动","时空观念"]},{"id":"h8b-u1-q6","type":"choice","stem":"抗美援朝战争的胜利对中国最主要的影响是","answer":"D","explain":"抗美援朝战争的胜利打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。中国进入社会主义社会以 1956 年三大改造基本完成为标志，结束半殖民地半封建社会历史以新中国成立为标志。","options":["使中国完成了国家统一","使中国从此进入社会主义社会","结束了半殖民地半封建社会的历史","打破了美军不可战胜的神话，大大提高了我国的国际地位"],"tags":["抗美援朝","历史解释"]},{"id":"cat-9a-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 两河流域实现初步统一\n③ 汉谟拉比统一两河流域中下游，定都巴比伦","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②两河流域实现初步统一（约公元前 24 世纪）→③汉谟拉比统一两河流域中下游，定都巴比伦（公元前 18 世纪）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q3","type":"choice","stem":"美国南北战争爆发前，南北方矛盾斗争的焦点是","answer":"B","explain":"南北两种经济制度（北方资本主义工商业与南方种植园奴隶制经济）的矛盾日益尖锐，焦点是奴隶制的存废问题；林肯当选总统成为战争爆发的导火线。","options":["关税税率的高低","奴隶制的存废问题","西部领土的扩张方向","总统选举的方式"],"tags":["美国内战","历史解释"]},{"id":"h7a-u1-q4","type":"choice","stem":"「禅让」制下，部落联盟首领产生的方式是","answer":"B","explain":"尧舜禹时期通过推举贤能者继位，称为禅让。父死子继的世袭制自夏启开始。","options":["父死子继","推举贤能者","以战功决定","由占卜决定"],"tags":["禅让制","历史解释"]},{"id":"h7a-u2-m1-q1","type":"short","stem":"（1）材料一反映的是西周的什么制度？受封者对周王承担哪些义务？（4 分）","answer":"分封制。义务：服从周王的调遣，向周王进献贡赋，平时镇守疆土、战时随从周王作战（「述职」「朝觐」）。","explain":"","tags":["分封制","历史解释"],"rubric":["答出分封制","答出服从调遣/随从作战","答出缴纳贡赋"]},{"id":"cat-7b-1-5-g4","type":"short","stem":"阅读材料，回答问题。\n材料：641 年，唐太宗派文成公主入吐蕃，带去大量书籍、种子、工匠和技术，促进吐蕃经济文化发展。（《旧唐书·吐蕃传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"隋唐时期的民族交往与交融；唐朝的民族交往：641 年文成公主入藏与松赞干布和亲，唐中宗时金城公主入藏；唐蕃订立盟约、互通使节；唐朝还册封回纥、南诏等少数民族首领。","explain":"材料出自《旧唐书·吐蕃传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h8a-u2-m1-q1","type":"short","stem":"（1）材料一反映了洋务派的什么主张？依据材料一、二说明这一主张在甲午战后为什么被国人普遍质疑。（6 分）","answer":"主张：认为中国的政治制度和文教制度远胜西方，只是在武器技术上不如人，因此主张「师夷长技」，只学习西方先进技术而不改变封建制度。被质疑的原因：甲午中日战争中国战败、北洋舰队全军覆没，说明单靠引进洋枪洋炮、创办近代军事工业，并不能挽救民族危亡；而材料二梁启超主张「变者天下之公理也」，认为必须变革制度。可见洋务运动「只学技术、不改制度」的道路走不通，必须进行制度变革。","explain":"","tags":["洋务运动","历史解释"],"rubric":["答出「只学技术」的主张","答出甲午战败、北洋舰队覆没","答出洋务运动破产","答出必须变革制度"]}]},{"id":"hp-mock-7","title":"广州中考历史模拟卷（第 7 套）","subtitle":"整卷模拟 · 选择题 25 题 + 材料题 3 题","grade":"all","tags":["中考模拟","第 7 套","整卷"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"中考模拟"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"组卷说明","text":"按广州中考历史卷面结构组卷：选择题覆盖六册，材料题取自各册重点课时。建议计时完成后再看解析。"},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"cat-7a-1-2-g5","type":"choice","stem":"「河姆渡文化（长江流域）」发生于","answer":"A","explain":"本课时间轴：河姆渡文化（长江流域）（约 7000 年前）。种植水稻、干栏式建筑、木结构水井。其余三个时间是同一单元相邻课时的事件时间。","options":["约 7000 年前","约 170 万年前","约 70 万—20 万年前","约 3 万年前"],"difficulty":1,"tags":["七年级上册","第一单元","本课练习"]},{"id":"h7b-u1-q2","type":"choice","stem":"科举制正式确立的标志是","answer":"B","explain":"隋文帝时只是开始用分科考试选拔官员；隋炀帝时进士科的创立，标志科举制正式确立。唐太宗、武则天、唐玄宗都是在隋朝创立的基础上加以完善。","options":["隋文帝开始用分科考试的办法选拔官员","隋炀帝设置进士科","唐太宗增加科举考试的科目","武则天创立殿试和武举"],"tags":["科举制","制度创新"]},{"id":"cat-8a-1-2-g5","type":"choice","stem":"「第二次鸦片战争」发生于","answer":"A","explain":"本课时间轴：第二次鸦片战争（1856 年 10 月—1860 年 10 月）。英法联军发动，是鸦片战争的继续和扩大；1858 年《天津条约》。其余三个时间是同一单元相邻课时的事件时间。","options":["1856 年 10 月—1860 年 10 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q4","type":"choice","stem":"1950—1952 年底土地改革完成后，我国农村土地的所有权状况是","answer":"D","explain":"土地改革废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，土地归农民私有。土地归集体所有是 1953—1956 年农业合作化的结果。","options":["归国家所有","归集体所有","归地主与农民共同所有","归农民所有"],"tags":["土地改革","历史解释"]},{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"cat-9b-1-2-g2","type":"choice","stem":"下列关于「俄国的改革」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"h7b-u1-q4","type":"choice","stem":"唐太宗说「舟所以比人君，水所以比黎庶，水能载舟，亦能覆舟」，这说明他","answer":"B","explain":"唐太宗从隋朝因暴政速亡的教训中认识到百姓的力量，因此减轻赋税徭役、推行有利于生产恢复的政策，这才有「贞观之治」。","options":["主张严刑峻法以驾驭臣下","注意吸取隋亡教训，爱惜民力","主张大力开疆拓土","主张抑制商业发展"],"tags":["贞观之治","家国情怀"]},{"id":"cat-8a-1-2-g6","type":"choice","stem":"下列考点中，属于「第二次鸦片战争」的是","answer":"A","explain":"本课考点（重点）：第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联军 1860 年所为。其余三项是同一单元相邻课时的考点。","options":["第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联…","鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战…","《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、…","鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q5","type":"choice","stem":"1949 年 9 月，中国人民政治协商会议第一届全体会议通过的、在 1954 年宪法颁布前起临时宪法作用的文件是","answer":"B","explain":"《共同纲领》是在 1954 年宪法颁布前起临时宪法作用的文件；1954 年宪法是我国第一部社会主义类型的宪法；《土地改革法》是 1950 年颁布的。","options":["《中华民国临时约法》","《中国人民政治协商会议共同纲领》","《中华人民共和国宪法》","《中华人民共和国土地改革法》"],"tags":["共同纲领","史料实证"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9b-1-2-g5","type":"choice","stem":"「俄国农奴制改革」发生于","answer":"A","explain":"本课时间轴：俄国农奴制改革（1861 年）。沙皇亚历山大二世签署废除农奴制的法令：农奴获得人身自由，可通过赎买获得份地——俄国历史上的重要转折点。其余三个时间是同一单元相邻课时的事件时间。","options":["1861 年","19 世纪初","1857—1859 年","1861—1865 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q3","type":"choice","stem":"良渚古城与陶寺古城的考古发现，最主要的价值在于","answer":"B","explain":"两处古城都出现城市、阶级分化与王权，是中华文明五千多年历史的实证，也说明中华文明本土起源、多元一体。","options":["证明中华文明是由西方传入的","为中华文明五千多年历史提供实证","说明我国最早的文字出现在长江流域","证明夏朝是我国第一个王朝"],"tags":["文明起源","家国情怀"]},{"id":"cat-7b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安\n② 唐太宗统治时期，出现「贞观之治」\n③ 玄奘西行天竺取经，后口述成《大唐西域记》\n④ 唐太宗把文成公主嫁给吐蕃赞普松赞干布","answer":"A","explain":"按时间顺序应为：①隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）→②唐太宗统治时期，出现「贞观之治」（627—649 年）→③玄奘西行天竺取经，后口述成《大唐西域记》（唐太宗时）→④唐太宗把文成公主嫁给吐蕃赞普松赞干布（641 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h8a-u1-q4","type":"choice","stem":"太平天国运动中，标志其由盛转衰的事件是","answer":"C","explain":"1856 年的天京事变是太平天国领导集团内讧，使其由盛转衰；1864 年天京陷落标志运动失败。","options":["金田起义","定都天京","天京事变","天京陷落"],"tags":["太平天国运动","时空观念"]},{"id":"h8b-u1-q6","type":"choice","stem":"抗美援朝战争的胜利对中国最主要的影响是","answer":"D","explain":"抗美援朝战争的胜利打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。中国进入社会主义社会以 1956 年三大改造基本完成为标志，结束半殖民地半封建社会历史以新中国成立为标志。","options":["使中国完成了国家统一","使中国从此进入社会主义社会","结束了半殖民地半封建社会的历史","打破了美军不可战胜的神话，大大提高了我国的国际地位"],"tags":["抗美援朝","历史解释"]},{"id":"cat-9a-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 两河流域实现初步统一\n③ 汉谟拉比统一两河流域中下游，定都巴比伦","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②两河流域实现初步统一（约公元前 24 世纪）→③汉谟拉比统一两河流域中下游，定都巴比伦（公元前 18 世纪）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q3","type":"choice","stem":"美国南北战争爆发前，南北方矛盾斗争的焦点是","answer":"B","explain":"南北两种经济制度（北方资本主义工商业与南方种植园奴隶制经济）的矛盾日益尖锐，焦点是奴隶制的存废问题；林肯当选总统成为战争爆发的导火线。","options":["关税税率的高低","奴隶制的存废问题","西部领土的扩张方向","总统选举的方式"],"tags":["美国内战","历史解释"]},{"id":"h7a-u1-q4","type":"choice","stem":"「禅让」制下，部落联盟首领产生的方式是","answer":"B","explain":"尧舜禹时期通过推举贤能者继位，称为禅让。父死子继的世袭制自夏启开始。","options":["父死子继","推举贤能者","以战功决定","由占卜决定"],"tags":["禅让制","历史解释"]},{"id":"cat-7b-1-2-g2","type":"choice","stem":"下列关于「唐朝建立与“贞观之治”」的表述，错误的是","answer":"A","explain":"把科举制的创立说成唐朝，或认为进士科是唐太宗设立的——「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。正确表述：科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","options":["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-3-g2","type":"choice","stem":"下列关于「太平天国运动」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中央人民政府颁布《中华人民共和国土地改革法》，土…\n② 中国人民志愿军开赴朝鲜，抗美援朝战争开始\n③ 西藏和平解放\n④ 全国大陆基本上完成土地改革","answer":"A","explain":"按时间顺序应为：①中央人民政府颁布《中华人民共和国土地改革法》，土地改革在全国展开（1950 年 6 月）→②中国人民志愿军开赴朝鲜，抗美援朝战争开始（1950 年 10 月）→③西藏和平解放（1951 年）→④全国大陆基本上完成土地改革（1952 年底）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g2","type":"choice","stem":"下列关于「古代两河流域」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》说成「世界上第一部成文法典」——限定语是得分点：少了「已知」「较为完整」，就不符合史实——苏美尔人早有成文法，只是不如它完整地保存下来。正确表述：它是「迄今**已知**世界上第一部较为完整的成文法典」。","options":["把《汉谟拉比法典》说成「世界上第一部成文法典」。","它是「迄今**已知**世界上第一部较为完整的成文法典」。","古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","《汉谟拉比法典》刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q4","type":"choice","stem":"使美国南北战争的战局发生扭转、为北方军队提供雄厚兵源的文件是","answer":"B","explain":"1862 年林肯颁布《宅地法》和《解放黑人奴隶宣言》，宣言宣布叛乱各州奴隶永远获得自由，黑人踊跃参军，扭转了战局。《独立宣言》《1787 年宪法》均为美国独立战争时期的文件。","options":["《独立宣言》","《解放黑人奴隶宣言》","《人权宣言》","1787 年美国宪法"],"tags":["美国内战","史料实证"]},{"id":"cat-7a-1-3-g2","type":"choice","stem":"下列关于「中华文明的起源」的表述，错误的是","answer":"A","explain":"把尧舜禹的「禅让」说成世袭——「公天下」到「家天下」的转折点是夏朝建立，不是尧舜时期。正确表述：禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","options":["把尧舜禹的「禅让」说成世袭。","禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","考古发现是研究史前历史的**唯一可靠依据**；传说（炎黄、尧舜禹）需要考古材料印证，不能当作信史。","良渚、陶寺古城的意义：证明中国在距今约 5000 多年已出现早期国家与文明。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7a-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：河南偃师二里头遗址发现宫殿基址、青铜爵、绿松石龙形器，学界多认为其与夏朝晚期都城有关，是探索夏文化的重要遗址。（中国社会科学院考古研究所《二里头》发掘报告）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"夏商西周王朝的更替；夏朝是我国历史上第一个王朝，世袭制代替禅让制，「公天下」变为「家天下」。","explain":"材料出自中国社会科学院考古研究所《二里头》发掘报告。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-1-6-g4","type":"short","stem":"阅读材料，回答问题。\n材料：鉴真应日本僧人邀请东渡，前五次或遇风浪、或遭阻拦而失败，双目失明后仍坚持，753 年第六次成功抵达日本，主持修建唐招提寺。（真人元开《唐大和上东征传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"隋唐时期的中外文化交流；唐朝的中外文化交流：日本先后派遣十几批遣唐使来华，鉴真六次东渡、在日本主持修建唐招提寺，玄奘西行天竺取经并写成《大唐西域记》，新罗也学习唐朝制度与文化。","explain":"材料出自真人元开《唐大和上东征传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：军事工业有安庆内军械所、江南机器制造总局、福州船政局；民用工业有轮船招商局、开平煤矿、汉阳铁厂、湖北织布局。（2024 部编版八上第 4 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"洋务运动和边疆危机；洋务运动：以「自强」「求富」为口号，创办安庆内军械所、江南机器制造总局、福州船政局等军事工业和轮船招商局、开平煤矿、汉阳铁厂、湖北织布局等民用企业，筹建北洋舰队等新式海陆军。","explain":"材料出自2024 部编版八上第 4 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hp-mock-8","title":"广州中考历史模拟卷（第 8 套）","subtitle":"整卷模拟 · 选择题 25 题 + 材料题 3 题","grade":"all","tags":["中考模拟","第 8 套","整卷"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"中考模拟"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"组卷说明","text":"按广州中考历史卷面结构组卷：选择题覆盖六册，材料题取自各册重点课时。建议计时完成后再看解析。"},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u1-q2","type":"choice","stem":"考古发现，某遗址出土了炭化稻粒、干栏式建筑遗迹和木结构水井。该遗址最有可能是","answer":"B","explain":"稻粒 + 干栏式建筑 + 水井是河姆渡文化的典型特征，位于长江流域。半坡以粟和半地穴式房屋为特征。","options":["半坡遗址","河姆渡遗址","周口店遗址","陶寺遗址"],"tags":["原始农业","史料实证"]},{"id":"h7b-u1-q4","type":"choice","stem":"唐太宗说「舟所以比人君，水所以比黎庶，水能载舟，亦能覆舟」，这说明他","answer":"B","explain":"唐太宗从隋朝因暴政速亡的教训中认识到百姓的力量，因此减轻赋税徭役、推行有利于生产恢复的政策，这才有「贞观之治」。","options":["主张严刑峻法以驾驭臣下","注意吸取隋亡教训，爱惜民力","主张大力开疆拓土","主张抑制商业发展"],"tags":["贞观之治","家国情怀"]},{"id":"cat-8a-1-2-g6","type":"choice","stem":"下列考点中，属于「第二次鸦片战争」的是","answer":"A","explain":"本课考点（重点）：第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联军 1860 年所为。其余三项是同一单元相邻课时的考点。","options":["第二次鸦片战争的实质是鸦片战争的继续和扩大，根本目的仍是打开中国市场；火烧圆明园是英法联…","鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战…","《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、…","鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u1-q5","type":"choice","stem":"1949 年 9 月，中国人民政治协商会议第一届全体会议通过的、在 1954 年宪法颁布前起临时宪法作用的文件是","answer":"B","explain":"《共同纲领》是在 1954 年宪法颁布前起临时宪法作用的文件；1954 年宪法是我国第一部社会主义类型的宪法；《土地改革法》是 1950 年颁布的。","options":["《中华民国临时约法》","《中国人民政治协商会议共同纲领》","《中华人民共和国宪法》","《中华人民共和国土地改革法》"],"tags":["共同纲领","史料实证"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9b-1-2-g5","type":"choice","stem":"「俄国农奴制改革」发生于","answer":"A","explain":"本课时间轴：俄国农奴制改革（1861 年）。沙皇亚历山大二世签署废除农奴制的法令：农奴获得人身自由，可通过赎买获得份地——俄国历史上的重要转折点。其余三个时间是同一单元相邻课时的事件时间。","options":["1861 年","19 世纪初","1857—1859 年","1861—1865 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u1-q3","type":"choice","stem":"良渚古城与陶寺古城的考古发现，最主要的价值在于","answer":"B","explain":"两处古城都出现城市、阶级分化与王权，是中华文明五千多年历史的实证，也说明中华文明本土起源、多元一体。","options":["证明中华文明是由西方传入的","为中华文明五千多年历史提供实证","说明我国最早的文字出现在长江流域","证明夏朝是我国第一个王朝"],"tags":["文明起源","家国情怀"]},{"id":"cat-7b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安\n② 唐太宗统治时期，出现「贞观之治」\n③ 玄奘西行天竺取经，后口述成《大唐西域记》\n④ 唐太宗把文成公主嫁给吐蕃赞普松赞干布","answer":"A","explain":"按时间顺序应为：①隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）→②唐太宗统治时期，出现「贞观之治」（627—649 年）→③玄奘西行天竺取经，后口述成《大唐西域记》（唐太宗时）→④唐太宗把文成公主嫁给吐蕃赞普松赞干布（641 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h8a-u1-q4","type":"choice","stem":"太平天国运动中，标志其由盛转衰的事件是","answer":"C","explain":"1856 年的天京事变是太平天国领导集团内讧，使其由盛转衰；1864 年天京陷落标志运动失败。","options":["金田起义","定都天京","天京事变","天京陷落"],"tags":["太平天国运动","时空观念"]},{"id":"h8b-u1-q6","type":"choice","stem":"抗美援朝战争的胜利对中国最主要的影响是","answer":"D","explain":"抗美援朝战争的胜利打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。中国进入社会主义社会以 1956 年三大改造基本完成为标志，结束半殖民地半封建社会历史以新中国成立为标志。","options":["使中国完成了国家统一","使中国从此进入社会主义社会","结束了半殖民地半封建社会的历史","打破了美军不可战胜的神话，大大提高了我国的国际地位"],"tags":["抗美援朝","历史解释"]},{"id":"cat-9a-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 两河流域实现初步统一\n③ 汉谟拉比统一两河流域中下游，定都巴比伦","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②两河流域实现初步统一（约公元前 24 世纪）→③汉谟拉比统一两河流域中下游，定都巴比伦（公元前 18 世纪）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q3","type":"choice","stem":"美国南北战争爆发前，南北方矛盾斗争的焦点是","answer":"B","explain":"南北两种经济制度（北方资本主义工商业与南方种植园奴隶制经济）的矛盾日益尖锐，焦点是奴隶制的存废问题；林肯当选总统成为战争爆发的导火线。","options":["关税税率的高低","奴隶制的存废问题","西部领土的扩张方向","总统选举的方式"],"tags":["美国内战","历史解释"]},{"id":"h7a-u1-q4","type":"choice","stem":"「禅让」制下，部落联盟首领产生的方式是","answer":"B","explain":"尧舜禹时期通过推举贤能者继位，称为禅让。父死子继的世袭制自夏启开始。","options":["父死子继","推举贤能者","以战功决定","由占卜决定"],"tags":["禅让制","历史解释"]},{"id":"cat-7b-1-2-g2","type":"choice","stem":"下列关于「唐朝建立与“贞观之治”」的表述，错误的是","answer":"A","explain":"把科举制的创立说成唐朝，或认为进士科是唐太宗设立的——「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。正确表述：科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","options":["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-3-g2","type":"choice","stem":"下列关于「太平天国运动」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中央人民政府颁布《中华人民共和国土地改革法》，土…\n② 中国人民志愿军开赴朝鲜，抗美援朝战争开始\n③ 西藏和平解放\n④ 全国大陆基本上完成土地改革","answer":"A","explain":"按时间顺序应为：①中央人民政府颁布《中华人民共和国土地改革法》，土地改革在全国展开（1950 年 6 月）→②中国人民志愿军开赴朝鲜，抗美援朝战争开始（1950 年 10 月）→③西藏和平解放（1951 年）→④全国大陆基本上完成土地改革（1952 年底）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g2","type":"choice","stem":"下列关于「古代两河流域」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》说成「世界上第一部成文法典」——限定语是得分点：少了「已知」「较为完整」，就不符合史实——苏美尔人早有成文法，只是不如它完整地保存下来。正确表述：它是「迄今**已知**世界上第一部较为完整的成文法典」。","options":["把《汉谟拉比法典》说成「世界上第一部成文法典」。","它是「迄今**已知**世界上第一部较为完整的成文法典」。","古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","《汉谟拉比法典》刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q4","type":"choice","stem":"使美国南北战争的战局发生扭转、为北方军队提供雄厚兵源的文件是","answer":"B","explain":"1862 年林肯颁布《宅地法》和《解放黑人奴隶宣言》，宣言宣布叛乱各州奴隶永远获得自由，黑人踊跃参军，扭转了战局。《独立宣言》《1787 年宪法》均为美国独立战争时期的文件。","options":["《独立宣言》","《解放黑人奴隶宣言》","《人权宣言》","1787 年美国宪法"],"tags":["美国内战","史料实证"]},{"id":"cat-7a-1-3-g2","type":"choice","stem":"下列关于「中华文明的起源」的表述，错误的是","answer":"A","explain":"把尧舜禹的「禅让」说成世袭——「公天下」到「家天下」的转折点是夏朝建立，不是尧舜时期。正确表述：禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","options":["把尧舜禹的「禅让」说成世袭。","禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","考古发现是研究史前历史的**唯一可靠依据**；传说（炎黄、尧舜禹）需要考古材料印证，不能当作信史。","良渚、陶寺古城的意义：证明中国在距今约 5000 多年已出现早期国家与文明。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7b-1-2-g3","type":"choice","stem":"下列结论中，属于「唐朝建立与“贞观之治”」的是","answer":"A","explain":"本课结论：隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-3-g5","type":"choice","stem":"「洪秀全在广西桂平金田村起义，建号太平天国」发生于","answer":"A","explain":"本课时间轴：洪秀全在广西桂平金田村起义，建号太平天国（1851 年 1 月）。1853 年攻占南京改名天京并定都，与清朝对峙。其余三个时间是同一单元相邻课时的事件时间。","options":["1851 年 1 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-2-g2","type":"choice","stem":"下列关于「巩固人民民主政权」的表述，错误的是","answer":"A","explain":"把抗美援朝战争开始的时间记成 1953 年——1950 年是「出兵」，1953 年是「停战」，两个时间点最容易被调换。正确表述：1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","options":["把抗美援朝战争开始的时间记成 1953 年。","1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。","土地改革彻底摧毁了在我国延续两千多年的封建土地制度，消灭了地主阶级，农民成为土地的主人，解放了农村生产力，为国家工业化建设准备了条件。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g3","type":"choice","stem":"下列结论中，属于「古代两河流域」的是","answer":"A","explain":"本课结论：古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明**大河流域是早期文明的共同摇篮**。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。","佛教于公元前 1 世纪（西汉末年）经中亚传入中国，说明**古代亚非文明之间的交流早于新航路开辟**，文明从来不是彼此隔绝的。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9b-1-3-g2","type":"choice","stem":"下列关于「美国内战」的表述，错误的是","answer":"A","explain":"认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制——「根本原因」与「导火线」的区分是必考得分点，答题时要先答经济制度矛盾，再答导火线。正确表述：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","options":["认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制。","根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","林肯的贡献在于**维护了国家统一、废除了奴隶制**，为美国经济的迅速发展创造了条件；评价历史人物要看其是否推动社会进步、是否符合人民利益。","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废；林肯颁布《宅地法》和《解放黑人奴隶宣言》，1865 年北方取胜。意义：维护了国家统一，废除了奴隶制，为经济迅速发展创造了条件。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u2-q1","type":"choice","stem":"「大道之行也，天下为公，选贤与能……今大道既隐，天下为家。」「天下为家」开始于","answer":"B","explain":"启继承禹的王位，世袭制代替禅让制，「公天下」变为「家天下」。","options":["禹建立夏朝","启继承王位","汤灭夏建商","武王伐纣"],"tags":["世袭制","历史解释"]},{"id":"cat-7a-2-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：管仲在齐国推行「相地而衰征」，按土地好坏分等征税；又设「轻重」之法调节物价，发展渔盐之利，使齐国国力大增。（《国语·齐语》；《史记·管晏列传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"动荡变化中的春秋时期；百家争鸣：孔子（仁、为政以德、有教无类）、老子（无为、辩证法）、墨子（兼爱非攻）、孟子（仁政）、韩非（以法治国、中央集权）。","explain":"材料出自《国语·齐语》；《史记·管晏列传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-1-7-g4","type":"short","stem":"阅读材料，回答问题。\n材料：莫高窟位于甘肃敦煌，现存洞窟 735 个，壁画 4.5 万平方米，彩塑 2400 余身，是世界上现存规模最大的佛教艺术宝库。（敦煌研究院《敦煌莫高窟》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"隋唐时期的科技与文化；隋唐科技文化：李春设计建造的赵州桥、隋唐时期的雕版印刷术、唐朝发明的火药；唐诗的黄金时代（李白、杜甫、白居易）。","explain":"材料出自敦煌研究院《敦煌莫高窟》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h8a-u2-m1-q1","type":"short","stem":"（1）材料一反映了洋务派的什么主张？依据材料一、二说明这一主张在甲午战后为什么被国人普遍质疑。（6 分）","answer":"主张：认为中国的政治制度和文教制度远胜西方，只是在武器技术上不如人，因此主张「师夷长技」，只学习西方先进技术而不改变封建制度。被质疑的原因：甲午中日战争中国战败、北洋舰队全军覆没，说明单靠引进洋枪洋炮、创办近代军事工业，并不能挽救民族危亡；而材料二梁启超主张「变者天下之公理也」，认为必须变革制度。可见洋务运动「只学技术、不改制度」的道路走不通，必须进行制度变革。","explain":"","tags":["洋务运动","历史解释"],"rubric":["答出「只学技术」的主张","答出甲午战败、北洋舰队覆没","答出洋务运动破产","答出必须变革制度"]}]},{"id":"hp-mock-9","title":"广州中考历史模拟卷（第 9 套）","subtitle":"整卷模拟 · 选择题 25 题 + 材料题 3 题","grade":"all","tags":["中考模拟","第 9 套","整卷"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"中考模拟"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"组卷说明","text":"按广州中考历史卷面结构组卷：选择题覆盖六册，材料题取自各册重点课时。建议计时完成后再看解析。"},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u1-q3","type":"choice","stem":"良渚古城与陶寺古城的考古发现，最主要的价值在于","answer":"B","explain":"两处古城都出现城市、阶级分化与王权，是中华文明五千多年历史的实证，也说明中华文明本土起源、多元一体。","options":["证明中华文明是由西方传入的","为中华文明五千多年历史提供实证","说明我国最早的文字出现在长江流域","证明夏朝是我国第一个王朝"],"tags":["文明起源","家国情怀"]},{"id":"cat-7b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安\n② 唐太宗统治时期，出现「贞观之治」\n③ 玄奘西行天竺取经，后口述成《大唐西域记》\n④ 唐太宗把文成公主嫁给吐蕃赞普松赞干布","answer":"A","explain":"按时间顺序应为：①隋炀帝被杀，隋朝灭亡；李渊建立唐朝，定都长安（618 年）→②唐太宗统治时期，出现「贞观之治」（627—649 年）→③玄奘西行天竺取经，后口述成《大唐西域记》（唐太宗时）→④唐太宗把文成公主嫁给吐蕃赞普松赞干布（641 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h8a-u1-q4","type":"choice","stem":"太平天国运动中，标志其由盛转衰的事件是","answer":"C","explain":"1856 年的天京事变是太平天国领导集团内讧，使其由盛转衰；1864 年天京陷落标志运动失败。","options":["金田起义","定都天京","天京事变","天京陷落"],"tags":["太平天国运动","时空观念"]},{"id":"h8b-u1-q6","type":"choice","stem":"抗美援朝战争的胜利对中国最主要的影响是","answer":"D","explain":"抗美援朝战争的胜利打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。中国进入社会主义社会以 1956 年三大改造基本完成为标志，结束半殖民地半封建社会历史以新中国成立为标志。","options":["使中国完成了国家统一","使中国从此进入社会主义社会","结束了半殖民地半封建社会的历史","打破了美军不可战胜的神话，大大提高了我国的国际地位"],"tags":["抗美援朝","历史解释"]},{"id":"cat-9a-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 两河流域实现初步统一\n③ 汉谟拉比统一两河流域中下游，定都巴比伦","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②两河流域实现初步统一（约公元前 24 世纪）→③汉谟拉比统一两河流域中下游，定都巴比伦（公元前 18 世纪）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q3","type":"choice","stem":"美国南北战争爆发前，南北方矛盾斗争的焦点是","answer":"B","explain":"南北两种经济制度（北方资本主义工商业与南方种植园奴隶制经济）的矛盾日益尖锐，焦点是奴隶制的存废问题；林肯当选总统成为战争爆发的导火线。","options":["关税税率的高低","奴隶制的存废问题","西部领土的扩张方向","总统选举的方式"],"tags":["美国内战","历史解释"]},{"id":"h7a-u1-q4","type":"choice","stem":"「禅让」制下，部落联盟首领产生的方式是","answer":"B","explain":"尧舜禹时期通过推举贤能者继位，称为禅让。父死子继的世袭制自夏启开始。","options":["父死子继","推举贤能者","以战功决定","由占卜决定"],"tags":["禅让制","历史解释"]},{"id":"cat-7b-1-2-g2","type":"choice","stem":"下列关于「唐朝建立与“贞观之治”」的表述，错误的是","answer":"A","explain":"把科举制的创立说成唐朝，或认为进士科是唐太宗设立的——「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。正确表述：科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","options":["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-3-g2","type":"choice","stem":"下列关于「太平天国运动」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中央人民政府颁布《中华人民共和国土地改革法》，土…\n② 中国人民志愿军开赴朝鲜，抗美援朝战争开始\n③ 西藏和平解放\n④ 全国大陆基本上完成土地改革","answer":"A","explain":"按时间顺序应为：①中央人民政府颁布《中华人民共和国土地改革法》，土地改革在全国展开（1950 年 6 月）→②中国人民志愿军开赴朝鲜，抗美援朝战争开始（1950 年 10 月）→③西藏和平解放（1951 年）→④全国大陆基本上完成土地改革（1952 年底）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g2","type":"choice","stem":"下列关于「古代两河流域」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》说成「世界上第一部成文法典」——限定语是得分点：少了「已知」「较为完整」，就不符合史实——苏美尔人早有成文法，只是不如它完整地保存下来。正确表述：它是「迄今**已知**世界上第一部较为完整的成文法典」。","options":["把《汉谟拉比法典》说成「世界上第一部成文法典」。","它是「迄今**已知**世界上第一部较为完整的成文法典」。","古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","《汉谟拉比法典》刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q4","type":"choice","stem":"使美国南北战争的战局发生扭转、为北方军队提供雄厚兵源的文件是","answer":"B","explain":"1862 年林肯颁布《宅地法》和《解放黑人奴隶宣言》，宣言宣布叛乱各州奴隶永远获得自由，黑人踊跃参军，扭转了战局。《独立宣言》《1787 年宪法》均为美国独立战争时期的文件。","options":["《独立宣言》","《解放黑人奴隶宣言》","《人权宣言》","1787 年美国宪法"],"tags":["美国内战","史料实证"]},{"id":"cat-7a-1-3-g2","type":"choice","stem":"下列关于「中华文明的起源」的表述，错误的是","answer":"A","explain":"把尧舜禹的「禅让」说成世袭——「公天下」到「家天下」的转折点是夏朝建立，不是尧舜时期。正确表述：禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","options":["把尧舜禹的「禅让」说成世袭。","禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","考古发现是研究史前历史的**唯一可靠依据**；传说（炎黄、尧舜禹）需要考古材料印证，不能当作信史。","良渚、陶寺古城的意义：证明中国在距今约 5000 多年已出现早期国家与文明。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7b-1-2-g3","type":"choice","stem":"下列结论中，属于「唐朝建立与“贞观之治”」的是","answer":"A","explain":"本课结论：隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-3-g5","type":"choice","stem":"「洪秀全在广西桂平金田村起义，建号太平天国」发生于","answer":"A","explain":"本课时间轴：洪秀全在广西桂平金田村起义，建号太平天国（1851 年 1 月）。1853 年攻占南京改名天京并定都，与清朝对峙。其余三个时间是同一单元相邻课时的事件时间。","options":["1851 年 1 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-2-g2","type":"choice","stem":"下列关于「巩固人民民主政权」的表述，错误的是","answer":"A","explain":"把抗美援朝战争开始的时间记成 1953 年——1950 年是「出兵」，1953 年是「停战」，两个时间点最容易被调换。正确表述：1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","options":["把抗美援朝战争开始的时间记成 1953 年。","1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。","土地改革彻底摧毁了在我国延续两千多年的封建土地制度，消灭了地主阶级，农民成为土地的主人，解放了农村生产力，为国家工业化建设准备了条件。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g3","type":"choice","stem":"下列结论中，属于「古代两河流域」的是","answer":"A","explain":"本课结论：古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明**大河流域是早期文明的共同摇篮**。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。","佛教于公元前 1 世纪（西汉末年）经中亚传入中国，说明**古代亚非文明之间的交流早于新航路开辟**，文明从来不是彼此隔绝的。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9b-1-3-g2","type":"choice","stem":"下列关于「美国内战」的表述，错误的是","answer":"A","explain":"认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制——「根本原因」与「导火线」的区分是必考得分点，答题时要先答经济制度矛盾，再答导火线。正确表述：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","options":["认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制。","根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","林肯的贡献在于**维护了国家统一、废除了奴隶制**，为美国经济的迅速发展创造了条件；评价历史人物要看其是否推动社会进步、是否符合人民利益。","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废；林肯颁布《宅地法》和《解放黑人奴隶宣言》，1865 年北方取胜。意义：维护了国家统一，废除了奴隶制，为经济迅速发展创造了条件。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u2-q1","type":"choice","stem":"「大道之行也，天下为公，选贤与能……今大道既隐，天下为家。」「天下为家」开始于","answer":"B","explain":"启继承禹的王位，世袭制代替禅让制，「公天下」变为「家天下」。","options":["禹建立夏朝","启继承王位","汤灭夏建商","武王伐纣"],"tags":["世袭制","历史解释"]},{"id":"h7b-u1-q1","type":"choice","stem":"605 年起下令开凿大运河，以洛阳为中心、北抵涿郡、南至余杭的皇帝是","answer":"B","explain":"大运河由隋炀帝下令开凿（605 年起），以洛阳为中心，北抵涿郡，南至余杭，是古代世界上最长的运河。隋文帝的功绩是统一全国、创立三省六部制与分科考试选官。","options":["隋文帝","隋炀帝","唐高祖","唐玄宗"],"tags":["大运河","时空观念"]},{"id":"cat-8a-1-3-g6","type":"choice","stem":"下列考点中，属于「太平天国运动」的是","answer":"A","explain":"本课考点（重点）：太平天国运动：金田起义（1851）—定都天京（1853）—《天朝田亩制度》—天京事变（1856，由盛转衰）—天京陷落（1864）；它沉重打击了清朝统治和外国侵略势力，但农民阶级不能领导中国革命取得胜利。其余三项是同一单元相邻课时的考点。","options":["太平天国运动：金田起义（1851）—定都天京（1853）—《天朝田亩制度》—天京事变（1…","鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战…","《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、…","鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u2-q2","type":"choice","stem":"1954 年《中华人民共和国宪法》的历史地位是","answer":"D","explain":"1954 年宪法是我国第一部社会主义类型的宪法，也是我国有史以来真正反映人民利益的宪法；起临时宪法作用的文件是 1949 年的《共同纲领》。","options":["我国第一部宪法性质的临时文件","我国第一部资产阶级民主主义宪法","我国第一部民族区域自治法","我国第一部社会主义类型的宪法"],"tags":["1954 年宪法","历史解释"]},{"id":"h9a-u1-q3","type":"choice","stem":"古印度种姓制度中，掌管祭祀、被视为最高等级的是","answer":"A","explain":"种姓制度第一等级是婆罗门，掌管祭祀；第二等级是刹帝利，掌管军政大权；第三等级是吠舍，从事农业、畜牧业和商业；第四等级是首陀罗。","options":["婆罗门","刹帝利","吠舍","首陀罗"],"tags":["种姓制度","历史解释"]},{"id":"cat-9b-1-3-g5","type":"choice","stem":"「美国南北战争」发生于","answer":"A","explain":"本课时间轴：美国南北战争（1861—1865 年）。根本原因是南北两种经济制度的矛盾（焦点是奴隶制的存废）；1861 年南方军队挑起内战，1865 年北方获胜。其余三个时间是同一单元相邻课时的事件时间。","options":["1861—1865 年","19 世纪初","1857—1859 年","1861 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u2-q2","type":"choice","stem":"「封建亲戚，以藩屏周」反映的西周制度是","answer":"B","explain":"分封制把土地和人民分给宗亲、功臣，让他们建立诸侯国，起到拱卫王室的作用。","options":["禅让制","分封制","郡县制","世袭制"],"tags":["分封制","史料实证"]},{"id":"h7a-u2-m1-q2","type":"short","stem":"（2）依据材料二、三，概括商鞅变法的两项措施，并说明变法为什么能使秦国「倾邻国而雄诸侯」。（6 分）","answer":"措施：①奖励军功，按军功授予爵位；②奖励耕织，生产粮食布帛多者可免除徭役；③废除井田制、开垦荒地。作用：奖励耕织使国家粮食充足、经济实力增强；奖励军功使军队战斗力提高；废井田、开阡陌承认土地私有，调动了生产积极性。因此秦国国力大增，在兼并战争中占据优势。","explain":"","tags":["商鞅变法","历史解释"],"rubric":["措施：奖励军功","措施：奖励耕织/废井田","作用：经济实力增强","作用：军队战斗力提高","作用：为统一奠定基础"]},{"id":"cat-7b-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：北宋扩大科举取士，重用文臣掌兵权，地方设通判监督知州，设转运使收财权，形成「强干弱枝」格局。（《宋史·职官志》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"北宋的政治；北宋加强中央集权与「重文轻武」：宋太祖解除禁军将领兵权，分割宰相权力，派文臣担任地方长官并设通判加以牵制，同时大力发展科举、重用文臣。","explain":"材料出自《宋史·职官志》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"h8a-u2-m1-q2","type":"short","stem":"（2）依据材料三并结合所学，说明「允许日本在中国通商口岸开设工厂」这一条款反映了列强侵华方式的什么变化，并指出《马关条约》对中国的影响。（6 分）","answer":"变化：反映列强侵华由以商品输出为主转向以资本输出为主。此前列强主要通过倾销商品、掠夺原料牟利，此后纷纷在中国开设工厂、修筑铁路、开采矿山、开设银行，直接利用中国的原料和廉价劳动力。影响：《马关条约》使中国的领土和主权进一步遭到破坏，半殖民地化程度大大加深；列强掀起瓜分中国的狂潮，民族危机空前严重；同时也刺激了中国人民的救亡图存运动。","explain":"","tags":["马关条约","资本输出"],"rubric":["答出由商品输出为主转向资本输出为主","答出开设工厂/修路开矿等具体表现","答出半殖民地化程度大大加深","答出瓜分中国狂潮/民族危机加深"]}]},{"id":"hp-mock-10","title":"广州中考历史模拟卷（第 10 套）","subtitle":"整卷模拟 · 选择题 25 题 + 材料题 3 题","grade":"all","tags":["中考模拟","第 10 套","整卷"],"blocks":[{"type":"meta","items":[{"k":"卷型","v":"中考模拟"},{"k":"题量","v":"选择题 25 题 · 材料题 3 题"},{"k":"赋分","v":"选择题每题 2 分；材料题按小问赋分（广州卷非选择题共 40 分）"},{"k":"建议用时","v":"60 分钟"}]},{"type":"note","title":"组卷说明","text":"按广州中考历史卷面结构组卷：选择题覆盖六册，材料题取自各册重点课时。建议计时完成后再看解析。"},{"type":"note","title":"作答提示","text":"先做选择题（控制在 20 分钟内），再按「材料—设问—分值」顺序作答材料题；材料题分点作答、写清关键词。"}],"questions":[{"id":"h7a-u1-q4","type":"choice","stem":"「禅让」制下，部落联盟首领产生的方式是","answer":"B","explain":"尧舜禹时期通过推举贤能者继位，称为禅让。父死子继的世袭制自夏启开始。","options":["父死子继","推举贤能者","以战功决定","由占卜决定"],"tags":["禅让制","历史解释"]},{"id":"cat-7b-1-2-g2","type":"choice","stem":"下列关于「唐朝建立与“贞观之治”」的表述，错误的是","answer":"A","explain":"把科举制的创立说成唐朝，或认为进士科是唐太宗设立的——「创立于隋、完善于唐」是固定表述，答成「唐朝创立」直接失分。正确表述：科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","options":["把科举制的创立说成唐朝，或认为进士科是唐太宗设立的。","科举制创立于隋朝：隋文帝开始用分科考试选拔官员，隋炀帝设进士科标志科举制正式确立；唐朝只是使其进一步完善。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-3-g2","type":"choice","stem":"下列关于「太平天国运动」的表述，错误的是","answer":"A","explain":"把《南京条约》的「割香港岛」写成「割香港」——三块地方分三次被占，是最经典的时序陷阱，写「割香港」不得分。正确表述：1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","options":["把《南京条约》的「割香港岛」写成「割香港」。","1842 年《南京条约》割香港岛；1860 年《北京条约》割九龙司地方一区；1898 年英国又强租新界。","**落后就要挨打**：清朝政治腐败、经济军事落后、闭关自守，必然在近代化程度更高的资本主义英国面前挨打。这是本单元最核心的认识。","鸦片战争是中国近代史的开端：中国社会性质由封建社会**开始沦为半殖民地半封建社会**，主要矛盾变为外国资本主义与中华民族的矛盾、封建主义与人民大众的矛盾，革命任务变为反侵略、反封建。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 中央人民政府颁布《中华人民共和国土地改革法》，土…\n② 中国人民志愿军开赴朝鲜，抗美援朝战争开始\n③ 西藏和平解放\n④ 全国大陆基本上完成土地改革","answer":"A","explain":"按时间顺序应为：①中央人民政府颁布《中华人民共和国土地改革法》，土地改革在全国展开（1950 年 6 月）→②中国人民志愿军开赴朝鲜，抗美援朝战争开始（1950 年 10 月）→③西藏和平解放（1951 年）→④全国大陆基本上完成土地改革（1952 年底）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g2","type":"choice","stem":"下列关于「古代两河流域」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》说成「世界上第一部成文法典」——限定语是得分点：少了「已知」「较为完整」，就不符合史实——苏美尔人早有成文法，只是不如它完整地保存下来。正确表述：它是「迄今**已知**世界上第一部较为完整的成文法典」。","options":["把《汉谟拉比法典》说成「世界上第一部成文法典」。","它是「迄今**已知**世界上第一部较为完整的成文法典」。","古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","《汉谟拉比法典》刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"h9b-u1-q4","type":"choice","stem":"使美国南北战争的战局发生扭转、为北方军队提供雄厚兵源的文件是","answer":"B","explain":"1862 年林肯颁布《宅地法》和《解放黑人奴隶宣言》，宣言宣布叛乱各州奴隶永远获得自由，黑人踊跃参军，扭转了战局。《独立宣言》《1787 年宪法》均为美国独立战争时期的文件。","options":["《独立宣言》","《解放黑人奴隶宣言》","《人权宣言》","1787 年美国宪法"],"tags":["美国内战","史料实证"]},{"id":"cat-7a-1-3-g2","type":"choice","stem":"下列关于「中华文明的起源」的表述，错误的是","answer":"A","explain":"把尧舜禹的「禅让」说成世袭——「公天下」到「家天下」的转折点是夏朝建立，不是尧舜时期。正确表述：禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","options":["把尧舜禹的「禅让」说成世袭。","禅让是推举贤能者继位；世袭（父死子继）从夏启开始。","考古发现是研究史前历史的**唯一可靠依据**；传说（炎黄、尧舜禹）需要考古材料印证，不能当作信史。","良渚、陶寺古城的意义：证明中国在距今约 5000 多年已出现早期国家与文明。"],"difficulty":2,"tags":["七年级上册","第一单元","本课练习"]},{"id":"cat-7b-1-2-g3","type":"choice","stem":"下列结论中，属于「唐朝建立与“贞观之治”」的是","answer":"A","explain":"本课结论：隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。","对隋炀帝应一分为二：开凿大运河、创立进士科在客观上影响深远，但其残暴统治激化了社会矛盾，导致隋朝二世而亡。","安史之乱是唐朝由盛转衰的转折点：此后中央集权削弱、藩镇割据，最终演变为五代十国的分裂局面。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"cat-8a-1-3-g5","type":"choice","stem":"「洪秀全在广西桂平金田村起义，建号太平天国」发生于","answer":"A","explain":"本课时间轴：洪秀全在广西桂平金田村起义，建号太平天国（1851 年 1 月）。1853 年攻占南京改名天京并定都，与清朝对峙。其余三个时间是同一单元相邻课时的事件时间。","options":["1851 年 1 月","1839 年 6 月","1840 年 6 月—1842 年 8 月","1842 年 8 月"],"difficulty":1,"tags":["八年级上册","第一单元","本课练习"]},{"id":"cat-8b-1-2-g2","type":"choice","stem":"下列关于「巩固人民民主政权」的表述，错误的是","answer":"A","explain":"把抗美援朝战争开始的时间记成 1953 年——1950 年是「出兵」，1953 年是「停战」，两个时间点最容易被调换。正确表述：1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","options":["把抗美援朝战争开始的时间记成 1953 年。","1950 年 10 月中国人民志愿军开赴朝鲜，抗美援朝战争开始；1953 年 7 月美国被迫签订《朝鲜停战协定》，战争胜利结束。","抗美援朝战争的胜利，打破了美军不可战胜的神话，大大提高了我国的国际地位，为我国的经济建设赢得了一个相对稳定的和平环境。","土地改革彻底摧毁了在我国延续两千多年的封建土地制度，消灭了地主阶级，农民成为土地的主人，解放了农村生产力，为国家工业化建设准备了条件。"],"difficulty":2,"tags":["八年级下册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g3","type":"choice","stem":"下列结论中，属于「古代两河流域」的是","answer":"A","explain":"本课结论：古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是**维护统治阶级利益的工具**。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明**大河流域是早期文明的共同摇篮**。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。","佛教于公元前 1 世纪（西汉末年）经中亚传入中国，说明**古代亚非文明之间的交流早于新航路开辟**，文明从来不是彼此隔绝的。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9b-1-3-g2","type":"choice","stem":"下列关于「美国内战」的表述，错误的是","answer":"A","explain":"认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制——「根本原因」与「导火线」的区分是必考得分点，答题时要先答经济制度矛盾，再答导火线。正确表述：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","options":["认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制。","根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","林肯的贡献在于**维护了国家统一、废除了奴隶制**，为美国经济的迅速发展创造了条件；评价历史人物要看其是否推动社会进步、是否符合人民利益。","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废；林肯颁布《宅地法》和《解放黑人奴隶宣言》，1865 年北方取胜。意义：维护了国家统一，废除了奴隶制，为经济迅速发展创造了条件。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u2-q1","type":"choice","stem":"「大道之行也，天下为公，选贤与能……今大道既隐，天下为家。」「天下为家」开始于","answer":"B","explain":"启继承禹的王位，世袭制代替禅让制，「公天下」变为「家天下」。","options":["禹建立夏朝","启继承王位","汤灭夏建商","武王伐纣"],"tags":["世袭制","历史解释"]},{"id":"h7b-u1-q1","type":"choice","stem":"605 年起下令开凿大运河，以洛阳为中心、北抵涿郡、南至余杭的皇帝是","answer":"B","explain":"大运河由隋炀帝下令开凿（605 年起），以洛阳为中心，北抵涿郡，南至余杭，是古代世界上最长的运河。隋文帝的功绩是统一全国、创立三省六部制与分科考试选官。","options":["隋文帝","隋炀帝","唐高祖","唐玄宗"],"tags":["大运河","时空观念"]},{"id":"cat-8a-1-3-g6","type":"choice","stem":"下列考点中，属于「太平天国运动」的是","answer":"A","explain":"本课考点（重点）：太平天国运动：金田起义（1851）—定都天京（1853）—《天朝田亩制度》—天京事变（1856，由盛转衰）—天京陷落（1864）；它沉重打击了清朝统治和外国侵略势力，但农民阶级不能领导中国革命取得胜利。其余三项是同一单元相邻课时的考点。","options":["太平天国运动：金田起义（1851）—定都天京（1853）—《天朝田亩制度》—天京事变（1…","鸦片战争爆发的根本原因是英国为打开中国市场、推销工业品并掠夺原料；虎门销烟只是英国发动战…","《南京条约》的内容：割香港岛给英国；赔款 2100 万银元；开放广州、厦门、福州、宁波、…","鸦片战争的影响：中国开始沦为半殖民地半封建社会，鸦片战争是中国近代史的开端。"],"difficulty":2,"tags":["八年级上册","第一单元","本课练习"]},{"id":"h8b-u2-q2","type":"choice","stem":"1954 年《中华人民共和国宪法》的历史地位是","answer":"D","explain":"1954 年宪法是我国第一部社会主义类型的宪法，也是我国有史以来真正反映人民利益的宪法；起临时宪法作用的文件是 1949 年的《共同纲领》。","options":["我国第一部宪法性质的临时文件","我国第一部资产阶级民主主义宪法","我国第一部民族区域自治法","我国第一部社会主义类型的宪法"],"tags":["1954 年宪法","历史解释"]},{"id":"h9a-u1-q3","type":"choice","stem":"古印度种姓制度中，掌管祭祀、被视为最高等级的是","answer":"A","explain":"种姓制度第一等级是婆罗门，掌管祭祀；第二等级是刹帝利，掌管军政大权；第三等级是吠舍，从事农业、畜牧业和商业；第四等级是首陀罗。","options":["婆罗门","刹帝利","吠舍","首陀罗"],"tags":["种姓制度","历史解释"]},{"id":"cat-9b-1-3-g5","type":"choice","stem":"「美国南北战争」发生于","answer":"A","explain":"本课时间轴：美国南北战争（1861—1865 年）。根本原因是南北两种经济制度的矛盾（焦点是奴隶制的存废）；1861 年南方军队挑起内战，1865 年北方获胜。其余三个时间是同一单元相邻课时的事件时间。","options":["1861—1865 年","19 世纪初","1857—1859 年","1861 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"h7a-u2-q2","type":"choice","stem":"「封建亲戚，以藩屏周」反映的西周制度是","answer":"B","explain":"分封制把土地和人民分给宗亲、功臣，让他们建立诸侯国，起到拱卫王室的作用。","options":["禅让制","分封制","郡县制","世袭制"],"tags":["分封制","史料实证"]},{"id":"cat-7b-1-3-g2","type":"choice","stem":"下列关于「“开元盛世”」的表述，错误的是","answer":"A","explain":"认为大运河是隋文帝开凿的——「隋文帝统一、隋炀帝开河」这两件事最容易被对调，选择题常把两个皇帝换位置。正确表述：大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","options":["认为大运河是隋文帝开凿的。","大运河是隋炀帝于 605 年起下令开凿的，以洛阳为中心，北抵涿郡、南至余杭。","隋唐时期的时代特征是**繁荣与开放**：繁荣表现为政治清明、经济发达、文化灿烂；开放表现为民族交融频繁、中外交流活跃、兼收并蓄。","科举制是隋唐最重要的制度创新：它以考试取士取代门第取士，把选官权集中到中央，扩大了统治基础，促进了社会阶层流动，影响了中国一千三百多年。"],"difficulty":2,"tags":["七年级下册","第一单元","本课练习"]},{"id":"h8a-u2-q1","type":"choice","stem":"洋务运动「只学习西方技术而不改变封建制度」，导致其最终破产。标志其破产的事件是","answer":"B","explain":"1895 年初威海卫战役中北洋舰队全军覆没，甲午战争中国战败，宣告了洋务运动的破产，也说明单靠引进技术不能救中国。","options":["太平天国运动失败","甲午中日战争中国战败、北洋舰队全军覆没","《辛丑条约》的签订","戊戌变法失败"],"tags":["洋务运动","历史解释"]},{"id":"h8b-u2-q3","type":"choice","stem":"标志着社会主义基本制度在我国建立起来的事件是","answer":"A","explain":"1956 年底三大改造基本完成，实现了生产资料私有制向社会主义公有制的转变，标志社会主义基本制度在我国建立起来，我国从此进入社会主义初级阶段。","options":["1956 年底三大改造基本完成","中华人民共和国成立","第一个五年计划超额完成","1954 年宪法的颁布"],"tags":["三大改造","历史解释"]},{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"h9b-u1-q5","type":"choice","stem":"日本明治维新措施中，属于政治方面、旨在加强中央集权的是","answer":"A","explain":"废藩置县废除了藩国、设置府县，由中央任命官员，加强了中央集权。殖产兴业属经济措施，征兵制属军事措施，文明开化属文化教育措施。","options":["废藩置县","殖产兴业，发展近代工业","实行征兵制，建立新式军队","提倡「文明开化」，发展教育"],"tags":["明治维新","制度创新"]},{"id":"cat-7a-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 禹建立夏朝\n② 武王伐纣，牧野之战后建立西周\n③ 犬戎攻破镐京，西周灭亡","answer":"A","explain":"按时间顺序应为：①禹建立夏朝（约公元前 2070 年）→②武王伐纣，牧野之战后建立西周（公元前 1046 年）→③犬戎攻破镐京，西周灭亡（公元前 771 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["七年级上册","第二单元","本课练习"]},{"id":"cat-7a-2-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：公元前 256 年，秦蜀郡守李冰主持修建都江堰，由鱼嘴、飞沙堰、宝瓶口三大主体工程组成，兼具防洪、灌溉、航运功能，至今仍在发挥作用。（《史记·河渠书》；都江堰水利工程管理局）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"战国时期的社会变革；商鞅变法：奖励耕织、奖励军功、确立县制、废除井田制、统一度量衡。","explain":"材料出自《史记·河渠书》；都江堰水利工程管理局。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-7b-2-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1004 年辽军南下，宋真宗在寇准力劝下亲征澶州。1005 年双方议和：宋每年给辽白银十万两、绢二十万匹，辽撤兵，双方约为兄弟之国。（《续资治通鉴长编》卷五十八）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"辽、西夏与北宋并立；辽、西夏、金与两宋的和战：1005 年宋辽订立澶渊之盟后长期和平；北宋与西夏议和；1141 年宋金议和，以淮河至大散关一线划界，南宋向金称臣、送岁币。","explain":"材料出自《续资治通鉴长编》卷五十八。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["七年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-8a-2-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1894 年 9 月 17 日，北洋舰队与日本联合舰队在黄海大东沟激战五小时，致远舰弹尽，邓世昌下令撞向日舰吉野，中鱼雷沉没，全舰官兵壮烈殉国。（《清史稿·邓世昌传》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"甲午中日战争与列强瓜分中国狂潮；洋务运动的评价：是中国近代化的开端，引进了西方先进技术，客观上促进了中国民族资本主义的产生，对外国资本的入侵起到一定抵制作用；但只学习技术、不改变封建制度，最终破产。","explain":"材料出自《清史稿·邓世昌传》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["八年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]}];
